package com.bankpricemovement;

import javax.annotation.Nullable;

/**
 * The one place that decides what a hidden amount reads (1.1.0 part E, "Hide amounts"): every gp amount and every item
 * quantity the sidebar draws goes through here when the eye is shut, and comes out as a FIXED mask that never depends on
 * the number - a one-digit amount and a twelve-digit one read the same, so a mask shows nothing about its figure, not
 * even its length.
 *
 * <p>Three masks, by what they stand for: {@link #AMOUNT} for a total, a stack value or any exact gp figure,
 * {@link #SHORT} for a gp change and for a quantity. A text that is not a number - the empty text that stands for "nothing
 * moved" and {@link MovementMath#DASH}, which stands for "no figure" - is left as it is: the mask goes where a number would
 * have printed and nowhere else, so shutting the eye changes what is written and never what the layout is made of.
 *
 * <p>What this class never touches: percentages, item names, dates, the price band, the counts of rows - they say nothing
 * about how much the player has. The drawers ask here and keep no rule of their own: with the amounts SHOWN every method
 * answers the text it was handed, so the sidebar is byte for byte what it was before the eye existed.
 */
final class AmountMask
{
	/** A bullet: a typed dot, because the drawn glyphs a bitmap face lacks would need an image for each size. */
	private static final String DOT = "\u2022";

	/** The mask for a total, a stack value or an exact gp amount: five dots. */
	static final String AMOUNT = DOT + DOT + DOT + DOT + DOT;
	/** The mask for a gp change and for an item quantity: three dots. */
	static final String SHORT = DOT + DOT + DOT;

	private AmountMask()
	{
	}

	/** Whether {@code text} is a figure that would say something: not empty and not the dash. */
	private static boolean isFigure(@Nullable final String text)
	{
		return text != null && !text.isEmpty() && !MovementMath.DASH.equals(text);
	}

	/**
	 * A total or a stack value, as printed: {@link #AMOUNT} while {@code hide} is on and there is a figure, else the text
	 * itself.
	 */
	static String amount(final boolean hide, final String text)
	{
		return hide && isFigure(text) ? AMOUNT : text;
	}

	/** A gp change, as printed: {@link #SHORT} while {@code hide} is on and there is a figure, else the text itself. */
	static String change(final boolean hide, final String text)
	{
		return hide && isFigure(text) ? SHORT : text;
	}

	/**
	 * An item quantity, as printed, or a whole text that carries one ("1 x 39.7m"): {@link #SHORT} while {@code hide} is
	 * on, else the text itself. Unlike the other two it masks the dash as well - the line it is used on says "-" for a row
	 * with no price, and its quantity is still the player's.
	 */
	static String quantity(final boolean hide, final String text)
	{
		return hide ? SHORT : text;
	}
}

package com.bankpricemovement;

import java.text.ParseException;
import java.util.Arrays;
import java.util.regex.Pattern;
import javax.annotation.Nullable;

/**
 * The three quick bands under the band button, carried as one immutable value the way {@link ViewOptions} carries
 * the view switches (addendum Z, line Z1): three DISTINCT POSITIVE gp amounts, always held ASCENDING.
 *
 * <p>Before addendum Z these were two constants in the panel - {@code PRESET_MINS} and {@code PRESET_LABELS} - so
 * a bank whose cheapest interesting stack is worth ten million had three chips it never pressed. They are now a
 * config line the user edits in the boxes at the foot of the gear menu, and this value is what travels between
 * that line, those boxes, the fold's chips and the dev bridge.
 *
 * <p>Pure on purpose, like {@link MovementMath}: nothing here touches Swing, the client or the config, so every
 * rule below - what a typed line means, what is refused, how a band is written back out - is testable without a
 * client.
 *
 * <p><b>The invariant is the type.</b> Only {@link #of(long, long, long)} and {@link #parse(String)} build one,
 * and neither can produce a trio that is out of order, holds a duplicate or holds a zero. A duplicate would draw
 * two identical chips of which only one could ever light; a zero or a negative is not a price (the same rule
 * {@code MovementMath.parseGp} applies to the Min / Max fields).
 */
public final class BandPresets
{
	/**
	 * What the plugin has always offered and what "Reset to default" restores: 100k, 1m, 10m - the trio the fold
	 * drew from {@code PRESET_MINS} up to addendum W, so a profile that never touches the new config line sees
	 * exactly today's chips.
	 */
	public static final BandPresets DEFAULT = new BandPresets(100_000L, 1_000_000L, 10_000_000L);

	/** How many bands a trio holds. Three chips beside "All" is what the 213 px fold has room for. */
	private static final int BANDS = 3;

	/**
	 * What separates one band from the next in a typed line: a run of whitespace and slashes, and a comma that is
	 * NOT a thousands grouping comma.
	 *
	 * <p>The three alternatives, in order: {@code [\s/]} is always a separator; {@code (?<![0-9]),} is a comma that
	 * does not follow a digit ("100k, 1m"); {@code ,(?![0-9]{3}(?![0-9]))} is a comma that does not introduce a
	 * group of exactly three digits ("1000,2000"). What is left - a comma between a digit and exactly three digits -
	 * is the grouping comma of "1,000", which {@code MovementMath.parseGp} reads as part of the number and which
	 * {@link #format()} itself writes for any band under 10,000 ({@code QuantityFormatter} spells 1,000 as
	 * "1,000", not as "1k"). Were the split blind to it, {@code parse(of(1000, 2000, 3000).format())} - six parts -
	 * would refuse the very line this class had just written.
	 *
	 * <p>The trailing {@code +} makes a whole run of separators one match, so ", " does not yield an empty band
	 * between the comma and the space.
	 */
	private static final Pattern SEPARATORS = Pattern.compile("(?:[\\s/]|(?<![0-9]),|,(?![0-9]{3}(?![0-9])))+");

	private final long small;
	private final long middle;
	private final long large;

	/**
	 * The only constructor, and private: {@link #of(long, long, long)} is the one door, so no caller can build a
	 * trio that breaks the invariant. The arguments must already be ascending, distinct and positive.
	 */
	private BandPresets(final long small, final long middle, final long large)
	{
		this.small = small;
		this.middle = middle;
		this.large = large;
	}

	/**
	 * Reads the config line, a dev verb's argument or the three boxes joined together (Z1): the text is split on
	 * commas, slashes and whitespace, each part is read by {@link MovementMath#parseGp(String)} - so "100k",
	 * "1.5m", "2b" and "1,000" all work - and the trio is sorted.
	 *
	 * <p>Answers NULL rather than throwing, because every caller of this treats a line it cannot read the same
	 * way: keep the last good presets (a stored string that does not parse reads as {@link #DEFAULT}, never a
	 * crash - Z1). The three refusals are: not exactly three values, a value that is not positive, and two values
	 * that are equal.
	 *
	 * @param text what the user typed, or what the config holds; null and blank are refusals like any other
	 * @return the trio held ascending, or null when the text names no valid one
	 */
	@Nullable
	public static BandPresets parse(final String text)
	{
		if (text == null)
		{
			return null;
		}

		final String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}

		final long[] values = new long[BANDS];
		int found = 0;
		for (final String part : SEPARATORS.split(trimmed))
		{
			if (part.isEmpty())
			{
				// A separator run at the very start of the text yields one empty piece; it is not a band.
				continue;
			}

			if (found == BANDS)
			{
				// A fourth value: the user meant something this line cannot hold, so read none of it.
				return null;
			}

			try
			{
				values[found] = MovementMath.parseGp(part);
			}
			catch (ParseException notANumber)
			{
				return null;
			}

			found++;
		}

		if (found != BANDS || !valid(values[0], values[1], values[2]))
		{
			return null;
		}

		return of(values[0], values[1], values[2]);
	}

	/**
	 * The trio of three amounts in any order, sorted ascending (Z1) - what the gear menu's three boxes and the
	 * {@code presets=} verb build once their text has been read.
	 *
	 * <p>Throws rather than answering null, because a caller that has three longs in hand has already done the
	 * reading: this is the invariant's last gate, not the place a typed line is judged. A panel that reads three
	 * boxes catches it beside the {@link ParseException} the boxes themselves can throw
	 * ({@code catch (ParseException | IllegalArgumentException bad)}) and paints them red.
	 *
	 * @throws IllegalArgumentException when a value is not positive, or two of the three are equal
	 */
	public static BandPresets of(final long a, final long b, final long c)
	{
		if (!valid(a, b, c))
		{
			throw new IllegalArgumentException(
				"Three distinct positive gp bands are needed, not " + a + ", " + b + ", " + c);
		}

		final long[] sorted = {a, b, c};
		Arrays.sort(sorted);
		return new BandPresets(sorted[0], sorted[1], sorted[2]);
	}

	/**
	 * The three lower bounds, smallest first - what the fold's chips apply as {@code applyBand(min, 0)} (Z3).
	 *
	 * @return a fresh array each call, so a caller sorting or scaling it cannot reach back into the value
	 */
	public long[] mins()
	{
		return new long[]{small, middle, large};
	}

	/**
	 * The three chip labels, smallest first: each band in gp shorthand with a "+" after it, since a preset has a
	 * lower bound and no upper one (Z1). For {@link #DEFAULT} exactly "100k+", "1m+", "10m+" - the labels the fold
	 * has drawn since addendum N, which is why the default presets leave every picture byte-identical.
	 *
	 * @return a fresh array each call
	 */
	public String[] labels()
	{
		return new String[]{label(small), label(middle), label(large)};
	}

	/**
	 * The three bands as one line in gp shorthand, smallest first - "100k, 1m, 10m" (Z1): what the config item
	 * holds, what the gear menu's boxes print (one band each), and what {@link #parse(String)} reads back.
	 *
	 * <p>Shorthand is LOSSY where it must be, because it is the same shorthand the boxes and the Min / Max fields
	 * use: a band of 1,234,567 gp is written "1.23m" and read back as 1,230,000. Anything the game itself writes
	 * exactly - every round thousand, million and billion, and every amount under 10,000 - survives the trip.
	 */
	public String format()
	{
		return MovementMath.formatGp(small) + ", " + MovementMath.formatGp(middle) + ", "
			+ MovementMath.formatGp(large);
	}

	/** One chip's label: the band, then the "+" that says "and everything dearer". */
	private static String label(final long min)
	{
		return MovementMath.formatGp(min) + "+";
	}

	/**
	 * The invariant in one place: three positive amounts, no two the same. Order is not its business -
	 * {@link #of(long, long, long)} sorts.
	 */
	private static boolean valid(final long a, final long b, final long c)
	{
		return a > 0L && b > 0L && c > 0L && a != b && b != c && a != c;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BandPresets))
		{
			return false;
		}
		final BandPresets other = (BandPresets) o;
		return small == other.small && middle == other.middle && large == other.large;
	}

	@Override
	public int hashCode()
	{
		int hash = Long.hashCode(small);
		hash = 31 * hash + Long.hashCode(middle);
		hash = 31 * hash + Long.hashCode(large);
		return hash;
	}

	/**
	 * A debugging line, in gp rather than in shorthand: {@link #format()} is the text the user sees, and a log
	 * that rounded 1,234,567 to "1.23m" would hide the very difference one would be reading a log to find.
	 */
	@Override
	public String toString()
	{
		return "BandPresets{" + small + ", " + middle + ", " + large + '}';
	}
}

package com.bankpricemovement;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * The Net Worth History's chart (addendum AU, plan 7.2 item 10), drawn as the user chose it on 2026-09-29 - "plain
 * line, design 2": the "Mountain". The bank's total over the chart's range, one point per drawn day, in a
 * {@link #PLOT_HEIGHT} px plot that is the whole component.
 *
 * <p><b>The mountain.</b> A 1.5 px line in the colour of the range's direction (a rise green, a fall the lifted red, no
 * change grey - the reader's own up and down colours since 1.1.0, or ONE colour whatever the range did while "Single
 * chart colour" is on, {@link #setFixedColour}) over a fill that fades from a tint of that colour at the line's
 * highest point down to nothing at the plot's bottom. The range's HIGH and LOW - chosen among the days WITH a
 * reading, the first of equals - each carry a small grey dot and their compact total ("759m") in small grey figures,
 * the high's above its point and the low's below; they are drawn only when the range has two readings or more and the
 * two differ, since a single reading or a flat range has no high or low to tell (the readout already gives the total).
 * The latest READING carries a filled dot inside a soft halo. No gridline, axis or baseline.
 *
 * <p><b>A plain line</b> (the user: "plain line"). A day with no reading is carried forward flat from the last reading
 * ({@link BankHistoryMath#days}) and takes its place on the time axis, and NOTHING marks it: the same stroke, colour
 * and fill as any other day, the step into the next reading an ordinary segment. A series of ONE reading draws that
 * one dot and halo and no line.
 *
 * <p><b>Hover</b>: one {@link MouseAdapter}, registered as the mouse and the mouse-motion listener, picks the drawn
 * point nearest the pointer by x - a carried day as readily as a reading - draws a thin dashed guide and a ring on it,
 * and tells the view (which prints the readout); leaving the chart hands the readout back to the latest reading. The
 * chart repaints only when the hovered index changes, and the points' coordinates and the figures' places are computed
 * when the data or the size changes - never per mouse move. It paints and hit-tests from its own {@link #getWidth()}
 * (amendment 9.8). No tooltip, ever (amendment 9.13).
 */
final class BankHistoryChart extends JComponent
{
	/** The plot's height, the whole component: 110 px (design 2; 84 before it, 42 as first built). */
	static final int PLOT_HEIGHT = 110;
	/** The first point's x: on the range bar's left edge. */
	static final int INSET_LEFT = 6;
	/**
	 * Room right of the last point: the latest point's {@link #DOT_RADIUS} px dot ends on the range bar's right edge and
	 * its {@link #HALO_RADIUS} px halo 3 px inside the chart block.
	 */
	static final int INSET_RIGHT = 9;
	/** Room above the highest point and below the lowest one, for the high's and the low's figures. */
	static final int INSET_Y = 14;
	/** The high's and the low's figures stay this far inside either side of the chart. */
	static final int FIGURE_MARGIN = 6;
	/** A figure's baseline (the high) or its ink's top (the low) stands at least this far from its point. */
	static final int FIGURE_CLEAR = 3;
	/** The air a figure keeps round the latest point's halo. */
	static final int HALO_AIR = 2;
	/**
	 * How far every pixel of a figure's ink keeps from the line's centre: the 1.5 px stroke's half and a little over a
	 * pixel of air.
	 */
	private static final double LINE_AIR = 0.75 + 1.2;
	/** No clear row inside the plot at a figure's left edge. */
	private static final int NOWHERE = Integer.MIN_VALUE;
	static final double HALO_RADIUS = 6;
	static final double DOT_RADIUS = 3;
	/** The fill's alpha at the line's highest point: 70 for a rise or no change, 80 for a fall (a red at 70 reads muddy). */
	static final int FILL_ALPHA = 70;
	static final int FILL_ALPHA_FALL = 80;
	static final int HALO_ALPHA = 50;
	/** The high's and the low's figures. */
	static final Font FIGURE_FONT = Widgets.sans(10);

	private static final BasicStroke LINE = new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final BasicStroke GUIDE = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f,
		new float[]{2f, 2f}, 0f);
	private static final BasicStroke RING = new BasicStroke(1.6f);
	private static final double MARK_RADIUS = 1.5;
	private static final double RING_RADIUS = 4.5;

	/** Told whenever the hovered point changes: its index, or -1 when the pointer left. */
	interface HoverListener
	{
		void hoverChanged(int index);
	}

	/** The high's or the low's figure as placed: the day it names, its text, its left edge and its baseline. */
	static final class Figure
	{
		/** The day's index among the drawn days. */
		final int index;
		final String text;
		final int left;
		final int baseline;

		Figure(final int index, final String text, final int left, final int baseline)
		{
			this.index = index;
			this.text = text;
			this.left = left;
			this.baseline = baseline;
		}
	}

	private final HoverListener listener;

	private List<BankHistoryMath.Day> days = Collections.emptyList();
	private boolean drawLine;
	private int sign;
	private Color line = ColorScheme.LIGHT_GRAY_COLOR;
	/**
	 * The one colour the line, its fill and the latest point are drawn in whatever the range did (1.1.0 part C's "Single
	 * chart colour"), or null for the range's own - a rise or a fall in the reader's up and down colours.
	 */
	@Nullable
	private Color fixed;
	/**
	 * 1.1.0 part E: whether the high's and the low's figures read their mask ({@link AmountMask#AMOUNT}) in place of the
	 * compact totals. The line, its shape, the dots and the hover are the same either way: only the two words change.
	 */
	private boolean hideAmounts;
	/** The latest reading among {@link #days}, or -1. */
	private int latest = -1;
	private int hover = -1;

	/** The points' coordinates and the figures' places, for the size they were computed at. */
	private double[] xs = new double[0];
	private double[] ys = new double[0];
	private List<Figure> figures = Collections.emptyList();
	private int laidWidth = -1;
	private int laidHeight = -1;

	BankHistoryChart(final HoverListener listener)
	{
		this.listener = Objects.requireNonNull(listener, "listener");
		setOpaque(false);
		setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, PLOT_HEIGHT));
		final MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(final MouseEvent e)
			{
				setHover(indexAt(e.getX()));
			}

			@Override
			public void mouseDragged(final MouseEvent e)
			{
				setHover(indexAt(e.getX()));
			}

			@Override
			public void mouseEntered(final MouseEvent e)
			{
				setHover(indexAt(e.getX()));
			}

			@Override
			public void mouseExited(final MouseEvent e)
			{
				setHover(-1);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	/**
	 * New points to draw. Clears the hover without telling the listener - the view that calls this prints its
	 * readout from the new data straight after.
	 *
	 * @param days     the drawn days, ascending, already thinned
	 * @param drawLine false for a series of one reading: the dot alone
	 * @param sign     the range's direction, which colours the line, its fill and the latest point: +1 a rise, -1 a
	 *                 fall, 0 no change
	 */
	void setData(final List<BankHistoryMath.Day> days, final boolean drawLine, final int sign)
	{
		this.days = days == null ? Collections.emptyList() : days;
		this.drawLine = drawLine;
		this.sign = Integer.signum(sign);
		line = lineFor(this.sign);
		latest = -1;
		for (int i = this.days.size() - 1; i >= 0; i--)
		{
			if (!this.days.get(i).carried())
			{
				latest = i;
				break;
			}
		}
		hover = -1;
		laidWidth = -1;
		repaint();
	}

	/**
	 * Draws the chart in one colour whatever the range did (1.1.0 part C), or in the range's own again for null: the line,
	 * its fill, its latest point and its halo, and the hover ring. The days and the hover are untouched; only the colour
	 * changes, so this costs a repaint and nothing else. Any transparency is dropped: the fill's tint is {@link #FILL_ALPHA}
	 * of it, as for a rise.
	 */
	void setFixedColour(@Nullable final Color colour)
	{
		fixed = colour == null ? null : new Color(colour.getRGB());
		line = lineFor(sign);
		repaint();
	}

	/**
	 * Hides or shows the high's and the low's figures (1.1.0 part E): each reads {@link AmountMask#AMOUNT} while hidden, so the
	 * chart keeps its line and shape and says nothing about the totals. The figures are placed again at the next paint
	 * (the mask is a different width from the total it replaces), so this costs a repaint and nothing else.
	 */
	void setAmountsHidden(final boolean hide)
	{
		hideAmounts = hide;
		laidWidth = -1;
		repaint();
	}

	/** The colour the line is drawn in for a range that went {@code direction}: the fixed colour, else the move rule's. */
	private Color lineFor(final int direction)
	{
		return fixed != null ? fixed : Widgets.move(direction, Widgets.Kind.FIGURE);
	}

	List<BankHistoryMath.Day> days()
	{
		return days;
	}

	/** The point the readout names: the hovered one, else the latest reading, else the last day drawn; -1 if none. */
	int readoutIndex()
	{
		if (hover >= 0)
		{
			return hover;
		}
		return latest >= 0 ? latest : days.size() - 1;
	}

	/**
	 * The line's colour, which is every point's: a day with no reading is drawn like any other. The fixed colour while
	 * "Single chart colour" is on, whatever the range did; otherwise the range's direction in the up and down colours.
	 */
	Color lineColour()
	{
		return line;
	}

	/** The x of point {@code i} of {@code n} across a chart {@code width} px wide: evenly spaced, one point centred. */
	static double xAt(final int i, final int n, final int width)
	{
		if (n <= 1)
		{
			return (INSET_LEFT + width - INSET_RIGHT) / 2.0;
		}
		return INSET_LEFT + i * (width - (double) INSET_LEFT - INSET_RIGHT) / (n - 1);
	}

	/** The drawn point nearest {@code x}, or -1 when nothing is drawn. */
	int indexAt(final int x)
	{
		final int n = days.size();
		if (n == 0)
		{
			return -1;
		}
		if (n == 1)
		{
			return 0;
		}
		final double step = (getWidth() - (double) INSET_LEFT - INSET_RIGHT) / (n - 1);
		if (step <= 0)
		{
			return n - 1;
		}
		final long i = Math.round((x - INSET_LEFT) / step);
		return (int) Math.max(0, Math.min(n - 1, i));
	}

	private void setHover(final int index)
	{
		if (index == hover)
		{
			return;
		}
		hover = index;
		repaint();
		listener.hoverChanged(index);
	}

	/**
	 * The high's and the low's figures as they are painted at the chart's present size: none with fewer than two
	 * readings among the drawn days, or when the high and the low are equal.
	 */
	List<Figure> figures()
	{
		layOut();
		return figures;
	}

	/** The coordinates and the figures for the current size, computed once per data or size change. */
	private void layOut()
	{
		final int w = getWidth();
		final int h = getHeight();
		if (w == laidWidth && h == laidHeight)
		{
			return;
		}
		laidWidth = w;
		laidHeight = h;
		final int n = days.size();
		xs = new double[n];
		ys = new double[n];
		long min = Long.MAX_VALUE;
		long max = Long.MIN_VALUE;
		for (BankHistoryMath.Day d : days)
		{
			min = Math.min(min, d.valueGp());
			max = Math.max(max, d.valueGp());
		}
		final double top = INSET_Y;
		final double plot = Math.max(1, h - 2 * INSET_Y);
		for (int i = 0; i < n; i++)
		{
			xs[i] = xAt(i, n, w);
			ys[i] = max == min ? top + plot / 2.0
				: top + (max - (double) days.get(i).valueGp()) * plot / ((double) max - (double) min);
		}
		figures = placeFigures(w, h);
	}

	/**
	 * The high and the low, chosen among the days with a reading (a carried day repeats a total, it never makes one),
	 * each placed by one rule: centred on its point's x and kept {@link #FIGURE_MARGIN} px inside either side; the
	 * high's baseline {@link #FIGURE_CLEAR} px above its point, the low's ink top as far below it; and a figure that
	 * would come within {@link #HALO_AIR} px of the latest point's halo, or within {@link #LINE_AIR} px of the line's
	 * centre, steps one pixel further from its point (the high up, the low down) until it is clear of both. When that
	 * would take it out of the plot - a high or a low that IS the latest point, at the plot's edge, or one the line
	 * comes down (or up) into from days carried from an older reading beyond every reading in the range - it slides
	 * sideways instead, to the nearest place (the left side first at equal distance) where the same steps find it a
	 * clear row inside the plot.
	 */
	private List<Figure> placeFigures(final int w, final int h)
	{
		int hi = -1;
		int lo = -1;
		int readings = 0;
		for (int i = 0; i < days.size(); i++)
		{
			final BankHistoryMath.Day d = days.get(i);
			if (d.carried())
			{
				continue;
			}
			readings++;
			if (hi < 0 || d.valueGp() > days.get(hi).valueGp())
			{
				hi = i;
			}
			if (lo < 0 || d.valueGp() < days.get(lo).valueGp())
			{
				lo = i;
			}
		}
		if (readings < 2 || days.get(hi).valueGp() == days.get(lo).valueGp())
		{
			return Collections.emptyList();
		}
		final FontMetrics fm = getFontMetrics(FIGURE_FONT);
		final List<Figure> out = new ArrayList<>(2);
		out.add(place(hi, true, fm, w, h));
		out.add(place(lo, false, fm, w, h));
		return out;
	}

	private Figure place(final int i, final boolean high, final FontMetrics fm, final int w, final int h)
	{
		final String text = AmountMask.amount(hideAmounts, MovementMath.formatGp(days.get(i).valueGp()));
		final int width = fm.stringWidth(text);
		// The ink's height above the baseline, as the face draws this text (the figures have no descenders).
		final int cap = -FIGURE_FONT.createGlyphVector(fm.getFontRenderContext(), text).getPixelBounds(null, 0, 0).y;
		final int maxLeft = Math.max(FIGURE_MARGIN, w - FIGURE_MARGIN - width);
		final int centred = (int) Math.max(FIGURE_MARGIN, Math.min(maxLeft, Math.round(xs[i] - width / 2.0)));
		int baseline = settle(i, high, centred, width, cap, h);
		if (baseline != NOWHERE)
		{
			return new Figure(i, text, centred, baseline);
		}
		for (int d = 1; centred - d >= FIGURE_MARGIN || centred + d <= maxLeft; d++)
		{
			for (int side = -1; side <= 1; side += 2)
			{
				final int left = centred + side * d;
				if (left < FIGURE_MARGIN || left > maxLeft)
				{
					continue;
				}
				baseline = settle(i, high, left, width, cap, h);
				if (baseline != NOWHERE)
				{
					return new Figure(i, text, left, baseline);
				}
			}
		}
		// Nowhere clear in the whole plot (it cannot happen at the sidebar's sizes): the first row, centred.
		return new Figure(i, text, centred, high ? (int) Math.round(ys[i] - FIGURE_CLEAR)
			: (int) Math.round(ys[i] + FIGURE_CLEAR) + cap);
	}

	/**
	 * The baseline of the first row, stepping away from point {@code i} (the high up, the low down) from
	 * {@link #FIGURE_CLEAR} px, at which the figure's ink {@code [left, left + width) x [baseline - cap, baseline)} stays
	 * inside the plot and clear of the latest point's halo and of the line; {@link #NOWHERE} when it leaves the plot first.
	 */
	private int settle(final int i, final boolean high, final int left, final int width, final int cap, final int h)
	{
		for (int clear = FIGURE_CLEAR; ; clear++)
		{
			final int b = high ? (int) Math.round(ys[i] - clear) : (int) Math.round(ys[i] + clear) + cap;
			if (b - cap < 0 || b > h)
			{
				return NOWHERE;
			}
			if ((latest < 0 || clearOfHalo(left, width, b - cap, b)) && clearOfLine(left, width, b - cap, b))
			{
				return b;
			}
		}
	}

	/** Whether the box {@code [left, left + width) x [top, bottom)} keeps {@link #HALO_AIR} px from the halo's box. */
	private boolean clearOfHalo(final int left, final int width, final int top, final int bottom)
	{
		final double reach = HALO_RADIUS + HALO_AIR;
		return left + width <= xs[latest] - reach || left >= xs[latest] + reach
			|| bottom <= ys[latest] - reach || top >= ys[latest] + reach;
	}

	/**
	 * Whether every pixel of the box {@code [left, left + width) x [top, bottom)} - the rectangle through its pixels'
	 * centres - keeps {@link #LINE_AIR} px from every segment of the line.
	 */
	private boolean clearOfLine(final int left, final int width, final int top, final int bottom)
	{
		final double x0 = left + 0.5;
		final double x1 = left + width - 0.5;
		final double y0 = top + 0.5;
		final double y1 = bottom - 0.5;
		for (int s = 0; s + 1 < xs.length; s++)
		{
			if (xs[s + 1] < x0 - LINE_AIR || xs[s] > x1 + LINE_AIR)
			{
				continue;
			}
			if (segmentToBox(xs[s], ys[s], xs[s + 1], ys[s + 1], x0, y0, x1, y1) < LINE_AIR)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * The distance from segment {@code (ax, ay) - (bx, by)} to the rectangle {@code [x0, x1] x [y0, y1]}: 0 when they
	 * meet, else the nearest of the segment's ends to the rectangle and of the rectangle's corners to the segment (two
	 * convex shapes apart are nearest at a corner of one of them).
	 */
	private static double segmentToBox(final double ax, final double ay, final double bx, final double by,
		final double x0, final double y0, final double x1, final double y1)
	{
		if (inside(ax, ay, x0, y0, x1, y1) || inside(bx, by, x0, y0, x1, y1)
			|| Line2D.linesIntersect(ax, ay, bx, by, x0, y0, x1, y0) || Line2D.linesIntersect(ax, ay, bx, by, x1, y0, x1, y1)
			|| Line2D.linesIntersect(ax, ay, bx, by, x1, y1, x0, y1) || Line2D.linesIntersect(ax, ay, bx, by, x0, y1, x0, y0))
		{
			return 0;
		}
		double d = Math.min(pointToBox(ax, ay, x0, y0, x1, y1), pointToBox(bx, by, x0, y0, x1, y1));
		d = Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x0, y0));
		d = Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x1, y0));
		d = Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x0, y1));
		return Math.min(d, Line2D.ptSegDist(ax, ay, bx, by, x1, y1));
	}

	private static boolean inside(final double x, final double y, final double x0, final double y0, final double x1,
		final double y1)
	{
		return x >= x0 && x <= x1 && y >= y0 && y <= y1;
	}

	private static double pointToBox(final double x, final double y, final double x0, final double y0, final double x1,
		final double y1)
	{
		final double dx = Math.max(0, Math.max(x0 - x, x - x1));
		final double dy = Math.max(0, Math.max(y0 - y, y - y1));
		return Math.hypot(dx, dy);
	}

	@Override
	protected void paintComponent(final Graphics g)
	{
		final int n = days.size();
		if (n == 0)
		{
			return;
		}
		final List<Figure> marks = figures();
		final Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			final int h = getHeight();
			final boolean line = drawLine && n > 1;
			if (line)
			{
				paintFill(g2, h);
			}
			if (hover >= 0 && hover < n)
			{
				g2.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				g2.setStroke(GUIDE);
				g2.draw(new Line2D.Double(xs[hover], 0, xs[hover], h));
			}
			if (line)
			{
				final Path2D.Double path = new Path2D.Double();
				path.moveTo(xs[0], ys[0]);
				for (int i = 1; i < n; i++)
				{
					path.lineTo(xs[i], ys[i]);
				}
				g2.setColor(this.line);
				g2.setStroke(LINE);
				g2.draw(path);
			}
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			for (Figure f : marks)
			{
				if (f.index != latest)
				{
					g2.fill(circle(xs[f.index], ys[f.index], MARK_RADIUS));
				}
			}
			if (latest >= 0)
			{
				g2.setColor(withAlpha(this.line, HALO_ALPHA));
				g2.fill(circle(xs[latest], ys[latest], HALO_RADIUS));
				g2.setColor(this.line);
				g2.fill(circle(xs[latest], ys[latest], DOT_RADIUS));
			}
			if (!marks.isEmpty())
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setFont(FIGURE_FONT);
				g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
				for (Figure f : marks)
				{
					g2.drawString(f.text, f.left, f.baseline);
				}
			}
			if (hover >= 0 && hover < n)
			{
				final Ellipse2D ring = circle(xs[hover], ys[hover], RING_RADIUS);
				g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
				g2.fill(ring);
				g2.setColor(this.line);
				g2.setStroke(RING);
				g2.draw(ring);
			}
		}
		finally
		{
			g2.dispose();
		}
	}

	/** The area under the line down to the plot's bottom, its tint fading from the line's highest point to nothing. */
	private void paintFill(final Graphics2D g2, final int h)
	{
		final int n = days.size();
		final Path2D.Double area = new Path2D.Double();
		area.moveTo(xs[0], ys[0]);
		double top = ys[0];
		for (int i = 1; i < n; i++)
		{
			area.lineTo(xs[i], ys[i]);
			top = Math.min(top, ys[i]);
		}
		area.lineTo(xs[n - 1], h);
		area.lineTo(xs[0], h);
		area.closePath();
		// A fall's red reads muddy at the rise's alpha; a colour the reader chose for the whole chart has no direction.
		final int alpha = fixed == null && sign < 0 ? FILL_ALPHA_FALL : FILL_ALPHA;
		g2.setPaint(new GradientPaint(0f, (float) top, withAlpha(line, alpha), 0f, (float) h, withAlpha(line, 0)));
		g2.fill(area);
	}

	private static Color withAlpha(final Color c, final int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	private static Ellipse2D circle(final double x, final double y, final double r)
	{
		return new Ellipse2D.Double(x - r, y - r, 2 * r, 2 * r);
	}

	/** The day of the hovered point, or null. */
	@Nullable
	BankHistoryMath.Day hoverDay()
	{
		return hover >= 0 && hover < days.size() ? days.get(hover) : null;
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Insets;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.temporal.ChronoUnit;
import java.util.Locale;
import java.util.Objects;
import javax.annotation.Nullable;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * One row of the History view's list of days (addendum AU, plan 7.2 items 3, 4 and 11; contract section 6).
 *
 * <p>A day WITH a reading is a {@value #HEIGHT} px card with a coloured left edge - green for a rise, the rows' red
 * for a fall, grey for no change or the first reading - and three columns of two lines:
 * <pre>
 *   Sat 26 Sep            736m            +0.4%
 *   vs 25 Sep             736,412,683     +3.41m
 * </pre>
 * A day with NO reading is a thin {@value #CARRIED_HEIGHT} px grey line reading its date alone, "Tue 22 Sep" (the
 * user on the first live look, 2026-09-29: "remove the text '-carried, 754m' on days we dont login"; the chart still
 * draws the day carried forward). There is no clock on a row (plan 7.2 item 3).
 *
 * <p><b>The columns are measured at 213 px, not taken from the mock</b> (plan 7.2 item 2, amendment 9.8). Mock 5 was
 * drawn 223 px wide; at 213 its second line - "vs 01 May, 100 days" (95 px at 10 px: a May date is the widest, and
 * every 3-digit span measures the same), "12,345,678,901" (75) and "+1.66m" (36, the widest the row face's gp figure
 * ever prints) - wants 206 px of text plus two gaps in 200 px of room, and collides. So the left column is
 * {@value #LEFT_COLUMN} px (the widest honest sub-line), the exact total is printed at {@value #EXACT_SIZE} px
 * (64 px for twelve billion), the gap between columns is {@value #GAP} px, the right column is right-aligned to the
 * row's inner edge, and the middle column takes what is left - line 2 of the worst row is then
 * 95 + 2 + 64 + 2 + 36 = 199 of 200 px at 213, and at 230 all the slack goes to the middle. Every label is laid out at
 * its own preferred width and cut to its room only as a last resort; {@code BankHistoryViewFitTest} proves the widest
 * honest row cuts nothing and overlaps nothing.
 *
 * <p>KNOWN LIMIT: a gap of 1,000 days or more between two readings ("vs 01 May, 1000 days", 101 px) does not fit
 * the column and is cut with an ellipsis; the words are final, and nearly three years without a reading is the
 * only way to reach it.
 *
 * <p>Built from an immutable {@link Model} of the strings it prints, so the view can keep a row whose model has not
 * changed (plan 7.2 item 9) and a test can build the widest honest row directly. Plain labels only: no
 * {@code <html>}, no tooltip (amendment 9.13).
 */
final class BankHistoryDayRow extends JPanel
{
	/** A day with a reading. */
	static final int HEIGHT = 36;
	/** A carried day: no reading of its own. */
	static final int CARRIED_HEIGHT = 20;
	/** The "Day / Bank Total / Change" header over the list. */
	static final int HEADER_HEIGHT = 16;

	/** Inside the {@link Widgets#EDGE_WIDTH} px edge, and before the right edge. */
	static final int PAD_LEFT = 5;
	static final int PAD_RIGHT = 5;
	/**
	 * The date column: "vs 01 May, 100 days" at {@value #SUB_SIZE} px, the widest honest sub-line (any May date with
	 * a 3-digit span), is 95 px; the widest date on line 1 ("01 May 2025", bold 12) is 71.
	 */
	static final int LEFT_COLUMN = 95;
	/** Between two columns: 2, not 3, so the 95 px sub-line and the 64 px exact total both fit line 2 at 213 px. */
	static final int GAP = 2;
	/** Where a carried row's words start, from the row's left edge (mock 5 indents them past the rows' text). */
	static final int CARRIED_INDENT = Widgets.EDGE_WIDTH + PAD_LEFT + 4;

	/** A date more than this many days before today prints its year (plan 7.2 item 11, amendment 9.14). */
	static final int YEAR_AFTER_DAYS = 300;

	static final String FIRST_READING = "first reading";
	static final String DAY_HEADER = "Day";
	static final String TOTAL_HEADER = "Bank Total";
	static final String CHANGE_HEADER = "Change";

	private static final int DATE_SIZE = 12;
	private static final int SUB_SIZE = 10;
	private static final int TOTAL_SIZE = 13;
	/** A size below the other sub-lines: the one thing that makes the widest honest row fit at 213 px. */
	private static final int EXACT_SIZE = 9;
	private static final int PCT_SIZE = 14;
	private static final int GP_SIZE = 10;
	private static final int CARRIED_SIZE = 11;
	private static final int HEADER_SIZE = 11;

	static final Font DATE_FONT = Widgets.sansBold(DATE_SIZE);
	static final Font SUB_FONT = Widgets.sans(SUB_SIZE);
	static final Font TOTAL_FONT = Widgets.sans(TOTAL_SIZE);
	static final Font EXACT_FONT = Widgets.sans(EXACT_SIZE);
	static final Font PCT_FONT = Widgets.sansBold(PCT_SIZE);
	static final Font GP_FONT = Widgets.sans(GP_SIZE);
	static final Font CARRIED_FONT = Widgets.sans(CARRIED_SIZE);
	static final Font HEADER_FONT = Widgets.sans(HEADER_SIZE);

	/**
	 * Line 1's baseline and line 2's, from the row's top: far enough apart that no line-1 label's box (the 14 px
	 * percentage's descent included) reaches into a line-2 label's.
	 */
	private static final int LINE1_BASELINE = 16;
	private static final int LINE2_BASELINE = 31;

	/** The grey of a carried row's ground: between the card grey and the sidebar's, as mock 5 draws it. */
	static final Color CARRIED_GROUND = ColorScheme.DARK_GRAY_HOVER_COLOR;
	/** The edge of a reading that did not move, or of the first reading: a grey that shows on the card grey. */
	static final Color FLAT_EDGE = ColorScheme.MEDIUM_GRAY_COLOR;

	private static final DateTimeFormatter WEEKDAY = DateTimeFormatter.ofPattern("EEE", Locale.ENGLISH);

	/** The strings one row prints, and the sign its colours follow. Value equality: the view reuses equal rows. */
	static final class Model
	{
		private final LocalDate day;
		private final boolean carried;
		private final String date;
		private final String sub;
		private final String total;
		private final String exact;
		private final String pct;
		private final String gp;
		/** +1 rise, -1 fall, 0 no change; {@link #first} rows are 0 too. */
		private final int signum;
		private final boolean first;

		Model(final LocalDate day, final boolean carried, final String date, final String sub, final String total,
			final String exact, final String pct, final String gp, final int signum, final boolean first)
		{
			this.day = Objects.requireNonNull(day, "day");
			this.carried = carried;
			this.date = text(date);
			this.sub = text(sub);
			this.total = text(total);
			this.exact = text(exact);
			this.pct = text(pct);
			this.gp = text(gp);
			this.signum = Integer.signum(signum);
			this.first = first;
		}

		private static String text(@Nullable final String s)
		{
			return s == null ? "" : s;
		}

		LocalDate day()
		{
			return day;
		}

		boolean carried()
		{
			return carried;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Model))
			{
				return false;
			}
			final Model m = (Model) o;
			return carried == m.carried && signum == m.signum && first == m.first && day.equals(m.day)
				&& date.equals(m.date) && sub.equals(m.sub) && total.equals(m.total) && exact.equals(m.exact)
				&& pct.equals(m.pct) && gp.equals(m.gp);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(day, carried, date, sub, total, exact, pct, gp, signum, first);
		}

		@Override
		public String toString()
		{
			return carried ? "Model{" + date + '}'
				: "Model{" + date + " | " + sub + " | " + total + " | " + exact + " | " + pct + " | " + gp + '}';
		}
	}

	/**
	 * What the row of one calendar day prints, every figure through {@link BankHistoryPoint#valueFor} by way of
	 * {@link BankHistoryMath}: the compact total as the card prints it ({@link MovementMath#formatGp}, so "736m"),
	 * the exact one, the change against the PREVIOUS reading (% bold, gp quiet), the sub-line naming the day
	 * compared - "vs 25 Sep", "vs 21 Sep, 2 days", or "first reading" for the first reading ever. A day with no
	 * reading prints its date and nothing else.
	 *
	 * <p>With {@code hideAmounts} on (1.1.0 part E) the total, the exact total and the gp change read their masks
	 * ({@link AmountMask}) and the date, the sub-line and the percentage are what they always are.
	 *
	 * @param series the series already cut to {@code today}
	 */
	static Model model(final BankHistorySeries series, final BankHistoryMath.Day day, final LocalDate today,
		@Nullable final ViewOptions options, final boolean hideAmounts)
	{
		final String date = dayText(day.day(), today);
		if (day.carried())
		{
			return new Model(day.day(), true, date, "", "", "", "", "", 0, false);
		}
		final String total = AmountMask.amount(hideAmounts, MovementMath.formatGp(day.valueGp()));
		final String exact = AmountMask.amount(hideAmounts, MovementMath.formatExact(day.valueGp()));
		final BankHistoryMath.Change change = BankHistoryMath.vsPrevious(series, day.day(), options);
		if (change == null)
		{
			return new Model(day.day(), false, date, FIRST_READING, total, exact, MovementMath.DASH, "", 0, true);
		}
		final long delta = change.deltaGp();
		final int span = change.spanDays();
		final String sub = "vs " + MovementMath.formatDay(change.fromDay()) + (span > 1 ? ", " + span + " days" : "");
		return new Model(day.day(), false, date, sub, total, exact,
			MovementMath.formatPctCompact(change.pct(), delta),
			delta == 0L ? "" : AmountMask.change(hideAmounts, MovementRowPanel.signedGp(delta)), Long.signum(delta), false);
	}

	/** "Tue 22 Sep" (amendment 9.14's weekday form). */
	static String weekday(final LocalDate day)
	{
		return WEEKDAY.format(day) + " " + MovementMath.formatDay(day);
	}

	/**
	 * A list row's date: the weekday form, or - for a day more than {@value #YEAR_AFTER_DAYS} days before today -
	 * amendment 9.14's {@code formatDay + " " + year} ("30 Sep 2025"), which leaves the weekday out so the year fits
	 * the date column.
	 */
	static String dayText(final LocalDate day, final LocalDate today)
	{
		if (ChronoUnit.DAYS.between(day, today) > YEAR_AFTER_DAYS)
		{
			return MovementMath.formatDay(day) + " " + day.getYear();
		}
		return weekday(day);
	}

	private final Model model;
	private final JLabel dateLabel;
	@Nullable
	private final JLabel subLabel;
	@Nullable
	private final JLabel totalLabel;
	@Nullable
	private final JLabel exactLabel;
	@Nullable
	private final JLabel pctLabel;
	@Nullable
	private final JLabel gpLabel;

	BankHistoryDayRow(final Model model)
	{
		super(null);
		this.model = Objects.requireNonNull(model, "model");
		setOpaque(true);
		if (model.carried)
		{
			setBackground(CARRIED_GROUND);
			setBorder(new EmptyBorder(0, CARRIED_INDENT, 0, PAD_RIGHT));
			dateLabel = add(Widgets.label(model.date, CARRIED_FONT, Widgets.PLACEHOLDER_COLOR));
			subLabel = null;
			totalLabel = null;
			exactLabel = null;
			pctLabel = null;
			gpLabel = null;
			setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, CARRIED_HEIGHT));
			return;
		}
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		final Color edge = model.signum == 0 ? FLAT_EDGE : Widgets.move(model.signum, Widgets.Kind.EDGE);
		setBorder(Widgets.card(edge, new Insets(0, PAD_LEFT, 0, PAD_RIGHT)));
		dateLabel = add(Widgets.label(model.date, DATE_FONT, Color.WHITE));
		subLabel = add(Widgets.label(model.sub, SUB_FONT, ColorScheme.LIGHT_GRAY_COLOR));
		totalLabel = add(Widgets.label(model.total, TOTAL_FONT, Color.WHITE));
		exactLabel = add(Widgets.label(model.exact, EXACT_FONT, ColorScheme.LIGHT_GRAY_COLOR));
		pctLabel = add(Widgets.label(model.pct, PCT_FONT, Widgets.move(model.signum, Widgets.Kind.FIGURE)));
		gpLabel = add(Widgets.label(model.gp, GP_FONT, Widgets.move(model.signum, Widgets.Kind.QUIET)));
		setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, HEIGHT));
	}

	private JLabel add(final JLabel label)
	{
		super.add(label);
		return label;
	}

	Model model()
	{
		return model;
	}

	/** Columns from the row's own width, so the same row is right at 213 px and at 230. */
	@Override
	public void doLayout()
	{
		final Insets in = getInsets();
		final int left = in.left;
		final int right = getWidth() - in.right;
		if (model.carried)
		{
			place(dateLabel, left, right - left, (getHeight() - height(dateLabel)) / 2);
			return;
		}
		final int middle = left + LEFT_COLUMN + GAP;
		final int pctX = right - width(pctLabel);
		final int gpX = right - width(gpLabel);
		place(pctLabel, pctX, width(pctLabel), top(pctLabel, LINE1_BASELINE));
		place(gpLabel, gpX, width(gpLabel), top(gpLabel, LINE2_BASELINE));
		place(totalLabel, middle, Math.min(width(totalLabel), pctX - GAP - middle), top(totalLabel, LINE1_BASELINE));
		place(exactLabel, middle, Math.min(width(exactLabel), gpX - GAP - middle), top(exactLabel, LINE2_BASELINE));
		place(dateLabel, left, Math.min(width(dateLabel), middle - GAP - left), top(dateLabel, LINE1_BASELINE));
		place(subLabel, left, Math.min(width(subLabel), middle - GAP - left), top(subLabel, LINE2_BASELINE));
	}

	private static int width(final JLabel label)
	{
		return label.getPreferredSize().width;
	}

	private static int height(final JLabel label)
	{
		return label.getPreferredSize().height;
	}

	/** Where a label's top goes for its text to stand on {@code baseline}. */
	private static int top(final JLabel label, final int baseline)
	{
		final FontMetrics fm = label.getFontMetrics(label.getFont());
		return baseline - fm.getAscent();
	}

	private static void place(final JLabel label, final int x, final int width, final int y)
	{
		label.setBounds(x, y, Math.max(0, width), height(label));
	}

	/**
	 * The "Day / Bank Total / Change" header over the list, on the sidebar's own ground, its words standing over the
	 * columns of {@link BankHistoryDayRow}.
	 */
	static JPanel header()
	{
		final JLabel day = Widgets.label(DAY_HEADER, HEADER_FONT, ColorScheme.LIGHT_GRAY_COLOR);
		final JLabel total = Widgets.label(TOTAL_HEADER, HEADER_FONT, ColorScheme.LIGHT_GRAY_COLOR);
		final JLabel change = Widgets.label(CHANGE_HEADER, HEADER_FONT, ColorScheme.LIGHT_GRAY_COLOR);
		final JPanel header = new JPanel(null)
		{
			@Override
			public void doLayout()
			{
				final int left = Widgets.EDGE_WIDTH + PAD_LEFT;
				final int right = getWidth() - PAD_RIGHT;
				final int y = (getHeight() - height(day)) / 2;
				place(day, left, width(day), y);
				place(total, left + LEFT_COLUMN + GAP, width(total), y);
				place(change, right - width(change), width(change), y);
			}
		};
		header.setOpaque(false);
		header.add(day);
		header.add(total);
		header.add(change);
		header.setPreferredSize(new Dimension(Widgets.CONTENT_WIDTH, HEADER_HEIGHT));
		return header;
	}
}

package com.bankpricemovement;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * The arithmetic over a {@link BankHistorySeries} (addendum AU; phase 0 contract sections 3, 9.5 and 9.6): the
 * change over a window, the change a day's reading made against the reading before it, the calendar days a
 * chart draws - carried days included - and the thinning that keeps a long range to about 120 points.
 *
 * <p>Pure and static. Nothing here reads a clock or a time zone: every caller hands in "today" (from its own
 * clock), and {@link #dayOf} takes the zone. Every figure is a reading's {@link BankHistoryPoint#valueFor}, so
 * everything drawn follows the switches that are on now; a null {@link ViewOptions} reads as
 * {@link ViewOptions#DEFAULT} everywhere (amendment 9.2).
 */
public final class BankHistoryMath
{
	private BankHistoryMath()
	{
	}

	/**
	 * The LOCAL calendar date of an epoch-millisecond stamp (contract section 3): what a reading is filed under.
	 * Production passes {@link ZoneId#systemDefault()}; a test passes the zone it needs.
	 */
	public static LocalDate dayOf(final long epochMillis, final ZoneId zone)
	{
		return Instant.ofEpochMilli(epochMillis).atZone(Objects.requireNonNull(zone, "zone")).toLocalDate();
	}

	/**
	 * The total moved from one reading to another (or to "now"). {@link #fromDay()} is the day of the reading
	 * actually USED, which is older than the window's day whenever that day had no reading - {@link #spanDays()}
	 * is what says so.
	 */
	public static final class Change
	{
		private final LocalDate fromDay;
		private final LocalDate toDay;
		private final long fromGp;
		private final long toGp;
		private final long deltaGp;
		@Nullable
		private final Double pct;
		private final int spanDays;

		/**
		 * deltaGp = toGp - fromGp; pct = deltaGp x 100 / fromGp, or null when fromGp is 0 (the formula
		 * {@link PortfolioMath} uses for a window); spanDays = the calendar days from fromDay to toDay.
		 */
		Change(final LocalDate fromDay, final LocalDate toDay, final long fromGp, final long toGp)
		{
			this.fromDay = Objects.requireNonNull(fromDay, "fromDay");
			this.toDay = Objects.requireNonNull(toDay, "toDay");
			this.fromGp = fromGp;
			this.toGp = toGp;
			this.deltaGp = toGp - fromGp;
			this.pct = fromGp == 0L ? null : deltaGp * 100.0d / fromGp;
			this.spanDays = (int) ChronoUnit.DAYS.between(fromDay, toDay);
		}

		/** The day of the reading compared FROM - the one actually used. */
		public LocalDate fromDay()
		{
			return fromDay;
		}

		/** The day compared TO. */
		public LocalDate toDay()
		{
			return toDay;
		}

		/** The total at the day compared TO less the total at the day compared FROM. */
		public long deltaGp()
		{
			return deltaGp;
		}

		/**
		 * The move as a percentage of the total compared FROM, unrounded (a reader truncates it toward zero when printing,
		 * as every percentage in the plugin is); null when {@code fromGp} is 0.
		 */
		@Nullable
		public Double pct()
		{
			return pct;
		}

		/** Calendar days from {@link #fromDay()} to {@link #toDay()}. */
		public int spanDays()
		{
			return spanDays;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Change))
			{
				return false;
			}
			final Change other = (Change) o;
			return fromDay.equals(other.fromDay) && toDay.equals(other.toDay) && fromGp == other.fromGp
				&& toGp == other.toGp;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(fromDay, toDay, fromGp, toGp);
		}

		@Override
		public String toString()
		{
			return "Change{" + fromDay + " " + fromGp + " -> " + toDay + " " + toGp + ", deltaGp=" + deltaGp
				+ ", pct=" + pct + ", spanDays=" + spanDays + '}';
		}
	}

	/**
	 * One calendar day as drawn. A day with no reading is CARRIED: its value is the last reading before it, carried
	 * forward. Two days are equal when they are the same day, value and reading.
	 */
	public static final class Day
	{
		private final LocalDate day;
		private final long valueGp;
		private final boolean carried;
		@Nullable
		private final BankHistoryPoint reading;

		Day(final LocalDate day, final long valueGp, @Nullable final BankHistoryPoint reading)
		{
			this.day = Objects.requireNonNull(day, "day");
			this.valueGp = valueGp;
			this.carried = reading == null;
			this.reading = reading;
		}

		public LocalDate day()
		{
			return day;
		}

		/** The day's total under the switches it was computed with - carried forward on a carried day. */
		public long valueGp()
		{
			return valueGp;
		}

		/** True when the day has no reading of its own. */
		public boolean carried()
		{
			return carried;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Day))
			{
				return false;
			}
			final Day other = (Day) o;
			return day.equals(other.day) && valueGp == other.valueGp && Objects.equals(reading, other.reading);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(day, valueGp, reading);
		}

		@Override
		public String toString()
		{
			return "Day{" + day + " " + valueGp + (carried ? " carried" : "") + '}';
		}
	}

	/**
	 * The change over a range of {@code days} ending today (amendment 9.5): the series is first cut to
	 * {@code upTo(today)}; to = the last reading on or before today; from = the first reading when
	 * {@code days <= 0} (the "all" range), else the last reading on or before {@code today - days}. Null when either
	 * is missing, or when from is the same reading as to - never a change of 0 that was not measured.
	 */
	@Nullable
	public static Change overDays(@Nullable final BankHistorySeries series, final LocalDate today, final int days,
		@Nullable final ViewOptions options)
	{
		Objects.requireNonNull(today, "today");
		final BankHistorySeries s = cut(series, today);
		final BankHistoryPoint to = s.atOrBefore(today);
		final BankHistoryPoint from = days <= 0 ? s.first() : s.atOrBefore(today.minusDays(days));
		if (to == null || from == null || from.day().equals(to.day()))
		{
			return null;
		}
		return new Change(from.day(), to.day(), from.valueFor(options), to.valueFor(options));
	}

	/**
	 * The card's move in History (amendment 9.6): the total NOW against the last reading on or before
	 * {@code today - days}. toDay is today and toGp is {@code nowGp}, the card's own headline, so the move is the
	 * figure the card prints against the day the footnote names. Null when no reading is old enough - the chip is
	 * then greyed. {@code days <= 0} compares against the first reading, as {@link #overDays} does.
	 */
	@Nullable
	public static Change sinceDay(@Nullable final BankHistorySeries series, final LocalDate today, final int days,
		@Nullable final ViewOptions options, final long nowGp)
	{
		Objects.requireNonNull(today, "today");
		final BankHistorySeries s = cut(series, today);
		final BankHistoryPoint from = days <= 0 ? s.first() : s.atOrBefore(today.minusDays(days));
		if (from == null)
		{
			return null;
		}
		return new Change(from.day(), today, from.valueFor(options), nowGp);
	}

	/**
	 * The reading of {@code day} against the reading before it (the day list's change column). Null when that day
	 * has no reading, or when it is the first reading ("first reading" on the row).
	 */
	@Nullable
	public static Change vsPrevious(@Nullable final BankHistorySeries series, @Nullable final LocalDate day,
		@Nullable final ViewOptions options)
	{
		if (series == null || day == null)
		{
			return null;
		}
		final BankHistoryPoint to = series.on(day);
		final BankHistoryPoint from = to == null ? null : series.atOrBefore(day.minusDays(1));
		if (from == null)
		{
			return null;
		}
		return new Change(from.day(), to.day(), from.valueFor(options), to.valueFor(options));
	}

	/**
	 * Every calendar day from {@code max(from, first reading)} to {@code to}, ascending - the ONE place carried days
	 * are derived (contract section 3). A day with a reading is that reading's total; a day without one carries the
	 * last reading before it forward. Readings after {@code to} play no part. Empty when the series is empty or
	 * {@code to} is before the first reading.
	 *
	 * @param from the first day wanted, or null for the first reading's day (the "all" range)
	 * @param to   the last day wanted - today, for the chart and the list
	 */
	public static List<Day> days(@Nullable final BankHistorySeries series, @Nullable final LocalDate from,
		final LocalDate to, @Nullable final ViewOptions options)
	{
		Objects.requireNonNull(to, "to");
		final BankHistoryPoint first = series == null ? null : series.first();
		if (first == null)
		{
			return Collections.emptyList();
		}
		final LocalDate start = from == null || from.isBefore(first.day()) ? first.day() : from;
		if (start.isAfter(to))
		{
			return Collections.emptyList();
		}

		final List<BankHistoryPoint> points = series.points();
		final List<Day> out = new ArrayList<>((int) Math.min(Integer.MAX_VALUE - 8,
			ChronoUnit.DAYS.between(start, to) + 1));
		// The last reading on or before `start` seeds the carry; `next` walks the readings after it in step with the
		// days, so the whole range is one pass however long it is.
		BankHistoryPoint carry = series.atOrBefore(start);
		int next = carry == null ? 0 : points.indexOf(carry) + 1;
		long carriedValue = carry == null ? 0L : carry.valueFor(options);
		for (LocalDate d = start; !d.isAfter(to); d = d.plusDays(1))
		{
			while (next < points.size() && !points.get(next).day().isAfter(d))
			{
				carry = points.get(next++);
				carriedValue = carry.valueFor(options);
			}
			final BankHistoryPoint reading = carry != null && carry.day().equals(d) ? carry : null;
			out.add(new Day(d, carriedValue, reading));
		}
		return Collections.unmodifiableList(out);
	}

	/**
	 * At most about {@code maxPoints} of these days (plan 7.2 item 10): unchanged when there are no more than that;
	 * otherwise buckets of {@code ceil(n / maxPoints)} days, aligned to the LAST day (so the newest bucket is always
	 * whole and ends today, and only the oldest may be short), each drawn as its last READING - or, when every day in
	 * it is carried, as its last day.
	 *
	 * @throws IllegalArgumentException if {@code maxPoints} is below 1
	 */
	public static List<Day> thin(@Nullable final List<Day> days, final int maxPoints)
	{
		if (maxPoints < 1)
		{
			throw new IllegalArgumentException("maxPoints must be at least 1, not " + maxPoints);
		}
		if (days == null || days.isEmpty())
		{
			return Collections.emptyList();
		}
		final int n = days.size();
		if (n <= maxPoints)
		{
			return days;
		}
		final int bucket = (n + maxPoints - 1) / maxPoints;
		final List<Day> out = new ArrayList<>(maxPoints);
		// Walk back from the last day, one bucket at a time, then reverse: the alignment is to the end.
		for (int end = n - 1; end >= 0; end -= bucket)
		{
			final int start = Math.max(0, end - bucket + 1);
			Day pick = days.get(end);
			for (int i = end; i >= start; i--)
			{
				if (!days.get(i).carried())
				{
					pick = days.get(i);
					break;
				}
			}
			out.add(pick);
		}
		Collections.reverse(out);
		return Collections.unmodifiableList(out);
	}

	/**
	 * The day a window of {@code days} first has a reading old enough - {@code first().day() + days} - which is
	 * when a greyed chip stops being grey (amendment 9.6). Null for an empty series.
	 */
	@Nullable
	public static LocalDate fillsOn(@Nullable final BankHistorySeries series, final int days)
	{
		final BankHistoryPoint first = series == null ? null : series.first();
		return first == null ? null : first.day().plusDays(Math.max(0, days));
	}

	/** The series cut to today; a null series reads as {@link BankHistorySeries#EMPTY}. */
	private static BankHistorySeries cut(@Nullable final BankHistorySeries series, final LocalDate today)
	{
		return series == null ? BankHistorySeries.EMPTY : series.upTo(today);
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * One day's reading of the player's net worth (addendum AU; plan 7.5 item 2 and 7.7 items 3-5; phase 0 contract
 * sections 2 and 9.4): the total the Bank value card showed that day, saved IN PARTS so the History line can be
 * drawn under whatever counting switches are on NOW.
 *
 * <p><b>The ten cells.</b> WHERE (in the bank | carried = inventory + worn) times WHAT (tradeable stacks | coins
 * and platinum tokens | untradeables valued as their tradeable PARTS that day | untradeables at their High Alchemy
 * value that day) - eight cells, to which 1.0.9 part 3 added two for the third place a player's worth can be, the
 * Grand Exchange offers: the tradeable stacks in them and the coins committed to or earned by them. The Grand
 * Exchange trades tradeables and holds coins, so it has no parts or alch cell. An untradeable is filed by its ACTUAL
 * source that day, not by whether it has a mapping: a parts stack with one unpriced part ended at its alch value, and
 * so is an alch cell. Every cell is recorded whatever the switches say, so a switch flipped later redraws the whole
 * line instead of showing as a one-day jump. A reading written before the offers were counted holds eight cells, and
 * reads as ten with the two new ones at zero ({@code PriceStore.cells}).
 *
 * <p><b>Two sets of figures.</b> {@code card} is the day as the card priced it (live mids where "Use live prices"
 * priced them live); {@code guide} is the same stacks at guide prices alone. When the two are equal - every day
 * recorded with live prices off, and any day no stack went live - {@code guide} is not stored and
 * {@link #hasGuide()} is false.
 *
 * <p><b>The day is a LOCAL date</b> (plan 7.1 item 2), unlike every other day in this plugin, which are the wiki's
 * UTC days. The caller derives it with {@link BankHistoryMath#dayOf(long, java.time.ZoneId)}; nothing here reads a
 * clock or a zone.
 *
 * <p>Immutable, with value equality. The arrays are copied in and never handed out.
 */
public final class BankHistoryPoint
{
	/** Tradeable stacks in the bank. Counted always. */
	public static final int BANK_TRADEABLE = 0;
	/** Coins and platinum tokens in the bank. Counted with "Include coins and platinum tokens". */
	public static final int BANK_CASH = 1;
	/** Untradeables in the bank valued as their tradeable parts that day. Counted always (addendum AV). */
	public static final int BANK_PARTS = 2;
	/** Untradeables in the bank at their alch value that day. Counted with "Include alch-only untradeables". */
	public static final int BANK_ALCH = 3;
	/** Tradeable stacks carried (inventory + worn). Counted with "Include inventory and worn gear". */
	public static final int CARRIED_TRADEABLE = 4;
	/** Carried coins and platinum tokens. Counted with the inventory switch AND the coins switch. */
	public static final int CARRIED_CASH = 5;
	/** Carried untradeables valued as their parts. Counted with the inventory switch. */
	public static final int CARRIED_PARTS = 6;
	/** Carried untradeables at their alch value. Counted with the inventory switch AND the untradeables switch. */
	public static final int CARRIED_ALCH = 7;
	/**
	 * Tradeable stacks in Grand Exchange offers - unsold in a sell offer, bought and uncollected in a buy offer, at the
	 * item's price that day. Counted with "Include Grand Exchange offers".
	 */
	public static final int GE_TRADEABLE = 8;
	/**
	 * Coins committed to buy offers, or received by sell offers and not yet collected. Counted with the Grand Exchange
	 * switch AND the coins switch.
	 */
	public static final int GE_CASH = 9;
	/** How many cells a reading holds, in {@code card} and in {@code guide}. */
	public static final int CELLS = 10;

	private final LocalDate day;
	private final long readAtMillis;
	private final long bankAtMillis;
	private final long[] card;
	/** Null when the guide figures equal {@link #card} - never an array equal to it (amendment 9.4). */
	@Nullable
	private final long[] guide;

	/**
	 * @param day          the LOCAL date of the reading
	 * @param readAtMillis when the reading was taken, epoch millis - the tie-breaker when two readings name a day
	 * @param bankAtMillis when the bank it priced was captured, epoch millis
	 * @param card         the {@value #CELLS} cells as the card priced them; copied, a negative cell reads as 0
	 * @param guide        the same cells at guide prices alone, or null when they equal {@code card}; copied, and an
	 *                     array equal to {@code card} is stored as null so the two spellings of one reading are equal
	 * @throws NullPointerException     if {@code day} or {@code card} is null
	 * @throws IllegalArgumentException if {@code card} or {@code guide} does not hold exactly {@value #CELLS} cells
	 */
	public BankHistoryPoint(final LocalDate day, final long readAtMillis, final long bankAtMillis, final long[] card,
		@Nullable final long[] guide)
	{
		this.day = Objects.requireNonNull(day, "day");
		this.readAtMillis = readAtMillis;
		this.bankAtMillis = bankAtMillis;
		this.card = cells(Objects.requireNonNull(card, "card"), "card");
		final long[] g = guide == null ? null : cells(guide, "guide");
		this.guide = g == null || Arrays.equals(g, this.card) ? null : g;
	}

	/** A copy of exactly {@value #CELLS} cells, each at least 0 - there is no such thing as a negative holding. */
	private static long[] cells(final long[] values, final String name)
	{
		if (values.length != CELLS)
		{
			throw new IllegalArgumentException(name + " must hold " + CELLS + " cells, not " + values.length);
		}
		final long[] copy = new long[CELLS];
		for (int i = 0; i < CELLS; i++)
		{
			copy[i] = Math.max(0L, values[i]);
		}
		return copy;
	}

	/** The LOCAL date this reading is of. */
	public LocalDate day()
	{
		return day;
	}

	/** When the reading was taken, epoch millis. */
	public long readAtMillis()
	{
		return readAtMillis;
	}

	/** When the bank it priced was captured, epoch millis. */
	public long bankAtMillis()
	{
		return bankAtMillis;
	}

	/**
	 * One cell as the card priced it that day.
	 *
	 * @throws ArrayIndexOutOfBoundsException if {@code cell} is not one of the ten
	 */
	public long card(final int cell)
	{
		return card[cell];
	}

	/**
	 * One cell at guide prices alone; equal to {@link #card(int)} when no separate figure was stored.
	 *
	 * @throws ArrayIndexOutOfBoundsException if {@code cell} is not one of the ten
	 */
	public long guide(final int cell)
	{
		return guide == null ? card[cell] : guide[cell];
	}

	/** False when the guide figures equal the card's and are not stored. */
	public boolean hasGuide()
	{
		return guide != null;
	}

	/**
	 * The reading's total under these switches - the ONE rule every History figure uses (contract section 2), so
	 * the History figure always equals the Bank value card. The cells counted:
	 * <ul>
	 * <li>bank tradeable and bank parts - always;</li>
	 * <li>bank cash - {@code countCash}; bank alch - {@code countUntradeables};</li>
	 * <li>carried tradeable and carried parts - {@code countInventory};</li>
	 * <li>carried cash - {@code countInventory && countCash}; carried alch -
	 * {@code countInventory && countUntradeables};</li>
	 * <li>Grand Exchange tradeable - {@code countGrandExchange}; Grand Exchange cash -
	 * {@code countGrandExchange && countCash} (1.0.9 part 3).</li>
	 * </ul>
	 * Summed from {@code card} with {@code livePrices} on and from {@code guide} with it off, with the clamped
	 * addition {@link PortfolioSummary} uses ({@link PortfolioMath#clampedAdd}).
	 *
	 * @param options the switches; null reads as {@link ViewOptions#DEFAULT} (amendment 9.2)
	 */
	public long valueFor(@Nullable final ViewOptions options)
	{
		final ViewOptions o = options == null ? ViewOptions.DEFAULT : options;
		final long[] figures = o.livePrices() || guide == null ? card : guide;
		final boolean cash = o.countCash();
		final boolean alch = o.countUntradeables();
		final boolean carried = o.countInventory();
		final boolean offers = o.countGrandExchange();

		long sum = figures[BANK_TRADEABLE];
		sum = PortfolioMath.clampedAdd(sum, figures[BANK_PARTS]);
		if (cash)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[BANK_CASH]);
		}
		if (alch)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[BANK_ALCH]);
		}
		if (carried)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_TRADEABLE]);
			sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_PARTS]);
			if (cash)
			{
				sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_CASH]);
			}
			if (alch)
			{
				sum = PortfolioMath.clampedAdd(sum, figures[CARRIED_ALCH]);
			}
		}
		if (offers)
		{
			sum = PortfolioMath.clampedAdd(sum, figures[GE_TRADEABLE]);
			if (cash)
			{
				sum = PortfolioMath.clampedAdd(sum, figures[GE_CASH]);
			}
		}
		return sum;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BankHistoryPoint))
		{
			return false;
		}
		final BankHistoryPoint other = (BankHistoryPoint) o;
		return day.equals(other.day)
			&& readAtMillis == other.readAtMillis
			&& bankAtMillis == other.bankAtMillis
			&& Arrays.equals(card, other.card)
			&& Arrays.equals(guide, other.guide);
	}

	@Override
	public int hashCode()
	{
		int h = Objects.hash(day, readAtMillis, bankAtMillis);
		h = 31 * h + Arrays.hashCode(card);
		return 31 * h + Arrays.hashCode(guide);
	}

	@Override
	public String toString()
	{
		return "BankHistoryPoint{day=" + day + ", readAtMillis=" + readAtMillis + ", bankAtMillis=" + bankAtMillis
			+ ", card=" + Arrays.toString(card) + (guide == null ? "" : ", guide=" + Arrays.toString(guide)) + '}';
	}
}

package com.bankpricemovement;

import javax.annotation.Nullable;

/**
 * The History chart's four ranges (addendum AU, plan 7.2 items 6 and 10; phase 0 contract section 3): the last 7,
 * 30 or 90 calendar days, or every day since the first reading.
 *
 * <p>A range covers the calendar days {@code [today - days(), today]} inclusive, and
 * {@code [first reading, today]} for {@link #ALL} (contract amendment 9.5). The chart's own range chips move only
 * the chart - unsaved, never sent to the service - and the card's window chip overrules them through
 * {@link #forWindow(MovementWindow)}.
 */
public enum BankHistoryRange
{
	D7("7d", 7),
	D30("30d", 30),
	D90("90d", 90),
	/** Every day since the first reading; {@link #days()} is 0. */
	ALL("all", 0);

	private final String label;
	private final int days;

	BankHistoryRange(final String label, final int days)
	{
		this.label = label;
		this.days = days;
	}

	/** How many calendar days back the range reaches: 7, 30, 90, or 0 for {@link #ALL}. */
	public int days()
	{
		return days;
	}

	/** The chip text: "7d", "30d", "90d", "all". */
	public String label()
	{
		return label;
	}

	/**
	 * The range the card's window chip selects (plan 7.2 item 6): 1d and 7d both show a week - one day is not a
	 * line - 30d and 90d show themselves, and 180d shows everything, because a history that reaches half a year is
	 * the whole of it for a long while. A null window reads as {@link MovementWindow#DEFAULT}.
	 */
	public static BankHistoryRange forWindow(@Nullable final MovementWindow window)
	{
		final MovementWindow w = window == null ? MovementWindow.DEFAULT : window;
		switch (w)
		{
			case D30:
				return D30;
			case D90:
				return D90;
			case D180:
				return ALL;
			case D1:
			case D7:
			default:
				return D7;
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.TreeMap;
import javax.annotation.Nullable;

/**
 * The readings of one account on one profile (addendum AU; phase 0 contract sections 1, 3 and 9.4): immutable,
 * sorted by day, at most ONE reading per day. Days with no reading are not here - they are derived when drawing,
 * by {@link BankHistoryMath#days} and nowhere else.
 *
 * <p><b>One reading per day.</b> Two readings that name one day are resolved by their {@code readAtMillis}: the
 * later one wins, because "the last one of the day stays" (plan 7.5 item 1). On a tie the one given later wins -
 * the element later in {@link #of}'s collection. {@link #with} replaces its day's reading unconditionally.
 *
 * <p>Value equality over {@link #points()}, so a series re-read from disk equals the one in memory when they hold
 * the same readings - which is how the store decides that a write would change nothing, and how the History view
 * decides that there is nothing to redraw.
 *
 * <p><b>The fresh start</b> (1.0.9 part 5). Readings recorded before 1.0.9 did not count the Grand Exchange offers,
 * so for a player who keeps much of their bank on offer those days read low. {@link #freshFrom()} names the first day
 * recorded by 1.0.9 or later: the days before it are the LEGACY days, and {@link #fromFresh()} is the series without
 * them. It is part of the value - two series holding the same readings but cut at different days are not equal - and
 * every copy carries it, so the store and the panel never have to remember it on the side. A series built by
 * {@link #of} has none: every day counts.
 *
 * <p><b>The placeholder judgement</b> (1.1.1 part B). Until 1.1.1 a bank placeholder that arrived with a quantity was
 * counted as one of its item, so every reading such a player recorded reads HIGH. The first reading taken from a fresh
 * bank read after the update judges the series, once: {@link #placeholdersChecked()} is the day it was judged, and when
 * that read dropped placeholders with a quantity and the series held an earlier day, the fresh start moves up to that day
 * with {@link #freshWhy()} {@value #WHY_PLACEHOLDERS} ({@link #judged}). Both are part of the value and carried by every
 * copy, as {@link #freshFrom()} is. An EMPTY series carries none of the three: it has nothing to hide or judge.
 */
public final class BankHistorySeries
{
	/** No readings at all. */
	public static final BankHistorySeries EMPTY = new BankHistorySeries(Collections.<BankHistoryPoint>emptyList(), null,
		null, null);

	/**
	 * The {@link #freshWhy()} of a fresh start made because the days before it counted bank placeholders as items (1.1.1
	 * part B). A series with no reason stands for 1.0.9 part 5's: the days before it did not count the Grand Exchange
	 * offers.
	 */
	public static final String WHY_PLACEHOLDERS = "placeholders";

	/** Ascending by day, one per day, unmodifiable. */
	private final List<BankHistoryPoint> points;

	/** The first day recorded by 1.0.9 or later; null = no legacy days; {@link LocalDate#MAX} = every day is one. */
	@Nullable
	private final LocalDate freshFrom;

	/** 1.1.1 part B: the day this series was judged for counted placeholders; null = not judged yet. */
	@Nullable
	private final LocalDate placeholdersChecked;

	/** 1.1.1 part B: why the days before {@link #freshFrom} are hidden; null = 1.0.9 part 5's reason. */
	@Nullable
	private final String freshWhy;

	private BankHistorySeries(final List<BankHistoryPoint> sorted, @Nullable final LocalDate freshFrom,
		@Nullable final LocalDate placeholdersChecked, @Nullable final String freshWhy)
	{
		this.points = sorted;
		this.freshFrom = freshFrom;
		this.placeholdersChecked = placeholdersChecked;
		this.freshWhy = freshWhy;
	}

	/**
	 * The series of these readings: sorted by day, one per day - the higher {@code readAtMillis} wins, and on a tie
	 * the one later in the collection. Null elements are skipped; a null or empty collection is {@link #EMPTY}.
	 */
	public static BankHistorySeries of(@Nullable final Collection<BankHistoryPoint> points)
	{
		if (points == null || points.isEmpty())
		{
			return EMPTY;
		}
		final TreeMap<LocalDate, BankHistoryPoint> byDay = new TreeMap<>();
		for (final BankHistoryPoint point : points)
		{
			if (point != null)
			{
				byDay.merge(point.day(), point, BankHistorySeries::later);
			}
		}
		return fromMap(byDay, null, null, null);
	}

	/** Of two readings of one day, the one taken later; {@code b} on a tie. */
	private static BankHistoryPoint later(final BankHistoryPoint a, final BankHistoryPoint b)
	{
		return a.readAtMillis() > b.readAtMillis() ? a : b;
	}

	private static BankHistorySeries fromMap(final TreeMap<LocalDate, BankHistoryPoint> byDay,
		@Nullable final LocalDate freshFrom, @Nullable final LocalDate placeholdersChecked, @Nullable final String freshWhy)
	{
		if (byDay.isEmpty())
		{
			return EMPTY;
		}
		return new BankHistorySeries(Collections.unmodifiableList(new ArrayList<>(byDay.values())), freshFrom,
			placeholdersChecked, freshWhy);
	}

	private TreeMap<LocalDate, BankHistoryPoint> toMap()
	{
		final TreeMap<LocalDate, BankHistoryPoint> byDay = new TreeMap<>();
		for (final BankHistoryPoint point : points)
		{
			byDay.put(point.day(), point);
		}
		return byDay;
	}

	/**
	 * This series with {@code point} as its day's reading, replacing whatever was there whatever its time - the
	 * reading just taken is the last one of its day (plan 7.5 item 1). A null point answers this series.
	 */
	public BankHistorySeries with(@Nullable final BankHistoryPoint point)
	{
		if (point == null)
		{
			return this;
		}
		final TreeMap<LocalDate, BankHistoryPoint> byDay = toMap();
		byDay.put(point.day(), point);
		return fromMap(byDay, freshFrom, placeholdersChecked, freshWhy);
	}

	/**
	 * This series with {@code freshFrom} as its fresh start (1.0.9 part 5): the store's way to say "the days before
	 * this one were recorded before 1.0.9". Null clears it; {@link LocalDate#MAX} says every day is a legacy day. An
	 * EMPTY series has nothing to hide and answers itself.
	 */
	public BankHistorySeries withFreshFrom(@Nullable final LocalDate freshFrom)
	{
		if (points.isEmpty() || Objects.equals(this.freshFrom, freshFrom))
		{
			return this;
		}
		return new BankHistorySeries(points, freshFrom, placeholdersChecked, freshWhy);
	}

	/**
	 * This series with {@code day} as the day it was judged for counted placeholders (1.1.1 part B): the store's way to
	 * put back what a file says. Null clears it. An EMPTY series answers itself.
	 */
	public BankHistorySeries withPlaceholdersChecked(@Nullable final LocalDate day)
	{
		if (points.isEmpty() || Objects.equals(placeholdersChecked, day))
		{
			return this;
		}
		return new BankHistorySeries(points, freshFrom, day, freshWhy);
	}

	/**
	 * This series with {@code why} as the reason for its fresh start (1.1.1 part B), as a file says it. Null is 1.0.9 part
	 * 5's reason. An EMPTY series answers itself.
	 */
	public BankHistorySeries withFreshWhy(@Nullable final String why)
	{
		if (points.isEmpty() || Objects.equals(freshWhy, why))
		{
			return this;
		}
		return new BankHistorySeries(points, freshFrom, placeholdersChecked, why);
	}

	/**
	 * This series judged for counted placeholders (1.1.1 part B) - the ONE rule, which the service applies to the series
	 * in memory and the store to the file it re-reads, so the two cannot come to disagree. A series already judged answers
	 * itself whatever {@code check} says: the judgement is made once per file. So do a null check (a reading that was not
	 * taken from a fresh bank read) and an EMPTY series.
	 *
	 * <p>Otherwise the series is marked judged as of {@link PlaceholderCheck#day()}; and when the check is a restart, the
	 * fresh start moves up to that day - never back: a later {@link #freshFrom()} already standing stays - with
	 * {@link #WHY_PLACEHOLDERS} as its reason.
	 */
	public BankHistorySeries judged(@Nullable final PlaceholderCheck check)
	{
		if (check == null || points.isEmpty() || placeholdersChecked != null)
		{
			return this;
		}
		if (!check.restart())
		{
			return new BankHistorySeries(points, freshFrom, check.day(), freshWhy);
		}
		final LocalDate from = freshFrom != null && freshFrom.isAfter(check.day()) ? freshFrom : check.day();
		return new BankHistorySeries(points, from, check.day(), WHY_PLACEHOLDERS);
	}

	/**
	 * The judgement this series carries (1.1.1 part B), or null while it has none: the day it was judged, and whether that
	 * judgement restarted it - which is what a {@link #freshWhy()} of {@link #WHY_PLACEHOLDERS} records. What the service
	 * hands the store with every write, so a file not yet judged gets the decision the series in memory already holds.
	 */
	@Nullable
	public PlaceholderCheck placeholderCheck()
	{
		return placeholdersChecked == null ? null
			: new PlaceholderCheck(placeholdersChecked, WHY_PLACEHOLDERS.equals(freshWhy));
	}

	/**
	 * This series without the readings dated after {@code today} - a clock that was wrong when they were taken
	 * (plan 7.1 item 7). They are not drawn, and the store drops them at its next write.
	 */
	public BankHistorySeries upTo(final LocalDate today)
	{
		Objects.requireNonNull(today, "today");
		final BankHistoryPoint last = last();
		if (last == null || !last.day().isAfter(today))
		{
			return this;
		}
		final List<BankHistoryPoint> kept = new ArrayList<>(points.size());
		for (final BankHistoryPoint point : points)
		{
			if (!point.day().isAfter(today))
			{
				kept.add(point);
			}
		}
		return kept.isEmpty() ? EMPTY
			: new BankHistorySeries(Collections.unmodifiableList(kept), freshFrom, placeholdersChecked, freshWhy);
	}

	/**
	 * The first day recorded by 1.0.9 or later (1.0.9 part 5), or null when this series has no legacy days: every new
	 * install, and every file that was never written by an older build. {@link LocalDate#MAX} means every day here
	 * is a legacy day - a file migrated from an older schema that 1.0.9 has not recorded into yet. Otherwise the days
	 * BEFORE it are the legacy ones.
	 */
	@Nullable
	public LocalDate freshFrom()
	{
		return freshFrom;
	}

	/**
	 * This series cut to the days recorded by 1.0.9 or later - the days at or after {@link #freshFrom()}: the whole
	 * series when there is none, {@link #EMPTY} when every day is a legacy day. The cut series has no legacy days of
	 * its own, so its {@link #freshFrom()} is null; it keeps the placeholder judgement and the reason (1.1.1 part B). The
	 * panel hands the History view and the card THIS unless the reader has asked to see the old days.
	 */
	public BankHistorySeries fromFresh()
	{
		if (freshFrom == null)
		{
			return this;
		}
		if (LocalDate.MAX.equals(freshFrom))
		{
			return EMPTY;
		}
		final List<BankHistoryPoint> kept = new ArrayList<>(points.size());
		for (final BankHistoryPoint point : points)
		{
			if (!point.day().isBefore(freshFrom))
			{
				kept.add(point);
			}
		}
		return kept.isEmpty() ? EMPTY
			: new BankHistorySeries(Collections.unmodifiableList(kept), null, placeholdersChecked, freshWhy);
	}

	/**
	 * Whether any reading here was recorded before 1.0.9 (1.0.9 part 5): a {@link #freshFrom()} is named and at least
	 * one day lies before it - {@link LocalDate#MAX} counts as long as the series is not empty. The settings menu
	 * carries its "Include days before v1.0.9" item only while this is true.
	 */
	public boolean hasLegacyDays()
	{
		if (freshFrom == null || points.isEmpty())
		{
			return false;
		}
		return points.get(0).day().isBefore(freshFrom);
	}

	/**
	 * The day this series was judged for bank placeholders counted as items (1.1.1 part B), or null while it has not been:
	 * every series an older build wrote, and every series no fresh bank read has recorded into since the update.
	 */
	@Nullable
	public LocalDate placeholdersChecked()
	{
		return placeholdersChecked;
	}

	/**
	 * Why the days before {@link #freshFrom()} are hidden (1.1.1 part B): {@link #WHY_PLACEHOLDERS} when they counted bank
	 * placeholders as items, or null for 1.0.9 part 5's reason - they did not count the Grand Exchange offers. A reason
	 * this build does not know is kept, and read as null's.
	 */
	@Nullable
	public String freshWhy()
	{
		return freshWhy;
	}

	/** Every reading, ascending by day; unmodifiable. */
	public List<BankHistoryPoint> points()
	{
		return points;
	}

	public boolean isEmpty()
	{
		return points.isEmpty();
	}

	/** How many readings - days WITH a reading; carried days are not counted. */
	public int size()
	{
		return points.size();
	}

	/** The earliest reading, or null when there is none. */
	@Nullable
	public BankHistoryPoint first()
	{
		return points.isEmpty() ? null : points.get(0);
	}

	/** The latest reading, or null when there is none. */
	@Nullable
	public BankHistoryPoint last()
	{
		return points.isEmpty() ? null : points.get(points.size() - 1);
	}

	/** The reading OF that day, or null when that day has none (or {@code day} is null). */
	@Nullable
	public BankHistoryPoint on(@Nullable final LocalDate day)
	{
		final int i = indexAtOrBefore(day);
		return i >= 0 && points.get(i).day().equals(day) ? points.get(i) : null;
	}

	/** The last reading on or before that day, or null when there is none (or {@code day} is null). */
	@Nullable
	public BankHistoryPoint atOrBefore(@Nullable final LocalDate day)
	{
		final int i = indexAtOrBefore(day);
		return i >= 0 ? points.get(i) : null;
	}

	/** The index of the last reading on or before {@code day}, or -1: a binary search over the sorted days. */
	private int indexAtOrBefore(@Nullable final LocalDate day)
	{
		if (day == null)
		{
			return -1;
		}
		int lo = 0;
		int hi = points.size() - 1;
		int found = -1;
		while (lo <= hi)
		{
			final int mid = (lo + hi) >>> 1;
			if (points.get(mid).day().isAfter(day))
			{
				hi = mid - 1;
			}
			else
			{
				found = mid;
				lo = mid + 1;
			}
		}
		return found;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof BankHistorySeries))
		{
			return false;
		}
		final BankHistorySeries that = (BankHistorySeries) o;
		return points.equals(that.points) && Objects.equals(freshFrom, that.freshFrom)
			&& Objects.equals(placeholdersChecked, that.placeholdersChecked) && Objects.equals(freshWhy, that.freshWhy);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(points, freshFrom, placeholdersChecked, freshWhy);
	}

	@Override
	public String toString()
	{
		final BankHistoryPoint first = first();
		final BankHistoryPoint last = last();
		return "BankHistorySeries{readings=" + points.size()
			+ (first == null ? "" : ", first=" + first.day() + ", last=" + last.day())
			+ (freshFrom == null ? "" : ", freshFrom=" + (LocalDate.MAX.equals(freshFrom) ? "all" : freshFrom))
			+ (freshWhy == null ? "" : ", freshWhy=" + freshWhy)
			+ (placeholdersChecked == null ? "" : ", placeholdersChecked=" + placeholdersChecked) + '}';
	}

	/**
	 * One placeholder judgement (1.1.1 part B): the LOCAL day a reading from a fresh bank read judged a series, and
	 * whether that read found placeholders with a quantity while the series held an earlier day - a restart. Made by the
	 * service in its fold, carried to the store with the write, applied at both sites by {@link #judged}. Immutable.
	 */
	public static final class PlaceholderCheck
	{
		private final LocalDate day;
		private final boolean restart;

		public PlaceholderCheck(final LocalDate day, final boolean restart)
		{
			this.day = Objects.requireNonNull(day, "day");
			this.restart = restart;
		}

		/** The day of the judging reading. */
		public LocalDate day()
		{
			return day;
		}

		/** Whether the days before {@link #day()} are hidden because they counted placeholders. */
		public boolean restart()
		{
			return restart;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof PlaceholderCheck))
			{
				return false;
			}
			final PlaceholderCheck that = (PlaceholderCheck) o;
			return restart == that.restart && day.equals(that.day);
		}

		@Override
		public int hashCode()
		{
			return 31 * day.hashCode() + (restart ? 1 : 0);
		}

		@Override
		public String toString()
		{
			return "PlaceholderCheck{" + day + (restart ? ", restart" : "") + '}';
		}
	}
}

