	/**
	 * The gutter the Items list had the last time its card was showing (1.1.1 part S), written only by
	 * {@link #syncGutter} while {@link #CARD_LIST} shows. The cards that stand in for the list - the empty one, the
	 * login and no-bank ones - hand the header this, so a search or a band that leaves nothing never reads a bar off a
	 * pane that is not on screen, and a trip to History does not leave History's gutter behind.
	 */
	private int itemsGutter;
	/** Set while {@link #syncHeader} restructures the header, so a focus lost to that cannot apply a bound. */
	private boolean syncingHeader;
	/** Whether the sidebar is showing this panel: false between {@link #onDeactivate} and {@link #onActivate}. */
	private boolean active = true;
	/** The publish that arrived while the sidebar was elsewhere, replayed on the next {@link #onActivate}. */
	private boolean pendingPublish;
	@Nullable
	private List<MovementRow> pendingRows;
	@Nullable
	private Status pendingStatus;
	/** Which of the Refresh link's three beats is standing right now (P2); see {@link RefreshPhase}. */
	private RefreshPhase refreshPhase = RefreshPhase.IDLE;
	/** The one-shot timer that ends the beat: it is restarted at the phase's own delay, never two timers. */
	@Nullable
	private Timer refreshTimer;

	// ---- the bank hold (addendum AS; EDT, mirrored from the plugin by setBankHold)
	/**
	 * Whether the plugin says the bank interface is open. Mirrored and never decided here: only the client thread can
	 * see the widget, and the panel acting on a guess of its own would be a second, disagreeing answer.
	 */
	private boolean bankOpen;
	/** Whether the plugin says the bank on screen is out of date and a read is owed - what the glow announces. */
	private boolean bankPending;
	/** The plugin's two counters, kept only so {@link #describe()} can hand a live run the numbers to prove it. */
	private int bankHeldEvents;
	private int bankReads;
	/**
	 * The plugin's open-bank Refresh: a local re-read of the bank with no download and no cooldown of its own (section
	 * 2.3) - the first half of a click on the link while the bank is open, the price re-check being the second (AS8) -
	 * or null while there is none. Volatile because the plugin hands it over from startUp and takes it back in
	 * shutDown, and the only reader is the link's click on the EDT - a hook written on one thread must be the hook read
	 * on the other.
	 */
	@Nullable
	private volatile Runnable bankRefresh;
	/**
	 * Set by the reader's own act while the bank is open ({@link #liftBankHold}): publishes are built again until the
	 * plugin reports a NEW change or the visit ends. The hold is for the bank's churn, not for the reader - a column
	 * picked while banking must re-order the list, and the Refresh link's own answer must be drawn.
	 */
	private boolean bankHoldLifted;
	/**
	 * Set by a click on the link ({@link #refreshNow}), which answers the glow, and cleared by the plugin's next word
	 * ({@link #setBankHold}): so the ring goes out on the click itself rather than when the read is reported.
	 */
	private boolean glowDismissed;
	/** The ring's frames ({@link #fireGlow}); null until the glow first runs, and stopped whenever it is unwanted. */
	@Nullable
	private Timer glowTimer;
	/** When the lit ring's breath began, by {@link #glowClock}: stamped as it lights, so every light starts dark. */
	private long glowStartedAtMillis;
	/**
	 * What the breath is timed by ({@link #glowLevel}): milliseconds off {@link System#nanoTime}, a clock that only
	 * moves forward, so a change of the computer's time cannot jump the ring mid-breath. A field so the tests drive a
	 * whole breath without waiting six seconds for it ({@link #setGlowClock}).
	 */
	private LongSupplier glowClock = BankPriceMovementPanel::monotonicMillis;

	/** What the rows on screen were built from; see {@link ListContext}. */
	private ListContext list;
	private int shown;
	private int rebuilds;
	private String card = CARD_LOGIN;
	private boolean foldOpen;
	/**
	 * 1.0.9 part 5: whether the History tab shows the days recorded before 1.0.9. Off unless the reader turned it on;
	 * {@link #visibleHistory} is the one place that reads it.
	 */
	private boolean includeLegacy;
	/**
	 * 1.1.0 part B: the colours a rise and a fall are drawn in - what the settings menu's swatches show, never null; the
	 * built-in green and red ({@link Widgets#MOVE_UP_DEFAULT}, {@link Widgets#MOVE_DOWN_TEXT}) until the reader chooses
	 * others. They are what the panel believes the palette to be: {@link #applyMoveColours} writes them and hands the
	 * same pair to {@link Widgets#setMoveColours}, which every painter reads through {@link Widgets#move}.
	 */
	private Color upColour = Widgets.MOVE_UP_DEFAULT;
	private Color downColour = Widgets.MOVE_DOWN_TEXT;
	/**
	 * 1.1.0 part J: the pair the colour presets' Slot 1 holds - what its row's two squares show, never null; Classic's pair
	 * until the reader saves their own with "Save current colours to Slot 1" ({@link #pressSaveSlot}). Only that press, the
	 * plugin's {@code ConfigChanged} for the slot's keys ({@link #applySlotColours}) and the seed from the prefs change them;
	 * "Reset to default" leaves them alone.
	 */
	private Color slotUp = Widgets.MOVE_UP_DEFAULT;
	private Color slotDown = Widgets.MOVE_DOWN_TEXT;
	/**
	 * Set when the colours changed while a tab was NOT showing, so that tab's heavy parts - the item rows (up to a page of
	 * 250 cells) and the history view's day list - are drawn once, when the reader switches to it, rather than at every
	 * move of the colour picker: the tab on screen follows the picker live (B-4b), the other one is redrawn on arrival.
	 */
	private boolean itemsStale;
	private boolean historyStale;
	/**
	 * 1.1.0 part C: whether the Net Worth History chart is drawn in ONE colour, and which - what the menu's "Single chart
	 * colour" row shows (its tick, and its swatch while ticked), never null for the colour. On and the logo gold
	 * ({@link Widgets#CHART_COLOUR_DEFAULT}) until the reader chooses otherwise (on since part D). The chart itself holds
	 * the colour it is to be drawn in ({@link BankHistoryView#setChartColour}); these are what the panel believes it was
	 * told.
	 */
	private boolean singleChartColour = true;
	private Color chartColour = Widgets.CHART_COLOUR_DEFAULT;
	/**
	 * 1.1.0 part E: whether every gp amount and item quantity the sidebar draws is hidden behind its mask
	 * ({@link AmountMask}) - what the eye on the hero card shows and toggles. Off unless the reader shut the eye. The card
	 * reads it as it renders, the rows are built with it, and the History view is handed it ({@link #applyHideAmounts});
	 * never the service, which knows nothing of it.
	 */
	private boolean hideAmounts;
	/** The colour picker the settings menu's colour rows open, or null for none; set by the plugin (1.1.0 part B). */
	@Nullable
	private ColourPicker colourPicker;
	/** The question {@link #pressLegacy(boolean)} asks; never null. */
	private final LegacyPrompt legacyPrompt;
	/** Set while the question is open, so a second press (a script's) cannot open a second dialog on top of it. */
	private boolean askingLegacy;
	/**
	 * 1.1.1 part B: the service's count of placeholder restarts the panel has already answered
	 * ({@link Status#placeholderRestarts()}) - each new one turns the days switch off once.
	 */
	private int placeholderRestartsSeen;
	/** Which of the two views is showing (addendum AU); never null. */
	private SidebarView view = SidebarView.ITEMS;
	/** Set while {@link #applyFilter} repaints the widgets, so the change is not saved a second time. */
	private boolean updating;
	private volatile boolean stopped;

	public BankPriceMovementPanel(ItemManager itemManager, PriceService service, Prefs prefs)
	{
		this(itemManager, service, prefs, LinkBrowser::browse);
	}

	/** @param browser what the brand marks hand their URL to; the tests record, the client browses */
	BankPriceMovementPanel(ItemManager itemManager, PriceService service, Prefs prefs, Consumer<String> browser)
	{
		this(itemManager, service, prefs, browser, null);
	}

	/**
	 * @param browser what the brand marks hand their URL to; the tests record, the client browses
	 * @param prompt  what the History tab's "Include days before v1.0.9" asks when it is turned on (1.0.9 part 5); the
	 *                tests answer it, the client (null) shows {@link LegacyDialog} over this panel's window
	 */
	BankPriceMovementPanel(ItemManager itemManager, PriceService service, Prefs prefs, Consumer<String> browser,
		@Nullable LegacyPrompt prompt)
	{
		super(false);
		this.itemManager = Objects.requireNonNull(itemManager, "itemManager");
		this.service = Objects.requireNonNull(service, "service");
		this.prefs = Objects.requireNonNull(prefs, "prefs");
		this.legacyPrompt = prompt != null ? prompt
			: question -> LegacyDialog.ask(SwingUtilities.getWindowAncestor(this), legacyText(), question);
		// The panel's own close of the settings menu is the hook a pressed header mark ends with; closeGearMenu reads the
		// menu lazily, so handing it over before the menu exists is fine.
		this.support = new SupportLinks(VERSION_NAME_TEXT, Version.CURRENT, GITHUB_URL, browser, this::closeGearMenu);

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final RowFilter loaded = prefs.load();
		filter = loaded == null ? RowFilter.DEFAULT : loaded;
		// Nothing is on screen yet, so the FIRST publish is the same list restated - and a list at the top with no
		// page open stays there whichever branch it takes.
		list = new ListContext(MovementWindow.DEFAULT, null, 0L, filter);
		final HeroVisibility savedHero = prefs.loadHero();
		heroVisibility = savedHero == null ? HeroVisibility.ALL : savedHero;
		final ViewOptions savedOptions = prefs.loadOptions();
		options = savedOptions == null ? ViewOptions.DEFAULT : savedOptions;
		// Z1: before buildHeader, because the gear menu's boxes and the fold's chips are both built from them.
		final BandPresets savedPresets = prefs.loadPresets();
		presets = savedPresets == null ? BandPresets.DEFAULT : savedPresets;
		// AA1: before renderAll below, which is what puts the fold into the header - so the sidebar is never
		// painted once without it and then again with it. Null is "nothing stored", and that reads OPEN.
		final Boolean savedFold = prefs.loadFoldOpen();
		foldOpen = savedFold == null || savedFold;
		// AU: the sidebar opens on the tab the player chose in the settings menu (the user, 2026-09-29), Items unless
		// it says otherwise; before renderAll below, so the header is never laid out in one tab and then the other.
		// The toggle writes nothing, so this is the ONLY thing that reads the choice.
		final SidebarView savedStartTab = prefs.loadStartTab();
		startTab = savedStartTab == null ? SidebarView.ITEMS : savedStartTab;
		view = startTab;
		// 1.0.9 part 5: before buildHeader and renderAll, so the first publish is drawn once, in the cut the reader
		// chose. Null is "nothing stored", which is the days before 1.0.9 hidden.
		final Boolean savedLegacy = prefs.loadIncludeLegacy();
		includeLegacy = savedLegacy != null && savedLegacy;
		// 1.1.0 part B: before buildHeader, whose menu rows paint a swatch of each. Null is "nothing stored", the built-in
		// green and red. Only the swatches are seeded here: the palette every painter reads is Widgets' own, which the
		// plugin sets from the same config before it builds this panel (a panel with no plugin behind it draws the defaults).
		upColour = colourOrDefault(prefs.loadUpColour(), Widgets.MOVE_UP_DEFAULT);
		downColour = colourOrDefault(prefs.loadDownColour(), Widgets.MOVE_DOWN_TEXT);
		// 1.1.0 part J, for the same reason: Slot 1's two squares and the ticks are built from the colours and the slot.
		slotUp = colourOrDefault(prefs.loadSlotUpColour(), Widgets.MOVE_UP_DEFAULT);
		slotDown = colourOrDefault(prefs.loadSlotDownColour(), Widgets.MOVE_DOWN_TEXT);
		// 1.1.0 part C, for the same reason: the menu's "Single chart colour" row is built from them. The chart (built
		// below, after the header) is handed the colour once it exists. Null is "nothing stored": on, and the gold (part D).
		final Boolean savedSingle = prefs.loadSingleChartColour();
		singleChartColour = savedSingle == null || savedSingle;
		chartColour = colourOrDefault(prefs.loadChartColour(), Widgets.CHART_COLOUR_DEFAULT);
		// 1.1.0 part E, before buildHeader (whose card builds the eye) and renderAll (which draws the card in the mask) so
		// the first paint is already what the reader left. Null is "nothing stored": the amounts shown.
		final Boolean savedHide = prefs.loadHideAmounts();
		hideAmounts = savedHide != null && savedHide;
		// 1.1.0 part G, before buildHeader (whose search row builds the List options menu with its tick). Null is "nothing
		// stored": the alch rows left out of the list.
		final Boolean savedAlch = prefs.loadShowAlchRows();
		showAlchRows = savedAlch != null && savedAlch;

		// The two gp fields: applied on Enter and on focus lost; a text that does not parse turns the field red
		// and changes nothing.
		minField = boundField(true);
		maxField = boundField(false);
		// 1.0.9 part 4: the search box, before buildHeader below for the reason the two fields are - the header's rows
		// are built from it.
		searchField = searchBox();
		// The sidebar's whole content sits in one JLayer, which hears the presses inside it and nothing else
		// (PressWatcher): a press anywhere but on the box that owns the focus hands the focus to the game.
		final JPanel content = new JPanel(new BorderLayout());
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(new JLayer<>(content, new PressWatcher()), BorderLayout.CENTER);

		header = Widgets.column(0);
		header.setBorder(new EmptyBorder(MARGIN, MARGIN, GAP, MARGIN));
		content.add(header, BorderLayout.NORTH);
		buildHeader();

		// The cards. Each message is a PluginErrorPanel inside its own holder: the holder is what CardLayout
		// shows and hides, so PluginErrorPanel.setContent (which calls setVisible(true), :73) can rewrite the
		// EMPTY card's description later without un-hiding it.
		loginGearLabel = settingsGear();
		loginCard = messageCard(LOGIN_TEXT, "Your last bank is remembered once you have opened it",
			support.supportPair(loginGearLabel));
		// The capture is driven by ItemContainerChanged on the bank container, which the server sends when the
		// bank interface OPENS and again on every deposit and withdrawal (ItemContainerChanged.java:30-38) - so
		// the list fills while the bank is on screen, and the old wording described something the plugin does not
		// do. The sidebar sits outside the game canvas, so the reader watches it happen.
		noBankGearLabel = settingsGear();
		noBankCard = messageCard(NO_BANK_TEXT, "The list fills as soon as you open your bank",
			support.supportPair(noBankGearLabel));
		emptyMessage = new PluginErrorPanel();
		typeMessage(emptyMessage);
		emptyMessage.setContent(EMPTY_TEXT, "");
		// Null to the factory, then through setHover, the one road a hover in this panel takes.
		clearBandButton = Widgets.smallButton(CLEAR_BAND_TEXT, null, e -> applyBand(0L, 0L));
		setHover(clearBandButton, "Show every item again, whatever its price");
		clearBandRow = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 2));
		clearBandRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		clearBandRow.add(clearBandButton);
		emptyColumn = Widgets.column(GAP);
		emptyColumn.add(emptyMessage);
		emptyCard = Widgets.north(emptyColumn);

		// The 2 px gutter between row cards is the DARK_GRAY ground showing through (N section 3 §4).
		rowsColumn = Widgets.column(ROWS_GAP);
		showMoreLabel = Widgets.linkLabel("", Widgets.sans(12), ColorScheme.LIGHT_GRAY_COLOR, Color.WHITE,
			this::showMore);
		showMoreLabel.setHorizontalAlignment(SwingConstants.CENTER);
		showMoreRow = new JPanel(new BorderLayout());
		showMoreRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		showMoreRow.add(showMoreLabel, BorderLayout.CENTER);
		Widgets.fixed(showMoreRow, W, SHOW_MORE_HEIGHT);
		listColumn = Widgets.column(3);
		listColumn.setBorder(new EmptyBorder(0, MARGIN, MARGIN, MARGIN));
		listColumn.add(rowsColumn);
		listView = Widgets.north(listColumn);

		scroll = new JScrollPane(listView);
		scroll.setBorder(null);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		// The header is outside the scroll pane, so the bar appearing narrows the LIST and nothing else: without
		// this the hero card and the control row would paint 7 px wider than the row cards under them, and the
		// step would come and go as the list crossed the scroll threshold (see syncGutter).
		final ComponentAdapter gutterWatch = new ComponentAdapter()
		{
			@Override
			public void componentShown(ComponentEvent e)
			{
				syncGutter();
			}

			@Override
			public void componentHidden(ComponentEvent e)
			{
				syncGutter();
			}

			@Override
			public void componentResized(ComponentEvent e)
			{
				syncGutter();
			}
		};
		scroll.getVerticalScrollBar().addComponentListener(gutterWatch);
		// 1.1.1 part S: whether a typed search keeps the bar depends on the height of the window the list scrolls in
		// (syncBarPolicy), so the panel growing or shrinking asks again.
		scroll.getViewport().addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				if (!stopped)
				{
					syncBarPolicy();
				}
			}
		});

		// AU (amendments 9.1 and 9.8): the History view, mounted exactly as the list above is - a column with the
		// list's margins, anchored north, in a scroll pane with the list pane's settings. Its clock is a lambda
		// reading the FIELD, so a later setClock reaches it too; it reads no clock and starts no timer as it builds.
		historyView = new BankHistoryView(() -> clock.getAsLong(), ZoneId.systemDefault());
		// 9.10: once here, after the prefs are read, and again wherever the window changes by any road.
		historyView.setRange(BankHistoryRange.forWindow(filter.window()));
		// 1.1.0 part C: the chart in the one colour the reader chose, if they chose one (seeded above, before the menu).
		historyView.setChartColour(singleChartColour ? chartColour : null);
		// 1.1.0 part E: and in the mask the reader left it in (nothing is drawn yet, so this only stores it).
		historyView.setAmountsHidden(hideAmounts);
		historyColumn = Widgets.column(0);
		historyColumn.setBorder(new EmptyBorder(0, MARGIN, MARGIN, MARGIN));
		historyColumn.add(historyView);
		historyHolder = Widgets.north(historyColumn);
		historyScroll = new JScrollPane(historyHolder);
		historyScroll.setBorder(null);
		historyScroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		historyScroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
		historyScroll.getVerticalScrollBar().setUnitIncrement(16);
		historyScroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		// The header keeps the SHOWING card's gutter (syncGutter), so this bar is watched exactly as the list's is.
		historyScroll.getVerticalScrollBar().addComponentListener(gutterWatch);

		cards = new JPanel(cardLayout);
		cards.setBackground(ColorScheme.DARK_GRAY_COLOR);
		cards.add(loginCard, CARD_LOGIN);
		cards.add(noBankCard, CARD_NO_BANK);
		cards.add(emptyCard, CARD_EMPTY);
		cards.add(scroll, CARD_LIST);
		cards.add(historyScroll, CARD_HISTORY);
		content.add(cards, BorderLayout.CENTER);

		renderBounds();
		renderAll();
		cardLayout.show(cards, CARD_LOGIN);

		// Listen last, so nothing above can leave a half-built panel registered; seed from what the service
		// already knows (the bridge's currentRows/currentStatus double as the first publish for a panel built
		// after the service started), and unwind the registration if the seed throws - startUp would
		// propagate, the plugin's field would never be assigned and stop() would never run.
		listener = this::onRows;
		service.addListener(listener);
		try
		{
			final Status current = service.currentStatus();
			if (current != null)
			{
				onRows(service.currentRows(), current);
			}
		}
		catch (RuntimeException | Error e)
		{
			stopped = true;
			service.removeListener(listener);
			throw e;
		}
	}

	// ---------------------------------------------------------------- building the header

	/**
	 * Builds every header widget once: the window strip, the hero card around it, the card's menu, the
	 * control row, the fold, the problem row and the search row (1.0.9 part 4). The header column itself is permanent and
	 * {@link #syncHeader} puts the right rows into it.
	 */
	private void buildHeader()
	{
		// The window chips (N 4.4 control 1): opaque-free JLabels, never JButtons; the segment swallows a
		// click on the lit one and a right-button press (the card's menu is the answer to that gesture).
		final List<JLabel> cells = new ArrayList<>(MovementWindow.values().length);
		for (MovementWindow w : MovementWindow.values())
		{
			final JLabel chip = Widgets.segment(w.label(), null, () -> selectWindow(w));
			Widgets.fixed(chip, CHIP_WIDTH, CHIP_HEIGHT);
			windowChips.put(w, chip);
			cells.add(chip);
		}
		chipRow = new JPanel(new GridLayout(1, cells.size(), 0, 0));
		chipRow.setOpaque(false);
		for (JLabel cell : cells)
		{
			chipRow.add(cell);
		}
		Widgets.fixed(chipRow, CARD_INNER, CHIP_HEIGHT);

		// 1.1.1 part G2: the strip before the card and its menu - the settings menu's sync ticks the History options menu's
		// twin items as well (renderLegacy), so they must exist when it first runs.
		viewStrip = buildViewStrip();
		hero = buildHero();
		// Q2: the menu moved off the card's right button and onto the gear, so the card sets NO component popup
		// and its children inherit none - a right-click anywhere on it now does nothing, which is the point of a
		// visible control. The gear opens the same JPopupMenu on a LEFT click (openGearMenu).
		heroMenu = buildHeroMenu();

		controlRow = buildControlRow();
		fold = buildFold();
		problemLabel = buildProblemLabel();
		searchRow = buildSearchRow();
	}

	/**
	 * The hero card (N 4.2): the caption row ("Bank value" WEST, the Discord mark and the settings icon EAST), the
	 * total line (the figure WEST, the "Refresh" link EAST), the move line (triangle, gp, percent), the window
	 * strip, the provenance footnote and - last, under it - the update line (S1). Which of the total and the move
	 * line are IN the card is {@link #syncHero}'s business (O3); every line is built here so a switch never
	 * rebuilds anything.
	 *
	 * <p><b>The support pair</b> (1.0.9, the 2hBuilds template - the user's pick from drawn choices on this very
	 * card): the top-right corner of every card holds the Discord mark and the settings icon side by side, the
	 * settings icon right-most, and the Refresh link, which used to be the corner, moves to the row under them, beside
	 * the number, where the settings icon sat from addendum Q until now. So the ring that breathes round the link
	 * while a bank change is held ({@link #paintRing}) breathes in open space. The two swapped rows, and the card is
	 * exactly as tall as it was, with or without the number: the top row is the pair's 16 px where the link made it
	 * 19, and the number keeps the 3 px the row gave up as air over it, so the number stands where it stood and
	 * everything under it stays where it was.
	 *
	 * <p><b>The settings icon is the one part of the card that is drawn whatever the three hero switches say</b>
	 * (Q1) - it rides the caption row, which is never removed - because a settings control that can be switched off by
	 * a setting is a control a reader cannot get back to.
	 */
	private JPanel buildHero()
	{
		// A HeroCard and no longer a plain Widgets.column(0) since AS7: the same panel, which also paints the ring
		// round the Refresh link while a change is owed - and nothing more while none is.
		final JPanel card = new HeroCard();
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(Widgets.card(null));

		captionLabel = Widgets.label(VALUE_TITLE, Widgets.sans(11), ColorScheme.LIGHT_GRAY_COLOR);
		refreshLabel = Widgets.linkLabel(REFRESH_TEXT, Widgets.sans(11), ColorScheme.LIGHT_GRAY_COLOR,
			ColorScheme.BRAND_ORANGE, this::refreshNow);
		// AS8: set once, here, and never changed - a click does the same thing whatever the bank is doing, so one
		// sentence describes it in every state.
		setHover(refreshLabel, REFRESH_TIP);
		// The only permanently visible action on the panel, at the smallest size on it: without padding its
		// clickable area is exactly the 39 x 15 px of the word. The inset costs nothing (the caption row asks for
		// 53 + 6 + 62 = 121 of the card's 191 px even while it says "Refreshing...") and buys ~50 x 19 px to hit.
		// A plain inset again since AS7: the ring that breathes round the link while the bank has changed under it
		// reaches outside the link's box, where no border of the link can draw, so the CARD paints it (HeroCard).
		refreshLabel.setBorder(new EmptyBorder(2, ROW_GAP, 2, 0));
		gearLabel = settingsGear();
		// 1.1.0 part I: the eye joins the corner as the FIRST of three icons - eye, Discord, settings - so it is part of the
		// top row whatever the total says: it is drawn with "Show bank value" off too, because a control that its own switch
		// could hide would be one a reader could not get back to.
		eyeLabel = buildEye();
		captionRow = transparentBar(ROW_GAP, captionLabel, null, iconTrio(support.supportPair(gearLabel)));

		totalLabel = Widgets.label("0", Widgets.sansBold(28), Color.WHITE);
		// The top row is shorter than it was - the pair's height, where the link made it the link's - and the number
		// takes the difference as air over it, so the two rows together are what they were and the number stands where it
		// stood. It is the LABEL's air and not the row's, so a card with the number switched off is as tall as before too.
		totalLabel.setBorder(new EmptyBorder(refreshLabel.getPreferredSize().height - captionRow.getPreferredSize().height,
			0, 0, 0));
		totalRow = transparentBar(ROW_GAP, totalLabel, null, refreshHolder());

		triangleLabel = new JLabel();
		deltaLabel = Widgets.label("", Widgets.sansBold(18), ColorScheme.LIGHT_GRAY_COLOR);
		deltaLabel.setBorder(new EmptyBorder(0, 0, 0, MOVE_GAP));
		pctLabel = Widgets.label("", Widgets.sansBold(18), ColorScheme.LIGHT_GRAY_COLOR);
		moveLine = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		moveLine.setOpaque(false);
		moveLine.add(triangleLabel);
		moveLine.add(deltaLabel);
		moveLine.add(pctLabel);

		// The strip's own preferred size is pinned, so it sits in a holder that carries the gaps around it.
		stripHolder = new JPanel(new BorderLayout());
		stripHolder.setOpaque(false);
		stripHolder.setBorder(new EmptyBorder(GAP, 0, 2, 0));
		stripHolder.add(chipRow, BorderLayout.CENTER);

		footnoteLabel = Widgets.label("", Widgets.sans(12), ColorScheme.LIGHT_GRAY_COLOR);
		// S1: the same face and the same grey as the footnote it sits under - the two grey lines under the chips
		// are one pair, one saying WHERE the figures come from and one saying HOW OFTEN they move. It has exactly
		// TWO texts since addendum T (T5, {@link #updateText}) and is never fitted: both are measured against the
		// card's 191 px in WidgetsTest instead (S3), the way the caption is. {@link #renderValue} keeps it in step
		// with the switch; this seeds it so the card reads right before the first publish.
		updateLabel = Widgets.label(updateText(options), Widgets.sans(UPDATE_SIZE), ColorScheme.LIGHT_GRAY_COLOR);
		faceUpdateLine(false);

		card.add(captionRow);
		card.add(totalRow);
		card.add(moveLine);
		card.add(stripHolder);
		card.add(footnoteLabel);
		card.add(updateLabel);
		// Neither the settings icon nor the update line is a tip target: each keeps its own tooltip. A settings control
		// that explained the bank's sums on hover would be the one thing on the card that does not say what it
		// does, and the update line's whole point is the sentence behind IT (S2).
		heroTipTargets.addAll(Arrays.asList(card, captionRow, captionLabel, totalRow, totalLabel, moveLine,
			triangleLabel, deltaLabel, pctLabel, stripHolder, footnoteLabel));
		return card;
	}

	/**
	 * The gear menu (Q2, the card's right-click menu of N 3.1 / O4 moved onto a visible control): the three card
	 * check items "Show bank value" / "Show change in gp" / "Show change in %", a separator, and the view check items
	 * "Use live prices" (T1) / "Include coins and platinum tokens" / "Include untradeable items" / "Include inventory
	 * and worn gear" (Y1) -
	 * two groups, because the first three say what the CARD draws and the last four what the figures MEAN. (Its first
	 * entry, "Refresh prices now", and the start-tab group were taken out in 1.1.0 part A: the card's Refresh link does
	 * the first and more, and the sidebar opens on the tab used last.)
	 *
	 * <p><b>Two colour rows follow the card's three items</b> (1.1.0 part B): "Up colour" and "Down colour", each the words
	 * and a swatch of the colour in force ({@link #colourRow}). Pressing one closes the menu and opens the colour picker
	 * through the {@link ColourPicker} seam; both tabs are drawn in the colour as the picker moves
	 * ({@link #applyMoveColours}) and the choice is stored when it closes. A rule stands above the two rows (part J) so the
	 * colours are a section of their own; directly under them stand the "Colour presets" (parts H and J:
	 * {@link #addColourPresets}), a caption, one row each for Classic, 2h and Colour-blind, a "Slot 1" row for the reader's own
	 * pair and the plain row "Save current colours to Slot 1". A click on a preset sets both colours at once
	 * ({@link #pressColourPreset}), and the menu's tick stands on the preset in use ({@link #syncPresetTicks}). The Reset to
	 * default button, in the last row, puts both colours back (Slot 1 is left alone) with the
	 * preset bands ({@link #pressReset}).
	 *
	 * <p>Every check item reflects the switch it carries and writes it: the card's three go through
	 * {@link #setHeroVisibility} and the view's four through {@link #setOptions}, which repaint at once and
	 * write the choice to the prefs so the stored config follows. They are {@link JCheckBoxMenuItem}s - plain
	 * Swing, painted by whatever menu UI the client's look and feel installs - and {@link #syncHeroMenu} keeps
	 * their ticks in step with the switches, which matters when the change came from the settings page instead.
	 *
	 * <p>The eight entries read in the order Y4 lists them, and the carried one is placed by what it MEANS: it is a
	 * third "Include", so it goes with the other two. It ends the group because addendum AO deleted the row switch
	 * that used to close it - addendum AN's three-line row prints the stack AND one item, so there was no longer a
	 * reading for a switch to pick.
	 *
	 * <p><b>A third group since addendum Z</b> (lines Z1-Z2;
	 * {@code docs/bank-price-movement-addendum-Z-2026-09-13.md}): after another separator, the
	 * {@link #buildPresetRow() preset row} - a caption and three boxes, not a switch - and the
	 * "Reset to default" item under it. They come after the switches because they are the only thing in this menu
	 * that edits a control elsewhere on the panel rather than the panel's own reading of the bank, and they are
	 * HERE because the fold they edit has no room to hold its own settings.
	 *
	 * <p><b>Then the net worth chart's group</b> (1.1.0 part A): a rule, the grey caption {@link #NET_WORTH_CHART_TEXT},
	 * "Single chart colour" ({@link #singleChartRow}, part C: a check item whose swatch of the chart colour shows while it
	 * is ticked) and - only while the record holds days recorded before 1.0.9 - the check item {@link #legacyItem}, which
	 * {@link #syncLegacyItem} puts in and takes out as the record changes (and again as the menu opens).
	 *
	 * <p><b>And one row after all of them</b> (addendum AB, line AB2): the {@link #buildOkRow() OK row}, the menu's
	 * drawn way out. It is last because it is what a reader presses when everything above it is as they want it.
	 */
	private JPopupMenu buildHeroMenu()
	{
		final JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		// 1.0.8: the header - which plugin and which build - behind a rule of its own, so the OK row stays the menu's
		// last thing (the user, on the third local look, 2026-09-30: "makes sense for the reset to default and ok
		// buttons to be the bottom most things").
		menu.add(support.header());
		menu.addSeparator();
		showValueItem = checkItem(SHOW_VALUE_TEXT, SHOW_VALUE_TIP, on -> setHeroVisibility(heroVisibility.withValue(on)));
		showGpItem = checkItem(SHOW_GP_TEXT, SHOW_GP_TIP, on -> setHeroVisibility(heroVisibility.withGp(on)));
		showPctItem = checkItem(SHOW_PCT_TEXT, SHOW_PCT_TIP, on -> setHeroVisibility(heroVisibility.withPct(on)));
		menu.add(showValueItem);
		menu.add(showGpItem);
		menu.add(showPctItem);
		// 1.1.0 part J: a rule above the colour block (Up colour, Down colour, the presets, Slot 1 and its save row), so
		// the block is a section of its own. The List options menu already has one above its colour rows.
		menu.addSeparator();
		// 1.1.0 part B: the colour a rise and a fall are drawn in, as two rows directly under the figures they colour. A
		// row is not a switch but a way into the colour picker, so it carries a swatch of the colour in force rather than a
		// tick - though it is a check item to Swing (SwatchRow), whose model never selects, so its words stand in the
		// check items' own column (part C).
		upColourRow = new SwatchRow(UP_COLOUR_TEXT, () -> upColour, false, null);
		setHover(upColourRow, UP_COLOUR_TIP);
		upColourRow.addActionListener(e -> pressColour(true));
		downColourRow = new SwatchRow(DOWN_COLOUR_TEXT, () -> downColour, false, null);
		setHover(downColourRow, DOWN_COLOUR_TIP);
		downColourRow.addActionListener(e -> pressColour(false));
		menu.add(upColourRow);
		menu.add(downColourRow);
		// 1.1.0 parts H and J: and the presets that set both at once - a caption, three rows, Slot 1 and the row that saves
		// into it - directly under them, the tick on the one in use.
		heroPresetRows.clear();
		addColourPresets(menu, heroPresetRows);
		menu.addSeparator();
		livePricesItem = checkItem(LIVE_PRICES_TEXT, LIVE_PRICES_TIP, on -> setOptions(options.withLivePrices(on)));
		countCashItem = checkItem(COUNT_CASH_TEXT, COUNT_CASH_TIP, on -> setOptions(options.withCountCash(on)));
		countUntradeablesItem = checkItem(COUNT_UNTRADEABLES_TEXT, COUNT_UNTRADEABLES_TIP,
			on -> setOptions(options.withCountUntradeables(on)));
		countInventoryItem = checkItem(COUNT_INVENTORY_TEXT, COUNT_INVENTORY_TIP,
			on -> setOptions(options.withCountInventory(on)));
		countGrandExchangeItem = checkItem(COUNT_GRAND_EXCHANGE_TEXT, COUNT_GRAND_EXCHANGE_TIP,
			on -> setOptions(options.withCountGrandExchange(on)));
		// T1: first of the group, before the two of addendum Q - the series the figures are read from, then what
		// is counted. Y1's switch is the third thing COUNTED, so it lands directly after the untradeables, and
		// 1.0.9 part 3's Grand Exchange switch, the fourth, directly after it and last of them.
		menu.add(livePricesItem);
		menu.add(countCashItem);
		menu.add(countUntradeablesItem);
		menu.add(countInventoryItem);
		menu.add(countGrandExchangeItem);
		// Z2: a third group, and the only one that is not a list of switches - the three quick bands, in boxes,
		// with the way back to 100k / 1m / 10m now a button in the bottom row (AH2).
		// (Addendum AH's "Show hover text" item stood here, the last ITEM in the menu, until release 1.2.0 deleted it:
		// the sidebar's hovers are always on.)
		menu.addSeparator();
		presetRow = buildPresetRow();
		menu.add(presetRow);
		// 1.1.0 part A: the net worth chart's group, last before the way out. The item stays OUT of the menu until the
		// record holds days before 1.0.9 (syncLegacyItem); its action is the press the History tab's check box used to
		// answer, and the tick is put back to what the panel believes whichever way the question was answered.
		// A JCheckBoxMenuItem like the Include items above it, with the same hover rule (LEGACY_TIP).
		menu.addSeparator();
		chartCaption = buildMenuCaption(NET_WORTH_CHART_TEXT);
		menu.add(chartCaption);
		// 1.1.0 part C: "Single chart colour" first - an ordinary check item whose swatch of the chart colour shows while
		// it is ticked and opens the colour picker when pressed (pressChartColour); the item above the days switch.
		singleChartRow = new SwatchRow(SINGLE_CHART_COLOUR_TEXT, () -> chartColour, true, this::pressChartColour);
		setHover(singleChartRow, SINGLE_CHART_COLOUR_TIP);
		singleChartRow.addActionListener(e -> pressSingleChartColour(singleChartRow.isSelected()));
		menu.add(singleChartRow);
		legacyItem = checkItem(LEGACY_TEXT, LEGACY_TIP, on ->
		{
			pressLegacy();
			renderLegacy();
		});
		// AB2: and under everything, the way out.
		okRow = buildOkRow();
		menu.add(okRow);
		menu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
				// The menu always opens on the presets in force: a box left red by a refused edit is a question
				// that was answered ("not saved"), and re-asking it on the next open would be the only place in
				// this sidebar where a control kept text the plugin does not believe.
				renderPresetFields();
				// 1.1.0 part A: ...and on the record it holds now - the days-before-1.0.9 item is in the menu exactly
				// while the record has such days, and the menu is laid out only after this event.
				syncLegacyItem();
				// Z6: ...and on NO box. The popup's window is focusable because of the row (see buildPresetRow),
				// and Swing hands a fresh focusable window's focus to the first focusable thing in it - which was
				// the first band, caret blinking, before the reader had asked for it. The ROW takes it instead, so
				// nothing is targeted until a box is clicked. invokeLater because that initial focus is assigned
				// after this event, when the window is actually shown: a request made now would be overruled.
				// Through menuFocusTarget() so that the target a test can name is the target the menu asks for.
				SwingUtilities.invokeLater(() -> menuFocusTarget().requestFocusInWindow());
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
				// Z2: closing the menu is the third way to commit - a reader who types and clicks the gear away
				// has finished editing, and the two fields one control row down have taught them that leaving a
				// box applies it.
				commitPresets();
				// AB1: and this is where the panel learns that its menu went away, whoever took it away. The
				// grabber's cancel arrives here BEFORE the gear's own press listener runs, which is what lets the
				// gear read that press as the close half of a toggle (gearPressOpens).
				menuClosedAtMillis = clock.getAsLong();
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});
		syncHeroMenu();
		return menu;
	}

	/**
	 * A group caption of the menu (the start-tab group's of AU, the net worth chart's since 1.1.0 part A):
	 * {@link #PRESETS_TEXT}'s look - grey 12 px, the same inset. No hover: the words are the whole of it.
	 */
	private JPanel buildMenuCaption(String text)
	{
		final JPanel row = Widgets.column(0);
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(4, ROW_GAP, 2, ROW_GAP));
		row.add(Widgets.label(text, Widgets.sans(12), ColorScheme.LIGHT_GRAY_COLOR));
		return row;
	}

	/**
	 * The colour presets' group (1.1.0 parts H and J), added to {@code menu} directly under its "Down colour" row: the grey
	 * caption {@link #COLOUR_PRESETS_TEXT}, one {@link SetRow} per {@link ColourSet} (Classic, 2h, Colour-blind) and then
	 * "Slot 1" (the reader's saved pair, read as the row paints), each showing its two colours and a press on it running
	 * {@link #pressColourPreset}; and, last, the plain row {@link #SAVE_SLOT_TEXT}, whose press is {@link #pressSaveSlot}.
	 * Both the settings menu and the List options menu call it, each getting caption and rows of its own (a component has
	 * one parent). The four preset rows are added to {@code rows}, in that order, and ticked by {@link #syncPresetTicks}
	 * (here once, for the menu just built).
	 */
	private void addColourPresets(JPopupMenu menu, List<SetRow> rows)
	{
		menu.add(buildMenuCaption(COLOUR_PRESETS_TEXT));
		for (final ColourSet set : ColourSet.values())
		{
			final SetRow row = SetRow.preset(set.label(), set::up, set::down);
			row.addActionListener(e -> pressColourPreset(set.up(), set.down()));
			rows.add(row);
			menu.add(row);
		}
		final SetRow slot = SetRow.preset(SLOT_TEXT, () -> slotUp, () -> slotDown);
		slot.addActionListener(e -> pressColourPreset(slotUp, slotDown));
		rows.add(slot);
		menu.add(slot);
		final SetRow save = SetRow.plain(SAVE_SLOT_TEXT);
		save.addActionListener(e -> pressSaveSlot());
		menu.add(save);
		syncPresetTicks();
	}

	/**
	 * Puts the menu's tick on the ONE preset row whose pair is the pair in use (1.1.0 part J): the first of Classic, 2h,
	 * Colour-blind and Slot 1, in that order, whose rise and fall are the rise and fall now drawn - and on none when no row's
	 * pair is. Both menus' rows, each time. The colours decide, never a click: every road that changes them
	 * ({@link #applyMoveColours}), and every change of Slot 1's pair, ends here.
	 */
	private void syncPresetTicks()
	{
		final int inUse = presetInUse();
		tickPresetRows(heroPresetRows, inUse);
		tickPresetRows(listPresetRows, inUse);
	}

	private static void tickPresetRows(List<SetRow> rows, int inUse)
	{
		for (int i = 0; i < rows.size(); i++)
		{
			rows.get(i).setTicked(i == inUse);
			// The squares are read as they paint, so a row whose pair changed (Slot 1) is drawn again either way.
			rows.get(i).repaint();
		}
	}

	/** The index, in menu order, of the first preset whose pair is the pair in use; -1 when none is. */
	private int presetInUse()
	{
		final ColourSet[] sets = ColourSet.values();
		for (int i = 0; i < sets.length; i++)
		{
			if (sameColour(sets[i].up(), upColour) && sameColour(sets[i].down(), downColour))
			{
				return i;
			}
		}
		return sameColour(slotUp, upColour) && sameColour(slotDown, downColour) ? sets.length : -1;
	}

	/** Whether two colours are the same opaque colour: a rise and a fall are never see-through, so alpha is no part of it. */
	private static boolean sameColour(Color a, Color b)
	{
		return (a.getRGB() & 0xFFFFFF) == (b.getRGB() & 0xFFFFFF);
	}

	/**
	 * Puts "Include days before v1.0.9" into the menu directly under "Single chart colour" (1.1.0 part C; under the "Net
	 * worth chart" caption itself before it) while the record
	 * holds days recorded before 1.0.9 ({@link #legacyDaysPresent}), and takes it out when it does not - 1.1.0 part A,
	 * which moved the check box out of the History tab's header (every row of which is added and removed, never hidden,
	 * playbook 7.5) and into this menu. Called with every header sync, so the menu follows the record, and as the menu
	 * opens, so it is right when it is laid out. It touches the menu only when the answer changed, and never while the
	 * menu stands open: a reader looking at it keeps the menu they opened, and the next open has the new one.
	 */
	private void syncLegacyItem()
	{
		renderLegacy();
		renderLegacyWords();
		final boolean want = legacyDaysPresent();
		final boolean has = legacyItem.getParent() == heroMenu;
		if (want != has && !heroMenu.isVisible())
		{
			if (want)
			{
				heroMenu.insert(legacyItem, heroMenu.getComponentIndex(singleChartRow) + 1);
			}
			else
			{
				heroMenu.remove(legacyItem);
			}
		}
		// 1.1.1 part G2: the History options menu holds the same item - first, with a rule under it - on the same condition and
		// by the same rule: never changed while that menu stands open.
		final boolean hasHistory = historyLegacyItem.getParent() == historyMenu;
		if (want != hasHistory && !historyMenu.isVisible())
		{
			if (want)
			{
				historyMenu.insert(historyLegacyItem, 0);
				historyMenu.insert(historyLegacyRule, 1);
			}
			else
			{
				historyMenu.remove(historyLegacyItem);
				historyMenu.remove(historyLegacyRule);
			}
		}
	}

	/**
	 * The gear menu's box row (Z2): the grey caption {@link #PRESETS_TEXT} over three boxes in the Min / Max
	 * fields' style, one per band, smallest first and prefilled in gp shorthand.
	 *
	 * <p><b>A {@link JPanel} and not a menu item</b>, which is the whole mechanism: {@code PopupFactory} makes a
	 * heavy-weight popup's window FOCUSABLE exactly when the popup holds a child that is neither a
	 * {@code MenuElement} nor a {@code JSeparator} ({@code PopupFactory.java}, {@code focusPopup}), and RuneLite
	 * forces every popup heavy-weight so the game applet cannot obscure it
	 * ({@code ClientUI.setupDefaults}). So this row is what lets the boxes take the keyboard at all;
	 * without it the popup window would refuse focus and every keystroke would go to the game. A press inside the
	 * popup's own hierarchy never cancels it either ({@code BasicPopupMenuUI.MouseGrabber.isInPopup}), which is
	 * the rest of what Z2 asks for: clicking a field must not close the menu.
	 *
	 * <p>The caption sits ABOVE the boxes rather than beside them because a popup is as wide as its widest child:
	 * "Preset price ranges" beside three 56 px boxes would ask for close to 300 px and widen the whole menu past
	 * its longest sentence, and the three boxes alone are narrower than "Include coins and platinum tokens"
	 * already is - as is the caption itself (Z7, AB3).
	 *
	 * <p><b>The row is FOCUSABLE</b> (line Z6), which is the other half of that mechanism and the user's own
	 * correction after the first hand look: "currently when you click the gear settings icon the 100k+ field is
	 * already selected and cursor is blinking there, i dont want that until its clicked". A focusable window hands
	 * its focus to the first focusable component in it, and until now that was the first band's text field. A plain
	 * {@link JPanel} is not focusable ({@code DefaultFocusTraversalPolicy.accept} asks a lightweight peer, which
	 * says no), so {@code setFocusable(true)} both puts the row ahead of its own boxes in the traversal cycle and
	 * lets the {@link #buildHeroMenu() menu's open event} park the keyboard on it ({@link #menuFocusTarget()} is
	 * that target). The boxes stay ordinary text fields: a click focuses one and everything after it (Enter, focus
	 * lost, the menu closing) is unchanged.
	 */
	private JPanel buildPresetRow()
	{
		final JPanel row = Widgets.column(2);
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(4, ROW_GAP, 2, ROW_GAP));
		row.setFocusable(true);
		final JLabel caption = Widgets.label(PRESETS_TEXT, Widgets.sans(12), ColorScheme.LIGHT_GRAY_COLOR);
		setHover(caption, PRESETS_TIP);
		final JPanel boxes = new JPanel();
		boxes.setLayout(new BoxLayout(boxes, BoxLayout.X_AXIS));
		boxes.setOpaque(false);
		for (int i = 0; i < presetFields.length; i++)
		{
			if (i > 0)
			{
				boxes.add(Box.createHorizontalStrut(PRESET_GAP));
			}
			presetFields[i] = presetBox(i);
			boxes.add(presetFields[i]);
		}
		// The glue keeps the three at their pinned widths when the menu is wider than they are - which it is,
		// because the check items above them are sentences.
		boxes.add(Box.createHorizontalGlue());
		row.add(caption);
		row.add(boxes);
		setHover(row, PRESETS_TIP);
		renderPresetFields();
		return row;
	}

	/**
	 * One preset box (Z2). It commits on Enter and on focus lost, exactly as the fold's gp fields do - and the
	 * three are read TOGETHER by {@link #commitPresets}, because a band is only valid beside the other two.
	 *
	 * <p>Its placeholder is that slot's DEFAULT band ("100k", "1m", "10m"), so a box emptied by mistake says what
	 * belongs in it and what "Reset to default" would put back. An empty box is not a band, so committing one is
	 * refused like any other unreadable text.
	 */
	private Widgets.PlaceholderField presetBox(int i)
	{
		final Widgets.PlaceholderField field = Widgets.gpField(MovementMath.formatGp(BandPresets.DEFAULT.mins()[i]));
		final String tip = "Quick band " + (i + 1) + " of " + presetFields.length
			+ ", in gp shorthand - e.g. 1m; the three must differ";
		// On the panel AND the text field, as the fold's fields do: the field is the mouse target inside its panel.
		setHover(field, tip);
		setHover(field.getTextField(), tip);
		Widgets.fixed(field, PRESET_FIELD_WIDTH, field.getPreferredSize().height);
		field.addActionListener(e -> commitPresets());
		field.getTextField().addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				// A temporary loss is the window going away, not the reader leaving the box - the same rule the
				// Min / Max fields follow.
				if (!e.isTemporary())
				{
					commitPresets();
				}
			}
		});
		return field;
	}

	/**
	 * The gear menu's last row (addendum AB, line AB2): a horizontal glue and, pushed to the right end of the menu
	 * by it, one small button reading {@link #OK_TEXT}.
	 *
	 * <p>The user asked for it in the same breath as the toggle - "also put a 'save' or 'ok' button at the bottom
	 * right of the gear settings menu that will close the settings box as well" - and it answers a real question
	 * this menu had left open: every other way out of it is a gesture (press the sidebar, press Escape, press the
	 * gear again) and none of them is drawn anywhere. A reader who has just typed three bands wants a control that
	 * says "done".
	 *
	 * <p>A {@link JPanel} carrying a {@link JButton}, like the {@link #buildPresetRow() preset row} above it, and
	 * for the same two reasons: a press inside the popup's own hierarchy never cancels it
	 * ({@code BasicPopupMenuUI.MouseGrabber.isInPopup}), so the button gets its click, and a non-{@code MenuElement}
	 * child is what makes RuneLite's heavy-weight popup focusable at all (Z2). It is the one control in this menu
	 * drawn by the look and feel's {@code ButtonUI} - {@link Widgets#smallButton}'s reasoning, that the way OUT of
	 * something should look like the platform's own control - wearing the menu's own face rather than the
	 * RuneScape small font, so it reads as part of the list it closes.
	 *
	 * <p>The row is as wide as the button and no wider: the glue has no preferred width, so the menu's width is
	 * still set by its longest sentence, and the button rides the right edge whatever that turns out to be.
	 */
	private JPanel buildOkRow()
	{
		final JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(2, ROW_GAP, 2, ROW_GAP));
		// AH2: "Reset to default" shares this row now, hard LEFT, with OK still hard right - the user, looking
		// at the menu: "i would like the 'reset to default' button to be in the orange box alongside 'OK' ...
		// just aligned left, OK button align right as it is currently is". A JMenuItem cannot sit in a BoxLayout
		// row and still look like one, so it is a small button like OK's, carrying the same text, the same
		// tooltip and the same action as the menu item it replaces.
		resetPresetsButton = Widgets.smallButton(RESET_PRESETS_TEXT, null, e -> pressReset());
		setHover(resetPresetsButton, RESET_PRESETS_TIP);
		resetPresetsButton.setFont(Widgets.sans(12));
		resetPresetsButton.setMaximumSize(resetPresetsButton.getPreferredSize());
		okButton = Widgets.smallButton(OK_TEXT, null, e -> pressOk());
		setHover(okButton, OK_TIP);
		okButton.setFont(Widgets.sans(12));
		// Read AFTER the font is set, and pinned so no ButtonUI can decide to fill the row with a 180 px "OK":
		// BoxLayout stretches a child up to its MAXIMUM, and the button's must stay the size of the word for the
		// glue to have anything to push against.
		okButton.setMaximumSize(okButton.getPreferredSize());
		// Reset first, then the glue, then OK: BoxLayout hands the row's spare width to the glue, so the one
		// before it is pinned left and the one after it right, however wide the menu is.
		row.add(resetPresetsButton);
		row.add(Box.createHorizontalGlue());
		row.add(okButton);
		return row;
	}

	/**
	 * The OK button's press (AB2): commit the three boxes, then take the menu down.
	 *
	 * <p>Both halves are spelled out even though each is implied by the other - the close commits (Z2) and a
	 * commit does not close - because the button's promise is that what is on screen is what is saved, and it must
	 * hold whichever way Swing delivers the hide. A trio that does not read is still refused, in red, and the menu
	 * still closes: the refusal was answered where it was made, and the next open asks the question afresh
	 * ({@code popupMenuWillBecomeVisible} re-prints the bands in force).
	 */
	private void pressOk()
	{
		commitPresets();
		closeGearMenu();
	}

	/**
	 * Opens the gear menu under {@code anchor}, the gear that was pressed (Q1) - {@code menu.show(anchor, x, y)}
	 * behind an {@code isShowing()} guard, the same rule {@link #openSortMenu} follows: RuneLite disables
	 * lightweight popups, and a menu can only be placed against something that is on the screen. There are three
	 * gears, the hero card's and one on each of the login and no-bank cards (a player who gets no further than
	 * those has no hero card), and one menu that belongs to them all, so the caller says which it is.
	 *
	 * <p><b>A press while the menu stands opens nothing</b> (addendum AB, line AB1), which is what makes the gear a
	 * toggle. The press arrives here in one of two orders, and both are answered: in this client the popup has
	 * already been cancelled by the same press (the grabber runs first), so the panel asks
	 * {@link #gearPressOpens()} how long ago the menu closed rather than asking the menu whether it is open; and
	 * should a popup ever survive the press that reached the gear, it is taken down here instead. Either way the
	 * second click closes and opens nothing.
	 */
	void openGearMenu(final JComponent anchor)
	{
		if (stopped)
		{
			return;
		}
		if (heroMenu.isVisible())
		{
			closeGearMenu();
			return;
		}
		if (!gearPressOpens() || !anchor.isShowing())
		{
			return;
		}
		heroMenu.show(anchor, 0, anchor.getHeight());
	}

	/**
	 * Whether a press on the gear right now OPENS the menu (AB1): true unless the menu went away within the last
	 * {@link #GEAR_REOPEN_GUARD_MILLIS}, in which case this press is the one that took it away and its work is
	 * done.
	 *
	 * <p>Named, and package-private, for the reason {@link #menuFocusTarget()} is: what a press decides can be
	 * asked of a panel that is not on any screen, and whether a popup is SHOWING cannot - a test has no window to
	 * show one in. The clock is {@link #setClock the panel's}, so a test drives this by moving it.
	 */
	boolean gearPressOpens()
	{
		return menuClosedAtMillis == MENU_NEVER_CLOSED
			|| clock.getAsLong() - menuClosedAtMillis >= GEAR_REOPEN_GUARD_MILLIS;
	}

	/**
	 * One check item of the card's menu. The action fires AFTER the item's model has toggled (a click on a
	 * {@code JCheckBoxMenuItem} flips its selection before the {@code ActionEvent}), so {@code isSelected()}
	 * in the listener is the NEW state; {@code setSelected} from {@link #syncHeroMenu} fires no action, which is
	 * what keeps the config round trip from writing the config back.
	 */
	private JCheckBoxMenuItem checkItem(String text, String tooltip, Consumer<Boolean> onToggle)
	{
		final JCheckBoxMenuItem item = new JCheckBoxMenuItem(text);
		// Every menu item in this sidebar sets its face: one that does not is drawn by the look and feel in the
		// 16 px bitmap RuneScape default, and this menu would then look nothing like the sort menu one control
		// row away. The TICK stays the look and feel's - it is what a reader expects of a settings toggle.
		item.setFont(Widgets.sans(12));
		setHover(item, tooltip);
		item.addActionListener(e -> onToggle.accept(item.isSelected()));
		return item;
	}

	/**
	 * A colour row's press (1.1.0 part B): takes the menu down and opens the colour picker on the colour in force. While the
	 * reader moves the picker the panel draws in the colour at once and writes nothing ({@link #previewColour}); the colour
	 * it closes on is stored ({@link #storeColour}). With no picker behind the seam the row does nothing.
	 */
	private void pressColour(boolean up)
	{
		// Either menu's row comes here (1.1.0 part G: the List options menu has the same two), so both are taken down.
		closeGearMenu();
		closeListMenu();
		final ColourPicker picker = colourPicker;
		if (stopped || picker == null)
		{
			return;
		}
		picker.open(this, up ? upColour : downColour, up ? UP_COLOUR_TEXT : DOWN_COLOUR_TEXT,
			colour -> previewColour(up, colour), colour -> storeColour(up, colour));
	}

	/** The picker moved: both tabs are drawn in the colour, and nothing is written - the reader has not chosen yet. */
	private void previewColour(boolean up, @Nullable Color colour)
	{
		if (colour == null)
		{
			return;
		}
		final Color chosen = colourOrDefault(colour, up ? Widgets.MOVE_UP_DEFAULT : Widgets.MOVE_DOWN_TEXT);
		applyMoveColours(up ? chosen : upColour, up ? downColour : chosen);
	}

	/** The picker closed: its last colour is the reader's choice, drawn and stored. */
	private void storeColour(boolean up, @Nullable Color colour)
	{
		if (colour == null || stopped)
		{
			return;
		}
		previewColour(up, colour);
		if (up)
		{
			prefs.saveUpColour(upColour);
		}
		else
		{
			prefs.saveDownColour(downColour);
		}
	}

	/**
	 * A colour preset row's press (1.1.0 parts H and J): takes whichever menu is up down, then sets BOTH colours at once -
	 * the rise's and the fall's - by the road a picked colour and "Reset to default" take: both tabs are drawn in them
	 * ({@link #applyMoveColours}, which reads a colour equal to the built-in one as no palette, so "Classic" is the sidebar as
	 * it ships, and which puts the menus' ticks right) and each key is stored through the guarded prefs write
	 * ({@link Prefs#saveUpColour}, {@link Prefs#saveDownColour}). No picker is involved, so the seam being null changes
	 * nothing. Nothing remembers which preset was pressed - the tick follows the colours - and either colour can be changed
	 * afterwards. Slot 1's row comes here with the slot's pair, like any other.
	 */
	private void pressColourPreset(Color up, Color down)
	{
		closeGearMenu();
		closeListMenu();
		if (stopped)
		{
			return;
		}
		applyMoveColours(up, down);
		prefs.saveUpColour(upColour);
		prefs.saveDownColour(downColour);
	}

	/**
	 * "Save current colours to Slot 1" (1.1.0 part J): takes whichever menu is up down, then stores the up and down colour
	 * in use into the slot - the one place the slot changes besides a ConfigChanged from outside - and writes both of its
	 * keys through the guarded prefs write ({@link Prefs#saveSlotUpColour}, {@link Prefs#saveSlotDownColour}). The colours
	 * in use do not change, so no tab is redrawn; Slot 1's squares show the saved pair and the ticks are put right
	 * ({@link #syncPresetTicks}). A stopped panel stores nothing.
	 */
	private void pressSaveSlot()
	{
		closeGearMenu();
		closeListMenu();
		if (stopped)
		{
			return;
		}
		slotUp = upColour;
		slotDown = downColour;
		syncPresetTicks();
		prefs.saveSlotUpColour(slotUp);
		prefs.saveSlotDownColour(slotDown);
	}

	/**
	 * "Reset to default" (AH2, and 1.1.0 parts B, C and D): the three preset bands back to 100k / 1m / 10m as before, the
	 * two colours back to the built-in green and red, and the net worth chart back to what ships - Single chart colour ON
	 * (since part D), its colour the logo gold - all drawn at once and stored. It does not bring any tab into view: it is
	 * not a request to look at the chart. Slot 1's saved pair is left alone (part J); the menus' tick lands on Classic.
	 */
	private void pressReset()
	{
		setPresets(BandPresets.DEFAULT);
		if (stopped)
		{
			return;
		}
		applyMoveColours(null, null);
		prefs.saveUpColour(upColour);
		prefs.saveDownColour(downColour);
		applyChartColour(true, null);
		prefs.saveSingleChartColour(singleChartColour);
		prefs.saveChartColour(chartColour);
	}

	/**
	 * The "Single chart colour" row's press (1.1.0 part C), {@code on} being the tick it was left in: the Net Worth History
	 * tab comes into view first - the chart is on that tab alone, and the change is to be seen as it is made, whichever
	 * tab was showing (C-3b) - then the chart is drawn in one colour or in the range's own, and the choice is stored. The
	 * tab it lands on is the one remembered, as for any press of the toggle ({@link #pressView}).
	 */
	private void pressSingleChartColour(boolean on)
	{
		if (stopped)
		{
			return;
		}
		pressView(SidebarView.HISTORY);
		applyChartColour(on, chartColour);
		prefs.saveSingleChartColour(on);
	}

	/**
	 * The swatch of a ticked "Single chart colour" row (1.1.0 part C): takes the menu down and opens the colour picker on
	 * the chart colour, under the title "Chart colour" - after bringing the Net Worth History tab into view, so the
	 * chart is on screen to follow the picker. With no picker behind the seam it does nothing at all, the tab included.
	 */
	private void pressChartColour()
	{
		// Either menu's row comes here (1.1.1 part G2: the History options menu has the same one), so both are taken down.
		closeGearMenu();
		closeHistoryMenu();
		final ColourPicker picker = colourPicker;
		if (stopped || picker == null)
		{
			return;
		}
		pressView(SidebarView.HISTORY);
		picker.open(this, chartColour, CHART_COLOUR_TEXT, this::previewChartColour, this::storeChartColour);
	}

	/** The picker moved: the chart alone is drawn in the colour, and nothing is written - the reader has not chosen yet. */
	private void previewChartColour(@Nullable Color colour)
	{
		if (colour == null)
		{
			return;
		}
		applyChartColour(singleChartColour, colour);
	}

	/** The picker closed: its last colour is the reader's choice, drawn and stored. */
	private void storeChartColour(@Nullable Color colour)
	{
		if (colour == null || stopped)
		{
			return;
		}
		previewChartColour(colour);
		prefs.saveChartColour(chartColour);
	}

	/** {@code colour} made opaque, or {@code builtIn} for none: a rise and a fall are never see-through. */
	private static Color colourOrDefault(@Nullable Color colour, Color builtIn)
	{
		return colour == null ? builtIn : new Color(colour.getRGB());
	}

	/**
	 * The control row (N 3.3): the band button WEST, the sort word-button EAST (AM) - a word-button that states
	 * its band ("All items v" / "100k - 5m v", N 4.4 control 3) and opens the price fold - between two 1 px
	 * rules.
	 *
	 * <p>The two buttons wear the same 7 px triangle for two different jobs (W2). The band button's points down
	 * for good: it is a MENU MARKER, the mark every "this opens something" control on the panel carries. The sort
	 * button's is the DIRECTION - down for biggest first, up for smallest - so it is not set here at all;
	 * {@link #renderControl} owns it, as it owns the text, and the constructor's {@link #renderAll} paints both
	 * before the panel is ever shown. A second marker beside it was considered and dropped: the sort button is the
	 * only thing on its half of the row, and two triangles on one word are two directions to read.
	 */
	private JPanel buildControlRow()
	{
		sortButton = Widgets.linkLabel("", Widgets.sansBold(12), ColorScheme.TEXT_COLOR, ColorScheme.BRAND_ORANGE,
			this::openSortMenu);
		sortButton.setHorizontalTextPosition(SwingConstants.LEFT);
		sortButton.setIconTextGap(ICON_GAP);

		bandTarget = Widgets.linkLabel("", Widgets.sans(12), ColorScheme.TEXT_COLOR, ColorScheme.BRAND_ORANGE,
			this::toggleFold);
		bandTarget.setIcon(Widgets.triangle(true));
		bandTarget.setHorizontalTextPosition(SwingConstants.LEFT);
		bandTarget.setIconTextGap(ICON_GAP);

		final JPanel row = new JPanel(new BorderLayout(ROW_GAP, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new CompoundBorder(new EmptyBorder(ROW_GAP, 0, 0, 0),
			new CompoundBorder(new MatteBorder(1, 0, 1, 0, ColorScheme.BORDER_COLOR), new EmptyBorder(0, ROW_GAP, 0, ROW_GAP))));
		// AK, the user's placement: the price band on the LEFT and the sort column on the RIGHT - they were the
		// other way round from addendum N until now. The two keep their own fitting rules; only the slots swap,
		// so the band still gets what the sort leaves and the sort is still the one that never truncates.
		row.add(bandTarget, BorderLayout.WEST);
		row.add(sortButton, BorderLayout.EAST);
		Widgets.fixed(row, W, ROW_GAP + 2 + CONTROL_HEIGHT);
		return row;
	}

	/**
	 * The price fold (N 3.5): the four presets over the two gp fields and the "x" that clears both. A plain
	 * panel and not a popup, so no MenuSelectionManager steals keystrokes from a text field; added under the
	 * control row while open and removed on the second tap - never hidden.
	 *
	 * <p>Since addendum Z (line Z3) the four chips are "All" and the reader's three {@link BandPresets}: each cell
	 * is built once and asks {@link #presetMin} for the band its place holds, so editing the presets in the gear
	 * menu re-labels them ({@link #renderPresetCells}) without rebuilding the fold. With the DEFAULT presets they
	 * are "All" / "100k+" / "1m+" / "10m+" - the four this fold has always drawn.
	 */
	private JPanel buildFold()
	{
		final JPanel panel = Widgets.column(5);
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(ROW_GAP, GAP, ROW_GAP, GAP));

		for (int i = 0; i < presetCells.length; i++)
		{
			// Z3: the INDEX is captured, never the band - a cell built once goes on pressing whatever band its
			// place holds after the reader edits the presets, so nothing here is rebuilt when they do.
			final int index = i;
			final JLabel cell = Widgets.segment("", null, () -> applyBand(presetMin(index), 0L));
			Widgets.fixed(cell, PRESET_WIDTH, PRESET_HEIGHT);
			presetCells[i] = cell;
		}
		renderPresetCells();
		final JPanel presetBar = Widgets.grid(PRESET_GAP, presetCells);
		presetBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		clearLabel = iconButton(Widgets.clearIcon(ColorScheme.LIGHT_GRAY_COLOR),
			Widgets.clearIcon(ColorScheme.BRAND_ORANGE), "Clear both bounds", () -> applyBand(0L, 0L));
		Widgets.fixed(clearLabel, SMALL_ICON, minField.getPreferredSize().height);
		// A box with struts, not a FlowLayout: FlowLayout's preferred width adds its gap at BOTH ends as well as
		// between the parts (90 + 90 + 11 with four gaps = 211, over the fold's 205), and the width rule is
		// measured on preferred sizes. The glue keeps the "x" beside the fields when the sidebar is wider.
		final JPanel fields = new JPanel();
		fields.setLayout(new BoxLayout(fields, BoxLayout.X_AXIS));
		fields.setOpaque(false);
		fields.add(minField);
		fields.add(Box.createHorizontalStrut(ICON_GAP));
		fields.add(maxField);
		fields.add(Box.createHorizontalStrut(ICON_GAP));
		fields.add(clearLabel);
		fields.add(Box.createHorizontalGlue());

		panel.add(presetBar);
		panel.add(fields);
		return panel;
	}

	/**
	 * Addendum AU's strip (plan 7.2 items 1 and 12; {@code mock-items-toggle-2x.png}): the "Items | Net Worth History"
	 * toggle over one grey caption line, directly under the card in both views. The gap above it is the control row's
	 * own {@link #ROW_GAP}, so the card stands the same distance from whatever follows it in either view; the caption
	 * is the 11 px face of the card's own caption, indented like the problem row's sentence.
	 *
	 * <p>No hover anywhere on it (ruling 9.7): the two words say what they do, and a hover would be invented text.
	 *
	 * <p><b>The caption stands in a row of its own since 1.1.1 part G2</b>: in History alone, the same two gears the Items
	 * tab carries at the search box's right end sit at the row's east end ({@link #renderHistoryGears}) and open the History
	 * options menu ({@link #buildHistoryMenu}); and, while the record's early days are hidden for the placeholder bug, the
	 * "i" icon stands directly left of them ({@link #syncLegacyInfo}, part I2). The row is as tall as the caption was, so the
	 * strip is exactly the strip it was whichever icons show - the Items tab is untouched, and nothing under the row ever moves.
	 */
	private JPanel buildViewStrip()
	{
		viewToggle = Widgets.toggle(SidebarView.ITEMS.toString(), SidebarView.HISTORY.toString(),
			index -> pressView(SidebarView.values()[index]));
		viewCaption = Widgets.label("", Widgets.sans(11), ColorScheme.LIGHT_GRAY_COLOR);
		viewCaption.setBorder(new EmptyBorder(VIEW_CAPTION_GAP, GAP, 0, GAP));
		viewCaptionRow = new JPanel(new GridBagLayout());
		viewCaptionRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		viewCaptionRow.add(viewCaption, captionRowCell(0, 1.0));
		historyMenu = buildHistoryMenu();
		historyOptionsLabel = buildHistoryOptionsIcon();
		legacyInfoLabel = buildLegacyInfoIcon();
		final JPanel strip = Widgets.column(0);
		strip.setBorder(new EmptyBorder(ROW_GAP, 0, 0, 0));
		strip.add(viewToggle);
		strip.add(viewCaptionRow);
		return strip;
	}

	/**
	 * Where a component stands in the caption's row: column {@code column}, the whole height of the row, and the width left over
	 * (the caption's, {@code weightx} 1) or just its own (an icon's, 0). The same geometry the row's BorderLayout gave the caption
	 * and the gears before part I2 - a grid-bag row only because it can hold two icons at its east end.
	 */
	private static GridBagConstraints captionRowCell(final int column, final double weightx)
	{
		final GridBagConstraints cell = new GridBagConstraints();
		cell.gridx = column;
		cell.gridy = 0;
		cell.weightx = weightx;
		cell.weighty = 1.0;
		cell.fill = GridBagConstraints.BOTH;
		return cell;
	}

	/**
	 * The "i" icon on the History caption's row (1.1.1 part I2): {@link InfoIcon}'s disc, grey like the gears and white under the
	 * mouse, with an always-on hover ({@link #LEGACY_INFO_TIP}) and a LEFT press that asks the include question by the box's own
	 * road ({@link #pressLegacy()}: the {@link LegacyPrompt}, the stored key, the cut). It is exactly the icon's width wide - the
	 * 6 px gap to the gears beside it is the gears' own air ({@link #LIST_OPTIONS_GAP}) - with {@link #VIEW_CAPTION_GAP} of air
	 * above, the caption's: the row stretches it and the icon is centred in what is left, which is the caption's text line, as
	 * the gears are.
	 */
	private JLabel buildLegacyInfoIcon()
	{
		final JLabel icon = new JLabel()
		{
			@Override
			public Point getToolTipLocation(MouseEvent e)
			{
				return legacyInfoTipLocation(this);
			}
		};
		icon.setBorder(new EmptyBorder(VIEW_CAPTION_GAP, 0, 0, 0));
		icon.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		icon.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (Widgets.isPress(e))
				{
					// The question is modal: the hover must not stay on screen over it, nor be shown again while it is up.
					ToolTipManager.sharedInstance().mousePressed(e);
					icon.setToolTipText(null);
					try
					{
						// The settings item's own road: the answer is put right in both menus whichever way the question went.
						pressLegacy();
					}
					finally
					{
						icon.setToolTipText(LEGACY_INFO_TIP);
					}
					renderLegacy();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				legacyInfoHot = true;
				renderLegacyInfoIcon();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				legacyInfoHot = false;
				renderLegacyInfoIcon();
			}
		});
		legacyInfoLabel = icon;
		renderLegacyInfoIcon();
		return icon;
	}

	/** The icon drawn for the state it is in: grey, or - under the mouse - white; its hover never changes. */
	private void renderLegacyInfoIcon()
	{
		legacyInfoLabel.setIcon(InfoIcon.icon(legacyInfoHot ? Color.WHITE : Widgets.PLACEHOLDER_COLOR));
		legacyInfoLabel.setToolTipText(LEGACY_INFO_TIP);
	}

	/**
	 * Where the "i" icon's hover opens (1.1.1 part I2, the user's look): in {@code label}'s own coordinates, as Swing asks, UNDER
	 * the icon with the tip's RIGHT edge on the icon's right edge, so it grows leftward over the sidebar instead of running off
	 * to the right of a pointer that already stands at the sidebar's right edge. The tip's width is what Swing will show - the
	 * label's own {@code createToolTip()} with the text set, at its preferred size. It never starts left of the panel's left
	 * edge: a tip wider than the panel is aligned to that edge.
	 */
	Point legacyInfoTipLocation(final JLabel label)
	{
		final JToolTip tip = label.createToolTip();
		tip.setTipText(label.getToolTipText());
		int x = label.getWidth() - tip.getPreferredSize().width;
		if (SwingUtilities.isDescendingFrom(label, this))
		{
			x = Math.max(x, SwingUtilities.convertPoint(this, 0, 0, label).x);
		}
		return new Point(x, label.getHeight() + 2);
	}

	/**
	 * The History options icon (1.1.1 part G2): {@link GearsIcon}'s two gears in the same grey and the same white under the
	 * mouse as the List options icon's, with an always-on hover ({@link #HISTORY_OPTIONS_TIP}) and a LEFT press that opens the
	 * History options menu under it ({@link #openHistoryMenu}). The label is the icon's width plus {@link #LIST_OPTIONS_GAP} of
	 * air on its left, so the gap is part of the hit area as the List options icon's is, and {@link #VIEW_CAPTION_GAP} of air
	 * above, the caption's own: BorderLayout stretches it to the row and the icon is centred in what is left, which is the
	 * caption's text line.
