	/**
	 * The History options menu (1.1.1 part G2), built like the List options menu: the settings menu's border and fonts, no
	 * header and no OK row. Its items are the settings menu's own twins - a component has one parent, so each is built again
	 * by the same factory and its press is the same method, never a second implementation:
	 * <ol>
	 * <li>{@link #historyLegacyItem}, "Include days before v1.0.9" or "... v1.1.1" with the same hover, whose press is the
	 * settings item's ({@link #pressLegacy()}: the {@link LegacyPrompt} question, the stored key, the cut), and the rule
	 * under it - both IN the menu only while the record holds hidden days ({@link #syncLegacyItem}, as for the settings
	 * menu's item);</li>
	 * <li>"Single chart colour" ({@link #historyChartRow}), the settings menu's {@link SwatchRow} again: its tick runs
	 * {@link #pressSingleChartColour} and its swatch {@link #pressChartColour}.</li>
	 * </ol>
	 */
	private JPopupMenu buildHistoryMenu()
	{
		final JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		historyLegacyItem = checkItem(LEGACY_TEXT, LEGACY_TIP, on ->
		{
			pressLegacy();
			renderLegacy();
		});
		historyLegacyRule = new JPopupMenu.Separator();
		historyChartRow = new SwatchRow(SINGLE_CHART_COLOUR_TEXT, () -> chartColour, true, this::pressChartColour);
		setHover(historyChartRow, SINGLE_CHART_COLOUR_TIP);
		historyChartRow.setSelected(singleChartColour);
		historyChartRow.addActionListener(e -> pressSingleChartColour(historyChartRow.isSelected()));
		menu.add(historyChartRow);
		menu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
				// The menu is laid out only after this event, so it opens on the record it holds now (the settings menu's rule)
				// and on the tick the panel believes.
				syncLegacyItem();
				historyChartRow.setSelected(singleChartColour);
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
				// The settings menu's rule (AB1): the grabber's cancel arrives here BEFORE the icon's own press listener
				// runs, which is what lets the icon read that press as the close half of a toggle.
				historyMenuClosedAtMillis = clock.getAsLong();
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});
		return menu;
	}

	/**
	 * Opens the History options menu under {@code anchor}, the icon that was pressed, with the menu's right edge on the icon's
	 * (1.1.1 part G2) - the icon is at the sidebar's right, so the menu opens leftward, as the List options menu does. A press
	 * while the menu stands opens nothing and takes it down: the same toggle the List options icon has ({@link #openListMenu}),
	 * by the same rule ({@link #historyPressOpens()}).
	 */
	void openHistoryMenu(final JComponent anchor)
	{
		if (stopped)
		{
			return;
		}
		if (historyMenu().isVisible())
		{
			closeHistoryMenu();
			return;
		}
		if (!historyPressOpens() || !anchor.isShowing())
		{
			return;
		}
		historyMenu().show(anchor, anchor.getWidth() - historyMenu().getPreferredSize().width, anchor.getHeight());
	}

	/**
	 * Whether a press on the History options icon right now OPENS the menu: true unless the menu went away within the last
	 * {@link #GEAR_REOPEN_GUARD_MILLIS}, in which case this press is the one that took it away ({@link #listPressOpens()}'s rule,
	 * over this menu's own stamp). Package-private for the reason that one is.
	 */
	boolean historyPressOpens()
	{
		return historyMenuClosedAtMillis == MENU_NEVER_CLOSED
			|| clock.getAsLong() - historyMenuClosedAtMillis >= GEAR_REOPEN_GUARD_MILLIS;
	}

	private void closeHistoryMenu()
	{
		if (historyMenu() != null && historyMenu().isVisible())
		{
			historyMenu().setVisible(false);
		}
	}

	/**
	 * Puts the icon at the caption row's east end in History and takes it out in Items (1.1.1 part G2) - added and removed,
	 * never hidden, like every row here - and takes its menu down with it. Touches nothing when it is already right.
	 */
	private void renderHistoryGears()
	{
		final boolean want = view == SidebarView.HISTORY;
		if (want == (historyOptionsLabel.getParent() == viewCaptionRow))
		{
			return;
		}
		if (want)
		{
			viewCaptionRow.add(historyOptionsLabel, captionRowCell(2, 0.0));
		}
		else
		{
			closeHistoryMenu();
			viewCaptionRow.remove(historyOptionsLabel);
		}
		viewCaptionRow.revalidate();
		viewCaptionRow.repaint();
	}

	/**
	 * Puts the "i" icon into the caption row, directly left of the gears, or takes it out (1.1.1 part I2; part G2 stood three grey
	 * lines under the row in its place). It is there exactly while ALL of these hold: the History tab is showing, the record hides
	 * its early days for the placeholder bug ({@link #placeholderDays} - never for 1.0.9's reason), there ARE hidden days
	 * ({@link #legacyDaysPresent}), and "Include days before ..." is off. Ticking the box from either menu, or from the icon's own
	 * press, takes it away and unticking brings it back. Added and removed, never hidden, like every row here; nothing under the row
	 * moves with it, because the row is as tall with it as without it. Touches nothing when the row is already right.
	 */
	private void syncLegacyInfo()
	{
		final boolean want = view == SidebarView.HISTORY && placeholderDays() && legacyDaysPresent() && !includeLegacy;
		if (want == (legacyInfoLabel.getParent() == viewCaptionRow))
		{
			return;
		}
		if (want)
		{
			// Right after the caption, so the row's children stand in the order they are drawn: the caption, this, the gears.
			viewCaptionRow.add(legacyInfoLabel, captionRowCell(1, 0.0), 1);
		}
		else
		{
			// A label that leaves under the pointer is never sent the exit, so it must not come back white.
			legacyInfoHot = false;
			renderLegacyInfoIcon();
			viewCaptionRow.remove(legacyInfoLabel);
		}
		viewCaptionRow.revalidate();
		viewCaptionRow.repaint();
	}

	/**
	 * The problem row (N 3.6): one 12 px line, its height taken from a probe so it never collapses while
	 * empty, fitted to the width with the whole sentence as its tooltip.
	 */
	private JLabel buildProblemLabel()
	{
		final JLabel label = Widgets.label("", Widgets.sans(12), ColorScheme.LIGHT_GRAY_COLOR);
		label.setBorder(new EmptyBorder(2, ROW_GAP, 0, ROW_GAP));
		final int probe = Widgets.label("X", Widgets.sans(12), ColorScheme.LIGHT_GRAY_COLOR).getPreferredSize().height;
		Widgets.fixed(label, W, probe + 2);
		return label;
	}

	private Widgets.PlaceholderField boundField(boolean min)
	{
		final Widgets.PlaceholderField field = Widgets.gpField(min ? "min gp" : "max gp");
		final String tip = (min ? "Lowest" : "Highest") + " unit price to show, e.g. 100k or 1.5m; empty = no "
			+ (min ? "lower" : "upper") + " bound";
		// On the panel AND the text field: the field is the mouse target inside its panel (playbook 7.5).
		setHover(field, tip);
		setHover(field.getTextField(), tip);
		Widgets.fixed(field, FIELD_WIDTH, field.getPreferredSize().height);
		field.addActionListener(e -> applyBound(field, min));
		field.getTextField().addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				// Not while the header itself is taking the field away (see syncHeader): that is not the user
				// leaving the field, and what is in it is half a number.
				if (!e.isTemporary() && !syncingHeader)
				{
					applyBound(field, min);
				}
			}
		});
		return field;
	}

	/** The key the search box's Escape is bound under in its action map (1.0.9 part 4). */
	private static final String CLEAR_SEARCH = "clearSearch";

	/**
	 * The search box (1.0.9 part 4): the Min / Max boxes' own look through {@link Widgets#searchField}, reading
	 * {@link #SEARCH_PLACEHOLDER} in grey while it is empty, with the hover on the panel AND the text field for the
	 * reason {@link #boundField} gives - the field is the mouse target inside its panel (playbook 7.5).
	 *
	 * <p>It answers EVERY change of its text, a character at a time, because the answer costs nothing: the list is
	 * narrowed from the rows this panel already holds ({@link #applySearch}), with no trip to the service and no
	 * recompute. Enter does the same at once, which after a keystroke has already been done, so it changes nothing more;
	 * Escape clears the box, and the clearing is itself a change of text and so clears the search. There is no magnifier -
	 * the user chose the plain box - but since 1.1.1 part X a small "x" ({@link Widgets.ClearX}) stands at the box's right end
	 * while it holds any text: its press empties the box through the same document, which clears the search as Escape does,
	 * and leaves the caret in the box. Its hover is {@link #CLEAR_SEARCH_TIP}, registered as the box's own is.
	 *
	 * <p><b>Nothing here ever takes the focus</b> (addendum Z's Z6 rule): not building, not the sidebar being shown, not
	 * the tab changing. A caret that appears in a box nobody clicked is a box that eats the next keystroke - a hotkey
	 * the player meant for the game. Only the reader's own click puts it there.
	 */
	private Widgets.PlaceholderField searchBox()
	{
		final Widgets.PlaceholderField field = Widgets.searchField(SEARCH_PLACEHOLDER);
		setHover(field, SEARCH_TIP);
		setHover(field.getTextField(), SEARCH_TIP);
		setHover(field.clearX(), CLEAR_SEARCH_TIP);
		final DocumentListener typing = new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				typed();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				typed();
			}

			private void typed()
			{
				// Not while applySearch is writing the box itself: it is the one asking, and it carries on by itself.
				if (!settingSearch)
				{
					applySearch(field.getText());
				}
			}
		};
		field.getTextField().getDocument().addDocumentListener(typing);
		field.addActionListener(e -> applySearch(field.getText()));
		field.getTextField().getInputMap(JComponent.WHEN_FOCUSED)
			.put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), CLEAR_SEARCH);
		field.getTextField().getActionMap().put(CLEAR_SEARCH, new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				field.setText("");
			}
		});
		return field;
	}

	/** What {@link #gameFocus} is until the plugin hands over a real one, and again once the panel stops. */
	private static final Runnable NO_HAND_OVER = () ->
	{
	};

	/**
	 * What a press that leaves a text box does about the focus: the plugin's hand-over of it to the game
	 * ({@link #setGameFocus}), a no-op until then. Volatile for the reason {@link #bankRefresh} is.
	 */
	private volatile Runnable gameFocus = NO_HAND_OVER;

	/**
	 * Hears every mouse press inside the sidebar, so a press on a label, a row or a panel - none of which can take the
	 * focus - can still take it off a text box (1.0.9 part 4, from the user's first look at the search box: "once
	 * the typing box is selected it stays selected even when i click off of it"). It is the decorator of the one
	 * {@link JLayer} that holds the panel's whole content: Swing hands it the events of that layer's own subtree and
	 * of nothing else, and it changes no event's target, so a press still goes to the row, chip or label it was made
	 * on. The panel asks its own boxes who owns the focus ({@link #focusedField}) and hands the focus to the game
	 * ({@link #setGameFocus}); it never asks the JVM's global focus manager or clears it, which is shared with the
	 * game's canvas and every other plugin and which the Hub's reviewers refuse (PR #17431, 2026-10-02).
	 */
	private final class PressWatcher extends LayerUI<JPanel>
	{
		@Override
		public void installUI(final JComponent c)
		{
			super.installUI(c);
			((JLayer<?>) c).setLayerEventMask(AWTEvent.MOUSE_EVENT_MASK);
		}

		@Override
		public void uninstallUI(final JComponent c)
		{
			((JLayer<?>) c).setLayerEventMask(0);
			super.uninstallUI(c);
		}

		@Override
		protected void processMouseEvent(final MouseEvent e, final JLayer<? extends JPanel> layer)
		{
			if (e.getID() == MouseEvent.MOUSE_PRESSED)
			{
				dropFieldFocus(focusedField(), e.getComponent());
			}
		}
	}

	/**
	 * A mouse press inside the sidebar: when one of this panel's text boxes - the search box, Min or Max - owns the
	 * focus ({@code owner}) and the press ({@code source}) is not on that box, the focus goes to the game. Swing moves
	 * the focus only to a component that can take it, and nothing else in this sidebar can, so without this a click
	 * anywhere but the game left the caret blinking in the box and the box eating the next keystroke. The box then
	 * loses the focus the way it would to any other control: Min and Max apply their bound on it
	 * ({@link #boundField}), the search box has nothing left to do. A press on another box or a button is unchanged:
	 * the control's own request for the focus follows the hand-over, so it ends with it. Nothing runs once the panel
	 * is stopped.
	 */
	void dropFieldFocus(@Nullable final Component owner, @Nullable final Object source)
	{
		if (!stopped && pressLeavesField(owner, source))
		{
			gameFocus.run();
		}
	}

	/**
	 * Where a press that leaves a text box sends the focus ({@link #dropFieldFocus}): the plugin hands over RuneLite's
	 * own "give the game the focus". Null takes it away, and a stopped panel keeps none, so a late registration cannot
	 * pin the plugin that made it. Callable from any thread: it writes one volatile field and touches nothing Swing.
	 */
	public void setGameFocus(@Nullable Runnable handOver)
	{
		gameFocus = stopped || handOver == null ? NO_HAND_OVER : handOver;
	}

	/**
	 * Whether a press on {@code source} takes the focus off {@code owner}: true exactly when the owner is the text
	 * field of one of this panel's three boxes and the press is not inside that box's own panel. Pure, so the test
	 * can ask it without a focus owner, which a headless JVM cannot have.
	 */
	boolean pressLeavesField(@Nullable final Component owner, @Nullable final Object source)
	{
		final Widgets.PlaceholderField field = fieldOwning(owner);
		if (field == null)
		{
			return false;
		}
		return !(source instanceof Component) || !SwingUtilities.isDescendingFrom((Component) source, field);
	}

	/** The text field of whichever of the three boxes owns the focus right now, or null when none does. */
	@Nullable
	private Component focusedField()
	{
		for (final Widgets.PlaceholderField field : textBoxes())
		{
			if (field.getTextField().isFocusOwner())
			{
				return field.getTextField();
			}
		}
		return null;
	}

	/** The box whose text field {@code owner} is, or null when it is none of the three. */
	@Nullable
	private Widgets.PlaceholderField fieldOwning(@Nullable final Component owner)
	{
		if (owner == null)
		{
			return null;
		}
		for (final Widgets.PlaceholderField field : textBoxes())
		{
			if (owner == field.getTextField())
			{
				return field;
			}
		}
		return null;
	}

	/** The panel's three text boxes: the search box, Min and Max. */
	private Widgets.PlaceholderField[] textBoxes()
	{
		return new Widgets.PlaceholderField[]{searchField, minField, maxField};
	}

	/**
	 * The search box's row (1.0.9 part 4): the box, a row cell wide ({@link #W}) and as tall as the Min / Max boxes - the
	 * field's own preferred height, which is the same builder's - under {@link #SEARCH_GAP} of air. It is the last row of
	 * the Items header ({@link #syncHeader}), so the air under the box is the header's own bottom padding
	 * ({@link #GAP}, equal by value) and the box stands exactly {@link #SEARCH_GAP} over the first row. Its edges are
	 * the row cells' edges: the header and the list both keep {@link #MARGIN} each side, and the header gives back the
	 * list's scrollbar gutter ({@link #syncGutter}).
	 */
	private JPanel buildSearchRow()
	{
		final JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(new EmptyBorder(SEARCH_GAP, 0, 0, 0));
		row.add(searchField, BorderLayout.CENTER);
		// 1.1.0 part G: the List options icon at the row's right end - the box is shortened by the icon and its 6 px gap, and
		// the icon's right edge stands where the box's right edge stood.
		listMenu = buildListMenu();
		listOptionsLabel = buildListOptionsIcon();
		row.add(listOptionsLabel, BorderLayout.EAST);
		Widgets.fixed(row, W, SEARCH_GAP + searchField.getPreferredSize().height);
		return row;
	}

	/**
	 * The List options icon (1.1.0 part G): {@link GearsIcon}'s two gears in the grey the search box paints its placeholder
	 * in ({@link Widgets#PLACEHOLDER_COLOR}) at rest and white under the mouse, a hover that is always on
	 * ({@link #LIST_OPTIONS_TIP}) and a LEFT press that opens the List options menu under it ({@link #openListMenu}). The label
	 * is the icon's width plus {@link #LIST_OPTIONS_GAP} of empty air on its left, so the gap between the box and the icon is
	 * part of the icon's hit area, as the settings icon's inset is; BorderLayout stretches it to the box's height and centres
	 * the icon in it.
	 */
	private JLabel buildListOptionsIcon()
	{
		final JLabel icon = new JLabel();
		icon.setBorder(new EmptyBorder(0, LIST_OPTIONS_GAP, 0, 0));
		icon.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		icon.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (Widgets.isPress(e))
				{
					openListMenu(icon);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				listOptionsHot = true;
				renderListOptionsIcon();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				listOptionsHot = false;
				renderListOptionsIcon();
			}
		});
		listOptionsLabel = icon;
		renderListOptionsIcon();
		return icon;
	}

	/** The icon drawn for the state it is in: grey, or - under the mouse - white; its hover never changes. */
	private void renderListOptionsIcon()
	{
		listOptionsLabel.setIcon(GearsIcon.icon(listOptionsHot ? Color.WHITE : Widgets.PLACEHOLDER_COLOR));
		listOptionsLabel.setToolTipText(LIST_OPTIONS_TIP);
	}

	/**
	 * The List options menu (1.1.0 part G): "Show alch-only items" - a check item in the settings menu's look, ticking
	 * {@code showAlchRows} - the settings menu's rule, and the same two colour rows the settings menu has ("Up colour" and
	 * "Down colour"), which open the same picker and change the one palette, each row's swatch drawn from the colour in force
	 * as it paints - and, since parts H and J, the settings menu's "Colour presets" caption and its preset rows (Classic, 2h,
	 * Colour-blind, Slot 1) and the "Save current colours to Slot 1" row directly under them, with the tick on the preset in
	 * use. The menu keeps the settings menu's border and fonts, and nothing else of it: no header, no OK row.
	 */
	private JPopupMenu buildListMenu()
	{
		final JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		showAlchItem = checkItem(SHOW_ALCH_TEXT, SHOW_ALCH_TIP, this::pressShowAlchRows);
		showAlchItem.setSelected(showAlchRows);
		menu.add(showAlchItem);
		menu.addSeparator();
		listUpColourRow = new SwatchRow(UP_COLOUR_TEXT, () -> upColour, false, null);
		setHover(listUpColourRow, UP_COLOUR_TIP);
		listUpColourRow.addActionListener(e -> pressColour(true));
		listDownColourRow = new SwatchRow(DOWN_COLOUR_TEXT, () -> downColour, false, null);
		setHover(listDownColourRow, DOWN_COLOUR_TIP);
		listDownColourRow.addActionListener(e -> pressColour(false));
		menu.add(listUpColourRow);
		menu.add(listDownColourRow);
		// 1.1.0 parts H and J: the settings menu's colour presets, the same caption and rows, directly under the colour rows.
		listPresetRows.clear();
		addColourPresets(menu, listPresetRows);
		menu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
				// The settings menu's rule (AB1): the grabber's cancel arrives here BEFORE the icon's own press listener
				// runs, which is what lets the icon read that press as the close half of a toggle.
				listMenuClosedAtMillis = clock.getAsLong();
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});
		return menu;
	}

	/**
	 * Opens the List options menu under {@code anchor}, the icon that was pressed, with the menu's right edge on the icon's
	 * (1.1.0 part G) - the menu is wider than the icon and the icon is at the sidebar's right, so it opens leftward. A press
	 * while the menu stands opens nothing and takes it down: the same toggle the settings icon has ({@link #openGearMenu}), by
	 * the same rule ({@link #listPressOpens()}).
	 */
	void openListMenu(final JComponent anchor)
	{
		if (stopped)
		{
			return;
		}
		if (listMenu().isVisible())
		{
			closeListMenu();
			return;
		}
		if (!listPressOpens() || !anchor.isShowing())
		{
			return;
		}
		listMenu().show(anchor, anchor.getWidth() - listMenu().getPreferredSize().width, anchor.getHeight());
	}

	/**
	 * Whether a press on the List options icon right now OPENS the menu: true unless the menu went away within the last
	 * {@link #GEAR_REOPEN_GUARD_MILLIS}, in which case this press is the one that took it away ({@link #gearPressOpens}'s
	 * rule, over this menu's own stamp). Package-private for the reason that one is.
	 */
	boolean listPressOpens()
	{
		return listMenuClosedAtMillis == MENU_NEVER_CLOSED
			|| clock.getAsLong() - listMenuClosedAtMillis >= GEAR_REOPEN_GUARD_MILLIS;
	}

	private void closeListMenu()
	{
		if (listMenu() != null && listMenu().isVisible())
		{
			listMenu().setVisible(false);
		}
	}

	/**
	 * An icon-only control: grey at rest, {@code hot} while the mouse is over it, a LEFT press runs
	 * {@code onClick} ({@link Widgets#isPress}: a right-button press is a menu gesture everywhere in this
	 * sidebar, never a press). Its {@code tooltip} is a SENTENCE-class hover like every other in this panel: it goes
	 * through {@link #setHover}. The icons that name themselves in one word go through
	 * {@link SupportLinks#namedIconButton} instead.
	 */
	private JLabel iconButton(ImageIcon rest, ImageIcon hot, String tooltip, Runnable onClick)
	{
		final JLabel label = SupportLinks.pressable(rest, hot, onClick);
		setHover(label, tooltip);
		return label;
	}

	/**
	 * One settings gear: the drawn gear, grey at rest and orange under the mouse, {@link SupportLinks#SETTINGS_TIP} for an
	 * always-on hover, and a LEFT press opens {@link #heroMenu} under IT ({@link #openGearMenu}) - the hero card's, and
	 * the one on each message card, which is why every gear is built here and each passes itself as the menu's anchor.
	 *
	 * <p>The inset on its left and above and below is the same 6 px of hit area the Refresh link buys, on the side the
	 * pointer arrives from: a 12 px glyph is a 12 px target otherwise, and this one is a settings button and not a
	 * decoration.
	 */
	private JLabel settingsGear()
	{
		// The press needs the label it belongs to, which does not exist until SupportLinks.namedIconButton has returned it.
		final JLabel[] self = new JLabel[1];
		self[0] = SupportLinks.namedIconButton(Widgets.gearIcon(Widgets.GEAR_SIZE, ColorScheme.LIGHT_GRAY_COLOR),
			Widgets.gearIcon(Widgets.GEAR_SIZE, ColorScheme.BRAND_ORANGE), SupportLinks.SETTINGS_TIP,
			() -> openGearMenu(self[0]));
		self[0].setBorder(SupportLinks.iconBorder());
		return self[0];
	}

	/**
	 * The Refresh link's place on the total's line (1.0.9): a holder that centres the link in the line's height at its
	 * own size. A bare link at the EAST of a {@link BorderLayout} would be stretched to the line's 34 px, and the ring
	 * that breathes round it ({@link #glowBox}) follows the link's bounds - a 34 px tall ring round a 15 px word. The
	 * holder is exactly as wide as the link, so the link still ends at the card's right padding and its texts
	 * ("Refreshing...", "Up to date") grow leftward, into the open ground beside the number.
	 */
	private JPanel refreshHolder()
	{
		final JPanel holder = new JPanel(new GridBagLayout());
		holder.setOpaque(false);
		holder.add(refreshLabel);
		return holder;
	}

	/**
	 * The card's top-right icons (1.1.0 part I): the eye, then {@code pair} - the Discord mark and the settings icon as
	 * {@link SupportLinks#supportPair} makes them, which is kit code and is not touched - so the corner reads eye, Discord,
	 * settings, the settings icon still the right-most thing. The gap between the eye and the Discord mark is the one between
	 * the Discord mark and the settings icon, {@link SupportLinks#PAIR_GAP} px of clear ground measured between the ink boxes:
	 * the eye's and the Discord mark's labels carry the same {@link SupportLinks#iconBorder} (6 px of hit area on the left, none
	 * on the right), so the strip between them is the gap less that inset, exactly as {@link SupportLinks#supportPair} sets its
	 * own. All three labels are 16 px tall - 12 px of icon and 2 px above and below - and the trio is as tall as they are, so
	 * the eye's 12 x 12 box is centred on the very line theirs are.
	 *
	 * <p>The trio is exactly as wide as the eye, the strip and the pair, so the bar that holds it at its east end gives it no
	 * more room than that, and the card's top row is as tall as it was.
	 */
	private JPanel iconTrio(JPanel pair)
	{
		final JPanel trio = new JPanel();
		trio.setLayout(new BoxLayout(trio, BoxLayout.X_AXIS));
		trio.setOpaque(false);
		trio.add(eyeLabel);
		final int strip = SupportLinks.PAIR_GAP - eyeLabel.getInsets().left;
		trio.add(Box.createHorizontalStrut(strip));
		trio.add(pair);
		final int width = eyeLabel.getPreferredSize().width + strip + pair.getPreferredSize().width;
		final int height = Math.max(eyeLabel.getPreferredSize().height, pair.getPreferredSize().height);
		trio.setPreferredSize(new Dimension(width, height));
		return trio;
	}

	/**
	 * The "Hide amounts" eye (1.1.0 part E): {@link EyeIcon} in the ink {@link EyeIcon#ink} says - grey 52 at rest while the
	 * amounts show, grey 165 while they are hidden, white under the mouse - a ONE-or-two-word hover that is always on
	 * ({@link #HIDE_AMOUNTS_TIP} while the amounts show, {@link #SHOW_AMOUNTS_TIP} while they are hidden), and a LEFT press
	 * that toggles the sidebar's amounts and stores the choice ({@link #pressHideAmounts}). It carries the settings icon's
	 * insets ({@link SupportLinks#iconBorder}), so it has the same hit area. Its look is {@link #renderEye}'s business.
	 */
	private JLabel buildEye()
	{
		final JLabel eye = new JLabel();
		eye.setBorder(SupportLinks.iconBorder());
		eye.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		eye.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (Widgets.isPress(e))
				{
					pressHideAmounts();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				eyeHot = true;
				renderEye();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				eyeHot = false;
				renderEye();
			}
		});
		eyeLabel = eye;
		renderEye();
		return eye;
	}

	/**
	 * The eye drawn for the state it is in: open in grey 52 while the amounts show, slashed in grey 165 while they are hidden,
	 * white in both under the mouse ({@link EyeIcon#ink}, part I) - and the hover that says what a press does.
	 */
	private void renderEye()
	{
		eyeLabel.setIcon(EyeIcon.icon(hideAmounts, EyeIcon.ink(hideAmounts, eyeHot)));
		eyeLabel.setToolTipText(hideAmounts ? SHOW_AMOUNTS_TIP : HIDE_AMOUNTS_TIP);
	}

	/**
	 * How wide the total's line must leave the Refresh link, in px: the widest of the link's three texts
	 * ({@link RefreshPhase}) with its insets, so the number never runs under "Refreshing..." however long the link is
	 * talking. Measured with the link's own font, like every fit in this panel.
	 */
	private int refreshReserve()
	{
		final FontMetrics fm = refreshLabel.getFontMetrics(refreshLabel.getFont());
		int widest = 0;
		for (RefreshPhase phase : RefreshPhase.values())
		{
			widest = Math.max(widest, fm.stringWidth(phase.text));
		}
		return widest + refreshLabel.getInsets().left + refreshLabel.getInsets().right;
	}

	/** {@link Widgets#bar} on a see-through ground, for the rows inside the hero card. */
	private static JPanel transparentBar(int gap, @Nullable JComponent west, @Nullable JComponent centre,
		@Nullable JComponent east)
	{
		final JPanel bar = Widgets.bar(gap, west, centre, east);
		bar.setOpaque(false);
		return bar;
	}

	/**
	 * A message card: the message in the middle as it always was, and {@code pair} - the Discord mark and the settings
	 * gear ({@link SupportLinks#supportPair}, 1.0.9) - at the right end of a bar of its own above it. The hero card, which carries
	 * the settings gear, is not drawn at the login and no-bank cards, and the user's reason for this bar was that a
	 * player who gets no further into the plugin than one of them has otherwise no way to "troubleshoot if this is as
	 * far as they load into the plugin".
	 */
	private static JPanel messageCard(String title, String description, JComponent pair)
	{
		final PluginErrorPanel message = new PluginErrorPanel();
		typeMessage(message);
		message.setContent(title, description);
		final JPanel bar = transparentBar(ROW_GAP, null, null, pair);
		bar.setBorder(new EmptyBorder(MARGIN, 0, 0, MARGIN));
		final JPanel card = new JPanel(new BorderLayout());
		card.setOpaque(false);
		card.add(bar, BorderLayout.NORTH);
		card.add(message, BorderLayout.CENTER);
		return Widgets.north(card);
	}

	/**
	 * Puts a {@link PluginErrorPanel}'s two labels into THIS panel's type (N section 3 §2), because it sets
	 * neither: its title inherits the look and feel's default - under {@code RuneLiteLAF} the 16 px bitmap
	 * RuneScape face ({@code RuneLiteLAF.java:132}) - and its description is
	 * {@code getRunescapeSmallFont()} in {@code Color.GRAY}, which measures 3.73:1 on the sidebar's ground.
	 * These three cards are the FIRST screen a new user sees, so the panel would introduce itself in one
	 * typeface and then work in another.
	 *
	 * <p>The labels are private to that class, so they are reached as its children - the title in
	 * {@code BorderLayout.NORTH}, the description in {@code CENTER} ({@code PluginErrorPanel.java:53-61}).
	 * {@code setContent} only sets text and calls {@code setVisible}, so a font set once here survives every
	 * later rewrite of the EMPTY card's description.
	 */
	private static void typeMessage(PluginErrorPanel message)
	{
		final Component title = ((BorderLayout) message.getLayout()).getLayoutComponent(BorderLayout.NORTH);
		final Component description = ((BorderLayout) message.getLayout()).getLayoutComponent(BorderLayout.CENTER);
		if (title instanceof JLabel)
		{
			title.setFont(Widgets.sansBold(16));
			title.setForeground(Color.WHITE);
		}
		if (description instanceof JLabel)
		{
			description.setFont(Widgets.sans(12));
			description.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
	}

	/**
	 * Puts exactly {@code want}, in order, into {@code parent} - and touches nothing when the set is already
	 * right, so a repaint that changes nothing causes no flicker (C30). Rows and lines are added and removed,
	 * never hidden: a hidden component still takes its place in a {@code DynamicGridLayout} column (playbook
	 * 7.5).
	 *
	 * <p><b>A diff, not a rebuild.</b> Only the children that are NOT wanted are removed, and only the missing
	 * ones are added, each at its place; a child that stays is never removed and never re-added. That matters
	 * because {@code removeAll()} tears down the peer of everything under it: with the price fold open and the
	 * caret in a gp field, a publish that merely added or dropped the problem row took the focus off that field
	 * permanently, and the field's own focus-lost handler then applied whatever half of "100k" had been typed.
	 * ({@code Container.addImpl} removes a component from its current parent first, so re-adding a stayer would
	 * be exactly the same tear-down - hence inserting the missing ones instead.) The header's four rows always
	 * keep their relative order, which is what makes the insert land the right list; anything else falls back to
	 * the wholesale replacement rather than painting a wrong card.
	 *
	 * @return whether anything moved
	 */
	private static boolean replaceChildren(Container parent, List<Component> want)
	{
		if (want.equals(Arrays.asList(parent.getComponents())))
		{
			return false;
		}
		for (int i = parent.getComponentCount() - 1; i >= 0; i--)
		{
			if (!want.contains(parent.getComponent(i)))
			{
				parent.remove(i);
			}
		}
		for (int i = 0; i < want.size(); i++)
		{
			final Component c = want.get(i);
			if (i >= parent.getComponentCount() || parent.getComponent(i) != c)
			{
				parent.add(c, i);
			}
		}
		if (!want.equals(Arrays.asList(parent.getComponents())))
		{
			parent.removeAll();
			for (Component c : want)
			{
				parent.add(c);
			}
		}
		parent.revalidate();
		parent.repaint();
		return true;
	}

	/**
	 * Keeps the pinned header exactly as wide as the row cards scrolling under it.
	 *
	 * <p>The panel is {@code super(false)}, so RuneLite gives it {@code PANEL_WIDTH + SCROLLBAR_WIDTH} = 242 px
	 * ({@code PluginPanel.java:88-92}), not the 225 px {@link #MARGIN} is derived from. The header sits in
	 * {@code BorderLayout.NORTH} of that (contract C28 - a header inside the scroll pane would scroll away) and
	 * the list sits inside {@link #scroll}, so the moment the vertical bar appears the LIST loses its width (7 px
	 * under {@code RuneLiteLAF}) and the header does not: two {@code DARKER_GRAY} cards on one ground with their
	 * right edges 7 px apart, appearing and disappearing as the list crosses the scroll threshold.
	 *
	 * <p>So the header reserves the same gutter, MEASURED off the bar rather than hard-coded - the look and feel
	 * owns that number and the test JVM's is not the client's - and gives it back when the bar goes. The policy
	 * stays {@code AS_NEEDED}, except while a search is typed ({@link #syncBarPolicy}): reserving it always would
	 * leave a permanent empty track, and at a narrower host width it would push the header's content under the 213 px
	 * the design is measured at.
	 *
	 * <p><b>Only a card that shows a list is read (1.1.1 part S).</b> A bar is read off the pane that is ON SCREEN: the
	 * Items list's while {@link #CARD_LIST} shows, History's while {@link #CARD_HISTORY} does. Any other card is a
	 * message standing in for the list - the one a search or a band empties, the login and no-bank ones - and the
	 * pane behind it is hidden: the queued layout still lays it out, its bar is hidden by that layout, and the header
	 * used to follow it, so the search box and its clear x jumped 7 px to the right the moment a typed search matched
	 * nothing. The stand-in keeps what the Items list had ({@link #itemsGutter}), so the header does not move when the
	 * list does, and coming back from History to an empty Items card does not inherit History's gutter either.
	 */
	private void syncGutter()
	{
		final int want;
		if (CARD_HISTORY.equals(card))
		{
			// AU (amendment 9.8): the History card has a scroll pane of its own, and the header must line up with it.
			final JScrollBar bar = historyScroll.getVerticalScrollBar();
			want = bar.isVisible() ? bar.getWidth() : 0;
		}
		else if (CARD_LIST.equals(card))
		{
			final JScrollBar bar = scroll.getVerticalScrollBar();
			itemsGutter = bar.isVisible() ? bar.getWidth() : 0;
			want = itemsGutter;
		}
		else
		{
			want = itemsGutter;
		}
		if (want == gutter)
		{
			return;
		}
		gutter = want;
		header.setBorder(new EmptyBorder(MARGIN, MARGIN, GAP, MARGIN + want));
		header.revalidate();
		header.repaint();
	}

	/**
	 * Decides whether the Items list's scroll bar is reserved while a search is typed (1.1.1 part S): ALWAYS if the
	 * list the box would show EMPTY - every row the panel holds, before {@link MovementMath#search}, less the alch rows
	 * the tick keeps out - is taller than the window it scrolls in, {@code AS_NEEDED} otherwise and whenever the box is
	 * empty.
	 *
	 * <p><b>The bar belongs to the bank, not to the search result.</b> Left to {@code AS_NEEDED} a search that narrows a
	 * long list below a screenful took the bar away, and the header - which reserves the bar's gutter so its cards end
	 * on the same pixel as the rows (B038) - followed it 7 px to the right, under the reader's cursor, on a keystroke.
	 * Kept as an empty track the bar costs nothing the reader sees, and nothing in the header or the rows moves; a
	 * short bank that never needed a bar never gets one. The decision is made again on every search change, publish and
	 * change of the tick (all through {@link #rebuildRows} or {@link #applyShowAlchRows}) and on the window's resize.
	 *
	 * <p>The height is the rows' own: {@link MovementRowPanel#ROW_HEIGHT} each with {@link #ROWS_GAP} between and the
	 * list's bottom margin, a row opened in place counted at its closed height. A window that has not been laid out
	 * yet has no height to compare with and reads as no bar; the resize asks again.
	 */
	private void syncBarPolicy()
	{
		final int want = !search.isEmpty() && fullListNeedsBar()
			? ScrollPaneConstants.VERTICAL_SCROLLBAR_ALWAYS : ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED;
		// setVerticalScrollBarPolicy revalidates even when nothing changed, so it is only called for a change.
		if (scroll.getVerticalScrollBarPolicy() != want)
		{
			scroll.setVerticalScrollBarPolicy(want);
		}
	}

	/** {@link #syncBarPolicy}'s question: is the whole list, with no search, taller than the window it scrolls in. */
	private boolean fullListNeedsBar()
	{
		final int window = scroll.getViewport().getHeight();
		if (window <= 0)
		{
			return false;
		}
		final int count = MovementMath.list(rows, "", showAlchRows).size();
		if (count == 0)
		{
			return false;
		}
		if (count > ROWS_PER_PAGE)
		{
			// More than a page is some 16,000 px and its "Show n more" row: no window is that tall.
			return true;
		}
		return count * MovementRowPanel.ROW_HEIGHT + (count - 1) * ROWS_GAP + MARGIN > window;
	}

	/** The gutter the header reserves for the list's scrollbar right now, in px (0 while there is no bar). */
	int gutter()
	{
		return gutter;
	}

	/**
	 * Syncs the gutter before laying out, so a header built at one width is measured against the list at the
	 * same one. The bar's own {@code ComponentListener} catches the case where it is the bar, and not the panel,
	 * that changed.
	 */
	@Override
	public void doLayout()
	{
		syncGutter();
		super.doLayout();
	}

	// ---------------------------------------------------------------- Activatable (sidebar shown / hidden)

	/**
	 * The sidebar opened on this panel: the service may fetch and schedule (contract C33 / C24).
	 *
	 * <p>Who calls this: {@code PluginPanel implements Activatable} ({@code PluginPanel.java:36},
	 * {@code Activatable.java:29-33} - default no-op hooks), and the sidebar's tab-change listener hands the
	 * outgoing panel to {@code SwingUtil.deactivate} and the incoming one to {@code SwingUtil.activate}
	 * ({@code ClientUI.java:407-441}, clone tag runelite-parent-1.12.37). Closing the sidebar deactivates the
	 * selected panel the same way, which is what makes "nothing while hidden" (design D8) hold.
	 *
	 * <p>Coming back does not end addendum AS's hold: a reader who opens the sidebar in the middle of banking gets the
	 * list as it stood and the glowing link, and the stored publish waits for the bank to close or for their click -
	 * "nothing redraws while you bank unless you click" (section 7.1).
	 */
	@Override
	public void onActivate()
	{
		if (stopped)
		{
			return;
		}
		active = true;
		// The stored publish, replayed - unless the bank is open, which holds it exactly as hiding did (AS 7.2).
		releaseHeld();
		// ...and the ring, if a change is owed: the reader can see the link again.
		syncGlow();
		service.setVisible(true);
	}

	/**
	 * The sidebar closed or moved on: nothing is fetched while nobody is looking (design D8), and nothing is
	 * BUILT either - {@link #onRows} stores the next publish instead of laying out a page of rows nobody can see
	 * ({@link #active}). The ring round the Refresh link goes out too (AS 7.3): 25 repaints a second of a ring
	 * nobody can see is the cost addendum AS exists to take away.
	 */
	@Override
	public void onDeactivate()
	{
		closeMenus();
		active = false;
		syncGlow();
		if (!stopped)
		{
			service.setVisible(false);
		}
	}

	/**
	 * shutDown: stops listening, drops the rows, and leaves nothing ticking - the acknowledgement's timer and the
	 * glow's (AGENTS.md: scheduled work is cancelled in shutDown). The plugin's open-bank hook is dropped as well, so
	 * a dead panel pins no plugin. Idempotent; the panel is dead afterwards.
	 */
	public void stop()
	{
		stopped = true;
		closeMenus();
		clearRefreshAck();
		stopGlow();
		bankRefresh = null;
		gameFocus = NO_HAND_OVER;
		service.removeListener(listener);
		rows = Collections.emptyList();
		matching = Collections.emptyList();
		pendingPublish = false;
		pendingRows = null;
		pendingStatus = null;
		images.clear();
		rowsColumn.removeAll();
		shown = 0;
		updateShowMore();
		renderControl();
		rowsColumn.revalidate();
		rowsColumn.repaint();
	}

	// ---------------------------------------------------------------- the hero switches (EDT, O2-O4)

	/**
	 * The switches changed under us (the plugin's {@code ConfigChanged} for one of the three keys): puts the
	 * right lines into the card, repaints it and its tooltip, and ticks the menu to match. Saves nothing back -
	 * the config already knows - and the same value again is a harmless repaint. The card's OWN write does not
	 * come back this way at all: the plugin marks {@code saveHero}'s three keys as its own and drops the events
	 * they post ({@code BankPriceMovementPlugin.prefsWriter}), because {@link #setHeroVisibility} has already
	 * applied the whole value here. Null reads as {@link HeroVisibility#ALL}.
	 */
	public void applyHeroVisibility(@Nullable HeroVisibility next)
	{
		if (stopped)
		{
			return;
		}
		heroVisibility = next == null ? HeroVisibility.ALL : next;
		syncHeroMenu();
		renderValue();
	}

	/**
	 * The card's own switch (O4: a check item of its right-click menu): applies at once AND writes the choice
	 * through {@link Prefs#saveHero}, so the stored config follows; the {@code ConfigChanged} events that write
	 * posts are the plugin's own and are dropped there rather than re-rendering this card once per key (see
	 * {@link #applyHeroVisibility}). Nothing is written when nothing changed.
	 *
	 * <p>An ALREADY-OPEN settings page keeps the old tick until it is re-entered from the plugin list - RuneLite
	 * rebuilds a {@code ConfigPanel} only then (see the class javadoc). The value on disk is right either way,
	 * and {@code bpm state | jq .result.hero} shows it at once.
	 */
	public void setHeroVisibility(@Nullable HeroVisibility next)
	{
		final HeroVisibility v = next == null ? HeroVisibility.ALL : next;
		final boolean changed = !v.equals(heroVisibility);
		applyHeroVisibility(v);
		if (changed && !updating)
		{
			prefs.saveHero(v);
		}
	}

	/** Which of the card's three figures are drawn right now; never null. */
	public HeroVisibility heroVisibility()
	{
		return heroVisibility;
	}

	/**
	 * Pins what the card calls "today" when it stamps the bank snapshot ({@link #provenanceText}), and what the
	 * gear calls "just now" when it asks how long ago its menu closed ({@link #gearPressOpens}, AB1) - for the
	 * tests and the headless renderer, whose fixtures carry a fixed capture instant. The client leaves it at the
	 * wall clock.
	 */
	void setClock(LongSupplier now)
	{
		clock = now == null ? System::currentTimeMillis : now;
		// AU: "today" moved, so the History card's chips, move and footnote are read again, and so is the view -
		// whose clock is a lambda over this same field (amendment 9.1). In Items both calls repaint nothing new.
		renderChips();
		renderValue();
		showHistory();
	}

	/**
	 * Puts the right lines into the card and the right figures onto the move line (O3): the caption row, the
	 * strip, the footnote and the update line always; the total while {@code value} is on; the move line while
	 * {@code gp} or {@code pct} is - carrying the triangle, then the gp figure while {@code gp} is on, then the
	 * percentage while {@code pct} is. Nothing prints a placeholder for a hidden figure: the card simply shrinks.
	 */
	private void syncHero()
	{
		// The total's LINE is always in the card - the gear lives on it (Q1) - and the figure comes and goes
		// inside it. So the card shrinks by the 28 px figure when the total is switched off, not by the line.
		final List<Component> lines = new ArrayList<>(6);
		lines.add(captionRow);
		lines.add(totalRow);
		if (heroVisibility.moveLine())
		{
			lines.add(moveLine);
		}
		lines.add(stripHolder);
		lines.add(footnoteLabel);
		// S1: last, under the footnote and before the card's bottom padding, in every state - the figures can be
		// switched off, the sentence explaining why they sit still cannot.
		lines.add(updateLabel);
		replaceChildren(hero, lines);
		// Not through replaceChildren: that adds by INDEX, and an index-added child of a BorderLayout lands in
		// the centre - which would put the total where the layout has no constraint for it. One child, one
		// constraint, added and removed like the EMPTY card's button.
		final boolean wantTotal = heroVisibility.value();
		if (wantTotal != (totalLabel.getParent() == totalRow))
		{
			if (wantTotal)
			{
				totalRow.add(totalLabel, BorderLayout.WEST);
			}
			else
			{
				totalRow.remove(totalLabel);
			}
			totalRow.revalidate();
			totalRow.repaint();
		}

		final List<Component> parts = new ArrayList<>(3);
		parts.add(triangleLabel);
		if (heroVisibility.gp())
		{
			parts.add(deltaLabel);
		}
		if (heroVisibility.pct())
		{
			parts.add(pctLabel);
		}
		replaceChildren(moveLine, parts);
	}

