	/**
	 * The panel's and the bridge's way into the config. Writing a widget's value back through
	 * {@link ConfigManager} rather than holding it in the panel is what makes the sidebar and the config panel
	 * one switch: the write posts a {@code ConfigChanged} that {@link #onConfigChanged} turns back into a
	 * filter for whichever half did not make the change.
	 *
	 * <p>{@code gpMin}/{@code gpMax} are stored as {@code int} (a gp band above 2^31 is not a band), so a
	 * filter carrying more is clamped rather than wrapped.
	 *
	 * <p><b>The card's three switches ride the same seam</b> (O2): {@code Prefs.loadHero} / {@code saveHero}
	 * are the panel's way to {@code showBankValue} / {@code showBankMoveGp} / {@code showBankMovePct}, so
	 * ticking one of the hero card's right-click check items writes the config and RuneLite's own settings
	 * panel follows on the {@code ConfigChanged} that write posts - the same round trip the filter widgets have
	 * always made. Both are {@code default} on the interface so a test's throwaway {@code Prefs} need not care;
	 * the plugin MUST override them, or a check item would re-render the card and forget the choice on the next
	 * launch.
	 *
	 * <p><b>And the gear menu's three boxes</b> (Z1): {@code loadPresets} / {@code savePresets} are the way to
	 * {@code bandPresets}, so a preset typed into a box at the foot of the menu is what RuneLite's settings page
	 * then shows on one line, and what the next launch opens the fold with. The save half does LESS than
	 * {@code saveHero} rather than more - one key, no service - because nothing behind the chips is computed.
	 *
	 * <p><b>And the band button itself</b> (AA1): {@code loadFoldOpen} / {@code saveFoldOpen} are the way to
	 * {@code foldOpen}, the same one-key-no-service shape as the pair above, so a fold the reader shut stays shut
	 * across a relaunch and RuneLite's settings page shows the switch unticked. The load half answers a
	 * {@code Boolean} the panel treats as "nothing stored = open"; this implementation never answers null, the
	 * config having a default of its own.
	 *
	 * <p><b>And so do the settings menu's five switches</b> (Q3, T1, Y1, 1.0.9 part 3): {@code loadOptions} /
	 * {@code saveOptions} are the way
	 * to {@code countCash} / {@code countUntradeables} / {@code livePrices} / {@code countInventory} /
	 * {@code countGrandExchange} - a sixth, {@code holdingOnRows}, travelled here until addendum AO deleted it (AO1),
	 * and a seventh, {@code showHoverText}, until release 1.2.0 did.
	 * The save half does one thing more
	 * than {@code saveHero} does, and the comment inside it says why: the switch it wrote is suppressed on the
	 * {@code ConfigChanged} round trip as this thread's own write, and three of the five change figures the
	 * SERVICE owns, so it is told directly.
	 */
	BankPriceMovementPanel.Prefs configPrefs()
	{
		return new BankPriceMovementPanel.Prefs()
		{
			@Override
			public RowFilter load()
			{
				return filterFromConfig();
			}

			@Override
			public void save(RowFilter filter)
			{
				if (filter == null)
				{
					return;
				}
				final ConfigManager cm = configManager;
				if (cm == null)
				{
					return;
				}
				// The five writes are ONE change of mind, and each one posts a ConfigChanged on this very
				// thread as it lands. Marking the thread keeps onConfigChanged out of the middle of them: see
				// prefsWriter. Restored rather than nulled, so a nested save (there is none today) still ends
				// with the outer one's mark in place.
				final Thread outer = prefsWriter;
				prefsWriter = Thread.currentThread();
				try
				{
					cm.setConfiguration(BankPriceMovementConfig.GROUP, "gpMin", clampToInt(filter.gpMin()));
					cm.setConfiguration(BankPriceMovementConfig.GROUP, "gpMax", clampToInt(filter.gpMax()));
					cm.setConfiguration(BankPriceMovementConfig.GROUP, "sortMode", filter.sort());
					cm.setConfiguration(BankPriceMovementConfig.GROUP, "sortDescending", filter.descending());
					cm.setConfiguration(BankPriceMovementConfig.GROUP, "window", filter.window());
				}
				finally
				{
					prefsWriter = outer;
				}
			}

			@Override
			public HeroVisibility loadHero()
			{
				return heroFromConfig();
			}

			@Override
			public void saveHero(HeroVisibility hero)
			{
				final ConfigManager cm = configManager;
				if (hero == null || cm == null)
				{
					return;
				}
				// The three writes are ONE change of mind, exactly as save's five are, and they are marked for
				// the same reason: each posts a ConfigChanged on this very thread as it lands, and the check
				// item that was ticked has already painted the card itself (setHeroVisibility applies, then
				// calls this). Unmarked, one tick re-rendered the card three more times - twice from a config
				// in which only some of the three keys had been written. See prefsWriter.
				final Thread outer = prefsWriter;
				prefsWriter = Thread.currentThread();
				try
				{
					// All three every time: a check item that only wrote its own key would leave the other two
					// unstored the first time a fresh profile touches the menu.
					cm.setConfiguration(BankPriceMovementConfig.GROUP, SHOW_VALUE_KEY, hero.value());
					cm.setConfiguration(BankPriceMovementConfig.GROUP, SHOW_GP_KEY, hero.gp());
					cm.setConfiguration(BankPriceMovementConfig.GROUP, SHOW_PCT_KEY, hero.pct());
				}
				finally
				{
					prefsWriter = outer;
				}
			}

			@Override
			public ViewOptions loadOptions()
			{
				return optionsFromConfig();
			}

			@Override
			public void saveOptions(ViewOptions options)
			{
				if (options == null)
				{
					return;
				}
				final ConfigManager cm = configManager;
				if (cm != null)
				{
					// Five writes since release 1.2.0 (six from 1.0.9 part 3 to 1.1.2), one change of mind, guarded
					// exactly as saveHero's three are: ConfigManager posts a ConfigChanged on this very thread as
					// each key lands, and the check item that was ticked has already applied the switch itself.
					// Unguarded, ticking one item would recompute the whole bank value again for every other key,
					// from a config in which only some of the five had been written - and each of those figures
					// would be wrong on screen for as long as the recompute took.
					final Thread outer = prefsWriter;
					prefsWriter = Thread.currentThread();
					try
					{
						// All five every time, for saveHero's reason: an item that wrote only its own key would
						// leave the others unstored the first time a fresh profile touched the menu.
						cm.setConfiguration(BankPriceMovementConfig.GROUP, COUNT_CASH_KEY, options.countCash());
						cm.setConfiguration(BankPriceMovementConfig.GROUP, COUNT_UNTRADEABLES_KEY,
							options.countUntradeables());
						// T1, and the one of the five that is worth a fetch: PriceService stops asking for the
						// traded feeds altogether when this goes off, so it must be stored before the service is
						// told below or a relaunch would quietly turn them back on.
						cm.setConfiguration(BankPriceMovementConfig.GROUP, LIVE_PRICES_KEY, options.livePrices());
						// Y1. Nothing is fetched for this one - the inventory and the worn gear come from the
						// client, not from the wiki - but it is stored the same way and before the service is
						// told below, or the choice would be forgotten by the next launch.
						cm.setConfiguration(BankPriceMovementConfig.GROUP, COUNT_INVENTORY_KEY,
							options.countInventory());
						// 1.0.9 part 3. The Grand Exchange offers come from the client the same way, and it is stored
						// with the rest before the service is told below.
						cm.setConfiguration(BankPriceMovementConfig.GROUP, COUNT_GRAND_EXCHANGE_KEY,
							options.countGrandExchange());
					}
					finally
					{
						prefsWriter = outer;
					}
				}
				// ...and then, OUTSIDE the guard and whether or not there was a manager to write to, the half the
				// guard just suppressed. The gear's check item paints the card and the rows itself, but the sums
				// behind the bank value are the service's (Q4/Q5), and the ConfigChanged that would have carried
				// them was skipped as this thread's own write. A service that already holds these options does
				// nothing with them, so saying it here as well as on the config round trip cannot double-count.
				final PriceService s = service;
				if (s != null)
				{
					s.setOptions(options);
				}
			}

			@Override
			public BandPresets loadPresets()
			{
				return presetsFromConfig();
			}

			@Override
			public void savePresets(BandPresets presets)
			{
				if (presets == null)
				{
					return;
				}
				final ConfigManager cm = configManager;
				if (cm == null)
				{
					return;
				}
				// ONE key, and still guarded (see prefsWriter): ConfigManager posts its ConfigChanged on this very
				// thread as the write lands, and the boxes that made the change have already applied it to the fold
				// themselves (BankPriceMovementPanel.setPresets applies, then calls this). The round trip would
				// therefore relabel four chips that are already right, from the EDT, while the user is still typing
				// in the next box.
				//
				// Nothing else happens here - no setOptions tail as saveOptions has, and no setFilter: the service
				// has never been told what the chips offer, because it decides nothing about them.
				final Thread outer = prefsWriter;
				prefsWriter = Thread.currentThread();
				try
				{
					// The stored form is the value's OWN text (Z1): ascending, trimmed, in the shorthand the boxes
					// print, so what the settings page shows and what the three boxes show are the same string.
					cm.setConfiguration(BankPriceMovementConfig.GROUP, BAND_PRESETS_KEY, presets.format());
				}
				finally
				{
					prefsWriter = outer;
				}
			}

			@Override
			public Boolean loadFoldOpen()
			{
				return foldOpenFromConfig();
			}

			@Override
			public void saveFoldOpen(boolean open)
			{
				final ConfigManager cm = configManager;
				if (cm == null)
				{
					return;
				}
				// ONE key and no service, exactly as savePresets above (AA1), and guarded for the same reason:
				// ConfigManager posts its ConfigChanged on this very thread as the write lands, and the band
				// button that made the change has already taken the fold out of the header itself
				// (BankPriceMovementPanel.pressFold applies, then calls this). The round trip would re-lay the
				// header a second time for a state it is already in.
				final Thread outer = prefsWriter;
				prefsWriter = Thread.currentThread();
				try
				{
					cm.setConfiguration(BankPriceMovementConfig.GROUP, FOLD_OPEN_KEY, open);
				}
				finally
				{
					prefsWriter = outer;
				}
			}

			@Override
			public SidebarView loadStartTab()
			{
				return startTabFromConfig();
			}

			@Override
			public void saveStartTab(SidebarView tab)
			{
				final ConfigManager cm = configManager;
				if (tab == null || cm == null)
				{
					return;
				}
				// ONE key and no service, guarded as saveFoldOpen is: the toggle has already moved itself, and
				// the ConfigChanged this write posts on this thread would only move it again.
				final Thread outer = prefsWriter;
				prefsWriter = Thread.currentThread();
				try
				{
					cm.setConfiguration(BankPriceMovementConfig.GROUP, START_TAB_KEY, tab);
				}
				finally
				{
					prefsWriter = outer;
				}
			}

			@Override
			public Boolean loadIncludeLegacy()
			{
				return includeLegacyFromConfig();
			}

			@Override
			public void saveIncludeLegacy(boolean include)
			{
				final ConfigManager cm = configManager;
				if (cm == null)
				{
					return;
				}
				// ONE key and no service, guarded as saveFoldOpen is (1.0.9 part 5): the menu item that was ticked has
				// already redrawn the tab itself (BankPriceMovementPanel.pressLegacy applies, then calls this), and the
				// ConfigChanged this write posts on this thread would only draw it a second time.
				final Thread outer = prefsWriter;
				prefsWriter = Thread.currentThread();
				try
				{
					cm.setConfiguration(BankPriceMovementConfig.GROUP, INCLUDE_LEGACY_KEY, include);
				}
				finally
				{
					prefsWriter = outer;
				}
			}

			@Override
			public Color loadUpColour()
			{
				return upColourFromConfig();
			}

			@Override
			public void saveUpColour(Color colour)
			{
				saveColour(UP_COLOUR_KEY, colour);
			}

			@Override
			public Color loadDownColour()
			{
				return downColourFromConfig();
			}

			@Override
			public void saveDownColour(Color colour)
			{
				saveColour(DOWN_COLOUR_KEY, colour);
			}

			@Override
			public Color loadSlotUpColour()
			{
				return slotUpFromConfig();
			}

			@Override
			public void saveSlotUpColour(Color colour)
			{
				saveColour(SLOT_UP_KEY, colour);
			}

			@Override
			public Color loadSlotDownColour()
			{
				return slotDownFromConfig();
			}

			@Override
			public void saveSlotDownColour(Color colour)
			{
				saveColour(SLOT_DOWN_KEY, colour);
			}

			@Override
			public Boolean loadSingleChartColour()
			{
				return singleChartFromConfig();
			}

			@Override
			public void saveSingleChartColour(boolean single)
			{
				saveColour(SINGLE_CHART_KEY, single);
			}

			@Override
			public Color loadChartColour()
			{
				return chartColourFromConfig();
			}

			@Override
			public void saveChartColour(Color colour)
			{
				saveColour(CHART_COLOUR_KEY, colour);
			}

			@Override
			public Boolean loadHideAmounts()
			{
				return hideAmountsFromConfig();
			}

			@Override
			public void saveHideAmounts(boolean hide)
			{
				// One key and no service, guarded like the colour switches: the eye that was pressed has already redrawn the
				// sidebar itself (BankPriceMovementPanel.pressHideAmounts applies, then calls this).
				saveColour(HIDE_AMOUNTS_KEY, hide);
			}

			@Override
			public Boolean loadShowAlchRows()
			{
				return showAlchFromConfig();
			}

			@Override
			public void saveShowAlchRows(boolean show)
			{
				// One key and no service, guarded like the eye's: the tick that was pressed has already redrawn the list itself
				// (BankPriceMovementPanel.pressShowAlchRows applies, then calls this).
				saveColour(SHOW_ALCH_KEY, show);
			}
		};
	}

	/**
	 * ONE colour or colour-switch key and no service, guarded as {@code saveFoldOpen} is (1.1.0 parts B and C): the picker,
	 * the menu item or the Reset button that made the change has already drawn the sidebar in it itself (the panel
	 * applies, then calls this), and the {@code ConfigChanged} this write posts on this thread would only draw it a second
	 * time.
	 */
	private void saveColour(String key, @Nullable Object value)
	{
		final ConfigManager cm = configManager;
		if (value == null || cm == null)
		{
			return;
		}
		final Thread outer = prefsWriter;
		prefsWriter = Thread.currentThread();
		try
		{
			cm.setConfiguration(BankPriceMovementConfig.GROUP, key, value);
		}
		finally
		{
			prefsWriter = outer;
		}
	}

	private static Integer clampToInt(long gp)
	{
		if (gp <= 0)
		{
			return 0;
		}
		return (int) Math.min(gp, Integer.MAX_VALUE);
	}

	// ---------------------------------------------------------------- account identity

	/**
	 * CLIENT THREAD. Reads and caches the logged-in account's hash and RuneScape profile type, and answers the
	 * hash. {@code Client.getAccountHash()} comes from {@code com.jagex.oldscape.pub.OAuthApi} (clone
	 * OAuthApi.java:32) and {@code RuneScapeProfileType.getCurrent(client)} (clone RuneScapeProfileType.java:60)
	 * never answers null, so the pair {@link PriceStore} keys its files on is always well formed.
	 */
	private long rememberAccount()
	{
		final long hash = client.getAccountHash();
		accountHash = hash;
		profileType = RuneScapeProfileType.getCurrent(client).name();
		return hash;
	}

	/** The cached pair, for the dev bridge's synthetic {@code bank=} (developer mode only). */
	private BpmCommands.Account account()
	{
		return new BpmCommands.Account()
		{
			@Override
			public long hash()
			{
				return accountHash;
			}

			@Override
			public String profileType()
			{
				return profileType;
			}
		};
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemMapping;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Turns the raw bank container into the priceable {@link BankSnapshot} the rest of 2h Bank Portfolio Tracker works
 * from (contract lines C11 and C12).
 *
 * <p>Since addendum Y line Y2 the same rules read two more containers: {@link #readContainers} turns the player's
 * INVENTORY and WORN gear into a {@link Carried}, which {@link BankSnapshot#withCarried(Carried)} hangs on the
 * snapshot so "Include inventory and worn gear" can count and list those stacks beside the bank's. Since 1.0.9
 * part 3 it reads a third source through the same walk - the items in the player's Grand Exchange offers
 * ({@link ExchangeOffers}) - so "Include Grand Exchange offers" can do the same for them.
 *
 * <p><b>Client thread only.</b> {@link #read} calls {@link ItemManager#canonicalize(int)} and
 * {@link ItemManager#getItemComposition(int)}, and both bottom out in {@code client.getItemDefinition(int)}
 * (clone {@code runelite-client/src/main/java/net/runelite/client/game/ItemManager.java:459-462, :467-482};
 * {@code runelite-api/src/main/java/net/runelite/api/Client.java:393-394}), which reads the live item cache.
 * The one caller is the plugin's {@code onItemContainerChanged} handler, which the client dispatches on the
 * client thread. Everything the method touches afterwards is plain data, so the finished snapshot can be
 * handed straight to the executor and the EDT.
 *
 * <p>Why each skip rule exists, in the order C11 lists them:
 * <ul>
 * <li>{@code null} entries and {@code id <= 0}: core's own bank valuation walks the array with exactly this
 * guard (clone {@code .../plugins/bank/BankPlugin.java:608-634}, the {@code id <= 0 || qty == 0} test at
 * :624) because an item container is a fixed-size array padded with empty slots.</li>
 * <li>{@code quantity <= 0}: the empty slot. Until 1.1.1 this was also the rule that removed BANK PLACEHOLDERS, on
 * the belief that one sits in container 95 as its own item id with quantity 0 (research claim C9, 2026-09-08); a
 * client that puts a quantity on a placeholder let it through, {@link ItemManager#canonicalize(int)} folded it onto
 * the real item and it was counted (GitHub issue #1, 2026-10-07). The test stays as the free first filter, so a slot
 * of 0 never costs a lookup, and the placeholders themselves are dropped by their definition, next.</li>
 * <li>A placeholder DEFINITION: the RAW id's composition answers {@code getPlaceholderTemplateId() != -1} (14401 on a
 * placeholder, -1 on every other item - the real item that OWNS a placeholder, a note and a worn variant included).
 * Whatever quantity the client put on it, it is dropped, and it is asked BEFORE {@link ItemManager#canonicalize(int)},
 * which would otherwise fold it onto the real item and count a ghost. The dropped slots that held a quantity are
 * counted per bank read ({@link #placeholdersSkipped}), so a real client can say whether the game ever sends one.</li>
 * <li>{@code BANK_FILLER} (20594, clone {@code runelite-api/.../gameval/ItemID.java:50013}): the grey filler
 * the bank layout uses for spacing. Core skips it in the same place (BankPlugin.java:589-606, the test at
 * :600).</li>
 * <li>{@code COINS} (995, ItemID.java:3280) and {@code PLATINUM} (13204, ItemID.java:44396): currency, not a
 * traded item. RuneLite hard-codes their prices at 1 and 1000 rather than looking them up
 * (ItemManager.java:328-337), and the wiki price feed has no market for them, so a movement row would always
 * read 0 %. They are tested on the RAW id only, which is enough: the sole way a currency id could appear
 * after canonicalisation is as its own bank placeholder, and that is dropped by its definition (a placeholder
 * has an id of its own, so its raw id is no currency id and it is never worth cash either).
 * Skipped as a ROW is not the same as thrown away, though: since B097 their WORTH leaves with the snapshot as
 * {@link BankSnapshot#currencyGp}, because a "bank value" that omits the player's cash disagrees with the total
 * the bank interface itself has just shown them. {@link #currencyWorth} is that sum, and the only place it is
 * defined.</li>
 * <li>{@code !isGeTradeable()} on the CANONICAL composition (clone
 * {@code runelite-api/src/main/java/net/runelite/api/ItemComposition.java:145}): an item the Grand Exchange
 * does not list has no market price to move. It is the GE flag and not {@code isTradeable()} (:140, which
 * only means "can change hands between players") because the wiki price feed IS the exchange - core's own
 * exchange search filters on the same flag ({@code GrandExchangeSearchPanel.java:207}). Amended by the lead
 * 2026-09-08 13:55 (contract C11) and switched by the gate. NARROWED by addendum Q line Q5: such a stack is
 * skipped only when it has no High Alchemy value either ({@code getHaPrice()}, :120). One WITH a value is kept
 * and marked ({@link BankItem#untradeable}, {@link BankItem#haPrice}) so the service can list it at that value
 * ("Include alch-only untradeables", addendum AV); the switch itself lives in the service, not here, because a
 * snapshot that recorded only what the switch of the day wanted would need a bank visit every time it was flipped -
 * the same reasoning that puts {@link BankSnapshot#currencyGp} in every capture (P1). WIDENED again by addendum R
 * line R1: a kept untradeable stack also records what RuneLite maps it onto ({@link BankItem#parts},
 * {@link #partsOf}), so it can be valued at its tradeable parts instead - a Crystal body at three Crystal armour seeds
 * rather than at its 900k alch value.</li>
 * </ul>
 *
 * <p><b>The name is {@code getMembersName()}</b> (addendum L line L8 b, and K3 before it). On a members world
 * the two composition names are identical; on a FREE world {@code getName()} appends " (Members)" to every
 * members item (clone {@code runelite-api/src/main/java/net/runelite/api/ItemComposition.java:34-41} against
 * {@code :43-49}, "the real item name, even if the player is on a F2P server"). The wiki's guide table has no
 * such key, so an F2P player reading their bank with {@code getName()} would lose the price of every members
 * item in it. The name is only ever the SECOND-choice lookup anyway - {@code PriceService} resolves an id
 * through the {@code /mapping} table first, because the composition-name route silently answers another item's
 * price for 287 of 4,662 ids, one of them in the user's own bank (id 3159, "Karambwan vessel (baited)" - L-F).
 *
 * <p>Canonicalisation is what folds a NOTED stack onto the item it notes (and, for the handful of ids in
 * {@code ItemManager.WORN_ITEMS}, a worn variant onto its base). Two bank slots that canonicalise to the same
 * id therefore become ONE row with the quantities summed, so a bank holding 500 noted and 3 un-noted of the
 * same thing prices 503 of it once.
 *
 * <p>Deliberately NOT final, and {@link #read} deliberately not final: the plugin's wiring test mocks this
 * class, and Mockito 4.11 without {@code mockito-inline} cannot mock a final class or stub a final method.
 */
public class BankReader
{
	private static final Logger log = LoggerFactory.getLogger(BankReader.class);

	/**
	 * The bank's item-container id (clone {@code runelite-api/src/main/java/net/runelite/api/gameval/
	 * InventoryID.java:102}, {@code public static final int BANK = 95}). Container 95 is {@code @Nullable}
	 * and absent until the player opens the bank once in the session, which is why the plugin captures on
	 * the event rather than polling (research claim C7, 2026-09-08).
	 */
	public static final int BANK_CONTAINER_ID = InventoryID.BANK;

	/**
	 * The player's carried inventory (clone {@code runelite-api/src/main/java/net/runelite/api/gameval/
	 * InventoryID.java:100}, {@code public static final int INV = 93}) - read beside the bank since addendum Y,
	 * line Y2, by {@link #readContainers}.
	 */
	public static final int INVENTORY_CONTAINER_ID = InventoryID.INV;

	/**
	 * The player's worn equipment (clone {@code runelite-api/src/main/java/net/runelite/api/gameval/
	 * InventoryID.java:101}, {@code public static final int WORN = 94}) - the other half of what "Include inventory
	 * and worn gear" counts (Y2).
	 */
	public static final int WORN_CONTAINER_ID = InventoryID.WORN;

	/**
	 * Rows leave in name order so the panel's "no sort key" tail and the dev bridge's {@code state} echo are
	 * reproducible; the id breaks a tie so two genuinely different items sharing a display name (clue
	 * scrolls, for one) never swap places between two captures of the same bank.
	 *
	 * <p>Package-private since addendum Y: {@code PriceService} puts the MERGED stacks - the bank's and the carried
	 * ones folded together (Y3) - in this same order, and two lists the sidebar draws from must not be ordered by
	 * two different rules.
	 */
	static final Comparator<BankItem> BY_NAME_THEN_ID = (a, b) ->
	{
		final String left = a.name == null ? "" : a.name;
		final String right = b.name == null ? "" : b.name;
		final int byName = left.compareTo(right);
		return byName != 0 ? byName : Integer.compare(a.id, b.id);
	};

	/**
	 * Parts leave in id order, then quantity (addendum R, R1). {@code ItemMapping.map} answers a
	 * {@code HashMultimap}'s collection, whose iteration order over enum constants follows their IDENTITY hash
	 * codes and so differs from one JVM run to the next. An order of our own keeps a captured stack - and the
	 * tooltip sentence built from it - the same on every launch.
	 */
	private static final Comparator<BankItem.Part> BY_PART_ID = (a, b) ->
	{
		final int byId = Integer.compare(a.id, b.id);
		return byId != 0 ? byId : Long.compare(a.quantity, b.quantity);
	};

	/**
	 * What the player is CARRYING and WEARING at one moment (addendum Y, line Y2): the inventory's stacks and the
	 * worn gear's, each folded onto canonical ids by exactly the bank's rules, and the coins and platinum tokens in
	 * hand as a worth rather than as rows - the carried half of {@link BankSnapshot}, which {@link
	 * BankSnapshot#withCarried(Carried)} puts on a snapshot. Since 1.0.9 part 3 it holds a third list beside the two,
	 * the stacks in the player's Grand Exchange offers ({@link #exchange}), and the worth of any currency among them
	 * ({@link #exchangeGp}) - read at the same moment, so all three are stamped by the one {@link #readAtMillis}.
	 *
	 * <p>Public final fields and no accessors, like the snapshot it is folded into: it is one read's answer, handed
	 * straight on. Never mutated after {@link #readContainers} builds it; the three lists are unmodifiable.
	 */
	public static final class Carried
	{
		/** Nothing carried and nothing worn, read at no particular time - what a logged-out read answers. */
		public static final Carried EMPTY = new Carried(Collections.emptyList(), Collections.emptyList(), 0L, 0L);

		/** The inventory's stacks, canonical, quantity-summed and name-ordered; never null, possibly empty. */
		public final List<BankItem> inventory;

		/** The worn gear's stacks, by the same rules; never null, possibly empty. */
		public final List<BankItem> worn;

		/**
		 * What the coins and platinum tokens in hand are worth, in gp ({@link #currencyWorth}) - the carried half of
		 * {@link BankSnapshot#currencyGp}, counted only while "Include coins and platinum tokens" is on and never a
		 * row, for the same reason the bank's cash is not one (design D6).
		 */
		public final long carriedGp;

		/**
		 * The stacks the Grand Exchange offers hold - unsold in a sell offer, bought and uncollected in a buy offer -
		 * by the same rules; never null, possibly empty (1.0.9 part 3).
		 */
		public final List<BankItem> exchange;

		/**
		 * What the offers hold in COINS, in gp: the coins committed to buy offers and those received by sell offers
		 * and not yet collected ({@link ExchangeOffers#cashGp()}), plus the worth of any currency among the offers'
		 * items - none in practice, because the Grand Exchange trades no coins, but the one walk of a container has
		 * nowhere to lose one. Counted only while the Grand Exchange switch AND the coins switch are on, and never a
		 * row, for the same reason the carried cash is not one (1.0.9 part 3).
		 */
		public final long exchangeGp;

		/** When the containers were read, epoch millis; 0 means "never". */
		public final long readAtMillis;

		/**
		 * The three-source constructor of 1.0.9 part 3.
		 *
		 * @param inventory    the inventory's stacks; null becomes empty
		 * @param worn         the worn gear's stacks; null becomes empty
		 * @param exchange     the stacks in the Grand Exchange offers; null becomes empty
		 * @param carriedGp    the coins and platinum tokens in hand, in gp; a negative reads as 0
		 * @param exchangeGp   the coins and platinum tokens among the offers' items, in gp; a negative reads as 0
		 * @param readAtMillis wall clock at the read; a negative reads as 0
		 */
		public Carried(final List<BankItem> inventory, final List<BankItem> worn, final List<BankItem> exchange,
			final long carriedGp, final long exchangeGp, final long readAtMillis)
		{
			this.inventory = inventory == null
				? Collections.<BankItem>emptyList() : Collections.unmodifiableList(inventory);
			this.worn = worn == null ? Collections.<BankItem>emptyList() : Collections.unmodifiableList(worn);
			this.exchange = exchange == null
				? Collections.<BankItem>emptyList() : Collections.unmodifiableList(exchange);
			this.carriedGp = Math.max(0L, carriedGp);
			this.exchangeGp = Math.max(0L, exchangeGp);
			this.readAtMillis = Math.max(0L, readAtMillis);
		}

		/**
		 * The inventory and the worn gear alone, as addendum Y built it: the Grand Exchange list is empty and its
		 * worth 0. A different arity and different parameter types from the six-argument constructor, so nothing
		 * written against this one can compile to the wrong meaning.
		 *
		 * @param inventory    the inventory's stacks; null becomes empty
		 * @param worn         the worn gear's stacks; null becomes empty
		 * @param carriedGp    the coins and platinum tokens in hand, in gp; a negative reads as 0
		 * @param readAtMillis wall clock at the read; a negative reads as 0
		 */
		public Carried(final List<BankItem> inventory, final List<BankItem> worn, final long carriedGp,
			final long readAtMillis)
		{
			this(inventory, worn, null, carriedGp, 0L, readAtMillis);
		}

		/**
		 * True when the player holds and wears nothing priceable, carries no cash and has nothing in the Grand
		 * Exchange.
		 */
		public boolean isEmpty()
		{
			return inventory.isEmpty() && worn.isEmpty() && exchange.isEmpty() && carriedGp <= 0L && exchangeGp <= 0L;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}

			if (!(o instanceof Carried))
			{
				return false;
			}

			final Carried other = (Carried) o;
			return carriedGp == other.carriedGp
				&& exchangeGp == other.exchangeGp
				&& readAtMillis == other.readAtMillis
				&& inventory.equals(other.inventory)
				&& worn.equals(other.worn)
				&& exchange.equals(other.exchange);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(inventory, worn, exchange, carriedGp, exchangeGp, readAtMillis);
		}

		@Override
		public String toString()
		{
			return "Carried{inventory=" + inventory.size() + ", worn=" + worn.size() + ", exchange=" + exchange.size()
				+ ", carriedGp=" + carriedGp + ", exchangeGp=" + exchangeGp + ", readAtMillis=" + readAtMillis + '}';
		}
	}

	private final ItemManager itemManager;

	/**
	 * Whether a slot the reader had to skip has been logged at WARN this session (1.0.8): the first failure is loud,
	 * so a bug report carries the item and the cause, and every later one is debug. The reader lives for the
	 * plugin's whole life, so this is per session. Written only on the client thread, where every read happens.
	 */
	private boolean warnedRead;

	/**
	 * Slots dropped as placeholders (each held a quantity above 0 - an empty one never gets that far) by the walk in
	 * progress. Zeroed at the start of {@link #read} and handed on to {@link #placeholdersSkipped} at its end; the
	 * carried containers' walks add to it too and are never published, because the next {@link #read} zeroes it.
	 * Client thread only, like every read.
	 */
	private int placeholdersFolded;

	/** The bank slots the LAST {@link #read} dropped as placeholders although they held a quantity; 0 before any read. */
	private int placeholdersSkipped;

	/**
	 * @param itemManager RuneLite's item manager, used for {@code canonicalize} and {@code getItemComposition}
	 *                    only - never for prices, which come from the wiki client
	 */
	public BankReader(final ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * Whether an item-container event is the BANK, and so worth a capture. The plugin ignores every other
	 * container: the inventory, the deposit box and group storage all raise this event too.
	 *
	 * <p>{@link ItemContainerChanged} is a Lombok {@code @Value} class (clone
	 * {@code runelite-api/src/main/java/net/runelite/api/events/ItemContainerChanged.java:42-54}), so it is
	 * final and tests build real instances rather than mocks.
	 *
	 * @param event the event, may be null
	 * @return true only when {@code event} is non-null and its container id is {@link #BANK_CONTAINER_ID}
	 */
	public static boolean isBank(final ItemContainerChanged event)
	{
		return event != null && event.getContainerId() == BANK_CONTAINER_ID;
	}

	/**
	 * Reads a bank container into a snapshot. CLIENT THREAD ONLY - see the class javadoc.
	 *
	 * <p>An empty or null array still answers a snapshot stamped with this account, profile and time (an
	 * emptied bank is a captured bank), never {@code BankSnapshot.EMPTY}, whose zeroed stamps mean "nothing
	 * has ever been captured".
	 *
	 * @param items       the container's items, from {@code ItemContainer.getItems()}; may be null or hold
	 *                    null entries
	 * @param accountHash {@code client.getAccountHash()} - half of the persistence key
	 * @param profileType {@code RuneScapeProfileType.getCurrent(client).name()} - the other half; a null is
	 *                    stored as "" so a file name can never read "bank-123-null.json"
	 * @param nowMillis   wall clock at capture, stored as {@code capturedAtMillis} and shown as
	 *                    "Bank as of HH:MM"
	 * @return a snapshot whose items are canonical, quantity-summed and name-ordered - every GE-tradeable stack,
	 *         plus (Q5) every untradeable one worth alching, marked as such and carrying the tradeable parts
	 *         RuneLite maps it onto (R1) - carrying the worth of the coins and platinum tokens it did NOT make rows
	 *         of as {@link BankSnapshot#currencyGp} (B097), and the placeholders this read dropped although they held
	 *         a quantity as {@link BankSnapshot#placeholderSlots} (1.1.1 part B)
	 */
	public BankSnapshot read(final Item[] items, final long accountHash, final String profileType, final long nowMillis)
	{
		final Map<Integer, BankItem> folded = new LinkedHashMap<>();
		placeholdersFolded = 0;
		final long currencyGp = fold(items, folded);
		placeholdersSkipped = placeholdersFolded;

		final BankSnapshot snapshot = new BankSnapshot(rowsOf(folded), nowMillis, accountHash,
			profileType == null ? "" : profileType, currencyGp);
		// 1.1.1 part B: the count rides the snapshot it describes, so the Net Worth History can tell a fresh read from a
		// bank loaded from disk, and a player whose placeholders were counted from one whose were not.
		snapshot.placeholderSlots = placeholdersSkipped;
		return snapshot;
	}

	/**
	 * How many bank slots the last {@link #read} dropped as placeholders although they held a quantity above 0 - the
	 * ghosts the quantity rule alone used to count (GitHub issue #1, 1.1.1). The bank's own read only: the inventory,
	 * the worn items and the offers do not add to it. 0 before any read, and for every player whose placeholders hold 0,
	 * which is what RuneLite's own bank code assumes; the plugin logs it so a client that does send one can be told.
	 */
	public int placeholdersSkipped()
	{
		return placeholdersSkipped;
	}

	/**
	 * Reads the player's INVENTORY and WORN containers into the carried half of a snapshot (addendum Y, line Y2).
	 * CLIENT THREAD ONLY, for the reason {@link #read} is - it is the same cache lookups over two more containers.
	 *
	 * <p>Exactly the bank's rules, because a carried stack and a banked one become ONE row and must therefore have
	 * been read the same way: canonicalised (so a noted stack in the inventory folds onto the item it notes, and a
	 * worn variant onto its base), quantity-summed - which is what turns 28 inventory slots of the same item into
	 * one stack of 28 - placeholders, fillers and empty slots dropped, GE-untradeable stacks kept only when they
	 * alch for something and then carrying their High Alchemy value and their tradeable parts (Q5, R1).
	 *
	 * <p>Currency leaves as {@link Carried#carriedGp} and never as a row, exactly as the bank's does. Y2 names the
	 * inventory for it, which is the only container of the two that can hold coins or platinum tokens; the rule is
	 * applied to both so that a currency slot can never become a row whichever container it arrives in.
	 *
	 * <p>The sources are read INDEPENDENTLY - an item in two of them is two stacks here, one in each list - because
	 * the row's hover has to name the parts separately ("3 in bank, 1 in inventory, 1 worn, 2 in the Grand
	 * Exchange"). Adding them up is the service's job, done under the switches.
	 *
	 * <p><b>The third source (1.0.9 part 3)</b> is the Grand Exchange offers. {@link ExchangeOffers#items()} hands
	 * their items over as slots and they go through the SAME walk as the two containers - canonicalised, so a noted
	 * item in an offer folds onto the item it notes; quantity-summed, so two offers for one item become one stack;
	 * the untradeable rules still run - which is what lets a stack in an offer and a stack in the bank become one row
	 * the way an inventory stack and a bank stack do. Null offers read as none. The coins the offers hold
	 * ({@link ExchangeOffers#cashGp()}) leave as {@link Carried#exchangeGp}, with the worth of any currency the walk
	 * finds among the items, never as a row.
	 *
	 * @param inventory the inventory container's items ({@code ItemContainer.getItems()} of
	 *                  {@link #INVENTORY_CONTAINER_ID}); NULL when the client has no such container yet, which
	 *                  reads as an empty list rather than as an error
	 * @param worn      the worn container's items ({@link #WORN_CONTAINER_ID}); null reads the same way
	 * @param offers    the Grand Exchange offers, copied by {@link ExchangeOffers#of}; null reads as none
	 * @param nowMillis wall clock at the read, stored as {@link Carried#readAtMillis}
	 * @return what the player carries, wears and has in the Grand Exchange; {@link Carried#EMPTY} is never answered -
	 *         an empty read is still a read, and is stamped with {@code nowMillis}
	 */
	public Carried readContainers(@Nullable final Item[] inventory, @Nullable final Item[] worn,
		@Nullable final ExchangeOffers offers, final long nowMillis)
	{
		final Map<Integer, BankItem> heldFold = new LinkedHashMap<>();
		final Map<Integer, BankItem> wornFold = new LinkedHashMap<>();
		final Map<Integer, BankItem> exchangeFold = new LinkedHashMap<>();
		final long held = fold(inventory, heldFold);
		final long onBody = fold(worn, wornFold);
		final long inOffers = fold(offers == null ? null : offers.items(), exchangeFold);

		final long offerCoins = offers == null ? 0L : offers.cashGp();

		return new Carried(rowsOf(heldFold), rowsOf(wornFold), rowsOf(exchangeFold),
			PortfolioMath.clampedAdd(held, onBody), PortfolioMath.clampedAdd(offerCoins, inOffers), nowMillis);
	}

	/**
	 * One container's slots, folded onto canonical ids in {@code folded} and its currency answered as a worth: the
	 * ONE walk of a container this plugin has, so the bank (C11) and the two carried containers (Y2) can never come
	 * to disagree about what a slot means.
	 *
	 * @param items  the container's items; null is an empty container, worth nothing
	 * @param folded the fold map, mutated in place; may already hold another container's stacks
	 * @return the coins and platinum tokens among those slots, in gp
	 */
	private long fold(@Nullable final Item[] items, final Map<Integer, BankItem> folded)
	{
		if (items == null)
		{
			return 0L;
		}

		long currencyGp = 0L;
		for (final Item item : items)
		{
			if (item == null)
			{
				continue;
			}

			// Currency leaves as a NUMBER, never as a row: it has no market to move (D6), but it is half of
			// what the player calls their bank value (B097). Taken on the RAW id, before canonicalisation, and
			// the same shape the dev bridge's synthetic bank= verb uses so the two cannot drift apart.
			final long currency = currencyWorth(item.getId(), item.getQuantity());
			if (currency > 0L)
			{
				currencyGp = PortfolioMath.clampedAdd(currencyGp, currency);
				continue;
			}

			accept(folded, item);
		}

		return currencyGp;
	}

	/** A fold map's stacks in the one row order this plugin has ({@link #BY_NAME_THEN_ID}). */
	private static List<BankItem> rowsOf(final Map<Integer, BankItem> folded)
	{
		final List<BankItem> rows = new ArrayList<>(folded.values());
		rows.sort(BY_NAME_THEN_ID);
		return rows;
	}

	/**
	 * What one slot of CURRENCY is worth, and 0 for anything else: coins at 1 gp each and platinum tokens at
	 * 1,000, which is exactly what RuneLite's own item manager answers for the two ids rather than looking them
	 * up (clone {@code runelite-client/src/main/java/net/runelite/client/game/ItemManager.java:328-337}), and so
	 * what the client's bundled Bank plugin counts them as in the bank title bar.
	 *
	 * <p>Public and static because two callers need the identical rule and neither should own a second copy of
	 * it: {@link #accept} on the live container, and the dev bridge's synthetic {@code bank=} verb
	 * ({@code BpmCommands}), whose made-up banks would otherwise be able to hold a coin ROW that no real bank
	 * can produce.
	 *
	 * <p>No clamp is needed here: the biggest stack the game can hold is {@link Integer#MAX_VALUE} platinum
	 * tokens, which is 2.1 x 10^12 gp - four million times short of a long. Summing MANY slots is where a clamp
	 * belongs, and {@link PortfolioMath#clampedAdd} is where it is.
	 *
	 * @param id       a raw item id, before canonicalisation
	 * @param quantity the slot's quantity; 0 or less is worth nothing
	 */
	public static long currencyWorth(final int id, final int quantity)
	{
		if (quantity <= 0)
		{
			return 0L;
		}

		if (id == ItemID.COINS)
		{
			return quantity;
		}

		if (id == ItemID.PLATINUM)
		{
			return quantity * 1000L;
		}

		return 0L;
	}

	/**
	 * Applies the C11 skip rules to one container slot and folds what survives into {@code folded}, keyed by
	 * canonical id. The map is a {@link LinkedHashMap} so the pre-sort order is bank order and the result is
	 * a function of the input alone.
	 *
	 * <p>Currency is not one of the rules here: {@link #read} takes a coins or platinum slot as a WORTH before
	 * this is called, so the only currency slot that can reach this method is one with no quantity, which the
	 * quantity rule below drops like any other empty slot.
	 *
	 * <p><b>One odd slot never costs the bank (1.0.8).</b> Everything from the canonical-id lookup on runs inside a
	 * {@code try}: a client that throws for one item's composition skips that item, logs the first such failure of
	 * the session at WARN and the rest at DEBUG, and the read goes on with the next slot. {@link #read} therefore
	 * never throws for one item - it used to abandon the whole capture, and with it the sidebar's first sight of the
	 * bank.
	 *
	 * @param folded the fold map, mutated in place
	 * @param item   one container slot, never null
	 */
	private void accept(final Map<Integer, BankItem> folded, final Item item)
	{
		final int id = item.getId();
		if (id <= 0)
		{
			return;
		}

		final int quantity = item.getQuantity();
		if (quantity <= 0)
		{
			return;
		}

		if (id == ItemID.BANK_FILLER)
		{
			return;
		}

		try
		{
			foldSlot(folded, id, quantity);
		}
		catch (final RuntimeException e)
		{
			if (!warnedRead)
			{
				warnedRead = true;
				log.warn("bank-portfolio-tracker: could not read item {} - skipped", id, e);
			}
			else
			{
				log.debug("bank-portfolio-tracker: could not read item {} - skipped", id, e);
			}
		}
	}

	/**
	 * The part of {@link #accept} that asks the client about an item: the raw composition (is it a placeholder?), the
	 * canonical id, the composition and what is built from them. Split out so that one {@code try} in {@link #accept}
	 * covers every client read of a slot.
	 */
	private void foldSlot(final Map<Integer, BankItem> folded, final int id, final int quantity)
	{
		// 1.1.1 (GitHub issue #1): a bank placeholder is dropped by its DEFINITION, before canonicalize folds it onto the
		// real item it stands for and the ghost is counted. The quantity rule in accept only catches the ones whose
		// quantity is 0; a client that puts a quantity on a placeholder slipped past it. -1 is the template id of every
		// other item, the real item that owns a placeholder included. A null composition reads as "not a placeholder".
		final ItemComposition raw = itemManager.getItemComposition(id);
		if (raw != null && raw.getPlaceholderTemplateId() != -1)
		{
			placeholdersFolded++;
			return;
		}

		final int canonical = itemManager.canonicalize(id);
		final ItemComposition composition = itemManager.getItemComposition(canonical);
		if (composition == null)
		{
			// Unreachable against a live client - getItemDefinition is @Nonnull (Client.java:393-394) - but
			// this loop runs inside an @Subscribe handler on the client thread, where one thrown NPE would
			// abandon the whole capture. One odd id costs one row instead.
			log.debug("no composition for canonical item {} (raw {}), skipping", canonical, id);
			return;
		}

		// Q5: not listed by the Grand Exchange is no longer the end of it - a stack with a High Alchemy value is
		// kept and marked, and the service decides whether to show it. getHaPrice is read only on this branch, so
		// an ordinary bank costs exactly the cache lookups it did before.
		final boolean untradeable = !composition.isGeTradeable();
		final int haPrice = untradeable ? composition.getHaPrice() : 0;
		if (untradeable && haPrice <= 0)
		{
			return;
		}

		final BankItem existing = folded.get(canonical);
		if (existing != null)
		{
			existing.quantity = addClamped(existing.quantity, quantity);
			return;
		}

		// getMembersName, never getName: on a FREE world getName appends " (Members)" to every members item
		// (clone runelite-api/src/main/java/net/runelite/api/ItemComposition.java:34-41 vs :43-49, tag
		// runelite-parent-1.12.37), and that suffix is not in the guide table, so an F2P player would lose the
		// price of every members item in their bank. Addendum L line L8 (b) makes this the composition name the
		// plugin uses. There is deliberately no fallback to getName() when this is empty: falling back would put
		// the suffix straight back into the lookup for exactly the items it breaks.
		final String name = composition.getMembersName();
		folded.put(canonical, new BankItem(
			canonical,
			quantity,
			name == null ? "" : name,
			composition.isStackable(),
			untradeable,
			haPrice,
			untradeable ? partsOf(canonical) : null));
	}

	/**
	 * What RuneLite says ONE of an untradeable item reverts to (addendum R, line R1): every
	 * {@code ItemMapping.map(canonicalId)} entry as a {@link BankItem.Part} - the mapping's
	 * {@code getTradeableItem()}, its {@code getQuantity()}, and that part's {@code getMembersName()} (the naming
	 * rule of L8 b, so the guide table can be asked for it by name) - in id order. Null when RuneLite maps the id
	 * to nothing, which is when the stack keeps the alch rule of Q5.
	 *
	 * <p>Asked only for a stack already KEPT as untradeable, so an ordinary bank costs not one extra lookup.
	 * {@code ItemMapping.map} is static and pure - its table is built once from the enum and
	 * {@code ItemVariationMapping} - so the only client reads here are the compositions the names come from, on the
	 * client thread with the rest of {@link #read}.
	 *
	 * <p>An entry with a non-positive id or quantity names nothing that can be priced and is dropped; if that
	 * leaves none, the answer is null rather than an empty list, because "RuneLite maps this to nothing" and "the
	 * mapping named nothing usable" are the same answer to every reader.
	 *
	 * @param canonical the stack's canonical id
	 */
	@Nullable
	private List<BankItem.Part> partsOf(final int canonical)
	{
		final Collection<ItemMapping> mappings;
		try
		{
			mappings = ItemMapping.map(canonical);
		}
		catch (final RuntimeException | LinkageError e)
		{
			// Read as "not mapped", which is the pre-R behaviour: the stack keeps its alch value. Mirrors
			// PriceService.rewrittenByItemMapping, the other caller of this enum.
			log.debug("bank-portfolio-tracker: ItemMapping could not be consulted for item {}", canonical, e);
			return null;
		}

		if (mappings == null || mappings.isEmpty())
		{
			return null;
		}

		final List<BankItem.Part> parts = new ArrayList<>(mappings.size());
		for (final ItemMapping mapping : mappings)
		{
			if (mapping == null)
			{
				continue;
			}

			final int partId = mapping.getTradeableItem();
			final long partQuantity = mapping.getQuantity();
			if (partId <= 0 || partQuantity <= 0L)
			{
				continue;
			}

			parts.add(new BankItem.Part(partId, partQuantity, partName(partId)));
		}

		if (parts.isEmpty())
		{
			return null;
		}

		parts.sort(BY_PART_ID);
		return parts;
	}

	/**
	 * A part's name for the L8 b lookup: {@code getMembersName()} on its own composition, "" when the client
	 * cannot serve one. Never throws - the capture loop runs inside an {@code @Subscribe} handler, where one
	 * escaped exception would abandon the whole bank for the sake of one part's name, and a nameless part is still
	 * priced by its id.
	 */
	private String partName(final int partId)
	{
		try
		{
			final ItemComposition part = itemManager.getItemComposition(partId);
			final String name = part == null ? null : part.getMembersName();
			return name == null ? "" : name;
		}
		catch (final RuntimeException e)
		{
			log.debug("bank-portfolio-tracker: no composition for mapped part {}", partId, e);
			return "";
		}
	}

	/**
	 * Sums two bank quantities without wrapping. Two int quantities can genuinely overflow an int - a bank
	 * can hold 2,147,483,647 of a stackable item AND that many again as a noted stack that folds onto it -
	 * so the sum is done in a long and clamped. Clamping rather than throwing keeps the capture alive; the
	 * row is already at the game's own display ceiling.
	 *
	 * <p>Package-private rather than private since addendum Y: {@code PriceService} adds a carried stack's quantity
	 * onto the banked one's when "Include inventory and worn gear" is on (Y3), and two callers of the same rule must
	 * not be two copies of it.
	 *
	 * @param a a non-negative quantity
	 * @param b a non-negative quantity
	 * @return {@code a + b}, or {@link Integer#MAX_VALUE} when that would overflow
	 */
	static int addClamped(final int a, final int b)
	{
		final long sum = (long) a + (long) b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * The last bank the plugin saw, for one account on one profile (contract C5). Persisted so the panel is
 * useful at the Grand Exchange and on the login screen: the file is read at start-up and the rows are drawn
 * with "Bank as of HH:MM" long before - or entirely without - a bank visit (design D7).
 *
 * <p>Public fields, no-arg constructor, plain types: the injected Gson writes and reads it directly
 * (playbook step 13). {@link #normalize()} is the single place a loaded file is made safe, so every reader
 * downstream may assume a non-null item list, non-null names and positive ids and quantities.
 *
 * <p>Since addendum Y line Y2 the same file carries what the player was CARRYING and WEARING at the last read
 * ({@link #inventory}, {@link #worn}, {@link #carriedGp}, {@link #carriedAtMillis}, put there by
 * {@link #withCarried(BankReader.Carried)}), so "Include inventory and worn gear" can be flipped on and off without
 * a bank visit - the same reasoning that keeps {@link #currencyGp} and every untradeable stack in every capture.
 * Older files have none of it and read as "carrying nothing".
 *
 * <p>Since 1.0.9 part 3 it carries a third such part, what was in the player's Grand Exchange offers at that same
 * read ({@link #exchange}, the stacks, and {@link #exchangeGp}, the coins), stamped by the same
 * {@link #carriedAtMillis} because it is read at the same moment. A file written before it has none of that and
 * reads as "nothing in the Grand Exchange".
 *
 * <p>The account hash and profile type are stored INSIDE the file as well as in its name
 * ({@code bank-<accountHash>-<profileType>.json}, contract C17) so a file that has been renamed or copied can
 * still be told apart from the current account - the service checks them before showing a snapshot as this
 * account's bank (C23).
 */
public class BankSnapshot
{
	/**
	 * The profile type used when a file names none - RuneLite's ordinary main-game profile
	 * ({@code RuneScapeProfileType.STANDARD}).
	 */
	public static final String DEFAULT_PROFILE_TYPE = "STANDARD";

	/**
	 * The "no bank captured" snapshot, which the panel renders as "Open your bank once to load your items".
	 *
	 * <p>Shared and to be treated as READ-ONLY: this class is a persisted bag of public fields, so nothing but
	 * discipline stops a caller mutating it. Its item list is {@link Collections#emptyList()} for that reason.
	 */
	public static final BankSnapshot EMPTY = new BankSnapshot(Collections.emptyList(), 0L, 0L, DEFAULT_PROFILE_TYPE);

	/**
	 * The stacks, one per canonical item id. Never null after {@link #normalize()}.
	 */
	public List<BankItem> items;

	/**
	 * When the bank was captured, epoch millis; 0 means "never" ({@link #EMPTY}).
	 */
	public long capturedAtMillis;

	/**
	 * {@code Client.getAccountHash()} at capture time - the account this bank belongs to.
	 */
	public long accountHash;

	/**
	 * {@code RuneScapeProfileType.getCurrent(client).name()} at capture time: a main-game bank and a
	 * Leagues/DMM bank are different banks and never share a file.
	 */
	public String profileType;

	/**
	 * What the bank's COINS and PLATINUM TOKENS are worth, in gp: {@code coins x 1 + platinum x 1000}, exactly
	 * the valuation RuneLite's own item manager hard-codes for the two (clone
	 * {@code runelite-client/src/main/java/net/runelite/client/game/ItemManager.java:328-337}). Clamped at
	 * {@link Long#MAX_VALUE} rather than wrapped.
	 *
	 * <p>Currency is NOT one of {@link #items}, and this field is why both can be true at once (B097). Design
	 * D6 keeps it out of the ROWS because it has no market - a movement row for coins would read 0 % for ever -
	 * but it is half of what a player means by "bank value", and a total that leaves it out disagrees with the
	 * figure RuneLite's own bundled Bank plugin puts in the bank title bar by exactly the player's cash.
	 * {@link BankReader#currencyWorth} is the one place the sum is defined.
	 *
	 * <p><b>Persistence caveat.</b> This is a Gson bag of public fields, so a {@code bank-*.json} written before
	 * the field existed reads back as 0: a REMEMBERED bank (the login-screen and Grand Exchange case of D7) shows
	 * no currency at all until the player next opens a bank. Nothing repairs that, and nothing should - the old
	 * file genuinely does not know.
	 */
	public long currencyGp;

	/**
	 * The stacks in the player's INVENTORY at the last carried read (addendum Y, line Y2), one per canonical id and
	 * by exactly the rules {@link #items} follows. Never null after {@link #normalize()}; EMPTY in every
	 * {@code bank-*.json} written before addendum Y. It is read at every bank read and every Refresh WHATEVER
	 * "Include inventory and worn gear" says - the switch acts only when the service adds up (addendum AV), which is
	 * what lets addendum AU's History keep the carried half of every reading - and "we have read nothing" and "you
	 * were carrying nothing" are the same thing to every reader, because both mean there is nothing to add.
	 */
	public List<BankItem> inventory;

	/** The stacks on the player's WORN gear at that same read (Y2), by the same rules. Never null after normalize. */
	public List<BankItem> worn;

	/**
	 * The stacks in the player's Grand Exchange OFFERS at that same read (1.0.9 part 3), by the same rules: the
	 * items still unsold in a sell offer and the items bought and not yet collected in a buy offer, one stack per
	 * canonical id. Never null after {@link #normalize()}; EMPTY in every {@code bank-*.json} written before this
	 * part, which reads as "nothing in the Grand Exchange". Read WHATEVER "Include Grand Exchange offers" says, for
	 * the reason {@link #inventory} is - the switch acts only when the service adds up, so the History keeps what the
	 * offers held.
	 */
	public List<BankItem> exchange;

	/**
	 * What the coins and platinum tokens the player was CARRYING are worth, in gp - the carried twin of
	 * {@link #currencyGp}, kept apart from it so that turning "Include inventory and worn gear" off takes exactly
	 * the carried cash back out of the bank value and leaves the bank's own alone. 0 in a file written before
	 * addendum Y.
	 */
	public long carriedGp;

	/**
	 * What the player's Grand Exchange offers hold in COINS, in gp (1.0.9 part 3): the coins committed to buy offers
	 * and the coins received by sell offers and not yet collected - {@link ExchangeOffers#cashGp()} - kept apart from
	 * {@link #carriedGp} so that turning "Include Grand Exchange offers" off takes exactly these back out. 0 in a file
	 * written before this part.
	 */
	public long exchangeGp;

	/**
	 * When the carried containers and the offers were read, epoch millis; 0 means "never" - which is what a pre-Y
	 * file and a snapshot captured with no client logged in both say.
	 *
	 * <p>Its own stamp rather than {@link #capturedAtMillis}, because the two really are read at different moments:
	 * Refresh re-reads what the player carries and republishes the STORED bank beside it (Y2), so the footnote's
	 * "bank HH:MM" clock has to keep naming the bank's own read.
	 */
	public long carriedAtMillis;

	/**
	 * The bank slots the read that made this snapshot dropped as placeholders although they held a quantity (1.1.1 part
	 * B) - {@link BankReader#placeholdersSkipped()}, put here by {@link BankReader#read}. A count above 0 is what tells
	 * the Net Worth History that the readings an older build recorded counted placeholders as items.
	 *
	 * <p>{@code -1} means "not judged by a fresh read": a snapshot loaded from disk (the field is {@code transient}, so
	 * Gson never writes it and its no-arg road leaves this default), the dev verb's made-up bank, or any snapshot not
	 * built by a bank read. {@link #withCarried} copies it, because a carried re-stamp is the same bank; neither
	 * {@link #sameContentAs} nor {@link #equals} reads it, because it says how the bank was read, not what it holds.
	 */
	public transient int placeholderSlots = -1;

	/**
	 * Whether {@code accountHash} names a real RuneScape account - the one test every site that files, loads or reads a
	 * bank by its owner asks (1.0.10). False for exactly two values: {@code 0}, this plugin's own spelling of "nobody",
	 * and {@code -1}, what {@code OAuthApi.getAccountHash()} answers while the client has not logged in yet ("or -1 if
	 * the client has not logged in yet"). True for every other value, NEGATIVE ones included: RuneLite's
	 * {@code ConfigManager.findRSProfile} refuses only {@code ACCOUNT_HASH_INVALID} (-1) and packs all 64 bits of any
	 * other hash into the profile key, so a negative hash is an ordinary account.
	 *
	 * @param accountHash {@code Client.getAccountHash()} or a stored owner hash
	 */
	public static boolean isAccount(final long accountHash)
	{
		return accountHash != 0L && accountHash != -1L;
	}

	public BankSnapshot()
	{
		items = new ArrayList<>();
		profileType = DEFAULT_PROFILE_TYPE;
		inventory = new ArrayList<>();
		worn = new ArrayList<>();
		exchange = new ArrayList<>();
	}

	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType)
	{
		this(items, capturedAtMillis, accountHash, profileType, 0L);
	}

	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType, final long currencyGp)
	{
		this(items, capturedAtMillis, accountHash, profileType, currencyGp, Collections.emptyList(),
			Collections.emptyList(), 0L, 0L);
	}

	/**
	 * The shape of addendum Y: a bank part and a carried part, each with its own cash and its own clock, and nothing
	 * in the Grand Exchange (an empty list and 0). Kept so a snapshot built without offers - the render fixtures, the
	 * tests - is spelled as it always was.
	 *
	 * @param inventory       the inventory's stacks; null becomes an empty list
	 * @param worn            the worn gear's stacks; null becomes an empty list
	 * @param carriedGp       the coins and platinum tokens in hand, in gp
	 * @param carriedAtMillis when the two carried containers were read; 0 = never
	 */
	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType, final long currencyGp, final List<BankItem> inventory, final List<BankItem> worn,
		final long carriedGp, final long carriedAtMillis)
	{
		this(items, capturedAtMillis, accountHash, profileType, currencyGp, inventory, worn, Collections.emptyList(),
			carriedGp, 0L, carriedAtMillis);
	}

	/**
	 * The full shape since 1.0.9 part 3: a bank part, a carried part and the Grand Exchange offers, with their cash
	 * and one clock for the two that are read together.
	 *
	 * @param inventory       the inventory's stacks; null becomes an empty list
	 * @param worn            the worn gear's stacks; null becomes an empty list
	 * @param exchange        the stacks in the Grand Exchange offers; null becomes an empty list
	 * @param carriedGp       the coins and platinum tokens in hand, in gp
	 * @param exchangeGp      the coins the offers hold, in gp
	 * @param carriedAtMillis when the carried containers and the offers were read; 0 = never
	 */
	public BankSnapshot(final List<BankItem> items, final long capturedAtMillis, final long accountHash,
		final String profileType, final long currencyGp, final List<BankItem> inventory, final List<BankItem> worn,
		final List<BankItem> exchange, final long carriedGp, final long exchangeGp, final long carriedAtMillis)
	{
		this.items = items;
		this.capturedAtMillis = capturedAtMillis;
		this.accountHash = accountHash;
		this.profileType = profileType;
		this.currencyGp = currencyGp;
		this.inventory = inventory == null ? Collections.<BankItem>emptyList() : inventory;
		this.worn = worn == null ? Collections.<BankItem>emptyList() : worn;
		this.exchange = exchange == null ? Collections.<BankItem>emptyList() : exchange;
		this.carriedGp = carriedGp;
		this.exchangeGp = exchangeGp;
		this.carriedAtMillis = carriedAtMillis;
	}

	/**
	 * This same BANK with a fresh carried part (addendum Y, line Y2) - what Refresh publishes: the stored stacks,
	 * their capture time, their cash and their account untouched, and the inventory, the worn gear, the Grand Exchange
	 * offers (1.0.9 part 3), the carried cash, the offers' coins and the carried clock replaced by what the client has
	 * just been asked for.
	 *
	 * <p>A copy rather than a mutation, because the snapshot the service holds is handed to the executor and the
	 * EDT and must never change under them; the item list is shared by reference, which is safe for the same reason
	 * {@code setBank}'s is - nothing mutates a captured list.
	 *
	 * @param carried what the player carries and wears; null clears the carried part, which is what a read with no
	 *                client logged in would have found
	 */
	public BankSnapshot withCarried(final BankReader.Carried carried)
	{
		final BankReader.Carried next = carried == null ? BankReader.Carried.EMPTY : carried;
		final BankSnapshot copy = new BankSnapshot(items, capturedAtMillis, accountHash, profileType, currencyGp,
			next.inventory, next.worn, next.exchange, next.carriedGp, next.exchangeGp, next.readAtMillis);
		// 1.1.1 part B: the same bank, read the same way - a fresh read keeps its count through the carried half the
		// plugin folds into it, and a bank from disk stays unjudged.
		copy.placeholderSlots = placeholderSlots;
		return copy;
	}

	/**
	 * True when there are no priceable ROWS to show. {@link #currencyGp} is deliberately not consulted: a bank of
	 * nothing but coins has no movement rows to draw, which is the question every caller asks this. What the card
	 * at the top of a row-less bank should say about the coins in it is the panel's call, made on the row count.
	 */
	public boolean isEmpty()
	{
		return items == null || items.isEmpty();
	}

	/**
	 * The same bank, of the same account and profile, whatever MOMENT the two were captured at - which
	 * {@link #equals(Object)} deliberately does not answer, because a persisted snapshot has to be told apart
	 * from a re-read of it.
	 *
	 * <p>Why it exists: OSRS posts one {@code ItemContainerChanged} per change to the bank container, and a great
	 * many of those carry an identical stack list - the plugin's own start-up replay of the cached container, a
	 * bank re-opened without a change, a placeholder shuffled. Each one used to cost a full serialisation of
	 * every stack plus a temp file and an atomic replace on the client's single shared executor. The service
	 * compares with this and skips the write when nothing about the CONTENT moved; the price of that is a
	 * persisted {@code capturedAtMillis} that keeps the first capture time of an unchanged bank, which is the
	 * honest stamp for it anyway.
	 *
	 * <p>{@link #currencyGp} counts as content (B097): a player who deposits their coins and nothing else has
	 * changed their bank, and a comparison that ignored the currency would leave the new total unwritten until
	 * some unrelated stack happened to move.
	 *
	 * @param other anything, including null (which is never the same content)
	 */
	public boolean sameContentAs(final BankSnapshot other)
	{
		if (other == null)
		{
			return false;
		}

		if (this == other)
		{
			return true;
		}

		return accountHash == other.accountHash
			&& currencyGp == other.currencyGp
			&& carriedGp == other.carriedGp
			&& exchangeGp == other.exchangeGp
			&& Objects.equals(profileType, other.profileType)
			&& Objects.equals(items, other.items)
			// Y2: what the player carries is content too, or a Refresh that found a different inventory would leave
			// the file saying the old one - and the next launch would draw a bank nobody has. The Grand Exchange offers
			// are content for the same reason (1.0.9 part 3): a Refresh that found a different offer must publish.
			&& Objects.equals(inventory, other.inventory)
			&& Objects.equals(worn, other.worn)
			&& Objects.equals(exchange, other.exchange);
	}

	/**
	 * Makes a snapshot that came off disk safe to read (contract C5): drops null entries and anything with a
	 * non-positive id or quantity - which is also how a bank PLACEHOLDER (quantity 0) disappears, exactly as
	 * design D6 asks - replaces a null name with "" so no renderer has to null-check, and fills in a missing
	 * profile type with {@link #DEFAULT_PROFILE_TYPE}.
	 *
	 * <p>Void, like {@code BeamLayer.normalize()}: it repairs this object in place and is called once, right
	 * after the file is parsed.
	 */
	public void normalize()
	{
		items = cleaned(items);
		// Y2: a file written before addendum Y has neither list, and Gson leaves an absent field at whatever the
		// no-arg constructor set - or at null when it instantiates without one. Both read as "carrying nothing",
		// which is the truth about a capture made before the plugin ever looked.
		inventory = cleaned(inventory);
		worn = cleaned(worn);
		// 1.0.9 part 3: a file written before the Grand Exchange offers were read has no such list either, and reads as
		// "nothing in the Grand Exchange".
		exchange = cleaned(exchange);

		if (profileType == null || profileType.isEmpty())
		{
			profileType = DEFAULT_PROFILE_TYPE;
		}

		if (capturedAtMillis < 0)
		{
			capturedAtMillis = 0;
		}

		// A hand-edited or truncated file could carry a negative worth, and a negative would be SUBTRACTED from
		// the bank's total. Absent reads as 0 through Gson already; this is the other half of that.
		if (currencyGp < 0)
		{
			currencyGp = 0;
		}

		if (carriedGp < 0)
		{
			carriedGp = 0;
		}

		if (exchangeGp < 0)
		{
			exchangeGp = 0;
		}

		if (carriedAtMillis < 0)
		{
			carriedAtMillis = 0;
		}
	}

	/**
	 * One stack list made safe: null entries and anything with a non-positive id or quantity dropped - which is also
	 * how a bank PLACEHOLDER (quantity 0) disappears, exactly as design D6 asks - and a null name replaced with ""
	 * so no renderer has to null-check. A null list is an empty one.
	 *
	 * <p>The one rule, so the bank's stacks and the carried stacks of Y2 cannot be cleaned two different ways.
	 */
	private static List<BankItem> cleaned(final List<BankItem> stacks)
	{
		final List<BankItem> clean = new ArrayList<>();
		if (stacks != null)
		{
			for (final BankItem item : stacks)
			{
				if (item == null || item.id <= 0 || item.quantity <= 0)
				{
					continue;
				}

				if (item.name == null)
				{
					item.name = "";
				}

				clean.add(item);
			}
		}
		return clean;
	}

	/**
	 * The same content captured at the same MOMENT: {@link #sameContentAs} plus {@link #capturedAtMillis}, which
	 * is the one field the content comparison leaves out (a persisted snapshot has to be told apart from a re-read
	 * of it). Spelling it this way keeps the field list in one place, so a field added to the content can never be
	 * forgotten here.
	 */
	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof BankSnapshot))
		{
			return false;
		}

		final BankSnapshot other = (BankSnapshot) o;
		return capturedAtMillis == other.capturedAtMillis && sameContentAs(other);
	}

	@Override
	public int hashCode()
	{
		int result = items == null ? 0 : items.hashCode();
		result = 31 * result + (int) (capturedAtMillis ^ (capturedAtMillis >>> 32));
		result = 31 * result + (int) (accountHash ^ (accountHash >>> 32));
		result = 31 * result + (profileType == null ? 0 : profileType.hashCode());
		result = 31 * result + (int) (currencyGp ^ (currencyGp >>> 32));
		result = 31 * result + (inventory == null ? 0 : inventory.hashCode());
		result = 31 * result + (worn == null ? 0 : worn.hashCode());
		result = 31 * result + (int) (carriedGp ^ (carriedGp >>> 32));
		result = 31 * result + (exchange == null ? 0 : exchange.hashCode());
		result = 31 * result + (int) (exchangeGp ^ (exchangeGp >>> 32));
		return result;
	}

	/**
	 * The carried part is printed only when there IS one, so a bank captured before addendum Y - and every bank of a
	 * player with the switch off - reads exactly as it did; the Grand Exchange part (1.0.9 part 3) likewise only when
	 * the offers held something.
	 */
	@Override
	public String toString()
	{
		final int held = inventory == null ? 0 : inventory.size();
		final int equipped = worn == null ? 0 : worn.size();
		final int offered = exchange == null ? 0 : exchange.size();
		return "BankSnapshot{items=" + (items == null ? 0 : items.size())
			+ ", capturedAtMillis=" + capturedAtMillis
			+ ", accountHash=" + accountHash
			+ ", profileType='" + profileType + "'"
			+ ", currencyGp=" + currencyGp
			+ (held == 0 && equipped == 0 && carriedGp == 0L
				? ""
				: ", inventory=" + held + ", worn=" + equipped + ", carriedGp=" + carriedGp)
			+ (offered == 0 && exchangeGp == 0L ? "" : ", exchange=" + offered + ", exchangeGp=" + exchangeGp) + '}';
	}
}

package com.bankpricemovement;

import java.util.function.Function;

/**
 * A test hook, and nothing else: the one static handle a developer-mode client hands the Effect Lab's HTTP
 * server so a script (or Claude) can drive the 2h Bank Portfolio Tracker sidebar without a person at the keyboard.
 * The same shape as {@code com.lootandbeam.DevBridge}, which the lab's {@code /lb} route reaches; this one is
 * reached by {@code /bpm}.
 *
 * <p><b>It is null in every production client.</b> {@link BankPriceMovementPlugin#startUp()} sets it only
 * when RuneLite's injected {@code @Named("developerMode")} constant is true - which the client only ever
 * binds true for a from-source launch with {@code --developer-mode} and no launcher version
 * (RuneLiteModule.java:120, from RuneLite.java:224) - and {@link BankPriceMovementPlugin#shutDown()} clears
 * it as its first statement. A Plugin Hub build therefore carries a field that is written once with
 * null-equivalent state, read by nothing, and reachable only from a class in the test source set
 * ({@code com.osrslos.lab.LabServer}) that is not in the jar at all.
 *
 * <p>The handler takes ONE command string ({@code key} or {@code key=value}) and answers a JSON string; see
 * {@link BpmCommands} for the command list and {@code docs/effect-lab.md} §3.3 for the {@code /bpm} route
 * that reaches it. It bounces the work onto the Swing thread itself, so it is safe to call from the HTTP
 * thread; it never throws.
 *
 * <p>Volatile because it is written on the EDT (plugin start/stop) and read on the lab's HTTP thread.
 */
public final class BpmDevBridge
{
	/** The running panel's command handler while a developer-mode client has the plugin on; null otherwise. */
	public static volatile Function<String, String> handler;

	private BpmDevBridge()
	{
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;

/**
 * The 2hBuilds coin, the family mark every 2hBuilds plugin carries in the top-left corner of its sidebar icon: a
 * hammered gold disc 9 px across with its "2h" struck in dark brown, drawn in code so it needs no image file. It is
 * the coin half of {@link NavIcon}, pulled out so the one picture can be copied into another plugin's package
 * unchanged - it refers to nothing of this plugin's and to no class but the JDK's.
 *
 * <p>{@link #paint} draws it where it sits in a 16 x 16 icon, the disc centred on (4.5, 4.5): three jittered discs
 * with antialiasing on, then the two letters crisp on top, antialiasing off again, so a caller that draws more on
 * the same {@link Graphics2D} afterwards gets the hint it had not set itself.
 */
final class CoinGlyph
{
	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	private CoinGlyph()
	{
	}

	/**
	 * Draws the coin in the top-left of the 16 x 16 icon {@code g} paints on: three jittered discs with
	 * antialiasing, then the letters crisp on top. Leaves the antialiasing hint off and the colour at the letters'
	 * ink.
	 */
	static void paint(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < RADII.length; i++)
		{
			g.setColor(RINGS[i]);
			g.fill(coin(RADII[i]));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		glyph(g, TWO, LETTERS_X, LETTERS_Y);
		glyph(g, H, LETTERS_X + 4, LETTERS_Y);
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

