package com.bankpricemovement;

import java.util.Arrays;
import javax.annotation.Nullable;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;

/**
 * An immutable COPY of the player's Grand Exchange offers at one moment (1.0.9 part 3): the six figures of each
 * slot - the item, the state, the quantity asked for, the quantity filled, the price asked and the coins spent - and
 * what they mean for the player's worth. The user banked, logged out with about 50m sitting in offers, and the day's
 * reading was 50m short: what is in an offer belongs to the player and the plugin counted it nowhere.
 *
 * <p><b>Why a copy.</b> {@code Client.getGrandExchangeOffers()} answers the client's own live objects, which the
 * client changes in place on every fill. A plugin that kept one would see a later offer event through an old read,
 * and a snapshot built from it would change under the thread that was publishing it. {@link #of} therefore copies
 * the six figures of every slot into this class's own arrays and holds no {@link GrandExchangeOffer} at all: a copy
 * taken at one read never changes under a later event, and can be handed to the executor and the EDT as it is.
 * {@code of} must run on the client thread, where the offers are consistent; everything else here can run anywhere.
 *
 * <p><b>What an offer holds, by state</b> (counted at the item's price, like the inventory's stacks):
 * <ul>
 * <li>A SELL offer - {@code SELLING}, {@code SOLD}, {@code CANCELLED_SELL} - holds the items not yet sold (still the
 * player's, in the offer's slot) and the coins received so far and not yet collected.</li>
 * <li>A BUY offer - {@code BUYING}, {@code BOUGHT}, {@code CANCELLED_BUY} - holds the items bought and not yet
 * collected, and the coins still committed to the part not yet filled. Those coins are {@code price x total - spent}:
 * they include the change a fill below the asked price hands back, because the client's {@code spent} is what the
 * fills actually cost.</li>
 * <li>An {@code EMPTY} slot holds nothing.</li>
 * </ul>
 * A figure that reads below zero reads as zero, and a filled quantity above the total reads as a full fill.
 *
 * <p><b>An open question, written down rather than guessed.</b> The figures follow what the client reports for the
 * slot at the read. What {@code spent} reads after the player collects only PART of a sell offer that is still
 * {@code SELLING} is not known from source: if the client zeroes it on a collect, coins already in the player's
 * pocket are not counted twice; if it does not, they are. The local look settles it (collect half, press Refresh,
 * compare), and no correction is applied here until it has.
 */
public final class ExchangeOffers
{
	/** No offers at all - what a read with no client, no array or only empty slots answers. */
	public static final ExchangeOffers EMPTY = new ExchangeOffers(new int[0], new GrandExchangeOfferState[0],
		new int[0], new int[0], new long[0], new long[0]);

	private final int[] itemIds;
	private final GrandExchangeOfferState[] states;
	private final int[] totalQuantities;
	private final int[] quantitiesSold;
	private final long[] prices;
	private final long[] spent;

	private ExchangeOffers(final int[] itemIds, final GrandExchangeOfferState[] states, final int[] totalQuantities,
		final int[] quantitiesSold, final long[] prices, final long[] spent)
	{
		this.itemIds = itemIds;
		this.states = states;
		this.totalQuantities = totalQuantities;
		this.quantitiesSold = quantitiesSold;
		this.prices = prices;
		this.spent = spent;
	}

	/**
	 * Copies the client's offers. CLIENT THREAD.
	 *
	 * <p>Null, an empty array, or an array whose every slot is null or {@code EMPTY} answers {@link #EMPTY}. A null
	 * slot or a slot with no state reads as {@code EMPTY}, and so does a slot whose item id is 0 or below - it has
	 * nothing to name a stack by. Every figure is clamped at zero as it is copied, and a filled quantity above the
	 * total is cut to the total, so everything this class answers afterwards is arithmetic over plain numbers.
	 *
	 * @param offers the client's offers ({@code Client.getGrandExchangeOffers()}), any of whose slots may be null
	 */
	public static ExchangeOffers of(@Nullable final GrandExchangeOffer[] offers)
	{
		if (offers == null || offers.length == 0)
		{
			return EMPTY;
		}

		final int n = offers.length;
		final int[] itemIds = new int[n];
		final GrandExchangeOfferState[] states = new GrandExchangeOfferState[n];
		final int[] totals = new int[n];
		final int[] sold = new int[n];
		final long[] prices = new long[n];
		final long[] spent = new long[n];
		boolean any = false;
		for (int i = 0; i < n; i++)
		{
			states[i] = GrandExchangeOfferState.EMPTY;
			final GrandExchangeOffer offer = offers[i];
			if (offer == null)
			{
				continue;
			}

			final GrandExchangeOfferState state = offer.getState();
			final int itemId = offer.getItemId();
			if (state == null || state == GrandExchangeOfferState.EMPTY || itemId <= 0)
			{
				continue;
			}

			any = true;
			itemIds[i] = itemId;
			states[i] = state;
			totals[i] = Math.max(0, offer.getTotalQuantity());
			sold[i] = Math.min(totals[i], Math.max(0, offer.getQuantitySold()));
			prices[i] = Math.max(0L, offer.getPrice());
			spent[i] = Math.max(0L, offer.getSpent());
		}

		return any ? new ExchangeOffers(itemIds, states, totals, sold, prices, spent) : EMPTY;
	}

	/**
	 * The items the offers hold, one {@link Item} per slot whose quantity is positive, in slot order: for a sell
	 * offer the quantity not yet sold, for a buy offer the quantity bought and not yet collected. Two slots of one
	 * item are two items here; the reader folds them into one stack, by the same rules it folds the inventory's.
	 *
	 * <p>A fresh array on every call, so a caller can keep it and nothing else sees it change.
	 */
	public Item[] items()
	{
		final Item[] out = new Item[itemIds.length];
		int count = 0;
		for (int i = 0; i < itemIds.length; i++)
		{
			final int quantity = itemQuantity(i);
			if (quantity > 0)
			{
				out[count++] = new Item(itemIds[i], quantity);
			}
		}

		return count == out.length ? out : Arrays.copyOf(out, count);
	}

	/**
	 * The coins the offers hold, in gp: the coins received by sell offers and not yet collected, plus the coins still
	 * committed to buy offers. Each slot's share is clamped at zero and the slots are summed with
	 * {@link PortfolioMath#clampedAdd}, so a figure this plugin cannot make sense of can only ever read low, never
	 * wrap.
	 */
	public long cashGp()
	{
		long sum = 0L;
		for (int i = 0; i < itemIds.length; i++)
		{
			sum = PortfolioMath.clampedAdd(sum, slotCash(i));
		}

		return sum;
	}

	/** True when the offers hold no item and no coin at all. */
	public boolean isEmpty()
	{
		return cashGp() <= 0L && items().length == 0;
	}

	/** How many of the slots are not empty, for the debug lines. */
	public int slotsInUse()
	{
		int count = 0;
		for (final GrandExchangeOfferState state : states)
		{
			if (state != GrandExchangeOfferState.EMPTY)
			{
				count++;
			}
		}

		return count;
	}

	/** The items slot {@code i} holds; 0 for an empty slot. */
	private int itemQuantity(final int i)
	{
		switch (states[i])
		{
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				return totalQuantities[i] - quantitiesSold[i];
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return quantitiesSold[i];
			default:
				return 0;
		}
	}

	/** The coins slot {@code i} holds, never below zero; 0 for an empty slot. */
	private long slotCash(final int i)
	{
		switch (states[i])
		{
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				return spent[i];
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return Math.max(0L, asked(prices[i], totalQuantities[i]) - spent[i]);
			default:
				return 0L;
		}
	}

	/** {@code price x quantity}, clamped at {@link Long#MAX_VALUE} instead of wrapping. */
	private static long asked(final long price, final int quantity)
	{
		if (price <= 0L || quantity <= 0)
		{
			return 0L;
		}

		return quantity > Long.MAX_VALUE / price ? Long.MAX_VALUE : price * quantity;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof ExchangeOffers))
		{
			return false;
		}

		final ExchangeOffers other = (ExchangeOffers) o;
		return Arrays.equals(itemIds, other.itemIds)
			&& Arrays.equals(states, other.states)
			&& Arrays.equals(totalQuantities, other.totalQuantities)
			&& Arrays.equals(quantitiesSold, other.quantitiesSold)
			&& Arrays.equals(prices, other.prices)
			&& Arrays.equals(spent, other.spent);
	}

	@Override
	public int hashCode()
	{
		int h = Arrays.hashCode(itemIds);
		h = 31 * h + Arrays.hashCode(states);
		h = 31 * h + Arrays.hashCode(totalQuantities);
		h = 31 * h + Arrays.hashCode(quantitiesSold);
		h = 31 * h + Arrays.hashCode(prices);
		return 31 * h + Arrays.hashCode(spent);
	}

	/** Counts only - slots in use, items, gp - and never an item id. */
	@Override
	public String toString()
	{
		return "ExchangeOffers{slots=" + slotsInUse() + ", items=" + items().length + ", gp=" + cashGp() + '}';
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The "Hide amounts" eye (1.1.0 part E): a PIXEL eye on a {@value #SIZE} x {@value #SIZE} grid, the user's pick (design D of
 * four drawn, 2026-10-04: "drawn on RuneLite's pixel grid; slashed when hidden"). Every pixel is the icon's ink or clear -
 * no anti-aliasing, no blend - so it is as sharp as the game's own sprites at any display scale and nothing about it
 * depends on a font or a look and feel. Built pixel by pixel into an image once per look; there is no image file.
 *
 * <p>While the amounts SHOW the eye is open: an almond outline round a pupil, in rows {@value #FIRST_ROW} to
 * {@value #LAST_ROW} of the grid with the rows above and below them clear. While they are HIDDEN the same eye carries a slash
 * from the bottom-left corner to the top-right: for each column {@code i} the pixel {@code (i, SIZE - 1 - i)} is ink and the
 * pixels either side of it on that row are cleared, so the slash stands apart from the eye it crosses instead of running
 * into its outline.
 *
 * <p>Its ink (1.1.0 part I, the user's pick, 2026-10-04) says which state it is in before it is read: grey 52, near the
 * card's ground and quiet, while the amounts SHOW - the open eye, nothing to draw attention to - and grey 165, the other
 * icons' grey ({@link ColorScheme#LIGHT_GRAY_COLOR}), while they are HIDDEN, the slashed eye that tells a reader why the
 * numbers are dots; white under the mouse in both. {@link #ink} is that rule.
 */
final class EyeIcon
{
	/** The grid's side in px: the same 12 px the settings icon is drawn at ({@link Widgets#GEAR_SIZE}). */
	static final int SIZE = 12;
	/** The open eye's ink at rest, while the amounts show (part I): grey 52 - quiet. */
	static final Color SHOWN_INK = new Color(52, 52, 52);
	/** The slashed eye's ink at rest, while the amounts are hidden (part I): the other icons' grey, 165. */
	static final Color HIDDEN_INK = ColorScheme.LIGHT_GRAY_COLOR;
	/** The open eye's first and last rows of ink; every other row of the grid is clear. */
	static final int FIRST_ROW = 2;
	static final int LAST_ROW = 9;

	/** The open eye, rows {@link #FIRST_ROW} to {@link #LAST_ROW}: {@code X} is ink, {@code .} is clear. */
	private static final String[] EYE = {
		"....XXXX....",
		"..XX....XX..",
		".X...XX...X.",
		"X...XXXX...X",
		"X...XXXX...X",
		".X...XX...X.",
		"..XX....XX..",
		"....XXXX....",
	};

	private EyeIcon()
	{
	}

	/**
	 * The ink the eye is drawn in (part I): white while {@code hot} - the pointer is over it - in either state, otherwise
	 * {@link #HIDDEN_INK} while {@code hidden} and {@link #SHOWN_INK} while the amounts show.
	 */
	static Color ink(final boolean hidden, final boolean hot)
	{
		if (hot)
		{
			return Color.WHITE;
		}
		return hidden ? HIDDEN_INK : SHOWN_INK;
	}

	/**
	 * The eye as an icon: open while {@code hidden} is false, slashed while it is true, every ink pixel {@code ink} and every
	 * other pixel fully transparent.
	 */
	static ImageIcon icon(final boolean hidden, final Color ink)
	{
		final int argb = new Color(ink.getRed(), ink.getGreen(), ink.getBlue()).getRGB();
		final BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		for (int row = 0; row < EYE.length; row++)
		{
			for (int x = 0; x < SIZE; x++)
			{
				if (EYE[row].charAt(x) == 'X')
				{
					image.setRGB(x, FIRST_ROW + row, argb);
				}
			}
		}
		if (hidden)
		{
			for (int i = 0; i < SIZE; i++)
			{
				final int y = SIZE - 1 - i;
				if (i > 0)
				{
					image.setRGB(i - 1, y, 0);
				}
				if (i < SIZE - 1)
				{
					image.setRGB(i + 1, y, 0);
				}
				image.setRGB(i, y, argb);
			}
		}
		return new ImageIcon(image);
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.AffineTransform;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;

/**
 * The "List options" icon (1.1.0 part G): TWO GEARS in a {@value #SIZE} x {@value #SIZE} box, the user's pick (icon 23 of the
 * sheet {@code docs/handoff/lab/search-row-icons-grey-2026-10-04.png}, in the grey the search box paints "Search items" in),
 * drawn in code and anti-aliased - no image file, and nothing about it depends on a font or a look and feel.
 *
 * <p>The geometry is the contract's, in units of the box (x to the right, y down): a BIG gear at ({@value #BIG_X},
 * {@value #BIG_Y}) with a body of radius {@value #BIG_BODY}, {@value #BIG_TEETH} teeth reaching from radius
 * {@value #BIG_TOOTH_IN} to {@value #BIG_TOOTH_OUT} ({@value #BIG_TOOTH_HALF} either side of their centre line) and a hole of
 * radius {@value #BIG_HOLE}; and a SMALL gear at ({@value #SMALL_X}, {@value #SMALL_Y}) with a body of radius
 * {@value #SMALL_BODY}, {@value #SMALL_TEETH} teeth from {@value #SMALL_TOOTH_IN} to {@value #SMALL_TOOTH_OUT}
 * ({@value #SMALL_TOOTH_HALF} either side) and a hole of radius {@value #SMALL_HOLE}. The first tooth of each points along
 * the positive x axis.
 */
final class GearsIcon
{
	/** The box's side in px: the same 12 px the settings icon and the eye are drawn at. */
	static final int SIZE = 12;

	static final double BIG_X = 4.3;
	static final double BIG_Y = 7.7;
	static final double BIG_BODY = 3.0;
	static final int BIG_TEETH = 7;
	static final double BIG_TOOTH_IN = 2.2;
	static final double BIG_TOOTH_OUT = 4.2;
	static final double BIG_TOOTH_HALF = 0.9;
	static final double BIG_HOLE = 1.2;

	static final double SMALL_X = 9.2;
	static final double SMALL_Y = 3.0;
	static final double SMALL_BODY = 2.0;
	static final int SMALL_TEETH = 6;
	static final double SMALL_TOOTH_IN = 1.4;
	static final double SMALL_TOOTH_OUT = 2.8;
	static final double SMALL_TOOTH_HALF = 0.7;
	static final double SMALL_HOLE = 0.8;

	private GearsIcon()
	{
	}

	/** The two gears as an icon, every pixel {@code ink} with the coverage the anti-aliasing gives it, the rest clear. */
	static ImageIcon icon(final Color ink)
	{
		final BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(new Color(ink.getRed(), ink.getGreen(), ink.getBlue()));
			g.fill(gear(BIG_X, BIG_Y, BIG_BODY, BIG_TEETH, BIG_TOOTH_IN, BIG_TOOTH_OUT, BIG_TOOTH_HALF, BIG_HOLE));
			g.fill(gear(SMALL_X, SMALL_Y, SMALL_BODY, SMALL_TEETH, SMALL_TOOTH_IN, SMALL_TOOTH_OUT, SMALL_TOOTH_HALF,
				SMALL_HOLE));
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(image);
	}

	/**
	 * One gear's outline: the body disc, the teeth (rectangles standing on the body, evenly round it, the first along the
	 * positive x axis) and then the hole cut out of the lot.
	 */
	private static Area gear(final double centreX, final double centreY, final double body, final int teeth,
		final double toothIn, final double toothOut, final double toothHalf, final double hole)
	{
		final Area area = new Area(new Ellipse2D.Double(centreX - body, centreY - body, body * 2.0, body * 2.0));
		for (int i = 0; i < teeth; i++)
		{
			final Area tooth = new Area(new Rectangle2D.Double(toothIn, -toothHalf, toothOut - toothIn, toothHalf * 2.0));
			tooth.transform(AffineTransform.getRotateInstance(i * 2.0 * Math.PI / teeth));
			tooth.transform(AffineTransform.getTranslateInstance(centreX, centreY));
			area.add(tooth);
		}
		area.subtract(new Area(new Ellipse2D.Double(centreX - hole, centreY - hole, hole * 2.0, hole * 2.0)));
		return area;
	}
}

package com.bankpricemovement;

/**
 * How far one live figure can be trusted (contract 1.2.0, line L3;
 * {@code docs/handoff/contract-1.2.0-graded-live-moves-2026-10-07.md}). Every row the traded feeds price carries one,
 * per window, beside its figure ({@link GradedMove#grade()}); a row computed with live prices off carries none.
 *
 * <p>The order is the order the % and gp sorts put the rows in, in both directions (L5): every SOLID row before every
 * SOFT one, and every SOFT one before every NONE one - so a soft figure, however large, never heads the list above a
 * solid one ({@link MovementMath#comparator}).
 */
public enum Grade
{
	/**
	 * Both sides traded today and yesterday, inside the plausibility anchor, with real money behind the thinner side, a
	 * price of at least 100 gp, and the two sides agreeing to within ten points ({@link GradeMath} has every line of
	 * the test). Drawn exactly as every figure was before 1.2.0.
	 */
	SOLID("solid"),
	/**
	 * A figure, but one fact of the solid test failed - and {@link GradedMove#word()} names the first that did, in the
	 * contract's order ({@link GradeWords}). Drawn with the same digits as a solid figure; only the word beside it
	 * differs (the user's pick, L5).
	 */
	SOFT("soft"),
	/** No trade today and nothing for a fallback to compare: no figure at all - the dash, with "no trades". */
	NONE("none");

	private final String label;

	Grade(final String label)
	{
		this.label = label;
	}

	/** The lower-case word the dev bridge echoes as {@code state.rows[].grade}: "solid", "soft" or "none". */
	public String label()
	{
		return label;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import javax.annotation.Nullable;

/**
 * The graded live figure of contract 1.2.0 ({@code docs/handoff/contract-1.2.0-graded-live-moves-2026-10-07.md}), in
 * ONE pure place: the plausibility anchor and the last 24 hours' observations (L2), the same-side figure for a window,
 * its fallback and its grade with the word that names why (L3), and every threshold those rules use - each a named
 * constant here, so a threshold is changed by changing one line (the user, 2026-10-07: "use your recommendations for
 * now and we can always change them quickly during testing").
 *
 * <p>Pure on purpose, like {@link MovementMath}: {@code PriceService} gathers the inputs on its executor and asks this
 * class, and the tests ask it the same questions with synthetic items, no client and no clock.
 *
 * <p><b>Why same-side.</b> The two sides of the exchange sit a spread apart, and the newest print flips between them
 * as buyers and sellers take turns: a "now" that is the last print, compared against a day's average of both, moves
 * by the spread with every trade (the comparator's R2 plan put 82 rows over 20 % a day). The last 24 hours' buys are
 * compared with yesterday's buys and the last 24 hours' sells with yesterday's sells, and each side's "now" is the
 * MEDIAN of its observations in those 24 hours, so one silly print cannot carry it - and the 3x anchor throws out the
 * 1 gp prints that would. "Today" is a rolling 24 hours and not the UTC calendar day (the user, 2026-10-07: measured on
 * a bank 2.7 h into the UTC day, 33 rows had a silent side by the calendar rule and 3 by the 24-hour one).
 *
 * <p><b>One side.</b> When exactly one side has observations the row is priced at that side's own median and compared
 * with that side's own average on the window's day (the user: "if all the trades were buyers paying that, that is the
 * current price"), and it is no weaker for it: it is solid when the same facts hold. With both sides the price is the
 * two-sided mark moved by the mean of the two moves.
 *
 * <p><b>Solid or soft</b> (the user's final decision, 2026-10-07). A figure is SOFT only when one of three facts holds,
 * and carries the word of the first: nothing traded in the last 24 hours (the fallback, {@link GradeWords#lastTraded}),
 * the compared day's thinner side under {@value #WORD_MIN_DAY_COUNT} units ({@link GradeWords#volume}), or the current
 * pair - both sides reported in the last 24 hours - more than {@value #WORD_MAX_QUOTE_GAP_PCT} % of its middle apart
 * ({@link GradeWords#spread}, which says how far). Everything else is SOLID and carries no word.
 */
final class GradeMath
{
	// ---------------------------------------------------------------- L2: the anchor and the observations

	/** A price is plausible within this factor of the anchor A, either way: {@code A / 3 <= p <= 3 x A} (L2). */
	static final long PLAUSIBLE_FACTOR = 3L;

	/**
	 * How far back "today" reaches (L2, the user's 2026-10-07 decision): a print of a side - the current {@code /latest}
	 * one, or one the poll memory holds - counts as an observation only up to this old, 24 hours, whatever UTC day it
	 * is of.
	 */
	static final long LATEST_PRINT_MAX_AGE_SECONDS = 24L * 60L * 60L;

	/** The {@code /1h} bucket's span. */
	static final long HOUR_SECONDS = 60L * 60L;

	/** The {@code /1h} side average counts as an observation while the bucket ended at most this long ago: 3 h (L2). */
	static final long HOUR_MAX_AGE_SECONDS = 3L * HOUR_SECONDS;

	/** A side average counts only when at least this many units traded on that side (L2): one. */
	static final long MIN_SIDE_VOLUME = 1L;

	/**
	 * The largest price reasoned about, above which a figure is not measured: {@link Long#MAX_VALUE} / 200, so no
	 * comparison here can wrap (the gap test multiplies by 100). Four orders of magnitude past the dearest item.
	 */
	static final long PRICE_CEILING = Long.MAX_VALUE / 200L;

	// ---------------------------------------------------------------- L3: the solid test and its words

	/**
	 * The compared day's thinner side must have traded at least this many units for a figure to be solid, and under it the
	 * word {@link GradeWords#volume} is said: ten (L3). The user's final decision of 2026-10-07 made this, the pair's gap
	 * and the fallback the only three facts that make a figure soft; the money floors, the hour's floor, the observation
	 * count, the 100 gp price floor and the sides-agree clause left the test.
	 */
	static final long WORD_MIN_DAY_COUNT = 10L;

	/**
	 * The word {@link GradeWords#spread} fires - and the figure is soft - when the current pair's gap is over this
	 * percentage of its middle: ten.
	 */
	static final int WORD_MAX_QUOTE_GAP_PCT = 10;

	/**
	 * Two side moves "agree" when they are at most this many percentage points apart: ten. It is no part of the solid test
	 * (the user's first live look retired the sides-agree clause); it only picks which of two sentences the open block
	 * closes on ({@link #sidesAgree}).
	 */
	static final int SOLID_MAX_SIDE_GAP_POINTS = 10;

	/**
	 * How far two side moves may differ and still be "within ten points", in points, to absorb the binary rounding of a
	 * difference that is exactly ten points in decimal (1.2 - 1.1 is not 0.1 in a double).
	 */
	private static final double SIDE_GAP_TOLERANCE_POINTS = 1e-9d;

	// ---------------------------------------------------------------- L3: the card

	/** The card is SOFT when its solid rows hold less than this percentage of the counted value (L3). */
	static final int CARD_SOLID_VALUE_PCT = 90;

	/** ... or when its soft rows supply more than this percentage of its gp move (L3). */
	static final int CARD_SOFT_MOVE_PCT = 10;

	// ---------------------------------------------------------------- L1: the inputs' cadence

	/**
	 * At most this many {@code /1h} requests in one UTC day (L1): one per closed hour, and a retry of an hour the wiki
	 * had not cut yet counts as a request, so a late wiki can use the day's twenty-four up before the day ends - the
	 * hour then goes without, and the figures carry on with today's prints (the no-hour rule of L3).
	 */
	static final int HOUR_MAX_FETCHES_PER_DAY = 24;

	/**
	 * How long after an EMPTY {@code /1h} answer (the wiki has not cut the hour yet) the same hour is asked for again,
	 * milliseconds: five minutes. The wiki's cut lands within a minute or two of the top of the hour; the empty answer
	 * carries {@code Cache-Control: no-cache}, so a retry reaches the origin and is not served the empty one.
	 */
	static final long HOUR_RETRY_MILLIS = 5L * 60L * 1000L;

	/**
	 * How many times one closed hour is asked for in all (the first request and its retries): three. An hour still empty
	 * after that is left (its figures carry on with today's prints) until the next hour closes.
	 */
	static final int HOUR_MAX_TRIES_PER_HOUR = 3;

	/**
	 * How many distinct prints of one side of one item the poll memory keeps (L1), the oldest dropped first: 48, a
	 * whole day of the thirty-minute tick. A bound on memory, never reached by the tick alone.
	 */
	static final int POLL_MEMORY_MAX_PRINTS = 48;

	private GradeMath()
	{
	}

	// ---------------------------------------------------------------- one item's facts, the same for every window

	/**
	 * One side's observations of the last 24 hours: how many there were and their median (L2). Immutable.
	 */
	static final class Observed
	{
		static final Observed NONE = new Observed(0, null);

		final int count;
		@Nullable
		final Long median;

		Observed(final int count, @Nullable final Long median)
		{
			this.count = count;
			this.median = median;
		}
	}

	/**
	 * What one item's figures are made from, the same for every window: the anchor, the last 24 hours' observations per
	 * side (the {@code /1h} bucket's averages among them), the current {@code /latest} pair and yesterday's and the day
	 * before's buckets. Built by {@link #facts}; immutable.
	 */
	static final class Facts
	{
		/** The clock the facts were taken at, unix seconds: how old a print and an hour are, and how long ago the item last traded. */
		final long nowSeconds;
		@Nullable
		final LocalDate today;
		@Nullable
		final Long anchor;
		final Observed buy;
		final Observed sell;
		@Nullable
		final TradedPriceClient.Quote quote;
		@Nullable
		final TradedPriceClient.Bucket d1;
		@Nullable
		final LocalDate d1Day;
		@Nullable
		final TradedPriceClient.Bucket d2;
		@Nullable
		final LocalDate d2Day;

		private Facts(final long nowSeconds, @Nullable final LocalDate today, @Nullable final Long anchor,
			final Observed buy, final Observed sell, @Nullable final TradedPriceClient.Quote quote,
			@Nullable final TradedPriceClient.Bucket d1, @Nullable final LocalDate d1Day,
			@Nullable final TradedPriceClient.Bucket d2, @Nullable final LocalDate d2Day)
		{
			this.nowSeconds = nowSeconds;
			this.today = today;
			this.anchor = anchor;
			this.buy = buy;
			this.sell = sell;
			this.quote = quote;
			this.d1 = d1;
			this.d1Day = d1Day;
			this.d2 = d2;
			this.d2Day = d2Day;
		}
	}

	/**
	 * One item's facts (L1, L2): its anchor, and the plausible observations of each side in the last 24 hours - every
	 * distinct print the poll memory holds, the current {@code /latest} print, each when it is at most
	 * {@value #LATEST_PRINT_MAX_AGE_SECONDS} seconds old, and the {@code /1h} side average when that side traded and the
	 * hour ended at most {@value #HOUR_MAX_AGE_SECONDS} seconds ago.
	 *
	 * @param nowSeconds the clock, unix seconds
	 * @param today      the live day - the UTC date of the {@code /latest} snapshot; it labels the figure (the day "now"
	 *                   is of) and no longer decides which prints count. Null: there is no live snapshot and nothing is
	 *                   observed
	 * @param guideNow   the item's guide price now (RuneLite's, or the newest guide table's), the anchor's first value
	 * @param quote      the item's current {@code /latest} pair, or null
	 * @param buyPrints  the poll memory's buy prints of the item as {@code price, seconds} pairs; null or empty for none
	 * @param sellPrints the same for the sell side
	 * @param hour       the item's {@code /1h} bucket, or null when the feed does not name it
	 * @param hourStart  the {@code /1h} bucket's start, unix seconds; 0 when there is no {@code /1h} feed in hand
	 * @param d1         yesterday's bucket for the item, or null
	 * @param d1Day      the day {@code d1} records
	 * @param d2         the day before yesterday's bucket for the item ({@code traded-D2.json}), or null
	 * @param d2Day      the day {@code d2} records
	 */
	static Facts facts(final long nowSeconds, @Nullable final LocalDate today, @Nullable final Long guideNow,
		@Nullable final TradedPriceClient.Quote quote, @Nullable final long[] buyPrints, @Nullable final long[] sellPrints,
		@Nullable final TradedPriceClient.Bucket hour, final long hourStart, @Nullable final TradedPriceClient.Bucket d1,
		@Nullable final LocalDate d1Day, @Nullable final TradedPriceClient.Bucket d2, @Nullable final LocalDate d2Day)
	{
		final Long anchor = anchor(guideNow, d1, d2);
		final boolean hourFresh = hourStart > 0L && nowSeconds - (hourStart + HOUR_SECONDS) <= HOUR_MAX_AGE_SECONDS;
		final Observed buy = observe(true, nowSeconds, today, buyPrints, quote, hour, hourFresh, anchor);
		final Observed sell = observe(false, nowSeconds, today, sellPrints, quote, hour, hourFresh, anchor);
		return new Facts(nowSeconds, today, anchor, buy, sell, quote, d1, d1Day, d2, d2Day);
	}

	/**
	 * The plausibility anchor A (L2): the median of the values present among the guide price now and yesterday's two
	 * side averages - the day before's two when yesterday's bucket names neither side. Null when none is present, and
	 * then no price is plausible.
	 */
	@Nullable
	static Long anchor(@Nullable final Long guideNow, @Nullable final TradedPriceClient.Bucket d1,
		@Nullable final TradedPriceClient.Bucket d2)
	{
		final long[] values = new long[3];
		int n = 0;
		if (sane(guideNow))
		{
			values[n++] = guideNow;
		}
		final TradedPriceClient.Bucket day = d1 != null && (d1.avgHigh() != null || d1.avgLow() != null) ? d1 : d2;
		if (day != null)
		{
			if (sane(day.avgHigh()))
			{
				values[n++] = day.avgHigh();
			}
			if (sane(day.avgLow()))
			{
				values[n++] = day.avgLow();
			}
		}
		return median(values, n);
	}

	/**
	 * Whether a price is plausible against the anchor (L2): {@code A / 3 <= p <= 3 x A}, in integers ({@code 3p >= A}
	 * and {@code p <= 3A}). No anchor, no price, or a price past {@link #PRICE_CEILING}: not plausible.
	 */
	static boolean plausible(@Nullable final Long price, @Nullable final Long anchor)
	{
		if (!sane(price) || !sane(anchor))
		{
			return false;
		}
		return price * PLAUSIBLE_FACTOR >= anchor && price <= anchor * PLAUSIBLE_FACTOR;
	}

	/**
	 * The median of the first {@code n} values (L2): the middle one, or the mean of the middle two - rounded half up,
	 * in halves so no pair can overflow - when {@code n} is even. Null for none.
	 */
	@Nullable
	static Long median(final long[] values, final int n)
	{
		if (values == null || n <= 0)
		{
			return null;
		}
		final long[] sorted = Arrays.copyOf(values, Math.min(n, values.length));
		Arrays.sort(sorted);
		final int middle = sorted.length / 2;
		if (sorted.length % 2 == 1)
		{
			return sorted[middle];
		}
		return halfUpMean(sorted[middle - 1], sorted[middle]);
	}

	/** One side's observations of the last 24 hours (L2), plausible ones only. */
	private static Observed observe(final boolean buySide, final long nowSeconds, @Nullable final LocalDate today,
		@Nullable final long[] prints, @Nullable final TradedPriceClient.Quote quote,
		@Nullable final TradedPriceClient.Bucket hour, final boolean hourFresh, @Nullable final Long anchor)
	{
		if (today == null)
		{
			return Observed.NONE;
		}
		final int printed = prints == null ? 0 : prints.length / 2;
		final long[] values = new long[printed + 2];
		final long[] times = new long[printed + 1];
		int n = 0;
		for (int i = 0; i < printed; i++)
		{
			final long price = prints[2 * i];
			final long seconds = prints[2 * i + 1];
			if (price > 0L && seconds > 0L && nowSeconds - seconds <= LATEST_PRINT_MAX_AGE_SECONDS
				&& !seen(values, times, n, price, seconds))
			{
				times[n] = seconds;
				values[n++] = price;
			}
		}
		if (quote != null)
		{
			final Long price = buySide ? quote.buy() : quote.sell();
			final long seconds = buySide ? quote.buySeconds() : quote.sellSeconds();
			if (price != null && price > 0L && seconds > 0L && nowSeconds - seconds <= LATEST_PRINT_MAX_AGE_SECONDS
				&& !seen(values, times, n, price, seconds))
			{
				times[n] = seconds;
				values[n++] = price;
			}
		}
		if (hourFresh && hour != null)
		{
			final Long average = buySide ? hour.avgHigh() : hour.avgLow();
			final long volume = buySide ? hour.highVolume() : hour.lowVolume();
			if (average != null && average > 0L && volume >= MIN_SIDE_VOLUME)
			{
				values[n++] = average;
			}
		}
		final long[] kept = new long[n];
		int k = 0;
		for (int i = 0; i < n; i++)
		{
			if (plausible(values[i], anchor))
			{
				kept[k++] = values[i];
			}
		}
		return k == 0 ? Observed.NONE : new Observed(k, median(kept, k));
	}

	/** Whether {@code price} at {@code seconds} is among the first {@code n} prints already taken. */
	private static boolean seen(final long[] values, final long[] times, final int n, final long price,
		final long seconds)
	{
		for (int i = 0; i < n && i < times.length; i++)
		{
			if (values[i] == price && times[i] == seconds)
			{
				return true;
			}
		}
		return false;
	}

	// ---------------------------------------------------------------- L2 and L3: one window's figure

	/**
	 * One window's graded figure (L2, L3) for an item whose {@link Facts} are in hand:
	 * <ul>
	 * <li>MEASURED when a side has both today's "now" and a "then" on the window's day (volume at least
	 * {@value #MIN_SIDE_VOLUME}, inside the anchor): the side moves, their mean, the mark and the grade;</li>
	 * <li>otherwise, when NO side was observed today, the FALLBACK - yesterday's move: yesterday's side averages against
	 * the day before's for 1d ({@code traded-D2.json}), and against the window's own day for a longer window (a day
	 * short of the window: the day before the window's day is not fetched). Always SOFT;</li>
	 * <li>otherwise NONE - "no trades".</li>
	 * </ul>
	 *
	 * @param facts  the item's facts
	 * @param window the window; null reads as 1d
	 * @param dN     the window's day's bucket for the item, or null
	 * @param dNDay  the day {@code dN} records
	 */
	static GradedMove figure(final Facts facts, @Nullable final MovementWindow window,
		@Nullable final TradedPriceClient.Bucket dN, @Nullable final LocalDate dNDay)
	{
		final Long anchor = facts.anchor;
		final Long lastBuy = facts.quote == null ? null : facts.quote.buy();
		final long lastBuyAt = facts.quote == null ? 0L : facts.quote.buySeconds();
		final Long lastSell = facts.quote == null ? null : facts.quote.sell();
		final long lastSellAt = facts.quote == null ? 0L : facts.quote.sellSeconds();

		final Long thenBuy = sideAverage(dN, true, anchor);
		final Long thenSell = sideAverage(dN, false, anchor);
		final Double buyMove = ratio(facts.buy.median, thenBuy);
		final Double sellMove = ratio(facts.sell.median, thenSell);
		if (buyMove != null || sellMove != null)
		{
			final double move = mean(buyMove, sellMove);
			// With exactly ONE side observed the row is priced at that side's own price against that side's own average
			// (the user: "if all the trades were buyers paying that, that is the current price"), so its worth, its was
			// and its change all stand on the one side. With both sides observed it is the two-sided mark moved by the
			// mean of the moves, as before.
			final boolean buyOnly = facts.buy.count > 0 && facts.sell.count == 0 && buyMove != null;
			final boolean sellOnly = facts.sell.count > 0 && facts.buy.count == 0 && sellMove != null;
			final long thenMark = buyOnly ? thenBuy : sellOnly ? thenSell : mark(thenBuy, thenSell, anchor);
			final long deltaGp = buyOnly ? facts.buy.median - thenBuy : sellOnly ? facts.sell.median - thenSell
				: deltaOf(thenMark, move);
			final long price = thenMark + deltaGp;
			// SOLID (the user's final decision, 2026-10-07): a figure that exists, inside the anchor's range, with none of the
			// three facts that name a word - not the fallback, the compared day's thinner side at least ten units, the
			// pair's gap at most a tenth of its middle. A figure reported on one side only is as solid as one reported on both.
			final Long spreadPct = wideSpreadPercent(facts);
			final String word = measuredWord(facts, dN, price, spreadPct);
			final boolean solid = GradeWords.SOLID.equals(word);
			return new GradedMove(solid ? Grade.SOLID : Grade.SOFT, word, move, thenMark, deltaGp, false,
				new GradedMove.Side(facts.buy.median, thenBuy, buyMove, facts.buy.count, lastBuy, lastBuyAt),
				new GradedMove.Side(facts.sell.median, thenSell, sellMove, facts.sell.count, lastSell, lastSellAt),
				facts.today, dNDay, anchor, spreadPct);
		}
		if (facts.buy.count == 0 && facts.sell.count == 0)
		{
			final boolean oneDay = window == null || window == MovementWindow.D1;
			final TradedPriceClient.Bucket thenBucket = oneDay ? facts.d2 : dN;
			final LocalDate thenDay = oneDay ? facts.d2Day : dNDay;
			final Long nowBuy = sideAverage(facts.d1, true, anchor);
			final Long nowSell = sideAverage(facts.d1, false, anchor);
			final Long dayBuy = sideAverage(thenBucket, true, anchor);
			final Long daySell = sideAverage(thenBucket, false, anchor);
			final Double dayBuyMove = ratio(nowBuy, dayBuy);
			final Double daySellMove = ratio(nowSell, daySell);
			if (dayBuyMove != null || daySellMove != null)
			{
				final double move = mean(dayBuyMove, daySellMove);
				final long thenMark = mark(dayBuy, daySell, anchor);
				final long deltaGp = deltaOf(thenMark, move);
				return new GradedMove(Grade.SOFT, fallbackWord(facts), move, thenMark,
					deltaGp, true, new GradedMove.Side(nowBuy, dayBuy, dayBuyMove, 0, lastBuy, lastBuyAt),
					new GradedMove.Side(nowSell, daySell, daySellMove, 0, lastSell, lastSellAt), facts.d1Day, thenDay,
					anchor);
			}
		}
		return new GradedMove(Grade.NONE, GradeWords.NO_TRADES, null, null, null, false,
			new GradedMove.Side(facts.buy.median, null, null, facts.buy.count, lastBuy, lastBuyAt),
			new GradedMove.Side(facts.sell.median, null, null, facts.sell.count, lastSell, lastSellAt), null, null,
			anchor);
	}

	/**
	 * The word of a MEASURED figure (L3, the user's final decision of 2026-10-07), or {@link GradeWords#SOLID} (the empty
	 * string) when it has none: the FIRST of the facts that make a figure soft. The compared day's thinner side traded
	 * under {@value #WORD_MIN_DAY_COUNT} units ({@link GradeWords#volume}); the current pair, both sides reported in the
	 * last 24 hours, more than {@value #WORD_MAX_QUOTE_GAP_PCT} % of its middle apart ({@link GradeWords#spread}, with its
	 * number). A figure with neither is solid
	 * if its price is inside the anchor's range - and a price outside it, the one other way a measured figure can fail
	 * (the two sides moving violently opposite ways, which no bank has met), has no word of its own, so it says
	 * the plain {@link GradeWords#SPREAD}, the sides being far apart: a soft row always carries a word and a row with no word is
	 * solid. A figure reported on one side only is judged by the same facts - the old word "1 side" is gone and
	 * one-sidedness is no weakness.
	 */
	private static String measuredWord(final Facts facts, @Nullable final TradedPriceClient.Bucket dN, final long price,
		@Nullable final Long spreadPct)
	{
		final long count = thinnerCount(dN);
		if (count < WORD_MIN_DAY_COUNT)
		{
			return GradeWords.volume(count);
		}
		if (spreadPct != null)
		{
			return GradeWords.spread(spreadPct);
		}
		return plausible(price, facts.anchor) ? GradeWords.SOLID : GradeWords.SPREAD;
	}

	/**
	 * The word of the FALLBACK figure (yesterday's move, nothing traded in the last 24 hours): how long it has been since the
	 * item last traded ({@link GradeWords#lastTraded}), from the newer of the two current prints' times that the figure would
	 * count, against the clock; {@link GradeWords#YDAY} when no print time is known. A plausible print is older than the 24
	 * hours that were silent - and an implausible one (outside the anchor's range) is no trade the figure counts, so it is no
	 * trade the word counts.
	 */
	private static String fallbackWord(final Facts facts)
	{
		final TradedPriceClient.Quote last = facts.quote;
		long lastTrade = 0L;
		if (last != null)
		{
			lastTrade = Math.max(plausible(last.buy(), facts.anchor) ? last.buySeconds() : 0L,
				plausible(last.sell(), facts.anchor) ? last.sellSeconds() : 0L);
		}
		return lastTrade <= 0L ? GradeWords.YDAY : GradeWords.lastTraded(facts.nowSeconds - lastTrade);
	}

	/**
	 * The current pair's spread as a whole percentage of its middle when it is a CURRENT and WIDE one, else null - the fact
	 * behind {@link GradeWords#spread}. Current: BOTH sides reported in the last 24 hours, each print at most
	 * {@value #LATEST_PRINT_MAX_AGE_SECONDS} seconds old and inside the anchor's range (the test a print passes to be an
	 * observation, so a side that is silent for a day or only prints junk makes the pair no spread, and a figure reported on
	 * one side only never has one). Wide: the gap over {@value #WORD_MAX_QUOTE_GAP_PCT} % of the middle, in integers.
	 */
	@Nullable
	private static Long wideSpreadPercent(final Facts facts)
	{
		final TradedPriceClient.Quote quote = facts.quote;
		if (quote == null || !reportedInTheLast24Hours(quote.buy(), quote.buySeconds(), facts)
			|| !reportedInTheLast24Hours(quote.sell(), quote.sellSeconds(), facts))
		{
			return null;
		}
		final Long gap = quote.spread();
		final Long mid = quote.mid();
		return gap != null && mid != null && mid > 0L && gap * 100L > mid * WORD_MAX_QUOTE_GAP_PCT
			? spreadPercent(quote.buy(), quote.sell()) : null;
	}

	/** Whether a print counts as its side having reported in the last 24 hours: the age and the range of an observation. */
	private static boolean reportedInTheLast24Hours(@Nullable final Long price, final long seconds, final Facts facts)
	{
		return price != null && seconds > 0L && facts.nowSeconds - seconds <= LATEST_PRINT_MAX_AGE_SECONDS
			&& plausible(price, facts.anchor);
	}

	/**
	 * Whether two side moves agree to within {@value #SOLID_MAX_SIDE_GAP_POINTS} percentage points. False when either is
	 * missing. Not part of the solid test since 2026-10-07; the open block closes on "Both sides agree." or "The sides
	 * disagree, so the move is uncertain." by it.
	 */
	static boolean sidesAgree(@Nullable final Double buyMove, @Nullable final Double sellMove)
	{
		return buyMove != null && sellMove != null
			&& Math.abs(buyMove - sellMove) * 100.0d <= SOLID_MAX_SIDE_GAP_POINTS + SIDE_GAP_TOLERANCE_POINTS;
	}

	/**
	 * An untradeable stack's figure as the sum of its tradeable parts' (addendum R's rule, carried to 1.2.0): "then" is
	 * the parts' marks summed, "now" their window prices summed, and the grade the worst of theirs - SOLID only when
	 * every part is, the first soft part's word otherwise. NONE ("no trades") when any part has no figure: half a sum is
	 * not the item's price.
	 *
	 * @param parts  the stack's parts
	 * @param moveOf each part id's figure for this window, or null when it has none
	 */
	static GradedMove combineParts(@Nullable final List<BankItem.Part> parts,
		final Function<Integer, GradedMove> moveOf)
	{
		if (parts == null || parts.isEmpty())
		{
			return new GradedMove(Grade.NONE, GradeWords.NO_TRADES, null, null, null, false, null, null, null, null, null);
		}
		long then = 0L;
		long now = 0L;
		Grade grade = Grade.SOLID;
		String word = GradeWords.SOLID;
		boolean fallback = false;
		LocalDate nowDay = null;
		LocalDate thenDay = null;
		for (final BankItem.Part part : parts)
		{
			final GradedMove move = part == null || part.quantity <= 0L ? null : moveOf.apply(part.id);
			if (move == null || !move.hasFigure())
			{
				return new GradedMove(Grade.NONE, GradeWords.NO_TRADES, null, null, null, false, null, null, null, null,
					null);
			}
			then = PortfolioMath.clampedAdd(then, clampedMultiply(move.thenMark(), part.quantity));
			now = PortfolioMath.clampedAdd(now, clampedMultiply(move.price(), part.quantity));
			if (move.grade() == Grade.SOFT && grade == Grade.SOLID)
			{
				grade = Grade.SOFT;
				word = move.word();
			}
			fallback |= move.fallback();
			if (nowDay == null)
			{
				nowDay = move.nowDay();
				thenDay = move.thenDay();
			}
		}
		if (then <= 0L)
		{
			return new GradedMove(Grade.NONE, GradeWords.NO_TRADES, null, null, null, false, null, null, null, null, null);
		}
		return new GradedMove(grade, word, now / (double) then - 1.0d, then, now - then, fallback, null, null, nowDay,
			thenDay, null);
	}

	// ---------------------------------------------------------------- small pure helpers

	/** {@code part} as a whole percentage of {@code whole}, rounded half up - the figure the open block's spread clause names. */
	static long percentOf(final long part, final long whole)
	{
		if (whole <= 0L)
		{
			return 0L;
		}
		return (part * 100L + whole / 2L) / whole;
	}

	/**
	 * The spread between a last buy print and a last sell print as a whole percentage of their middle - {@code |buy -
	 * sell| / mid}, rounded half up - which is the figure behind {@link GradeWords#spread}, shown in the word and in the open block
	 * ("The buy and sell prices are 30% apart."). Null when either print is missing or past the ceiling.
	 */
	@Nullable
	static Long spreadPercent(@Nullable final Long buy, @Nullable final Long sell)
	{
		if (!sane(buy) || !sane(sell))
		{
			return null;
		}
		return percentOf(Math.abs(buy - sell), halfUpMean(buy, sell));
	}

	/**
	 * Whether {@code part} is under {@code pct} percent of {@code whole} - {@code part x 100 < whole x pct} - in longs,
	 * and in doubles only when a product would overflow. The card's two shares (L3).
	 */
	static boolean underShare(final long part, final long whole, final int pct)
	{
		try
		{
			return Math.multiplyExact(part, 100L) < Math.multiplyExact(whole, (long) pct);
		}
		catch (final ArithmeticException overflow)
		{
			return part * 100.0d < whole * (double) pct;
		}
	}

	/**
	 * Whether {@code part} is over {@code pct} percent of {@code whole} - {@code part x 100 > whole x pct} - in longs,
	 * and in doubles only when a product would overflow. The card's soft-move share (L3).
	 */
	static boolean overShare(final long part, final long whole, final int pct)
	{
		try
		{
			return Math.multiplyExact(part, 100L) > Math.multiplyExact(whole, (long) pct);
		}
		catch (final ArithmeticException overflow)
		{
			return part * 100.0d > whole * (double) pct;
		}
	}

	/**
	 * One side's average of a bucket when it counts (L2): that side traded at least {@value #MIN_SIDE_VOLUME} unit and
	 * its average is plausible against the anchor. Null otherwise.
	 */
	@Nullable
	private static Long sideAverage(@Nullable final TradedPriceClient.Bucket bucket, final boolean buySide,
		@Nullable final Long anchor)
	{
		if (bucket == null)
		{
			return null;
		}
		final Long average = buySide ? bucket.avgHigh() : bucket.avgLow();
		final long volume = buySide ? bucket.highVolume() : bucket.lowVolume();
		return volume >= MIN_SIDE_VOLUME && plausible(average, anchor) ? average : null;
	}

	/** {@code now / then - 1}, or null when either is missing. */
	@Nullable
	private static Double ratio(@Nullable final Long now, @Nullable final Long then)
	{
		return now == null || then == null || then <= 0L ? null : now / (double) then - 1.0d;
	}

	/** The mean of the present moves; one of them is always present where this is called. */
	private static double mean(@Nullable final Double a, @Nullable final Double b)
	{
		if (a != null && b != null)
		{
			return (a + b) / 2.0d;
		}
		return a != null ? a : (b != null ? b : 0.0d);
	}

	/**
	 * The mark a figure moves from (L2): the two sides' "then" halved when both are present, else the one present,
	 * else the anchor - and 1 if even that is missing, which no caller reaches (a move implies a "then").
	 */
	private static long mark(@Nullable final Long buy, @Nullable final Long sell, @Nullable final Long anchor)
	{
		if (buy != null && sell != null)
		{
			return halfUpMean(buy, sell);
		}
		if (buy != null)
		{
			return buy;
		}
		if (sell != null)
		{
			return sell;
		}
		return anchor != null && anchor > 0L ? anchor : 1L;
	}

	/**
	 * One item's gp move, {@code round(thenMark x move)} - held so the price it makes stays at least 1 gp, because a
	 * price of 0 is "no price" everywhere in this plugin.
	 */
	private static long deltaOf(final long thenMark, final double move)
	{
		final long delta = Math.round(thenMark * move);
		return Math.max(delta, 1L - thenMark);
	}

	/** The thinner side's unit count on one bucket; 0 for none. */
	private static long thinnerCount(@Nullable final TradedPriceClient.Bucket bucket)
	{
		return bucket == null ? 0L : Math.min(bucket.highVolume(), bucket.lowVolume());
	}

	/** The mean of two non-negative longs rounded half up, added in halves so it cannot overflow. */
	private static long halfUpMean(final long a, final long b)
	{
		final long half = a / 2L + b / 2L;
		final long remainder = (a % 2L) + (b % 2L);
		return half + (remainder + 1L) / 2L;
	}

	/** {@code a x b} clamped at {@link Long#MAX_VALUE}; both are non-negative where this is called. */
	private static long clampedMultiply(final long a, final long b)
	{
		try
		{
			return Math.multiplyExact(Math.max(0L, a), Math.max(0L, b));
		}
		catch (final ArithmeticException overflow)
		{
			return Long.MAX_VALUE;
		}
	}

	/** A price this class reasons about: present, positive and at most {@link #PRICE_CEILING}. */
	private static boolean sane(@Nullable final Long gp)
	{
		return gp != null && gp > 0L && gp <= PRICE_CEILING;
	}
}

package com.bankpricemovement;

import java.util.Objects;

/**
 * The card's grade (contract 1.2.0, line L3): how the counted rows of one computation split between SOLID, SOFT and
 * NONE for the window on screen, how much of the bank's value the solid ones hold, and how much of its gp move the soft
 * ones supply. The card is SOFT ({@link #soft()}) when the solid rows hold less than
 * {@value GradeMath#CARD_SOLID_VALUE_PCT} % of the counted value or the soft rows supply more than
 * {@value GradeMath#CARD_SOFT_MOVE_PCT} % of the gp move; its hover then says "n of m rows solid" (L5).
 *
 * <p>The counted value is every stack the bank value adds up, cash left out; the gp move is the sum of every counted
 * row's stack move taken WITHOUT its sign, so a rise and a fall cannot cancel into a soft share of nothing. Immutable;
 * {@link #NONE} for a computation that graded nothing (live prices off, or no usable snapshot), which is never soft.
 */
public final class GradeSummary
{
	/** Nothing graded: live prices off or unusable. Never soft. */
	public static final GradeSummary NONE = new GradeSummary(false, 0, 0, 0, 0L, 0L, 0L, 0L);

	private final boolean graded;
	private final int solidRows;
	private final int softRows;
	private final int noneRows;
	private final long solidValue;
	private final long countedValue;
	private final long softMoveGp;
	private final long totalMoveGp;

	GradeSummary(final boolean graded, final int solidRows, final int softRows, final int noneRows,
		final long solidValue, final long countedValue, final long softMoveGp, final long totalMoveGp)
	{
		this.graded = graded;
		this.solidRows = Math.max(0, solidRows);
		this.softRows = Math.max(0, softRows);
		this.noneRows = Math.max(0, noneRows);
		this.solidValue = Math.max(0L, solidValue);
		this.countedValue = Math.max(0L, countedValue);
		this.softMoveGp = Math.max(0L, softMoveGp);
		this.totalMoveGp = Math.max(0L, totalMoveGp);
	}

	/**
	 * Gathers one computation's counted rows into a {@link GradeSummary} - what {@code PriceService} adds each counted
	 * stack's row to as it builds the bank value.
	 */
	static final class Tally
	{
		private final boolean graded;
		private int solid;
		private int soft;
		private int none;
		private long solidValue;
		private long countedValue;
		private long softMove;
		private long totalMove;

		/** @param graded whether this computation grades its rows at all */
		Tally(final boolean graded)
		{
			this.graded = graded;
		}

		/**
		 * One counted stack's row: its holding joins the counted value, its grade and stack move the shares. A row with
		 * no price at all is no row on the list and counts nothing.
		 */
		void add(final MovementRow row)
		{
			if (row == null || row.unitPrice() == null)
			{
				return;
			}
			countedValue = PortfolioMath.clampedAdd(countedValue, Math.max(0L, row.holdingValue()));
			final GradedMove move = row.graded();
			final long stackMove = row.hasMovement() ? abs(row.holdingDeltaGp()) : 0L;
			totalMove = PortfolioMath.clampedAdd(totalMove, stackMove);
			if (move == null)
			{
				return;
			}
			if (move.grade() == Grade.SOLID)
			{
				solid++;
				solidValue = PortfolioMath.clampedAdd(solidValue, Math.max(0L, row.holdingValue()));
			}
			else if (move.grade() == Grade.SOFT)
			{
				soft++;
				softMove = PortfolioMath.clampedAdd(softMove, stackMove);
			}
			else
			{
				none++;
			}
		}

		GradeSummary done()
		{
			return graded ? new GradeSummary(true, solid, soft, none, solidValue, countedValue, softMove, totalMove)
				: NONE;
		}

		private static long abs(final long gp)
		{
			return gp == Long.MIN_VALUE ? Long.MAX_VALUE : Math.abs(gp);
		}
	}

	/** Whether the computation graded its rows at all - live prices on, with a usable snapshot. */
	public boolean graded()
	{
		return graded;
	}

	/** Counted rows whose figure on the window on screen is SOLID. */
	public int solidRows()
	{
		return solidRows;
	}

	/** Counted rows whose figure is SOFT. */
	public int softRows()
	{
		return softRows;
	}

	/** Counted rows with no figure (NONE). */
	public int noneRows()
	{
		return noneRows;
	}

	/** Every graded counted row - the m of "n of m rows solid". */
	public int gradedRows()
	{
		return solidRows + softRows + noneRows;
	}

	/** What the SOLID rows' stacks are worth, gp. */
	public long solidValue()
	{
		return solidValue;
	}

	/** What every counted stack is worth, gp, cash left out - the bank value's stacks. */
	public long countedValue()
	{
		return countedValue;
	}

	/** The SOFT rows' stack moves, summed without their signs, gp. */
	public long softMoveGp()
	{
		return softMoveGp;
	}

	/** Every counted row's stack move, summed without its sign, gp. */
	public long totalMoveGp()
	{
		return totalMoveGp;
	}

	/**
	 * Whether the CARD is soft (L3): graded, and either the solid rows hold under
	 * {@value GradeMath#CARD_SOLID_VALUE_PCT} % of the counted value or the soft rows supply over
	 * {@value GradeMath#CARD_SOFT_MOVE_PCT} % of the gp move. Integer arithmetic.
	 */
	public boolean soft()
	{
		if (!graded)
		{
			return false;
		}
		final boolean solidShort = countedValue > 0L
			&& GradeMath.underShare(solidValue, countedValue, GradeMath.CARD_SOLID_VALUE_PCT);
		final boolean softHeavy = totalMoveGp > 0L
			&& GradeMath.overShare(softMoveGp, totalMoveGp, GradeMath.CARD_SOFT_MOVE_PCT);
		return solidShort || softHeavy;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof GradeSummary))
		{
			return false;
		}
		final GradeSummary other = (GradeSummary) o;
		return graded == other.graded && solidRows == other.solidRows && softRows == other.softRows
			&& noneRows == other.noneRows && solidValue == other.solidValue && countedValue == other.countedValue
			&& softMoveGp == other.softMoveGp && totalMoveGp == other.totalMoveGp;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(graded, solidRows, softRows, noneRows, solidValue, countedValue, softMoveGp, totalMoveGp);
	}

	@Override
	public String toString()
	{
		return graded ? "GradeSummary{solid=" + solidRows + ", soft=" + softRows + ", none=" + noneRows
			+ ", solidValue=" + solidValue + "/" + countedValue + ", softMove=" + softMoveGp + "/" + totalMoveGp
			+ (soft() ? ", SOFT" : "") + '}' : "GradeSummary{not graded}";
	}
}

package com.bankpricemovement;

import javax.annotation.Nullable;

/**
 * The words a graded figure can carry (contract 1.2.0, line L3), in ONE place: the sidebar prints one of them in the
 * free slot under a soft row's percentage (L5), and the dev bridge echoes it as {@code state.rows[].word}. A SOLID
 * figure carries none ({@link #SOLID}, the empty string): a row with no word is solid.
 *
 * <p>The user's final decision (2026-10-07): a figure is SOFT only when one of THREE facts holds, and it carries the word
 * of the FIRST of them, in this order (applied by {@link GradeMath#figure}):
 * <ol>
 * <li>{@link #lastTraded(long)} - nothing traded in the last 24 hours, so the figure is yesterday's move, and the word
 * says how long it has been since the item last traded ("last 1d ago"); {@link #YDAY} stands in only when no
 * last-trade time is known (the fallback; always first);</li>
 * <li>{@link #volume(long)} - the compared day's thinner side traded under ten units ("low vol 3");</li>
 * <li>{@link #spread(long)} - the current buy and sell prints, both from the last 24 hours, sit more than ten percent of
 * their middle apart, and the word says how far ("spread 55%").</li>
 * </ol>
 * A figure reported on one side only is no weaker for it: it is priced at that side and is solid unless one of the facts
 * above holds. A NONE row says {@link #NO_TRADES}, a label and not a warning. The words are the user's picks (2026-10-07,
 * and the two last wordings of 2026-10-08: "spread 55%" and "low vol 7"), and this class is where they change.
 */
public final class GradeWords
{
	/** A SOLID figure's word: none. */
	public static final String SOLID = "";

	/**
	 * The plain word for a spread with no number to say - the rare figure whose price fell outside the anchor's range, which
	 * has no current pair to measure. A spread with a number says {@link #spread(long)}.
	 */
	public static final String SPREAD = "spread";

	/**
	 * Nothing traded in the last 24 hours and no last-trade time is known: the figure is yesterday's move, always SOFT. With
	 * a time known the fallback says {@link #lastTraded(long)} instead.
	 */
	public static final String YDAY = "yday";

	/** A NONE row: no trade in the last 24 hours and no fallback pair - the dash. */
	public static final String NO_TRADES = "no trades";

	/** The longest age {@link #lastTraded} prints, in days: two digits, so "last 99d ago" is the widest it gets. */
	private static final long LAST_TRADED_MAX_DAYS = 99L;

	private static final long SECONDS_PER_HOUR = 60L * 60L;

	private static final long SECONDS_PER_DAY = 24L * SECONDS_PER_HOUR;

	private GradeWords()
	{
	}

	/**
	 * "last Nh ago" or "last Nd ago" - how long since the item last traded, for the fallback row whose figure is
	 * yesterday's move (the user, 2026-10-07: "last 5h ago" in place of "yday"). Whole hours below 24 h ("last 5h ago"),
	 * whole days from 24 h ("last 1d ago", "last 2d ago"), each rounded DOWN as an age is. Under one hour it still says
	 * "last 1h ago" - the word never says 0 - and a negative age (a clock a little behind the print) reads as 0. Days are
	 * capped at {@value #LAST_TRADED_MAX_DAYS} so the word stays inside the slot; a fallback row's last trade is a day or
	 * two old, so the cap is a safety net and never reached.
	 *
	 * <p>The word is wider than the slot under the percentage at 11 px from "last 10h ago" up (59 px against 54 in the face
	 * this plugin draws in, so "last 23h ago" is drawn at 9 px); "last 9h ago" and "last 2d ago" fit at 11.
	 *
	 * @param secondsAgo the age of the item's newest trade, in seconds
	 */
	public static String lastTraded(final long secondsAgo)
	{
		final long age = Math.max(0L, secondsAgo);
		if (age < SECONDS_PER_DAY)
		{
			return "last " + Math.max(1L, age / SECONDS_PER_HOUR) + "h ago";
		}
		return "last " + Math.min(LAST_TRADED_MAX_DAYS, age / SECONDS_PER_DAY) + "d ago";
	}

	/**
	 * "low vol N" - the thinner side's unit count on the compared day ("low vol 3"). Negative reads as 0. {@link GradeMath}
	 * says the word only for a count under ten units (a thin day), so the count is one digit and the word fits the slot under
	 * the percentage at 11 px (44 px against 54).
	 *
	 * @param count units the thinner side traded on the compared day
	 */
	public static String volume(final long count)
	{
		return "low vol " + Math.max(0L, count);
	}

	/**
	 * "spread N%" - the current buy and sell prints are this whole percentage of their middle apart ("spread 55%"). Negative
	 * reads as 0. Both prints are inside the anchor's range, so the percentage is at most 160 and the word is at most
	 * "spread 160%". Neither fits the slot under the percentage at 11 px; the row draws them at 9 px, where "spread 55%"
	 * measures 49 and "spread 100%" - the widest, any three-digit percentage being as wide - exactly the slot's 54.
	 *
	 * @param pct the pair's spread as a whole percentage of its middle ({@code GradedMove#spreadPercent})
	 */
	public static String spread(final long pct)
	{
		return SPREAD + " " + Math.max(0L, pct) + "%";
	}

	/** Whether a word is the spread word, with its number ("spread 55%") or without ({@link #SPREAD}). */
	public static boolean isSpread(@Nullable final String word)
	{
		return word != null && word.startsWith(SPREAD);
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * One item's graded live figure for ONE window (contract 1.2.0, lines L2-L4): the same-side move, how far it can be
 * trusted, and every number it was made from - so the sidebar can print the figure, the word and the open block's
 * sentences without doing any arithmetic of its own. Built only by {@link GradeMath}; immutable, so a row can carry it
 * from the service's executor to the EDT.
 *
 * <p><b>The figure.</b> Per side (buy = the instant-buy prints, sell = the instant-sell ones), "now" is the median of
 * the last 24 hours' plausible observations and "then" the window's day's side average; the side's move is {@code now / then - 1}
 * and {@link #move()} is the mean of the side moves present. {@link #thenMark()} is the window day's two-sided average
 * (or its one side), {@link #deltaGp()} is {@code round(thenMark x move)} per item, and {@link #price()} is
 * {@code thenMark + deltaGp} - the microquant mark, so the % and the gp can never disagree. When exactly ONE side was
 * observed the figure stands on that side alone: {@link #thenMark()} is that side's own average, {@link #price()} its
 * own median and {@link #deltaGp()} the difference, so the worth, the was and the change agree on the one side. A
 * {@link #fallback()} figure is yesterday's move instead: "now" is yesterday's side average and "then" the day before's
 * (for 1d) or the window's day's (for longer windows).
 *
 * <p><b>NONE</b> carries no figure: {@link #move()}, {@link #thenMark()}, {@link #deltaGp()} and {@link #price()} are
 * null, the word is {@link GradeWords#NO_TRADES}, and the row prints the dash.
 */
public final class GradedMove
{
	/**
	 * One side of the book as one figure saw it: its "now" (the median of its observations in the last 24 hours), the window day's
	 * "then", the side's own move, how many observations "now" was taken over, and the side's newest print with its
	 * time - "last sold 1,250 at 14:02". Immutable.
	 */
	public static final class Side
	{
		/** A side nothing is known of. */
		static final Side EMPTY = new Side(null, null, null, 0, null, 0L);

		@Nullable
		private final Long now;
		@Nullable
		private final Long then;
		@Nullable
		private final Double move;
		private final int observations;
		@Nullable
		private final Long last;
		private final long lastSeconds;

		Side(@Nullable final Long now, @Nullable final Long then, @Nullable final Double move, final int observations,
			@Nullable final Long last, final long lastSeconds)
		{
			this.now = now;
			this.then = then;
			this.move = move;
			this.observations = Math.max(0, observations);
			this.last = last;
			this.lastSeconds = last == null ? 0L : Math.max(0L, lastSeconds);
		}

		/**
		 * This side's "now": the median of its plausible observations in the last 24 hours - or, on a {@link GradedMove#fallback()}
		 * figure, yesterday's side average. Null when there is none.
		 */
		@Nullable
		public Long now()
		{
			return now;
		}

		/** This side's "then": the window day's side average (volume at least one, inside the anchor), or null. */
		@Nullable
		public Long then()
		{
			return then;
		}

		/** {@code now / then - 1}, or null when either end is missing. A ratio: 0.05 is +5 %. */
		@Nullable
		public Double move()
		{
			return move;
		}

		/** How many plausible observations of this side in the last 24 hours "now" was taken over; 0 on a fallback figure. */
		public int observations()
		{
			return observations;
		}

		/**
		 * The newest print of this side in the {@code /latest} snapshot - what someone last paid (buy) or got (sell) -
		 * whatever its age, or null when the feed had none. The open block's "last sold 1,250 at 14:02".
		 */
		@Nullable
		public Long last()
		{
			return last;
		}

		/** When {@link #last()} traded, unix seconds; 0 when there is no last print. */
		public long lastSeconds()
		{
			return lastSeconds;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Side))
			{
				return false;
			}
			final Side other = (Side) o;
			return observations == other.observations && lastSeconds == other.lastSeconds
				&& Objects.equals(now, other.now) && Objects.equals(then, other.then)
				&& Objects.equals(move, other.move) && Objects.equals(last, other.last);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(now, then, move, observations, last, lastSeconds);
		}

		@Override
		public String toString()
		{
			return "{now=" + now + ", then=" + then + ", move=" + move + ", obs=" + observations
				+ (last == null ? "" : ", last=" + last + "@" + lastSeconds) + '}';
		}
	}

	private final Grade grade;
	private final String word;
	@Nullable
	private final Double move;
	@Nullable
	private final Long thenMark;
	@Nullable
	private final Long deltaGp;
	private final boolean fallback;
	private final Side buy;
	private final Side sell;
	@Nullable
	private final LocalDate nowDay;
	@Nullable
	private final LocalDate thenDay;
	@Nullable
	private final Long anchor;
	@Nullable
	private final Long spreadPct;

	/**
	 * @param grade    the grade; null reads as {@link Grade#NONE}
	 * @param word     the word ({@link GradeWords}); null reads as "" for SOLID and {@link GradeWords#NO_TRADES} for NONE
	 * @param move     the figure as a ratio, or null for NONE
	 * @param thenMark the window day's mark, or null for NONE
	 * @param deltaGp  {@code round(thenMark x move)}, or null for NONE
	 * @param fallback whether this is yesterday's move (the word {@link GradeWords#lastTraded}, or {@link GradeWords#YDAY}
	 *                 when no last-trade time is known)
	 * @param buy      the buy side; null reads as nothing known
	 * @param sell     the sell side; null reads as nothing known
	 * @param nowDay   the UTC day "now" is of - today for a measured figure, yesterday for a fallback; null for NONE
	 * @param thenDay  the UTC day "then" is of; null for NONE
	 * @param anchor   the plausibility anchor the figure was judged against; null when there was none
	 */
	GradedMove(@Nullable final Grade grade, @Nullable final String word, @Nullable final Double move,
		@Nullable final Long thenMark, @Nullable final Long deltaGp, final boolean fallback, @Nullable final Side buy,
		@Nullable final Side sell, @Nullable final LocalDate nowDay, @Nullable final LocalDate thenDay,
		@Nullable final Long anchor)
	{
		this(grade, word, move, thenMark, deltaGp, fallback, buy, sell, nowDay, thenDay, anchor, null);
	}

	/**
	 * As the constructor above, with the current pair's wide spread.
	 *
	 * @param spreadPct the current buy and sell pair's spread as a whole percentage of its middle when it is a CURRENT and
	 *                  WIDE one (see {@link #spreadPercent()}); null otherwise, and for a figure with no figure at all
	 */
	GradedMove(@Nullable final Grade grade, @Nullable final String word, @Nullable final Double move,
		@Nullable final Long thenMark, @Nullable final Long deltaGp, final boolean fallback, @Nullable final Side buy,
		@Nullable final Side sell, @Nullable final LocalDate nowDay, @Nullable final LocalDate thenDay,
		@Nullable final Long anchor, @Nullable final Long spreadPct)
	{
		this.grade = grade == null ? Grade.NONE : grade;
		this.word = word != null ? word : this.grade == Grade.NONE ? GradeWords.NO_TRADES : GradeWords.SOLID;
		final boolean figure = this.grade != Grade.NONE && move != null && thenMark != null && deltaGp != null;
		this.move = figure ? move : null;
		this.thenMark = figure ? thenMark : null;
		this.deltaGp = figure ? deltaGp : null;
		this.fallback = figure && fallback;
		this.buy = buy == null ? Side.EMPTY : buy;
		this.sell = sell == null ? Side.EMPTY : sell;
		this.nowDay = figure ? nowDay : null;
		this.thenDay = figure ? thenDay : null;
		this.anchor = anchor;
		this.spreadPct = figure ? spreadPct : null;
	}

	/** Never null. */
	public Grade grade()
	{
		return grade;
	}

	/**
	 * The word the sidebar prints under a soft figure (L5): {@link GradeWords#SOLID} ("") for a solid one,
	 * {@link GradeWords#NO_TRADES} for NONE, otherwise the first failing fact's word. Never null.
	 */
	public String word()
	{
		return word;
	}

	/** Whether there is a figure at all - SOLID or SOFT. */
	public boolean hasFigure()
	{
		return grade != Grade.NONE;
	}

	/** The figure as a ratio ({@code 0.05} is +5 %), or null for NONE. The row prints it x 100, truncated. */
	@Nullable
	public Double move()
	{
		return move;
	}

	/**
	 * The window day's mark - its two sides' averages, halved, when both are present and plausible, else the one -
	 * which the figure moves from; null for NONE. The row's "then" (L2).
	 */
	@Nullable
	public Long thenMark()
	{
		return thenMark;
	}

	/** One item's gp move: {@code round(thenMark x move)}; null for NONE. */
	@Nullable
	public Long deltaGp()
	{
		return deltaGp;
	}

	/**
	 * The mark this figure puts one item at: {@code thenMark + deltaGp}, i.e. {@code thenMark x (1 + move)} rounded
	 * (L4); null for NONE. On the 1d window this is the row's price; on the others it is that window's own "now".
	 */
	@Nullable
	public Long price()
	{
		return thenMark == null || deltaGp == null ? null : PortfolioMath.clampedAdd(thenMark, deltaGp);
	}

	/** Whether this is yesterday's move (no trade in the last 24 hours) rather than the last 24 hours' own; always SOFT. */
	public boolean fallback()
	{
		return fallback;
	}

	/** The buy side - what buyers paid. Never null. */
	public Side buy()
	{
		return buy;
	}

	/** The sell side - what sellers got. Never null. */
	public Side sell()
	{
		return sell;
	}

	/**
	 * Whether both sides moved and agree to within {@value GradeMath#SOLID_MAX_SIDE_GAP_POINTS} points - the open
	 * block's "Both sides agree." False when either side has no move.
	 */
	public boolean sidesAgree()
	{
		return GradeMath.sidesAgree(buy.move(), sell.move());
	}

	/** The UTC day "now" is of: the live day for a measured figure, yesterday for a fallback; null for NONE. */
	@Nullable
	public LocalDate nowDay()
	{
		return nowDay;
	}

	/** The UTC day "then" is of - the window's traded day, or the day before yesterday for a 1d fallback; null for NONE. */
	@Nullable
	public LocalDate thenDay()
	{
		return thenDay;
	}

	/** The plausibility anchor A every price here was judged against (L2), or null when there was none to judge with. */
	@Nullable
	public Long anchor()
	{
		return anchor;
	}

	/**
	 * The number in {@link GradeWords#spread} ("spread 55%"): the current buy and sell pair's gap as a whole percentage of its middle,
	 * when the pair is a CURRENT and WIDE spread - both prints from the last 24 hours and inside the anchor's range, and more
	 * than ten percent of their middle apart. Null when it is not (a side that has been silent for a day makes the pair no
	 * spread, so a figure reported on one side only has none), for a fallback figure and for NONE. The open block prints it
	 * ("The buy and sell prices are 30% apart.").
	 */
	@Nullable
	public Long spreadPercent()
	{
		return spreadPct;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof GradedMove))
		{
			return false;
		}
		final GradedMove other = (GradedMove) o;
		return grade == other.grade && fallback == other.fallback && word.equals(other.word)
			&& Objects.equals(move, other.move) && Objects.equals(thenMark, other.thenMark)
			&& Objects.equals(deltaGp, other.deltaGp) && buy.equals(other.buy) && sell.equals(other.sell)
			&& Objects.equals(nowDay, other.nowDay) && Objects.equals(thenDay, other.thenDay)
			&& Objects.equals(anchor, other.anchor) && Objects.equals(spreadPct, other.spreadPct);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(grade, word, move, thenMark, deltaGp, fallback, buy, sell, nowDay, thenDay, anchor, spreadPct);
	}

	@Override
	public String toString()
	{
		return "GradedMove{" + grade.label() + (word.isEmpty() ? "" : " '" + word + "'")
			+ (move == null ? "" : ", move=" + move + ", thenMark=" + thenMark + ", deltaGp=" + deltaGp)
			+ (fallback ? ", yday" : "") + ", buy=" + buy + ", sell=" + sell
			+ (thenDay == null ? "" : ", " + nowDay + " vs " + thenDay) + ", anchor=" + anchor
			+ (spreadPct == null ? "" : ", spread=" + spreadPct + "%") + '}';
	}
}

package com.bankpricemovement;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.regex.Pattern;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The plugin's only network code (addendum L, contract lines L4, L6, L7, L8, L11): the HISTORY of the Grand
 * Exchange guide price, read off the OSRS wiki page {@value #PAGE}, plus the id-to-wiki-name table that lets a
 * bank item find its row in it. "Now" needs no request at all - it is RuneLite's own guide price from
 * {@code ItemManager} (L1).
 *
 * <p><b>Why the guide table and not the real-time trade API.</b> The first live look (2026-09-08 19:20) showed
 * "Green hat +1,413 gp (+12845.5 %)" while the GE web site said -38 gp (-3 %). Nothing was broken: the wiki's
 * hourly TRADE bucket 24 h earlier held nine units at an average high of 11 gp with no low side. The number every
 * player recognises - in-game GE, the GE web site, RuneLite's own tooltips - is the Jagex daily GUIDE price, and
 * the wiki republishes the whole guide table as {@value #PAGE} (bot "Gaz GEBot", one revision a day until 29 Sep 2026
 * and about eight a day since, 4,566 names, 126 KB). Its revisions reproduce Jagex's own daily history exactly: 70 of 70 archived values across 14 items
 * and five spans match {@code secure.runescape.com/m=itemdb_oldschool/api/graph/<id>.json} (L-A). Evidence:
 * {@code docs/research/bank-price-movement-calibration-2026-09-08.md} and addendum L.
 *
 * <p><b>Two calls a day, not two per window</b> (L4, L6, L10). Addendum K asked MediaWiki for "the newest
 * revision at or before instant X" and then fetched that revision's bytes - two requests per window, and, worse,
 * the wrong revision about half the time, because the bot publishes at a random hour (L-C). This client instead
 * fetches:
 * <ul>
 * <li>the revision INDEX ({@link #fetchRevisionIndex}): one call of {@code rvlimit=250} revisions, roughly 3.6 KB
 * gzipped, followed back with {@code rvcontinue} - the same query, at most {@value #MAX_INDEX_PAGES} calls, one at a
 * time - only as far as the caller asks (contract 1.1.2, T2). The baseline for any window is then chosen from that
 * list LOCALLY, by time ({@link RevisionRef#pickThen}), with no request at all;</li>
 * <li>the bodies it still needs ({@link #fetchTables}): several whole tables in ONE call through
 * {@code revids=a|b|c}. Measured by the lead: two revisions, 76.6 KB on the wire, 0.37 s. The
 * {@code index.php?action=raw} route of K2 is gone - it is served uncompressed, 126 KB per revision (L-G).</li>
 * </ul>
 * Per-item requests are never made, whatever the bank holds.
 *
 * <p><b>What leaves the client, exactly</b> (B035; the evidence the Hub manifest's {@code warning=} decision
 * rests on - the decision itself is the lead's, beside D15). Three URLs exist in this plugin and NONE of them
 * carries anything derived from the player: {@link #revisionIndexUrl()} is a fixed query for one fixed page
 * title (its later pages add only the wiki's own {@code rvcontinue} token), {@link #tablesUrl(Collection)} carries
 * only wiki revision ids the plugin picked out of that public index, and {@link #MAPPING_URL} is a bare GET of a public
 * table. No item id, no item name, no quantity, no
 * account and no search text is ever a parameter, so every user of this plugin issues BYTE-IDENTICAL requests
 * and the hosts learn only an IP - which the descriptive {@link #USER_AGENT} already discloses - and that this
 * plugin is installed. The bank itself never leaves the client: it is read on the client thread and persisted
 * under {@code ~/.runelite/plugin-data/bank-portfolio-tracker/} only. {@code theRequestUrlsCarryNothingDerivedFromThePlayer}
 * in the tests is what keeps that true as the routes change.
 *
 * <p><b>Why the client and the Gson are injected.</b> RuneLite's {@code @Provides OkHttpClient}
 * ({@code runelite-client/src/main/java/net/runelite/client/RuneLiteModule.java:180-205}, clone tag
 * runelite-parent-1.12.37) is the only client whose requests carry a usable User-Agent: the boot interceptor at
 * {@code RuneLite.java:415-437} stamps {@code RuneLite/<version>-<commit>} when a request has no UA and PREPENDS
 * it to any UA that does not already start with "RuneLite" ({@code RuneLite.java:425-429}), so the wiki sees
 * both the client and this plugin. It also gives us transparent gzip (OkHttp sets {@code Accept-Encoding} itself
 * and decompresses, which is what makes the batched call cheap - so this class never sets that header), the
 * shared disk cache, and the three refusals that arrive as plain {@code IOException}s in {@code onFailure}
 * (client thread, EDT, and the non-LIVE environment block). Constructing an OkHttpClient or a Gson here is a
 * Plugin Hub packaging blocker (C46) as well.
 *
 * <p><b>Why enqueue, never execute.</b> {@code RuneLiteModule.java:185-192} throws for a blocking call made on
 * the client thread or the EDT in EVERY environment, and this client is driven from the panel and from the
 * plugin's scheduled executor. {@code enqueue} hands the work to OkHttp's dispatcher and completes the returned
 * future on that thread, so no caller thread is ever parked. Shape copied from
 * {@code LootTrackerClient.java:84-106} and {@code ConfigClient.java:151-193}; the {@code try (response)} close
 * idiom from {@code WikiDpsManager.java:425-448}.
 *
 * <p><b>Why every failure is one exception type</b> (L11, failure shapes L-G). A MediaWiki error arrives as
 * {@code {"error": {...}}} with HTTP 200, so neither the status nor the body alone is the failure test. Non-2xx,
 * an {@code error} member, a body that is not the expected shape, a page that is {@code missing}, a batch in
 * which no revision survived validation, an empty table and a transport {@code IOException} all complete the
 * future exceptionally with a {@link WikiPriceException}; the future never completes with null. Callers keep
 * their last good baseline and carry on (design D9, fail soft). A window whose target simply predates the page
 * is NOT a failure and never reaches here: {@code pickThen} answers null and the panel says "No 180d history".
 *
 * <p>This class holds no cache and no history: staleness, scheduling and one-in-flight-per-window are
 * {@code PriceService}'s rules (L10). Its only state is {@link #setEnabled(boolean)}, the list of calls still on
 * the wire for {@link #cancelInFlight()}, and the "a failure has already been logged loudly" flag.
 */
public class GuidePriceClient
{
	private static final Logger log = LoggerFactory.getLogger(GuidePriceClient.class);

	/** The wiki's MediaWiki API endpoint - the revision index (L4) and the batched bodies (L6) both go here. */
	public static final String API_URL = "https://oldschool.runescape.wiki/api.php";

	/**
	 * The guide-price table page. Its content is a flat JSON object of item name to guide gp plus two
	 * {@code %...%} bookkeeping keys (measured 2026-09-08: 4,566 names, 125,696 bytes).
	 */
	public static final String PAGE = "Module:GEPrices/data.json";

	/**
	 * The id-to-name table (K3, restated by L8). It is the PRIMARY name source, not a fallback: {@code /mapping}
	 * has zero id-to-name collisions and the guide table's keys are a strict subset of its names, and
	 * {@code table[mapping name(id)]} equalled the GE price for 28 of 28 probed ids (L-F).
	 */
	public static final String MAPPING_URL = "https://prices.runescape.wiki/api/v1/osrs/mapping";

	/**
	 * The descriptive User-Agent both wiki hosts' policies ask for; unchanged since the first build so an
	 * operator reading the wiki's logs sees one plugin across every change of route. RuneLite prepends its own
	 * {@code RuneLite/<version>-<commit>} because this string does not start with "RuneLite"
	 * ({@code RuneLite.java:425-429}).
	 */
	public static final String USER_AGENT = "bank-portfolio-tracker (RuneLite plugin; github.com/2hBuilds)";

	/** Header name, spelled once so the request builder and the tests cannot drift apart. */
	public static final String USER_AGENT_HEADER = "User-Agent";

	/**
	 * How many revisions one index call asks for (L4). 250 is the anonymous {@code rvlimit} ceiling, so ONE call sees
	 * at most this many revisions however far back the page goes.
	 *
	 * <p>That was about 232 days at the one bot run a day L-C measured, and it is about 31 at the eight a day the bot
	 * has saved since 30 Sep 2026 - short of every window past 30d. So a caller that needs more asks for it
	 * ({@link #fetchRevisionIndex}'s reach) and the client follows the wiki's {@code rvcontinue} back, at most
	 * {@link #MAX_INDEX_PAGES} calls; {@code PriceService.finishIndex} MERGES each answer with the index it already
	 * holds, so a long-running install keeps reach it has already seen.
	 */
	public static final int INDEX_LIMIT = 250;

	/**
	 * How many calls one index fetch may make: {@value} (contract 1.1.2, T2). Eight pages of {@value #INDEX_LIMIT} are
	 * 2,000 revisions - about 250 days at eight a day, past the 181 a fresh install asks for.
	 */
	public static final int MAX_INDEX_PAGES = 8;

	/**
	 * The shape of the wiki's {@code rvcontinue} token, {@code <yyyymmddhhmmss>|<revid>} - all digits round one bar. A
	 * token of any other shape ends the paging rather than reaching a URL: nothing but digits and the bar is ever sent.
	 */
	private static final Pattern CONTINUE_TOKEN = Pattern.compile("[0-9]{1,20}\\|[0-9]{1,20}");

	/**
	 * How many revision ids one batched body call may carry (L6). 50 is MediaWiki's own {@code revids} ceiling
	 * for an anonymous client; the service never needs more than six (the newest table plus one per window).
	 */
	public static final int MAX_REVIDS = 50;

	/** The table's own time marker, and the authoritative one (L7, evidence L-E; contract 1.1.2). */
	public static final String LAST_UPDATE_KEY = "%LAST_UPDATE%";

	/** Keys in the guide table that are bookkeeping, not items: {@code %LAST_UPDATE%}, {@code %LAST_UPDATE_F%}. */
	private static final char BOOKKEEPING_PREFIX = '%';

	/**
	 * How far BEHIND its own save time a body's {@code %LAST_UPDATE%} may be before the body is refused (L7).
	 * Two days: a human maintenance edit republishes the previous day's table (L-E), which is one day behind and
	 * is still a real table, labelled with its own time; anything older than that is not this page's data.
	 */
	private static final long MAX_DATA_LAG_SECONDS = 48L * 60L * 60L;

	/**
	 * How far AHEAD of its own save time a body's {@code %LAST_UPDATE%} may be (L7). Five minutes of clock skew:
	 * a table cannot be stamped after the edit that published it, so anything further ahead is a body that does
	 * not belong to this revision.
	 */
	private static final long MAX_DATA_LEAD_SECONDS = 300L;

	/** Error and diagnostic text is cut to this many characters before it reaches a message or the log. */
	private static final int MAX_DETAIL_CHARS = 200;

	private final OkHttpClient client;
	private final Gson gson;

	/**
	 * Developer-mode switch behind the dev bridge's {@code wiki=on|off} verb (L13): when false every fetch fails
	 * immediately without touching the network, so the "no history" statuses can be exercised in a live client.
	 * Volatile because it is written from the bridge/EDT and read on whichever thread starts a fetch. Never
	 * flipped by user-facing code.
	 */
	private volatile boolean enabled = true;

	/**
	 * Every call enqueued and not yet answered, so {@link #cancelInFlight()} can drop them when the plugin stops
	 * (B012). Copy-on-write: at most a handful of entries, written from whichever thread starts a fetch and from
	 * OkHttp's dispatcher as each answers.
	 */
	private final List<Call> inFlight = new CopyOnWriteArrayList<>();

	/** Whether {@link #report} has already logged a failure loudly this session (B010). */
	private volatile boolean reported;

	public GuidePriceClient(final OkHttpClient client, final Gson gson)
	{
		if (client == null)
		{
			throw new IllegalArgumentException("client is required (inject RuneLite's OkHttpClient)");
		}
		if (gson == null)
		{
			throw new IllegalArgumentException("gson is required (inject RuneLite's Gson)");
		}
		this.client = client;
		this.gson = gson;
	}

	// ---------------------------------------------------------------- L4: the revision index

	/**
	 * The page's revision history back to {@code reachSeconds}, newest first, no content (L4; contract 1.1.2, T2).
	 *
	 * <p>The first call is today's query, the newest {@value #INDEX_LIMIT} revisions. While the oldest revision in hand
	 * is still newer than {@code reachSeconds} and the wiki says there is more ({@code continue.rvcontinue}), the next
	 * page is asked for - the same query plus that token, AFTER the previous one has answered, so the calls are spaced
	 * one at a time and never overlap - up to {@value #MAX_INDEX_PAGES} calls in all. A caller refreshing an index it
	 * holds passes its newest revision's time and gets one call, a second only to close a gap of more than
	 * {@value #INDEX_LIMIT} revisions; a fresh install passes 181 days back. A run of more than one call writes ONE
	 * info line - how many revisions over which span - and never one per call.
	 *
	 * <p>With an index in hand the baseline for any window is {@link RevisionRef#pickThen} on a time, decided locally
	 * and instantly, and a window change costs a request only when the chosen revision is one the store has not
	 * already got (L10).
	 *
	 * <p>A FIRST call that fails fails the whole fetch: the caller keeps the index it holds and tries again on its next
	 * tick. A LATER page that fails ends the run with the pages already in hand - a fresh install is better off with
	 * the days the first call reached than with no baseline at all until the next tick - and the answer is a
	 * {@link CutShortIndex}, so the caller can tell it from a whole history and page again. Revisions are immutable, so
	 * what was fetched is as true as a whole history; only its reach is short.
	 *
	 * @param nowMillis    the caller's clock; not used by the request itself, but taken so the SERVICE's settable
	 *                     clock - never {@code System.currentTimeMillis()} in here - decides when the index is stale
	 *                     and what stamp {@code revindex.json} is written with
	 * @param reachSeconds how far back the history must reach, unix seconds; paging stops once a revision at or before
	 *                     it is in hand
	 * @return a future completing with the history, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<List<RevisionRef>> fetchRevisionIndex(final long nowMillis, final long reachSeconds)
	{
		log.debug("bank-portfolio-tracker: fetching the guide-table revision index at {}, back to {}", nowMillis,
			reachSeconds);
		final CompletableFuture<List<RevisionRef>> done = new CompletableFuture<>();
		indexPage(null, 1, reachSeconds, new ArrayList<>(), done);
		return done;
	}

	/**
	 * One call of {@link #fetchRevisionIndex}'s run, and the decision on its answer: another page, or done. The
	 * completion runs on OkHttp's dispatcher thread; every path through it completes {@code done} or starts exactly
	 * one more call, and a {@link Throwable} out of it completes {@code done} first (B006's rule, {@link #request}).
	 */
	private void indexPage(final String token, final int call, final long reachSeconds, final List<RevisionRef> found,
		final CompletableFuture<List<RevisionRef>> done)
	{
		final CompletableFuture<IndexPage> page = request(token == null ? revisionIndexUrl() : revisionIndexUrl(token),
			this::parseRevisionPage);
		page.whenComplete((answer, error) ->
		{
			try
			{
				if (error != null)
				{
					if (call > 1 && !found.isEmpty())
					{
						found.sort(RevisionRef.NEWEST_FIRST);
						log.debug("bank-portfolio-tracker: the revision index run was cut short at call {} ({}): keeping the"
							+ " {} revisions of the earlier calls", call, messageOf(error), found.size());
						done.complete(new CutShortIndex(found));
						return;
					}
					done.completeExceptionally(error instanceof CompletionException && error.getCause() != null
						? error.getCause() : error);
					return;
				}
				found.addAll(answer.revisions);
				long oldest = Long.MAX_VALUE;
				for (final RevisionRef ref : found)
				{
					oldest = Math.min(oldest, ref.editSeconds());
				}
				if (oldest > reachSeconds && answer.next != null && call < MAX_INDEX_PAGES)
				{
					indexPage(answer.next, call + 1, reachSeconds, found, done);
					return;
				}
				found.sort(RevisionRef.NEWEST_FIRST);
				if (call > 1)
				{
					log.info("bank-portfolio-tracker: paged the guide-table revision index: {} revisions in {} calls,"
						+ " {} back to {}", found.size(), call, found.get(0).editDay(),
						found.get(found.size() - 1).editDay());
				}
				done.complete(found);
			}
			catch (final Throwable t)
			{
				done.completeExceptionally(new WikiPriceException("could not page the revision index: " + messageOf(t), t));
				if (t instanceof Error)
				{
					throw (Error) t;
				}
			}
		});
	}

	/**
	 * The answer of an index run whose paging was cut short by a failed later page ({@link #fetchRevisionIndex}): the
	 * revisions of the earlier calls, newest first. A list in every other respect; the type is the flag.
	 */
	static final class CutShortIndex extends ArrayList<RevisionRef>
	{
		private static final long serialVersionUID = 1L;

		CutShortIndex(final Collection<? extends RevisionRef> revisions)
		{
			super(revisions);
		}
	}

	// ---------------------------------------------------------------- L6: the batched bodies

	/**
	 * The full guide table of every named revision, in ONE request (L6).
	 *
	 * <p>MediaWiki serves several revisions of a page from a single {@code revids=} query and the response is
	 * gzipped in flight, which is the whole reason this replaced K2's per-revision {@code action=raw} reads: the
	 * lead measured two whole tables at 76.6 KB on the wire in 0.37 s, against 126 KB uncompressed EACH the old
	 * way (L-G). A steady day therefore costs one index call and one body call (L10).
	 *
	 * <p>A revision that comes back unusable - no content, a table with no prices, or a {@code %LAST_UPDATE%}
	 * outside the window its own save time allows (L7) - is left OUT of the map rather than failing the batch:
	 * the caller keeps the stored baseline for that window and every other window still gets its table. Only a
	 * batch in which NOTHING survived fails, because that is a route change, not one odd revision. A revision
	 * the wiki declined to include at all (a {@code badrevids} entry, or a {@code continue} the caller is not
	 * asked to follow) is simply absent for the same reason: the map is what arrived, and the caller reads it by
	 * revision id rather than by position.
	 *
	 * @param revIds    the revisions to read; nulls and non-positive ids are dropped and duplicates collapse
	 * @param nowMillis stamped onto every snapshot as {@code fetchedAtMillis}; passed in rather than read here so
	 *                  the service's settable clock governs every staleness decision (C27)
	 * @return a future completing with revision id to table, or exceptionally with {@link WikiPriceException} -
	 *         including when no id is usable, or when more than {@value #MAX_REVIDS} are asked for at once
	 */
	public CompletableFuture<Map<Long, GuideSnapshot>> fetchTables(final Collection<Long> revIds, final long nowMillis)
	{
		final List<Long> ids = usableIds(revIds);
		if (ids.isEmpty())
		{
			// Deliberately a failure and not an empty success: a caller that asked for nothing has a bug, and an
			// empty map would look like "every requested revision was fetched" to the code that stores baselines.
			return failed(new WikiPriceException("no usable revision ids to fetch"));
		}

		if (ids.size() > MAX_REVIDS)
		{
			return failed(new WikiPriceException(
				"a batched revision fetch may carry at most " + MAX_REVIDS + " ids, was asked for " + ids.size()));
		}

		log.debug("bank-portfolio-tracker: fetching {} guide table(s) in one call: {}", ids.size(), ids);
		return request(tablesUrl(ids), body -> parseTables(body, nowMillis));
	}

	/**
	 * The wiki's id-to-name table (L8), fetched at most weekly by the caller and persisted as {@code mapping.json}.
	 *
	 * @param nowMillis unused by the request itself; present so the caller's clock, not this class, decides what
	 *                  "weekly" means and so the signature matches the other two fetches
	 * @return a future completing with item id to wiki name, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<Map<Integer, String>> fetchMapping(final long nowMillis)
	{
		log.debug("bank-portfolio-tracker: fetching the id/name mapping at {}", nowMillis);
		return request(MAPPING_URL, this::parseMapping);
	}

	/**
	 * Developer-mode kill switch for the {@code wiki=on|off} bridge verb (L13); true is the shipped state.
	 * User-facing behaviour must never depend on this (workspace rule: no user feature may need a dev hook).
	 */
	public void setEnabled(final boolean enabled)
	{
		this.enabled = enabled;
	}

	/** @see #setEnabled(boolean) */
	public boolean isEnabled()
	{
		return enabled;
	}

	// ---------------------------------------------------------------- the exact URLs (L4, L6)

	/**
	 * The revision index query of L4, verbatim:
	 * {@code api.php?action=query&prop=revisions&titles=Module:GEPrices/data.json&rvlimit=250&rvdir=older&rvprop=ids|timestamp|user|comment&format=json&formatversion=2}.
	 *
	 * <p>{@code user} and {@code comment} are asked for because they are what separates the bot's daily run from
	 * a human's maintenance edit ({@link RevisionRef#isBot()}, L-E), and {@code rvdir=older} is what makes the
	 * answer start at the newest revision.
	 *
	 * <p>Assembled as a literal string rather than through {@code HttpUrl.Builder} because OkHttp's query
	 * canonicaliser leaves {@code :}, {@code /} and {@code |} alone (they are legal query characters, RFC 3986
	 * {@code pchar / "/" / "?"}) while {@code addQueryParameter} would still be a second spelling of the same
	 * thing; one literal is the shape a maintainer can paste into curl to reproduce a bug.
	 */
	static String revisionIndexUrl()
	{
		return API_URL
			+ "?action=query"
			+ "&prop=revisions"
			+ "&titles=" + PAGE
			+ "&rvlimit=" + INDEX_LIMIT
			+ "&rvdir=older"
			+ "&rvprop=ids|timestamp|user|comment"
			+ "&format=json"
			+ "&formatversion=2";
	}

	/**
	 * The next page of the same query (contract 1.1.2, T2): {@link #revisionIndexUrl()} plus the wiki's own
	 * {@code &rvcontinue=<token>}, which carries nothing but the timestamp and revision id the previous page stopped at
	 * ({@link #parseRevisionPage} refuses any other shape).
	 */
	static String revisionIndexUrl(final String continueToken)
	{
		return revisionIndexUrl() + "&rvcontinue=" + continueToken;
	}

	/**
	 * The batched content query of L6:
	 * {@code api.php?action=query&prop=revisions&revids=<a>|<b>&rvprop=ids|timestamp|content&rvslots=main&format=json&formatversion=2}.
	 *
	 * <p>{@code rvslots=main} is not optional: since MediaWiki 1.32 a revision's text lives in a slot, and asking
	 * for {@code content} without naming a slot answers a deprecation warning instead of the bytes.
	 * {@code timestamp} rides along because {@link #parseTables} needs each revision's own save time to bound the
	 * {@code %LAST_UPDATE%} check (L7).
	 */
	static String tablesUrl(final Collection<Long> revIds)
	{
		final StringBuilder ids = new StringBuilder();
		for (final Long revId : revIds)
		{
			if (ids.length() > 0)
			{
				ids.append('|');
			}
			ids.append(revId);
		}

		return API_URL
			+ "?action=query"
			+ "&prop=revisions"
			+ "&revids=" + ids
			+ "&rvprop=ids|timestamp|content"
			+ "&rvslots=main"
			+ "&format=json"
			+ "&formatversion=2";
	}

	// ---------------------------------------------------------------- parsers (package-private, pure, L4/L6)

	/**
	 * One page of the revision index (L4): its revisions as a newest-first list, and the wiki's token for the page after
	 * it. Shape under {@code formatversion=2}:
	 * {@code {"continue":{"rvcontinue":"20261002155512|15360320","continue":"||"},"query":{"pages":[{"pageid":180412,
	 * "title":"Module:GEPrices/data.json","revisions":[{"revid":15334656,"parentid":15333448,
	 * "timestamp":"2026-09-08T09:25:12Z","user":"Gaz GEBot","comment":"GE update"}, ...]}]}}}.
	 *
	 * <p>{@code pages} is an ARRAY under {@code formatversion=2} and an object keyed by page id in the default
	 * output format; both are read, because the wiki could switch its default and a silently empty index is
	 * worse than a loud failure. One revision that cannot be used - no id, or a timestamp that will not parse,
	 * without which it has no time - is skipped; a page with nothing usable in it is fatal.
	 *
	 * <p>The revisions are SORTED newest-first rather than trusted to arrive that way, so a change of default
	 * ordering at the wiki could only make the dev bridge's echo untidy. {@link RevisionRef#pickThen} does not
	 * depend on the order either way. The token is {@code null} when the wiki sends none - the history ends here - or
	 * one that is not the {@code <digits>|<digits>} shape it has always had, which ends the paging rather than putting
	 * an unknown string into a URL.
	 *
	 * @throws WikiPriceException on a non-object body, an {@code error} member, a missing page or no usable
	 *                            revision at all
	 */
	IndexPage parseRevisionPage(final String json) throws WikiPriceException
	{
		final JsonObject root = readObject(json);
		failOnErrorMember(root);

		final List<RevisionRef> index = new ArrayList<>();
		for (final JsonObject revision : revisionsOf(root))
		{
			final Long revId = optLong(revision, "revid");
			if (revId == null || revId <= 0L)
			{
				continue;
			}

			final Long editSeconds = optInstantSeconds(revision);
			if (editSeconds == null)
			{
				continue;
			}

			index.add(new RevisionRef(revId, editSeconds, memberText(revision, "user"),
				memberText(revision, "comment")));
		}

		if (index.isEmpty())
		{
			throw new WikiPriceException("the wiki listed no usable revisions of " + PAGE);
		}

		index.sort(RevisionRef.NEWEST_FIRST);
		String next = null;
		final JsonElement more = root.get("continue");
		if (more != null && more.isJsonObject())
		{
			final String token = memberText(more.getAsJsonObject(), "rvcontinue");
			if (token != null && CONTINUE_TOKEN.matcher(token).matches())
			{
				next = token;
			}
			else if (token != null)
			{
				log.debug("bank-portfolio-tracker: the revision index's continuation token has an unknown shape - paging"
					+ " stops here");
			}
		}
		return new IndexPage(index, next);
	}

	/** One page of the revision index: what {@link #parseRevisionPage} read. Immutable. */
	static final class IndexPage
	{
		/** The page's revisions, newest first; never empty. */
		final List<RevisionRef> revisions;
		/** The wiki's {@code rvcontinue} token for the next page, or null when there is none to follow. */
		final String next;

		IndexPage(final List<RevisionRef> revisions, final String next)
		{
			this.revisions = Collections.unmodifiableList(revisions);
			this.next = next;
		}
	}

	/**
	 * Every revision body in a batched answer, keyed by revision id (L6). Shape is
	 * {@link #parseRevisionPage}'s, with the text under
	 * {@code query.pages[0].revisions[i].slots.main.content} and several revisions of the one page in the array.
	 *
	 * <p>Each body is validated before it is kept (L7): its {@code %LAST_UPDATE%} must sit between 48 hours
	 * before and 5 minutes after the revision's own save time. That window is what a human maintenance edit
	 * looks like - it republishes the previous day's table under a later timestamp (L-E) - while a body with no
	 * marker at all, or one from another page entirely, falls outside it. A revision that fails is skipped with
	 * a log line, never guessed at: the marker is the TIME the service picks every window's table by once the body
	 * is read ({@code GuideSnapshot.dataSeconds()}, contract 1.1.2) and the time each row is labelled with, and a
	 * marker invented here would put a table behind a window it is too new for.
	 *
	 * @param nowMillis stamped onto every snapshot as {@code fetchedAtMillis}
	 * @throws WikiPriceException on a non-object body, an {@code error} member, or a batch in which no revision
	 *                            survived (a route change, as opposed to one odd revision)
	 */
	Map<Long, GuideSnapshot> parseTables(final String json, final long nowMillis) throws WikiPriceException
	{
		final JsonObject root = readObject(json);
		failOnErrorMember(root);

		final Map<Long, GuideSnapshot> tables = new LinkedHashMap<>();
		for (final JsonObject revision : revisionsOf(root))
		{
			final Long revId = optLong(revision, "revid");
			final Long editSeconds = optInstantSeconds(revision);
			if (revId == null || revId <= 0L || editSeconds == null)
			{
				continue;
			}

			final String content = contentOf(revision);
			if (content == null || content.trim().isEmpty())
			{
				log.debug("bank-portfolio-tracker: revision {} came back without content", revId);
				continue;
			}

			final JsonObject body;
			final Map<String, Long> prices;
			try
			{
				body = readObject(content);
				prices = tableOf(body);
			}
			catch (final WikiPriceException e)
			{
				log.debug("bank-portfolio-tracker: revision {} carried no usable table: {}", revId, e.getMessage());
				continue;
			}

			final long dataSeconds = dataSecondsOf(body);
			if (dataSeconds < editSeconds - MAX_DATA_LAG_SECONDS || dataSeconds > editSeconds + MAX_DATA_LEAD_SECONDS)
			{
				// No day marker, or one that cannot belong to this revision. Guessing a day here would produce a
				// row labelled with a date its numbers are not from - the exact defect addendum L exists to fix.
				log.debug("bank-portfolio-tracker: revision {} has a {} of {} against an edit time of {} - skipped",
					revId, LAST_UPDATE_KEY, dataSeconds, editSeconds);
				continue;
			}

			tables.put(revId, new GuideSnapshot(revId, editSeconds, dataSeconds, nowMillis, prices));
		}

		if (tables.isEmpty())
		{
			throw new WikiPriceException("the wiki returned no usable guide tables");
		}
		return tables;
	}

	/**
	 * One revision of {@value #PAGE} as folded item name to guide gp. Content shape (calibration doc):
	 * {@code {"Green hat":1086, "Abyssal whip":799012, ..., "%LAST_UPDATE%":1788859349,
	 * "%LAST_UPDATE_F%":"08 September 2026 09:22:29 (UTC)"}}.
	 *
	 * <p>Keys beginning with {@code %} are the page's own bookkeeping and are skipped; a value that is not a
	 * number is skipped rather than fatal, so one odd entry cannot cost the other four and a half thousand. Every
	 * surviving key is folded through {@code GuideSnapshot.key} (L8) - the wiki case-renamed 81 keys in August
	 * 2026, so a byte-exact table loses three of the user's bank items on any window of 30 days or more.
	 *
	 * <p>The table's "unpriced" sentinel (2,147,483,646) is left in the map here and dropped by
	 * {@link GuideSnapshot}: the model applies that rule once, for every construction path, including a baseline
	 * read back off disk.
	 *
	 * <p>An empty result IS fatal: a JSON-shaped body with no prices in it means the page moved or the revision
	 * was deleted, and publishing an empty baseline would quietly show "-" on every row as though the plugin
	 * were working.
	 *
	 * @throws WikiPriceException on a non-object body or a table with no prices in it
	 */
	Map<String, Long> parseGuideTable(final String json) throws WikiPriceException
	{
		return tableOf(readObject(json));
	}

	/**
	 * The {@code /mapping} array as item id to wiki name. Shape:
	 * {@code [{"id":4151,"name":"Abyssal whip","examine":"...","members":true,...}, ...]}, about 4,660 entries.
	 *
	 * <p>Only {@code id} and {@code name} are read; every other member is ignored so a new field cannot break a
	 * release. An entry that is not an object, or that lacks either member, is skipped. Names are kept in the
	 * wiki's own spelling - the fold to a table key happens at lookup time ({@code GuideSnapshot.get}) so the
	 * mapping stays readable on disk and in the dev bridge's echo.
	 *
	 * <p>An empty result is fatal for the same reason as {@link #parseGuideTable(String)}: without names, nothing
	 * can be priced.
	 *
	 * @throws WikiPriceException on a body that is not a JSON array, or an array with no usable entries
	 */
	Map<Integer, String> parseMapping(final String json) throws WikiPriceException
	{
		final JsonElement root = readElement(json);
		if (!root.isJsonArray())
		{
			throw new WikiPriceException("the wiki mapping response was not a JSON array");
		}

		final JsonArray array = root.getAsJsonArray();
		final Map<Integer, String> names = new LinkedHashMap<>();
		for (final JsonElement element : array)
		{
			if (element == null || !element.isJsonObject())
			{
				continue;
			}

			final JsonObject entry = element.getAsJsonObject();
			final Long id = optLong(entry, "id");
			final String name = memberText(entry, "name");
			if (id == null || name == null || name.isEmpty() || id <= 0L || id > Integer.MAX_VALUE)
			{
				continue;
			}
			names.put(id.intValue(), name);
		}

		if (names.isEmpty())
		{
			throw new WikiPriceException("the wiki mapping table carried no entries");
		}
		return names;
	}

	// ---------------------------------------------------------------- internals

	/**
	 * Builds the request, enqueues it and adapts OkHttp's callback pair onto one future. Nothing in here blocks:
	 * the method returns as soon as the call is queued. The response is CLOSED before the future completes, so a
	 * dependent that starts another request never runs while a body is still open.
	 *
	 * <p><b>The future is completed on every path, including an {@link Error}</b> (B006). OkHttp 3.14.9 sets
	 * {@code signalledCallback} before it invokes {@code onResponse}, so a Throwable thrown from inside the
	 * callback is rethrown on the dispatcher thread and never routed to {@code onFailure}: the future would then
	 * never complete, and {@code PriceService}'s in-flight flag would stay claimed for the rest of the session -
	 * the whole history subsystem stopping with nothing on screen and nothing in the log. A parse of six 4,566-entry
	 * tables is exactly the shape that can raise {@code OutOfMemoryError} on a small heap, or
	 * {@code StackOverflowError} on a hostile body, so the catch is on {@code Throwable}, the future is completed
	 * FIRST, and an {@code Error} is rethrown afterwards for the JVM's own handling. {@link #fail} and
	 * {@link #failAndRethrow} are that order, spelled once: every failure path here goes through them.
	 *
	 * <p>The call is remembered for {@link #cancelInFlight()} until it answers.
	 */
	private <T> CompletableFuture<T> request(final String url, final BodyParser<T> parser)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();

		if (!enabled)
		{
			future.completeExceptionally(new WikiPriceException("wiki fetches are switched off (developer mode)"));
			return future;
		}

		final Request request;
		try
		{
			request = new Request.Builder()
				.url(url)
				.header(USER_AGENT_HEADER, USER_AGENT)
				.get()
				.build();
		}
		catch (final RuntimeException e)
		{
			// IllegalArgumentException from HttpUrl for a url this class built itself: a programming error, but
			// it must not escape onto the caller's thread (the service's executor) as an unchecked throw.
			future.completeExceptionally(new WikiPriceException("could not build the wiki request for " + url, e));
			return future;
		}

		try
		{
			final Call call = client.newCall(request);
			inFlight.add(call);
			future.whenComplete((value, error) -> inFlight.remove(call));
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(final Call call, final IOException e)
				{
					// Everything the injected client refuses lands here: no network, DNS, TLS, and the three
					// RuneLiteModule interceptor throws (client thread, EDT, non-LIVE environment domain block).
					fail(future, url, new WikiPriceException("wiki request failed: " + messageOf(e), e));
				}

				@Override
				public void onResponse(final Call call, final Response response)
				{
					final T value;
					try (Response closing = response)
					{
						final String body = bodyText(closing);
						if (!closing.isSuccessful())
						{
							fail(future, url, httpFailure(closing.code(), body));
							return;
						}
						value = parser.parse(body);
					}
					catch (final IOException e)
					{
						fail(future, url, e instanceof WikiPriceException
							? (WikiPriceException) e
							: new WikiPriceException("could not read the wiki response: " + messageOf(e), e));
						return;
					}
					catch (final Throwable t)
					{
						failAndRethrow(future, url, new WikiPriceException(
							"could not parse the wiki response: " + messageOf(t), t), t);
						return;
					}
					future.complete(value);
				}
			});
		}
		catch (final Throwable t)
		{
			// Throwable for the same reason: this runs on the service's executor, whose own guard used to stop at
			// RuntimeException, and an unanswered future is a flag claimed for the session.
			failAndRethrow(future, url, new WikiPriceException("could not queue the wiki request: " + messageOf(t), t), t);
		}

		return future;
	}

	/**
	 * The one way a request fails: {@link #report} the failure, THEN complete the future with it. Every failure
	 * site in {@link #request} goes through here, so the once-per-session warning has a single gate and no path
	 * can leave the future unanswered - which is the whole of B006, since an unanswered future leaves
	 * {@code PriceService}'s in-flight flag claimed for the rest of the session.
	 */
	private <T> void fail(final CompletableFuture<T> future, final String url, final WikiPriceException failure)
	{
		report(url, failure);
		future.completeExceptionally(failure);
	}

	/**
	 * {@link #fail} for a {@code catch} on {@link Throwable}: the future is completed FIRST and an {@link Error}
	 * is rethrown afterwards, for the JVM's own handling. The order is the point (class note above) - OkHttp
	 * 3.14.9 rethrows on its dispatcher thread rather than routing to {@code onFailure}, so a rethrow before the
	 * completion would strand the caller.
	 *
	 * @param cause what was caught; rethrown only when it is an {@link Error}
	 */
	private <T> void failAndRethrow(final CompletableFuture<T> future, final String url,
		final WikiPriceException failure, final Throwable cause)
	{
		fail(future, url, failure);
		if (cause instanceof Error)
		{
			throw (Error) cause;
		}
	}

	/**
	 * Cancels every call still on the wire. Called from {@code PriceService.stop()} when the plugin is switched
	 * off or its config profile changes: a batched body download is most of a megabyte, and neither finishing it
	 * nor parsing six tables afterwards can produce anything but a discarded result. {@code Call.cancel()} is safe
	 * from any thread; a cancelled call's {@code onFailure} completes its future as an ordinary failure, which the
	 * stopped service drops.
	 */
	public void cancelInFlight()
	{
		for (final Call call : new ArrayList<>(inFlight))
		{
			inFlight.remove(call);
			try
			{
				call.cancel();
			}
			catch (final RuntimeException e)
			{
				log.debug("bank-portfolio-tracker: a wiki call refused to cancel", e);
			}
		}
	}

	/**
	 * Logs one failure. The FIRST of the session is a warning carrying the url and, where the wiki answered with
	 * a status, that status; every one after it is debug (B010).
	 *
	 * <p>Why the first one is loud: RuneLite logs at INFO, so before this every network failure in the plugin -
	 * an outage, a proxy serving HTML, the 403 the prices API returns to a default User-Agent - left NOTHING in
	 * the user's client.log, while every DISK failure in the same plugin was a warning. A bug report then could
	 * not tell a 403 from a DNS failure without asking the user to reproduce with debug logging on. Why only the
	 * first: an outage lasts hours and the tick is thirty minutes, and a repeated line is noise in someone else's
	 * log.
	 */
	private void report(final String url, final WikiPriceException failure)
	{
		final String status = failure.hasHttpCode() ? " (HTTP " + failure.getHttpCode() + ")" : "";
		if (reported)
		{
			log.debug("bank-portfolio-tracker: wiki request to {} failed{}", url, status, failure);
			return;
		}
		reported = true;
		log.warn("bank-portfolio-tracker: wiki request to {} failed{} - movement will show stored data until it recovers",
			url, status, failure);
	}

	/** A future that has already failed - the shape {@link #fetchTables} refuses a bad argument with. */
	private static <T> CompletableFuture<T> failed(final WikiPriceException failure)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();
		future.completeExceptionally(failure);
		return future;
	}

	/**
	 * The revision ids worth asking for: non-null, positive, in the caller's order and each named once. A
	 * duplicate would be answered once by MediaWiki anyway; collapsing it here keeps the {@code revids=} count
	 * honest against {@value #MAX_REVIDS}.
	 */
	private static List<Long> usableIds(final Collection<Long> revIds)
	{
		final Set<Long> unique = new LinkedHashSet<>();
		if (revIds != null)
		{
			for (final Long revId : revIds)
			{
				if (revId != null && revId > 0L)
				{
					unique.add(revId);
				}
			}
		}
		return new ArrayList<>(unique);
	}

	/**
	 * Every revision object in a {@code query} answer, across every page it lists. Reads both the
	 * {@code formatversion=2} array of pages and the default object keyed by page id; a page that is
	 * {@code missing} simply has no revisions and contributes nothing.
	 *
	 * @throws WikiPriceException when there is no {@code query} object at all (a shape this parser cannot read)
	 */
	private static List<JsonObject> revisionsOf(final JsonObject root) throws WikiPriceException
	{
		final JsonElement query = root.get("query");
		if (query == null || !query.isJsonObject())
		{
			throw new WikiPriceException("the wiki revision response has no query object");
		}

		final List<JsonObject> revisions = new ArrayList<>();
		final JsonElement pages = query.getAsJsonObject().get("pages");
		if (pages == null)
		{
			return revisions;
		}

		if (pages.isJsonObject())
		{
			for (final Map.Entry<String, JsonElement> page : pages.getAsJsonObject().entrySet())
			{
				collectRevisions(page.getValue(), revisions);
			}
		}
		else if (pages.isJsonArray())
		{
			for (final JsonElement page : pages.getAsJsonArray())
			{
				collectRevisions(page, revisions);
			}
		}
		return revisions;
	}

	/** Appends one page's {@code revisions} array; a missing page or a malformed entry adds nothing. */
	private static void collectRevisions(final JsonElement page, final List<JsonObject> into)
	{
		if (page == null || !page.isJsonObject())
		{
			return;
		}

		final JsonElement revisions = page.getAsJsonObject().get("revisions");
		if (revisions == null || !revisions.isJsonArray())
		{
			return;
		}

		for (final JsonElement revision : revisions.getAsJsonArray())
		{
			if (revision != null && revision.isJsonObject())
			{
				into.add(revision.getAsJsonObject());
			}
		}
	}

	/**
	 * One revision's wikitext. {@code slots.main.content} is the {@code rvslots=main} shape this client asks for;
	 * the bare {@code content} and the pre-1.32 {@code *} members are read as well so a change of API default
	 * cannot silently empty every table.
	 */
	private static String contentOf(final JsonObject revision)
	{
		final JsonElement slots = revision.get("slots");
		if (slots != null && slots.isJsonObject())
		{
			final JsonElement main = slots.getAsJsonObject().get("main");
			if (main != null && main.isJsonObject())
			{
				final String text = rawText(main.getAsJsonObject().get("content"));
				if (text != null)
				{
					return text;
				}
			}
		}

		final String direct = rawText(revision.get("content"));
		return direct != null ? direct : rawText(revision.get("*"));
	}

	/** A JSON string member as its whole text - unlike {@link #memberText} this is never truncated. */
	private static String rawText(final JsonElement value)
	{
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return value.getAsString();
		}
		catch (final RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * The prices out of one parsed table body, folded through {@code GuideSnapshot.key} and without the
	 * {@code %...%} bookkeeping.
	 *
	 * @throws WikiPriceException when nothing in the object is a price
	 */
	private static Map<String, Long> tableOf(final JsonObject root) throws WikiPriceException
	{
		final Map<String, Long> prices = new HashMap<>();
		for (final Map.Entry<String, JsonElement> entry : root.entrySet())
		{
			final String name = entry.getKey();
			if (name == null || name.isEmpty() || name.charAt(0) == BOOKKEEPING_PREFIX)
			{
				continue;
			}

			final Long price = asLong(entry.getValue());
			if (price == null)
			{
				continue;
			}

			final String folded = GuideSnapshot.key(name);
			if (folded != null && !folded.isEmpty())
			{
				prices.put(folded, price);
			}
		}

		if (prices.isEmpty())
		{
			throw new WikiPriceException("the wiki guide table carried no prices");
		}
		return prices;
	}

	/**
	 * The body's {@code %LAST_UPDATE%} in unix seconds, or 0 when it is absent or not a number - which
	 * {@link #parseTables} treats as "outside the allowed window" and refuses (L7). Never guessed from the
	 * revision timestamp: the whole point of the marker is that the two disagree on 4 of 38 sampled bodies.
	 */
	private static long dataSecondsOf(final JsonObject root)
	{
		final Long seconds = optLong(root, LAST_UPDATE_KEY);
		return seconds == null ? 0L : seconds;
	}

	/**
	 * A revision's {@code timestamp} as unix seconds, or null when it is absent or not ISO-8601. Null costs the
	 * revision its place in the index or the batch: without a save time there is no time to select on and no
	 * window to validate a body's time marker against.
	 */
	private static Long optInstantSeconds(final JsonObject revision)
	{
		final String timestamp = memberText(revision, "timestamp");
		if (timestamp == null)
		{
			return null;
		}

		try
		{
			return Instant.parse(timestamp).getEpochSecond();
		}
		catch (final DateTimeParseException e)
		{
			log.debug("bank-portfolio-tracker: revision timestamp is not ISO-8601: {}", timestamp);
			return null;
		}
	}

	/**
	 * MediaWiki reports an error as {@code {"error":{"code":"...","info":"..."}}} with HTTP 200, so the body -
	 * not the status - is the failure test. Checked before anything else is read out of the envelope.
	 */
	private void failOnErrorMember(final JsonObject root) throws WikiPriceException
	{
		final String error = memberText(root, "error");
		if (error != null)
		{
			throw new WikiPriceException("wiki error: " + error);
		}
	}

	/** Reads the whole body as text, tolerating a null body (a HEAD-shaped or synthetic response). */
	private static String bodyText(final Response response) throws IOException
	{
		final ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	/**
	 * A body as a {@link JsonObject}, or a failure. Parsed as {@link JsonElement} first so a non-object body (an
	 * array, or a bare string from Gson's lenient reader) becomes a clean failure rather than a
	 * ClassCastException out of {@code fromJson(json, JsonObject.class)}.
	 */
	private JsonObject readObject(final String json) throws WikiPriceException
	{
		final JsonElement root = readElement(json);
		if (!root.isJsonObject())
		{
			throw new WikiPriceException("wiki response was not a JSON object");
		}
		return root.getAsJsonObject();
	}

	/**
	 * A body as any JSON value, with the INJECTED Gson - constructing a Gson or a GsonBuilder in plugin code is
	 * a Plugin Hub blocker (C46), and Gson 2.8.5 (the version the pinned client ships) has no static
	 * {@code JsonParser.parseString} to reach for instead.
	 */
	private JsonElement readElement(final String json) throws WikiPriceException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new WikiPriceException("empty response from the wiki");
		}

		final JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (final RuntimeException e)
		{
			throw new WikiPriceException("malformed JSON from the wiki: " + messageOf(e), e);
		}

		if (root == null || root.isJsonNull())
		{
			// A literal "null" body: JSON-shaped, but there is nothing in it for any caller to read.
			throw new WikiPriceException("wiki response was a JSON null");
		}
		return root;
	}

	/**
	 * A nullable numeric member as a {@code Long}. Guide prices, revision ids and unix seconds all exceed what an
	 * {@code int} comfortably holds (a revid is already past 15 million and a price past two billion), so every
	 * number is read as a long. A member that is absent, JSON null, or not a number reads as null.
	 */
	private static Long optLong(final JsonObject object, final String key)
	{
		return object == null ? null : asLong(object.get(key));
	}

	/** One JSON value as a {@code Long}, or null when it is absent, null, or not a number. Never throws. */
	private static Long asLong(final JsonElement value)
	{
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return Long.valueOf(value.getAsLong());
		}
		catch (final RuntimeException e)
		{
			// A boolean primitive, or a string that is not a number: skip the entry, never fail the refresh.
			return null;
		}
	}

	/** A member rendered as short text, or null when it is absent or JSON null. Never throws. */
	private static String memberText(final JsonObject root, final String key)
	{
		final JsonElement value = root.get(key);
		if (value == null || value.isJsonNull())
		{
			return null;
		}
		if (value.isJsonPrimitive())
		{
			try
			{
				return truncate(value.getAsString());
			}
			catch (final RuntimeException e)
			{
				// fall through to the structural rendering
			}
		}
		return truncate(value.toString());
	}

	/**
	 * A non-2xx answer. The status is carried on the exception because 403 is diagnosable on its own (both wiki
	 * hosts pre-emptively block default user agents, research C3) while the body for it is unhelpful.
	 */
	private WikiPriceException httpFailure(final int code, final String body)
	{
		String detail = null;
		try
		{
			detail = memberText(readObject(body), "error");
		}
		catch (final WikiPriceException e)
		{
			// A non-JSON error body (an HTML error page, cloudflare's one-byte 403) is normal here - the status
			// is the information.
		}

		final String message = detail == null
			? "wiki request failed with HTTP " + code
			: "wiki request failed with HTTP " + code + ": " + detail;
		return new WikiPriceException(message, code);
	}

	/** {@code Throwable.getMessage()} is null for plenty of IO failures; fall back to the type name. */
	private static String messageOf(final Throwable t)
	{
		final String message = t.getMessage();
		return truncate(message == null || message.isEmpty() ? t.getClass().getSimpleName() : message);
	}

	private static String truncate(final String text)
	{
		if (text == null)
		{
			return null;
		}
		return text.length() <= MAX_DETAIL_CHARS ? text : text.substring(0, MAX_DETAIL_CHARS) + "...";
	}

	/**
	 * The one thing that differs between the three requests once the bytes are in hand. A tiny interface rather
	 * than a {@code Function} because the parsers throw a checked {@link WikiPriceException}.
	 */
	@FunctionalInterface
	private interface BodyParser<T>
	{
		T parse(String body) throws WikiPriceException;
	}
}

package com.bankpricemovement;

import java.text.Normalizer;
import java.time.LocalDate;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * One revision of the wiki's Grand Exchange guide-price table: the revision it came from, the moment that
 * revision was SAVED, the DAY its prices belong to, the moment we read it, and the whole name-to-gp map
 * (contract K12, rewritten by addendum L - L7, L8).
 *
 * <p><b>The day marker, and why it is not the timestamp</b> (L7, evidence L-E). The revision timestamp says
 * when someone pressed save; it does not say which Jagex day the prices in the body are. Human maintenance
 * edits - 24 of 194 in-window revisions, and once the bot itself - republish the PREVIOUS day's table under the
 * next day's timestamp (revision 15329323, Riblet15, saved 2026-09-03T06:46Z, carries
 * {@code %LAST_UPDATE_F%} "02 September 2026 07:21:23"). The table's own {@code %LAST_UPDATE%} field is the
 * authoritative marker and was right on 38 of 38 sampled bodies against 34 of 38 for the timestamp, so
 * {@link #dataSeconds()} - not {@link #revisionSeconds()} - is what the status line, the tooltip and the L5 day
 * check read. {@link #revisionSeconds()} stays for cache identity beside {@link #revId()}.
 *
 * <p><b>Why the map is keyed by NAME.</b> {@code Module:GEPrices/data.json} is a wiki page written for wiki
 * templates, so its keys are item names ({@code {"Green hat": 1086, "Abyssal whip": 799012, ...}}, 4,566 of them,
 * 126 KB - {@code docs/research/bank-price-movement-calibration-2026-09-08.md}). Turning that into the id-keyed
 * {@link PriceMap} the rows are computed from needs the id-to-wiki-name table
 * ({@code prices.runescape.wiki/api/v1/osrs/mapping}, contract K3), which is the caller's business and is
 * refreshed on a completely different cadence (weekly, against six-hourly for the history - L10). Keeping this
 * type name-keyed means one fetched revision can be re-projected onto ids whenever the mapping changes, without
 * going back to the network.
 *
 * <p><b>Why every key goes through {@link #key(String)}</b> (L8, evidence L-F). The wiki case-renamed 81 keys on
 * 2026-08-12..20 ("3rd age amulet" became "3rd Age amulet"), so a byte-exact lookup silently loses three of the
 * user's bank items on every window of 30 days or more - the older revision spells them the other way.
 * Lower-casing with {@link Locale#ROOT} after an NFC normalise and a whitespace collapse recovers all of them and
 * was collision-free on all six sampled revisions. Both the parsed table and every lookup are keyed through the
 * one method, so a caller cannot accidentally compare a raw name against a folded key.
 *
 * <p>Immutable and safe to share across threads: the map is built on an OkHttp dispatcher thread, handed to the
 * service's executor and read while rows are computed, so it is copied once here and handed out
 * {@link Collections#unmodifiableMap unmodifiable}.
 */
public final class GuideSnapshot
{
	private static final Logger log = LoggerFactory.getLogger(GuideSnapshot.class);

	/** The "no guide table yet" snapshot: no revision, no day, no stamp, no prices. Immutable, safe to share. */
	public static final GuideSnapshot EMPTY = new GuideSnapshot(0L, 0L, 0L, 0L, Collections.emptyMap());

	/**
	 * The table's "this item has no price" value (L8 c). Three keys carried exactly 2,147,483,646 on the sampled
	 * revisions - "3rd Age axe", "3rd Age druidic robe top", "3rd Age pickaxe" - one short of
	 * {@link Integer#MAX_VALUE}, which is the wiki's way of writing "unpriced" in a field that must hold a
	 * number. Treated as a threshold rather than an equality so a future 2,147,483,647 cannot slip a two-billion
	 * gp price onto a row.
	 */
	public static final long NO_PRICE = 2_147_483_646L;

	/**
	 * Anything Java calls whitespace, plus U+00A0. {@code \s} does NOT match a non-breaking space, and a wiki
	 * name saved with one would otherwise never match the same name typed with an ordinary space.
	 */
	private static final Pattern WHITESPACE = Pattern.compile("[\\s\\u00A0]+");

	private final long revId;
	private final long revisionSeconds;
	private final long dataSeconds;
	private final long fetchedAtMillis;
	private final Map<String, Long> pricesByName;

	/**
	 * @param revId           the wiki revision id this table came from; 0 only for {@link #EMPTY}
	 * @param revisionSeconds when that revision was SAVED, unix seconds (the API's {@code timestamp}); cache
	 *                        identity only (L7)
	 * @param dataSeconds     the table's own {@code %LAST_UPDATE%}, unix seconds - the day marker every label
	 *                        and every day comparison uses (L7)
	 * @param fetchedAtMillis when we read it, epoch millis - the value the six-hourly refetch rule compares (L10)
	 * @param pricesByName    wiki item name to guide price in gp. Copied; keys are folded through
	 *                        {@link #key(String)}, null keys and values are dropped, and a value at or above
	 *                        {@link #NO_PRICE} is dropped because it is the table's "unpriced" marker, not a price
	 */
	public GuideSnapshot(final long revId, final long revisionSeconds, final long dataSeconds,
		final long fetchedAtMillis, final Map<String, Long> pricesByName)
	{
		final Map<String, Long> copy = new HashMap<>();
		if (pricesByName != null)
		{
			for (final Map.Entry<String, Long> entry : pricesByName.entrySet())
			{
				final String folded = key(entry.getKey());
				final Long price = entry.getValue();
				if (folded == null || folded.isEmpty() || price == null || price >= NO_PRICE)
				{
					continue;
				}

				final Long clash = copy.putIfAbsent(folded, price);
				if (clash != null && !clash.equals(price))
				{
					// Never seen: the fold was collision-free on all six sampled revisions (L-F). If the wiki
					// ever ships two spellings of one name with two prices, one of them wins arbitrarily and
					// this line is the only record of it - a wrong-by-a-rename row is still better than a throw
					// inside a fetch callback.
					log.debug("bank-portfolio-tracker: revision {} folds two spellings of \"{}\" onto {} gp (kept {})",
						revId, folded, price, clash);
				}
			}
		}

		this.revId = revId;
		this.revisionSeconds = revisionSeconds;
		this.dataSeconds = dataSeconds;
		this.fetchedAtMillis = fetchedAtMillis;
		this.pricesByName = Collections.unmodifiableMap(copy);
	}

	/**
	 * The wiki revision id this table is the content of. Never 0 for a fetched snapshot -
	 * {@code GuidePriceClient} drops a revision it could not identify rather than report one.
	 */
	public long revId()
	{
		return revId;
	}

	/**
	 * When the revision was SAVED, in unix seconds. Cache identity, not a day marker: a body whose
	 * {@link #dataSeconds()} disagrees with it by up to two days is an ordinary human edit (L-E), which is why
	 * nothing user-facing prints this value any more (L7).
	 */
	public long revisionSeconds()
	{
		return revisionSeconds;
	}

	/**
	 * The table's own {@code %LAST_UPDATE%} in unix seconds - the moment Jagex stamped the guide prices in this
	 * body. This is the authoritative day marker (L7): the status line and the tooltip print its DAY, and L5's
	 * "is this really day T's table?" check compares {@link #dataDay()} against the target date.
	 */
	public long dataSeconds()
	{
		return dataSeconds;
	}

	/**
	 * The UTC calendar day these prices belong to, or null when the body carried no marker ({@link #EMPTY}).
	 * UTC always (L9) - the guide price steps once a day and every date in this plugin's selection maths is a UTC
	 * date, so a local-zone date would put a user east of Greenwich a whole day out.
	 *
	 * <p><b>What this rests on, exactly.</b> Not a midnight stamp: the Jagex rollover was observed between 00:47
	 * and 02:06 UTC (L-A), and {@code %LAST_UPDATE%} is not the rollover at all - it is the wiki bot's own capture
	 * moment for that step, which lands anywhere in the day (02:11-22:20 UTC, L-C; the five stored baselines here
	 * read 03:35, 07:21, 09:22, 13:00 and 13:51 UTC, each a few minutes before its revision's save time). So the
	 * UTC date of the marker names the right Jagex day only while the bot runs AFTER the rollover - a margin of
	 * about five minutes between the latest observed rollover and the earliest observed bot run. A body whose
	 * marker falls outside the window its own save time allows is already refused upstream
	 * ({@code GuidePriceClient}, L7); a bot run that slipped in front of a late rollover would not be, and would
	 * date its table one day late. Since contract 1.1.2 nothing selects by this date any more - the service picks by
	 * {@link #dataSeconds()} - so the case costs at most a label one day out, never a wrong table.
	 */
	public LocalDate dataDay()
	{
		return dataSeconds <= 0L ? null : RevisionRef.dayOf(dataSeconds);
	}

	/**
	 * When this snapshot was read from the network, in epoch millis. The index and the newest table are refetched
	 * when this is more than six hours old (L10), because the table only changes about once a day.
	 */
	public long fetchedAtMillis()
	{
		return fetchedAtMillis;
	}

	/**
	 * The guide price for one wiki item name, or null when the table does not list it or lists it as unpriced.
	 * The name is folded through {@link #key(String)} first, so the caller may pass the {@code /mapping} name,
	 * the item composition name, or the table's own spelling in any case (L8).
	 */
	public Long get(final String name)
	{
		final String folded = key(name);
		return folded == null ? null : pricesByName.get(folded);
	}

	/** Every folded-name-to-gp entry, unmodifiable. Keys are {@link #key(String)} output, not wiki spelling. */
	public Map<String, Long> pricesByName()
	{
		return pricesByName;
	}

	public int size()
	{
		return pricesByName.size();
	}

	public boolean isEmpty()
	{
		return pricesByName.isEmpty();
	}

	/**
	 * The one name-folding rule (L8): NFC normalise, collapse every run of whitespace to a single space, trim,
	 * then lower-case with {@link Locale#ROOT}.
	 *
	 * <p>Each step earns its place. NFC because the wiki serves UTF-8 that may spell an accent either
	 * pre-composed or as a combining pair and the two are different Strings. The whitespace collapse because a
	 * double space between words is invisible in a wiki edit box. {@link Locale#ROOT} rather than the default
	 * locale because a Turkish user's JVM lower-cases "I" to a dotless "&#x131;", which would fold "Ice gloves"
	 * onto a key no table has - the classic locale bug, and this method runs on whatever machine the plugin is
	 * installed on.
	 *
	 * <p>Package-private: it is an internal key, and letting the panel or the service invent its own folding is
	 * exactly the drift L8 exists to prevent.
	 *
	 * @param name any name, including null
	 * @return the folded key, or null when {@code name} is null
	 */
	static String key(final String name)
	{
		if (name == null)
		{
			return null;
		}

		final String composed = Normalizer.normalize(name, Normalizer.Form.NFC);
		final String collapsed = WHITESPACE.matcher(composed).replaceAll(" ").trim();
		return collapsed.toLowerCase(Locale.ROOT);
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}

		if (!(o instanceof GuideSnapshot))
		{
			return false;
		}

		final GuideSnapshot other = (GuideSnapshot) o;
		return revId == other.revId
			&& revisionSeconds == other.revisionSeconds
			&& dataSeconds == other.dataSeconds
			&& fetchedAtMillis == other.fetchedAtMillis
			&& pricesByName.equals(other.pricesByName);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(revId, revisionSeconds, dataSeconds, fetchedAtMillis, pricesByName);
	}

	@Override
	public String toString()
	{
		return "GuideSnapshot{revId=" + revId
			+ ", dataDay=" + dataDay()
			+ ", revisionSeconds=" + revisionSeconds
			+ ", fetchedAtMillis=" + fetchedAtMillis
			+ ", names=" + pricesByName.size() + '}';
	}
}

package com.bankpricemovement;

import java.util.LinkedHashMap;
import java.util.Locale;
import javax.annotation.Nullable;

/**
 * Which of the hero card's three figures the sidebar prints: the whole-bank TOTAL, its gp move for the lit
 * window, and that move as a percentage (addendum O line O2;
 * {@code docs/bank-price-movement-addendum-O-2026-09-09.md}). The user asked for it in one sentence -
 * "i prefer the ticker look, also have an option to show/hide the bank value and pnl and percentage"
 * (2026-09-09) - so the card's headline block is three independent switches and everything else on it (the
 * caption, the Refresh link, the window chips, the footnote) is always drawn.
 *
 * <p><b>Immutable, and the three switches are independent.</b> Every {@code with*} answers a new value, so a
 * visibility can be handed to the panel, stored in a field and compared with {@code equals} without anyone
 * having to copy it. The eight combinations are all legal: {@link #ALL} is the default a fresh profile gets
 * and {@link #NONE} - the card reduced to its caption, its chips and its footnote - is one of them, not an
 * error.
 *
 * <p><b>Presentation only.</b> Hiding a figure hides the FIGURE, never the arithmetic: {@code PortfolioMath}
 * still computes the whole-bank sums, {@code state.portfolio} still echoes them in full (developer mode only)
 * and every row keeps its own numbers. This is deliberately not part of {@link RowFilter} for the reason
 * addendum N gave the look it replaces - a filter says what the list CONTAINS, and a switch that only decides
 * what is painted must not make the service recompute anything.
 *
 * <p><b>The move line is the pair.</b> {@link #gp()} and {@link #pct()} are the two halves of one line, so
 * {@link #moveLine()} - "is anything left of it" - is what the card asks before it decides whether to draw
 * the line and its direction triangle at all (O3).
 *
 * <p>The three switches are stored as three flat boolean config items ({@code showBankValue},
 * {@code showBankMoveGp}, {@code showBankMovePct}), which is what makes them reachable from RuneLite's own
 * settings panel as well as from the card's right-click menu; {@link BankPriceMovementPlugin#heroFromConfig()}
 * is the one place the three are read back into this value.
 */
public final class HeroVisibility
{
	/** Everything shown - the default a fresh profile gets, and what addendum M's card always drew (O2). */
	public static final HeroVisibility ALL = new HeroVisibility(true, true, true);
	/** All three figures hidden: the card keeps its caption, its chips and its footnote and nothing else (O3). */
	public static final HeroVisibility NONE = new HeroVisibility(false, false, false);

	private final boolean value;
	private final boolean gp;
	private final boolean pct;

	private HeroVisibility(boolean value, boolean gp, boolean pct)
	{
		this.value = value;
		this.gp = gp;
		this.pct = pct;
	}

	/**
	 * @param value whether the 28 px whole-bank total is drawn
	 * @param gp    whether the move line carries the gp change
	 * @param pct   whether the move line carries the percentage
	 */
	public static HeroVisibility of(boolean value, boolean gp, boolean pct)
	{
		if (value && gp && pct)
		{
			return ALL;
		}
		if (!value && !gp && !pct)
		{
			return NONE;
		}
		return new HeroVisibility(value, gp, pct);
	}

	/** Whether the whole-bank total is drawn; with it off the 28 px line is REMOVED and the card shrinks (O3). */
	public boolean value()
	{
		return value;
	}

	/** Whether the move line carries the gp change ("+12.4m"). */
	public boolean gp()
	{
		return gp;
	}

	/** Whether the move line carries the percentage ("+1.0%"). */
	public boolean pct()
	{
		return pct;
	}

	/**
	 * Whether the move line exists at all: with BOTH figures off the line is removed and the direction triangle
	 * goes with it (O3). The card's coloured left edge is not a figure and stays either way - it is a direction
	 * hint, and hiding a number is not the same as hiding which way the bank went.
	 */
	public boolean moveLine()
	{
		return gp || pct;
	}

	/** Whether any figure is drawn at all; false is {@link #NONE}, the caption-chips-footnote card. */
	public boolean any()
	{
		return value || gp || pct;
	}

	/**
	 * The three switches as an ordered map - {@code value}, {@code gp}, {@code pct} - which is the shape both
	 * JSON answers about them are built from: the dev bridge's {@code state.hero} ({@code BpmCommands.heroJson})
	 * and the panel's own {@code describe()} echo of it (O3). Two writers of one object used to spell the same
	 * three names twice, and a switch renamed in one of them would have quietly split the two answers apart.
	 *
	 * <p>A fresh {@link LinkedHashMap} per call, so a caller may hand it to Gson, add to it or keep it; the
	 * insertion order IS the field order those answers print in.
	 */
	public LinkedHashMap<String, Boolean> asMap()
	{
		final LinkedHashMap<String, Boolean> m = new LinkedHashMap<>(4);
		m.put("value", value);
		m.put("gp", gp);
		m.put("pct", pct);
		return m;
	}

	public HeroVisibility withValue(boolean shown)
	{
		return shown == value ? this : of(shown, gp, pct);
	}

	public HeroVisibility withGp(boolean shown)
	{
		return shown == gp ? this : of(value, shown, pct);
	}

	public HeroVisibility withPct(boolean shown)
	{
		return shown == pct ? this : of(value, gp, shown);
	}

	/**
	 * The dev bridge's {@code hero=} verb (O5), as a pure function of the visibility it is applied to: one of
	 * the three field words TOGGLES that figure, {@code all} shows every figure and {@code none} hides every
	 * figure. So {@code hero=value} flips the total, {@code hero=none} empties the card's headline block and
	 * {@code hero=all} puts it back.
	 *
	 * <p>The spellings are generous because the verb is typed by hand into a URL query: the field words take
	 * their obvious synonyms ({@code total}, {@code move}, {@code pnl}, {@code percent}, {@code %}) and the
	 * whole text is trimmed and case-folded first.
	 *
	 * @param text the verb's value; anything, including null
	 * @return the visibility to apply, or null when the text names none of the five - the caller then answers
	 *         {@code ok:false} and leaves the card exactly as it was, rather than guessing at a figure
	 */
	@Nullable
	public HeroVisibility applyVerb(@Nullable String text)
	{
		if (text == null)
		{
			return null;
		}
		final String key = text.trim().toLowerCase(Locale.ENGLISH);
		switch (key)
		{
			case "value":
			case "total":
			case "bankvalue":
			case "bank value":
			case "v":
				return withValue(!value);
			case "gp":
			case "move":
			case "movegp":
			case "amount":
			case "pnl":
				return withGp(!gp);
			case "pct":
			case "percent":
			case "percentage":
			case "movepct":
			case "%":
				return withPct(!pct);
			case "all":
			case "on":
			case "show":
				return ALL;
			case "none":
			case "off":
			case "hide":
				return NONE;
			default:
				return null;
		}
	}

	/** The five words {@link #applyVerb(String)} takes, for a refusal that says what to type instead. */
	public static String verbs()
	{
		return "value, gp, pct, all or none";
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof HeroVisibility))
		{
			return false;
		}
		final HeroVisibility other = (HeroVisibility) o;
		return value == other.value && gp == other.gp && pct == other.pct;
	}

	@Override
	public int hashCode()
	{
		return (value ? 4 : 0) | (gp ? 2 : 0) | (pct ? 1 : 0);
	}

	@Override
	public String toString()
	{
		return "HeroVisibility{value=" + value + ", gp=" + gp + ", pct=" + pct + '}';
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The note icon on the Net Worth History tab (1.1.1 part I2, the user's pick of six drawn, 2026-10-07: variant 2, "Filled disc
 * + i"): a filled disc {@value #DISC} px across with a lower-case "i" cut out of it, in a {@value #SIZE} x {@value #SIZE} box
 * like the two gears it stands beside. Like {@link EyeIcon} it is a PIXEL icon - every pixel is the disc's ink, the cut's
 * colour or clear, no anti-aliasing, no blend - so it is as sharp as the game's own sprites at any display scale, and nothing
 * about it depends on a font or a look and feel. There is no image file.
 *
 * <p>The disc is the gears' grey at rest and white under the mouse ({@link BankPriceMovementPanel#legacyInfoIcon}); the "i" -
 * a one-pixel dot, a one-pixel gap and a seven-pixel stem - is cut out in the caption row's own background, so it reads as a
 * hole in the disc. The disc stands against the box's right edge and top, which is where the sheet drew it: the gap to the
 * gears beside it is then the gears' own {@link BankPriceMovementPanel#LIST_OPTIONS_GAP}, to the pixel.
 */
final class InfoIcon
{
	/** The box's side in px: the same 12 px the gears and the eye are drawn at. */
	static final int SIZE = 12;
	/** The disc's width and height in px. */
	static final int DISC = 11;
	/** The colour of the cut-out "i": the caption row's background, so the disc reads as holed. */
	static final Color CUT = ColorScheme.DARK_GRAY_COLOR;

	/**
	 * The disc, row by row: {@code X} is the disc's ink, {@code i} the cut-out and {@code .} clear. The dot is row 1, the stem
	 * rows 3 to 9; rows 2 and 10 are whole.
	 */
	private static final String[] ROWS = {
		"....XXXXX...",
		"...XXXiXXX..",
		"..XXXXXXXXX.",
		".XXXXXiXXXXX",
		".XXXXXiXXXXX",
		".XXXXXiXXXXX",
		".XXXXXiXXXXX",
		".XXXXXiXXXXX",
		"..XXXXiXXXX.",
		"...XXXiXXX..",
		"....XXXXX...",
		"............",
	};

	private InfoIcon()
	{
	}

	/**
	 * The icon with its disc in {@code disc}: every disc pixel that colour, every "i" pixel {@link #CUT}, every other pixel
	 * fully transparent.
	 */
	static ImageIcon icon(final Color disc)
	{
		final int ink = new Color(disc.getRed(), disc.getGreen(), disc.getBlue()).getRGB();
		final int cut = new Color(CUT.getRed(), CUT.getGreen(), CUT.getBlue()).getRGB();
		final BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < SIZE; y++)
		{
			for (int x = 0; x < SIZE; x++)
			{
				final char pixel = ROWS[y].charAt(x);
				if (pixel == 'X')
				{
					image.setRGB(x, y, ink);
				}
				else if (pixel == 'i')
				{
					image.setRGB(x, y, cut);
				}
			}
		}
		return new ImageIcon(image);
	}
}

package com.bankpricemovement;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.DefaultFocusTraversalPolicy;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GraphicsEnvironment;
import java.awt.Window;
import java.awt.event.ActionEvent;
import java.awt.event.KeyEvent;
import javax.annotation.Nullable;
import javax.swing.AbstractAction;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.KeyStroke;
import javax.swing.WindowConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * The question the Net Worth History tab asks before it shows the days recorded before 1.0.9 (1.0.9 part 5): the
 * sentence {@link BankPriceMovementPanel#LEGACY_ASK} - or, for a record restarted because its days counted bank
 * placeholders, {@link BankPriceMovementPanel#LEGACY_PLACEHOLDERS_ASK} (1.1.1 part B) - over two buttons, <i>Include</i>
 * and <i>Cancel</i>, in RuneLite's dark colours. <i>Include</i> is the default button and takes the focus, so Enter
 * answers yes; Escape, <i>Cancel</i> and the window's close box all answer no. It is modal to the client window that
 * owns it: the reader has been asked something about their own numbers, and the sidebar behind it waits for the answer.
 *
 * <p><b>The model and the window are apart.</b> The panel of controls ({@link #content}) is built without a window,
 * so a test can press its buttons on a machine with no screen; the {@link JDialog} that hosts it is made only by
 * {@link #window}.
 */
final class LegacyDialog
{
	static final String INCLUDE_TEXT = "Include";
	static final String CANCEL_TEXT = "Cancel";

	/** The width the question wraps at, in px. */
	static final int TEXT_WIDTH = 320;
	private static final int PADDING = 12;
	/** The key Escape is bound under in {@link #content}'s action map. */
	static final String CANCEL_KEY = "cancel";

	/** Everything the window shows, built without a window. */
	final JPanel content = new JPanel(new BorderLayout());
	final JTextArea textArea;
	final JButton includeButton;
	final JButton cancelButton;
	/** True once <i>Include</i> was pressed; false until then, whatever else closes the window. EDT. */
	boolean included;
	/** The hosting dialog; null until {@link #window}, and again once closed. EDT. */
	@Nullable
	private JDialog dialog;

	LegacyDialog(final String question)
	{
		content.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		content.setBorder(new EmptyBorder(PADDING, PADDING, PADDING, PADDING));

		textArea = new JTextArea(question);
		textArea.setEditable(false);
		textArea.setLineWrap(true);
		textArea.setWrapStyleWord(true);
		textArea.setOpaque(false);
		textArea.setFont(Widgets.sans(12));
		textArea.setForeground(Color.WHITE);
		textArea.setBorder(null);
		// A read-only box that can take the focus shows its caret; this one is a label that wraps, and the first
		// thing that may hold the focus must be Include.
		textArea.setFocusable(false);
		// A wrapped text area has no height of its own until it knows its width: give it the width, ask, and pin both.
		textArea.setSize(new Dimension(TEXT_WIDTH, Short.MAX_VALUE));
		textArea.setPreferredSize(new Dimension(TEXT_WIDTH, textArea.getPreferredSize().height));
		content.add(textArea, BorderLayout.CENTER);

		includeButton = Widgets.smallButton(INCLUDE_TEXT, null, e -> answer(true));
		cancelButton = Widgets.smallButton(CANCEL_TEXT, null, e -> answer(false));
		final JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
		buttons.setOpaque(false);
		buttons.setBorder(new EmptyBorder(PADDING, 0, 0, 0));
		buttons.add(includeButton);
		buttons.add(cancelButton);
		content.add(buttons, BorderLayout.SOUTH);

		// Escape is Cancel wherever the focus is in the window.
		content.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW)
			.put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), CANCEL_KEY);
		content.getActionMap().put(CANCEL_KEY, new AbstractAction()
		{
			@Override
			public void actionPerformed(final ActionEvent e)
			{
				answer(false);
			}
		});
	}

	/**
	 * EDT. Puts the question to the reader and answers what they chose: true for <i>Include</i> only. Blocks - the dialog
	 * is modal - until it is closed. Answers false at once on a machine with no display, which is a test or a server.
	 *
	 * @param owner the RuneLite frame (the panel's window ancestor), or null
	 * @param title the check item's own words, which the panel picks by the record's reason (1.1.1 part B)
	 */
	static boolean ask(@Nullable final Window owner, final String title, final String question)
	{
		if (GraphicsEnvironment.isHeadless())
		{
			return false;
		}
		final LegacyDialog window = window(owner, title, question);
		window.dialog.setVisible(true);
		return window.included;
	}

	/**
	 * The window built and sized but not yet shown: a {@link JDialog} owned by {@code owner}, titled with the check
	 * box's own words ({@code title}), modal to its owner's windows, closing by disposing, with <i>Include</i> as its
	 * default button and the focus on it when the window first gets it. Needs a display.
	 */
	static LegacyDialog window(@Nullable final Window owner, final String title, final String question)
	{
		final LegacyDialog window = new LegacyDialog(question);
		final JDialog dialog = new JDialog(owner, title);
		dialog.setModalityType(Dialog.ModalityType.DOCUMENT_MODAL);
		dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
		dialog.setContentPane(window.content);
		dialog.getRootPane().setDefaultButton(window.includeButton);
		dialog.setResizable(false);
		dialog.pack();
		dialog.setLocationRelativeTo(owner);
		// Where the focus lands when the window first gets it: Include, so Enter answers yes and no text box shows a caret.
		dialog.setFocusTraversalPolicy(new DefaultFocusTraversalPolicy()
		{
			@Override
			public Component getInitialComponent(final Window w)
			{
				return window.includeButton;
			}
		});
		window.dialog = dialog;
		return window;
	}

	/** A button's press, or Escape: remembers the answer and closes the window; harmless with no window. */
	private void answer(final boolean yes)
	{
		included = yes;
		final JDialog host = dialog;
		dialog = null;
		if (host != null)
		{
			host.dispose();
		}
	}
}

package com.bankpricemovement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.ParseException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.client.util.QuantityFormatter;

/**
 * Every number the sidebar shows, in one pure place (contract C8-C10): how a bank stack plus two price points
 * become a row, how a row list is filtered and ordered, and how a long becomes the short text a 213 px column
 * has room for.
 *
 * <p>Pure on purpose. The service computes rows on its executor and the panel formats them on the EDT, so
 * nothing here touches the client, Swing, the network or the clock beyond the millis it is handed - which is
 * also what makes the whole of the plugin's arithmetic testable without a client (playbook 7.6, style PURE).
 *
 * <p>The formatting delegates to RuneLite's own {@code QuantityFormatter} rather than inventing a second
 * house style for gp
 * ({@code runelite-client/src/main/java/net/runelite/client/util/QuantityFormatter.java}:
 * {@code quantityToStackSize} :80-115, {@code parseQuantity} :165-170, {@code formatNumber} :177-180),
 * so "12.3k" here means exactly what it means on an item stack in the game.
 */
public final class MovementMath
{
	/**
	 * What every "there is no number here" cell reads. One dash, everywhere, so a missing baseline is never
	 * mistaken for a zero move.
	 */
	public static final String DASH = "-";

	/**
	 * {@code HH:mm} in the viewer's own zone. Immutable and therefore safe to share
	 * ({@link DateTimeFormatter} is thread-safe); {@link Locale#ENGLISH} only pins the digits, as the pattern
	 * carries no locale-sensitive text.
	 */
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);

	/**
	 * {@code dd MMM} for a CALENDAR DATE - "07 Sep" - the day marker addendum L put in the status line and every
	 * row tooltip (L7). No clock and no zone: what it prints is a {@link LocalDate} that was already derived in
	 * UTC from the guide table's own {@code %LAST_UPDATE%} (L9), and turning a date into an instant to show it in
	 * the viewer's zone would shift it a day for half the world.
	 */
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("dd MMM", Locale.ENGLISH);

	/**
	 * How many decimals a percentage keeps (L2). The Grand Exchange site prints whole percents; ours keeps one,
	 * because a bank full of guide prices moves by fractions of a percent on most days (calibration: median
	 * |move| 0.36 % over 504 items) and whole percents would print a wall of zeroes.
	 */
	private static final int PCT_DECIMALS = 1;

	private MovementMath()
	{
	}

	// ---------------------------------------------------------------- rows (C8)

	/**
	 * Builds one row from a bank stack and the two price points that bracket the window (contract C8, sources
	 * per addendum K line K6/K13).
	 *
	 * <p>The source ladder is: the "now" point's mid if there is a POSITIVE one - since addendum K the service
	 * builds it as {@code new PricePoint(guide, guide)} from RuneLite's guide price (K1), so the mid IS that price
	 * and the source is GUIDE; otherwise the fallback price if the caller offered a positive one (source RUNELITE -
	 * the pre-K path, which the service no longer takes: it always passes 0); otherwise no price. A point that
	 * exists but has NEITHER side counts as no price, not as zero.
	 *
	 * <p><b>Why a "now" of 0 or less is no price at all.</b> L1 spells 0 as "RuneLite has no price for this item",
	 * and both the other two places that decide what counts as a price already say so - {@code PriceService.finish}
	 * ({@code price > 0 ? Long.valueOf(price) : null}) and {@code PortfolioMath}'s own {@code priced} test. The
	 * degraded mode of L3 takes "now" from the newest guide TABLE instead, where a 0 or a negative would survive
	 * the fold, and a row priced at 0 would pass the gp band, count as priced, and read "-100.0%" at the top of
	 * the losers - while the bank-value card, which applies the rule, would leave the same stack out. One rule,
	 * three places.
	 *
	 * <p>A move is computed ONLY for a GUIDE row with both ends present and a positive "then": the baseline is
	 * the same Jagex series at an earlier revision, so the difference is a real move, while a fallback price is
	 * a different measurement and subtracting a baseline from it would invent one; a "then" of 0 would make the
	 * percentage infinite.
	 *
	 * @param item                  the bank stack; never null
	 * @param now                   the guide price now as a point, or null when RuneLite has none
	 * @param then                  the baseline revision's point for this item, or null when no table names it
	 * @param runeliteFallbackPrice a fallback price with no history behind it, or 0 for "do not fall back"
	 * @return the row, never null
	 */
	public static MovementRow row(final BankItem item, final PricePoint now, final PricePoint then,
		final int runeliteFallbackPrice)
	{
		Objects.requireNonNull(item, "item");

		final Long guideNow = now == null ? null : now.mid();

		final Long unitPrice;
		final MovementRow.PriceSource source;
		if (guideNow != null && guideNow > 0L)
		{
			unitPrice = guideNow;
			source = MovementRow.PriceSource.GUIDE;
		}
		else if (runeliteFallbackPrice > 0)
		{
			unitPrice = (long) runeliteFallbackPrice;
			source = MovementRow.PriceSource.RUNELITE;
		}
		else
		{
			unitPrice = null;
			source = MovementRow.PriceSource.NONE;
		}

		final Long thenPrice = then == null ? null : then.mid();

		Long deltaGp = null;
		Double deltaPct = null;
		if (source == MovementRow.PriceSource.GUIDE && thenPrice != null && thenPrice > 0L)
		{
			deltaGp = unitPrice - thenPrice;
			deltaPct = deltaGp * 100.0d / thenPrice;
		}

		return new MovementRow(item.id, item.name, item.quantity, item.stackable, unitPrice, thenPrice,
			deltaGp, deltaPct, holdingValue(unitPrice, item.quantity), source);
	}

	/**
	 * The row an UNTRADEABLE stack that could not be parts-priced becomes (addendum Q, line Q5; addendum AV; produced
	 * whatever "Include alch-only untradeables" says since 1.1.0 part G, which decides only whether it is in the bank value): its unit price is the item's High Alchemy value
	 * ({@link BankItem#alchPrice()}), its source is {@link MovementRow.PriceSource#ALCH}, and it has no baseline and
	 * therefore no move - an alch value is a constant of the item rather than a series, so subtracting one from
	 * another would invent a movement that never happened.
	 *
	 * <p>The holding is the alch value times the quantity, as for any other row, which is what puts the stack in
	 * the bank value and what the row's headline line prints (addendum AN).
	 *
	 * @param item the bank stack; never null. A stack that is not untradeable, or whose alch value is 0, has no
	 *             price here at all and renders as the dash - the caller decides whether such a row is worth
	 *             drawing ({@code MovementMath.apply} drops it)
	 */
	public static MovementRow alchRow(final BankItem item)
	{
		Objects.requireNonNull(item, "item");

		final Long alch = item.alchPrice();
		return new MovementRow(item.id, item.name, item.quantity, item.stackable, alch, null, null, null,
			holdingValue(alch, item.quantity),
			alch == null ? MovementRow.PriceSource.NONE : MovementRow.PriceSource.ALCH);
	}

	/**
	 * What a stack is worth: unit price times quantity (contract C8). A bank can hold 2.1 billion of a
	 * 2 billion gp item on paper, so the multiplication is checked and CLAMPED to {@link Long#MAX_VALUE}
	 * rather than allowed to wrap into a negative fortune.
	 *
	 * @return 0 when there is no price or nothing to hold
	 */
	public static long holdingValue(final Long unitPrice, final int quantity)
	{
		if (unitPrice == null || quantity <= 0)
		{
			return 0L;
		}

		try
		{
			return Math.multiplyExact(unitPrice, (long) quantity);
		}
		catch (ArithmeticException overflow)
		{
			return Long.MAX_VALUE;
		}
	}

	/**
	 * What a stack's price CHANGED by: the unit change times the quantity - the gp figure the row's headline
	 * line prints (addendum AN) and the key the {@link SortMode#GP_MOVE} column sorts on, since addendum AO
	 * line AO1 under every switch rather than only while {@code holdingOnRows} was on (Q6).
	 *
	 * <p>Not {@link #holdingValue}: a change is signed, so the overflow clamp has to pick an END rather than
	 * always {@link Long#MAX_VALUE}. A fall clamped upwards would sort a collapse to the top of the gainers.
	 *
	 * @param deltaGp  the change in the price of one, or null when there is no move
	 * @param quantity how many the bank holds
	 * @return 0 when there is no move or nothing to hold; otherwise the product, clamped to
	 *         {@link Long#MAX_VALUE} or {@link Long#MIN_VALUE} by the change's own sign
	 */
	public static long holdingDelta(@Nullable final Long deltaGp, final int quantity)
	{
		if (deltaGp == null || quantity <= 0)
		{
			return 0L;
		}

		try
		{
			return Math.multiplyExact(deltaGp, (long) quantity);
		}
		catch (ArithmeticException overflow)
		{
			return deltaGp > 0L ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	// ---------------------------------------------------------------- filter and sort (C9)

	/**
	 * The user's view of the rows: keep what the gp band admits, order it by the chosen sort (contract C9).
	 *
	 * <p>A row with no unit price is dropped rather than shown at the bottom - a band on the price of one
	 * cannot say anything about an item that has no price, and the count line would otherwise claim items the
	 * filter never considered.
	 *
	 * <p>The band judges the price of ONE item whatever a row prints - it is "gp min / max" on the unit price
	 * (design D4), and a band that silently meant something else would be a different feature. Nothing but the
	 * {@link RowFilter} reaches this any more: the overload the view switches used to arrive by existed for the
	 * single key {@code holdingOnRows}, and went with it (addendum AO, line AO1).
	 *
	 * @param rows   every bank row; null reads as empty
	 * @param filter the band, sort, direction and window; null reads as {@link RowFilter#DEFAULT}
	 * @return a new unmodifiable list
	 */
	public static List<MovementRow> apply(final List<MovementRow> rows, final RowFilter filter)
	{
		final RowFilter used = filter == null ? RowFilter.DEFAULT : filter;
		final List<MovementRow> kept = new ArrayList<>();

		if (rows != null)
		{
			for (final MovementRow row : rows)
			{
				if (row == null || row.unitPrice() == null)
				{
					continue;
				}

				if (inBand(row.unitPrice(), used.gpMin(), used.gpMax()))
				{
					kept.add(row);
				}
			}
		}

		kept.sort(comparator(used.sort(), used.descending()));
		return Collections.unmodifiableList(kept);
	}

	/**
	 * Whether an item's name holds the text the reader typed into the search box (1.0.9 part 4): any PART of the
	 * name, whatever the case, so "run" finds both "Rune platebody" and "Runite ore" and "ite o" finds the second - a
	 * reader looking for an item rarely remembers how its name begins.
	 *
	 * <p>The query is trimmed first, because a space typed after a word is a slip rather than a request, and a
	 * blank one - nothing typed, or only spaces - matches every name, so an emptied box brings the whole list
	 * back. A row with no name matches nothing: there is no text to find the query in, and a search is for
	 * finding names.
	 *
	 * @param name  the item's name; null matches nothing
	 * @param query what was typed; null reads as blank
	 */
	public static boolean matches(@Nullable final String name, @Nullable final String query)
	{
		final String wanted = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		if (wanted.isEmpty())
		{
			return true;
		}

		return name != null && name.toLowerCase(Locale.ROOT).contains(wanted);
	}

	/**
	 * The rows whose names {@linkplain #matches match} what the reader typed, in the order they came (1.0.9 part 4).
	 *
	 * <p>This narrows rows the panel already holds and never asks the service for anything: the service keeps
	 * only the band's rows and a filter change there is a full recompute with a hop to the client thread, which a
	 * keystroke must never cause. So the band, the sort and the prices are exactly what they were, and the list
	 * simply gets shorter.
	 *
	 * <p>A blank query answers the SAME list instance it was given, so a box nobody has typed in costs one
	 * comparison and not a copy of every row.
	 *
	 * @param rows  the rows to narrow; null reads as empty
	 * @param query what was typed; null reads as blank
	 * @return the rows given when the query is blank, otherwise a new unmodifiable list
	 */
	public static List<MovementRow> search(final List<MovementRow> rows, @Nullable final String query)
	{
		final List<MovementRow> held = rows == null ? Collections.<MovementRow>emptyList() : rows;
		final String wanted = query == null ? "" : query.trim();
		if (wanted.isEmpty())
		{
			return held;
		}

		final List<MovementRow> kept = new ArrayList<>();
		for (final MovementRow row : held)
		{
			if (row != null && matches(row.name(), wanted))
			{
				kept.add(row);
			}
		}

		return Collections.unmodifiableList(kept);
	}

	/**
	 * Whether a row is an ALCH row (1.1.0 part G): an untradeable stack with no tradeable parts, at its High Alchemy
	 * value ({@link MovementRow.PriceSource#ALCH}). False for null. The one test the list rule, the sort rule and the
	 * counts share.
	 */
	public static boolean isAlch(@Nullable final MovementRow row)
	{
		return row != null && row.source() == MovementRow.PriceSource.ALCH;
	}

	/**
	 * The rows the Items list SHOWS (1.1.0 part G, G-4): {@link #search} over {@code rows}, less the ALCH rows while the
	 * "Show alch-only items" tick is off - unless the reader has typed something, in which case a row is listed when its
	 * name matches, alch or not (a search finds an alch item whatever the tick says). With the tick on this is
	 * {@link #search} exactly.
	 *
	 * <p>It narrows rows the panel already holds, like {@link #search}, and answers the SAME list instance it was given when
	 * nothing is dropped and nothing is searched, so a panel nobody has searched in or ticked in holds one list and not two.
	 *
	 * @param rows     the rows to narrow; null reads as empty
	 * @param query    what was typed; null reads as blank
	 * @param showAlch whether the tick is on
	 */
	public static List<MovementRow> list(final List<MovementRow> rows, @Nullable final String query, final boolean showAlch)
	{
		final List<MovementRow> held = rows == null ? Collections.<MovementRow>emptyList() : rows;
		final String wanted = query == null ? "" : query.trim();
		if (showAlch || !wanted.isEmpty())
		{
			return search(held, wanted);
		}

		List<MovementRow> kept = null;
		for (int i = 0; i < held.size(); i++)
		{
			final MovementRow row = held.get(i);
			if (isAlch(row))
			{
				if (kept == null)
				{
					kept = new ArrayList<>(held.subList(0, i));
				}
			}
			else if (kept != null)
			{
				kept.add(row);
			}
		}

		return kept == null ? held : Collections.unmodifiableList(kept);
	}

	/**
	 * The order one sort puts rows in (contract C9).
	 *
	 * <p>Two rules beyond "compare the key": a row WITHOUT the key - no move to speak of, or no price - is
	 * always last whichever way the arrow points (flipping the direction must not fill the top of the list
	 * with dashes), and equal keys fall back to name then id so the list never shuffles between two
	 * recomputes of the same data.
	 *
	 * <p><b>An ALCH row sorts after every other row</b> (1.1.0 part G, G-5), those with no key included, in all four
	 * columns and both directions: it never moved and its price is a constant, so it has no place among the items whose
	 * price is a series. Among themselves the alch rows order by the rules above.
	 *
	 * <p><b>The % and gp columns are ONE list</b> (the user, 2026-10-07, on the first live look at 1.2.0: "sort as 1
	 * list and not a separate second list for problem ones"): a {@link Grade#SOFT} figure sorts by its figure like any
	 * other - the word under its percentage is what says how much to lean on it - and a {@link Grade#NONE} row, which
	 * has no figure, sorts with the dashes as it always did. Contract 1.2.0's L5 asked for three tiers (solid, soft,
	 * none); they were built and removed the same day.
	 *
	 * <p><b>Every key is a property of the row alone.</b> {@code holdingOnRows} used to make
	 * {@link SortMode#GP_MOVE} compare the whole STACK's change (Q6) and, for one addendum, {@link
	 * SortMode#UNIT_PRICE} the whole stack's WORTH (V1) - the question V was answering, that a hundred Robin
	 * hood hats are a large holding though one hat is not a dear item, having since been given a column of its
	 * own in {@link SortMode#STACK_VALUE} (W1, which reverted V1). Addendum AO then deleted the key outright:
	 * the gp column compares the stack's change always (AO1), the price column one item's price always, and the
	 * percentage column is the same number however many are held. So no view switch reaches the ordering, and
	 * this takes no {@link ViewOptions}.
	 *
	 * @param sort       which key to compare; null reads as {@link SortMode#PERCENT_MOVE}
	 * @param descending true for biggest first
	 */
	public static Comparator<MovementRow> comparator(final SortMode sort, final boolean descending)
	{
		final SortMode used = sort == null ? SortMode.PERCENT_MOVE : sort;

		return (a, b) ->
		{
			final boolean alchA = isAlch(a);
			final boolean alchB = isAlch(b);
			if (alchA != alchB)
			{
				return alchA ? 1 : -1;
			}

			final Double keyA = key(a, used);
			final Double keyB = key(b, used);

			if (keyA == null || keyB == null)
			{
				if (keyA != null)
				{
					return -1;
				}

				if (keyB != null)
				{
					return 1;
				}

				return byNameThenId(a, b);
			}

			final int byKey = Double.compare(keyA, keyB);
			if (byKey != 0)
			{
				return descending ? -byKey : byKey;
			}

			return byNameThenId(a, b);
		};
	}

	/**
	 * Whether a unit price sits inside the band, where a maximum of 0 means "no upper bound" (contract C10) -
	 * the reading an empty Max field writes.
	 */
	public static boolean inBand(final long unit, final long min, final long max)
	{
		return unit >= min && (max == 0L || unit <= max);
	}

	/**
	 * The sort key as a double. Every gp figure a bank can hold is far below 2^53, where a double still counts
	 * exactly, so this loses nothing and keeps one comparator for the four columns (addendum W, line W1).
	 *
	 * <p>{@link SortMode#STACK_VALUE} is gated on {@link MovementRow#unitPrice()} rather than on the holding
	 * value itself, because {@link MovementRow#holdingValue()} answers a plain 0 for a row with no price, and a
	 * 0 sorts as the cheapest thing in the bank rather than as a dash. The same gate the price column has always
	 * used therefore serves both, and a priceless row is last under either whichever way the arrow points.
	 *
	 * <p>{@link SortMode#GP_MOVE} is gated the same way, on {@link MovementRow#deltaGp()}, though what it
	 * compares is {@link MovementRow#holdingDeltaGp()} (AO1): a row with no move has no gp key under either
	 * reading, and the stack's change answers a plain 0 for it, which would sort it among the unmoved instead
	 * of behind them.
	 *
	 * @return null when this row has no such key - the "always last" case
	 */
	private static Double key(final MovementRow row, final SortMode sort)
	{
		switch (sort)
		{
			case PERCENT_MOVE:
				return row.deltaPct();
			case GP_MOVE:
				return row.deltaGp() == null ? null : (double) row.holdingDeltaGp();
			case UNIT_PRICE:
				return row.unitPrice() == null ? null : (double) row.unitPrice();
			case STACK_VALUE:
				return row.unitPrice() == null ? null : (double) row.holdingValue();
			default:
				return null;
		}
	}

	/**
	 * The tiebreak, always ascending whichever way the sort points: alphabetical (case-insensitive, so
	 * "Abyssal whip" and "abyssal whip" land together), then by id so two items sharing a name still have a
	 * fixed order.
	 */
	private static int byNameThenId(final MovementRow a, final MovementRow b)
	{
		final int byName = String.CASE_INSENSITIVE_ORDER.compare(a.name(), b.name());
		return byName != 0 ? byName : Integer.compare(a.id(), b.id());
	}

	// ---------------------------------------------------------------- text (C10)

	/**
	 * Reads a gp amount the user typed: "100k", "1.5m", "2b", "1,000", "850" (contract C10). Delegates to
	 * {@code QuantityFormatter.parseQuantity} ({@code QuantityFormatter.java:165-170}) so the field accepts
	 * exactly what the rest of the client accepts, then adds the two rules a PRICE band needs and the
	 * formatter does not have: blank is not a number, and a negative is not a price (the formatter's suffix
	 * pattern :49 admits a leading "-" and would return it happily).
	 *
	 * @param text what the field holds; null and blank both throw
	 * @return the amount in gp, never negative
	 * @throws ParseException when the text names no non-negative amount - the panel turns the field's border
	 *                        red and leaves the filter alone (design C29 (5))
	 */
	public static long parseGp(final String text) throws ParseException
	{
		final String trimmed = text == null ? "" : text.trim();
		if (trimmed.isEmpty())
		{
			throw new ParseException("Enter a gp amount", 0);
		}

		final long value = QuantityFormatter.parseQuantity(trimmed);
		if (value < 0L)
		{
			throw new ParseException("A price cannot be negative: " + trimmed, 0);
		}

		return value;
	}

	/**
	 * A gp amount as the game writes a stack size: "850", "12.3k", "1.52m"
	 * ({@code QuantityFormatter.quantityToStackSize}, {@code QuantityFormatter.java:80-115}), lower-cased so
	 * the suffix sits quietly beside the number in a small row.
	 *
	 * <p>Note the client's own threshold rides along: anything under 10,000 is written out in full with
	 * commas ("4,100", not "4.1k").
	 */
	public static String formatGp(final long gp)
	{
		return lowerSuffix(QuantityFormatter.quantityToStackSize(gp));
	}

	/**
	 * The same amount in full, comma grouped ({@code QuantityFormatter.formatNumber},
	 * {@code QuantityFormatter.java:177-180}) - what the tooltip shows, where there is room for every digit.
	 */
	public static String formatExact(final long gp)
	{
		return QuantityFormatter.formatNumber(gp);
	}

	/**
	 * A price change with its sign: "+12.3k", "-4,100", "0", or {@link #DASH} when there is no move to show
	 * (contract C10).
	 *
	 * <p>A negative is formatted through the formatter's own minus rather than by negating the value, so
	 * {@link Long#MIN_VALUE} cannot overflow on its way to the screen.
	 */
	public static String formatDelta(final Long gp)
	{
		if (gp == null)
		{
			return DASH;
		}

		if (gp > 0L)
		{
			return "+" + formatGp(gp);
		}

		return formatGp(gp);
	}

	/**
	 * A percentage move as the Grand Exchange site writes one, to one decimal: "+0.8%", "-12.4%", "0.0%", or
	 * {@link #DASH} when there is none (contract C10, redefined by addendum L line L2).
	 *
	 * <p>The sign comes from the percentage itself here; the {@link #formatPct(Double, Long)} overload takes it
	 * from the gp change instead, which is what a row shows (L2).
	 */
	public static String formatPct(@Nullable final Double pct)
	{
		return formatPct(pct, null);
	}

	/**
	 * The same percentage, signed by the gp change beside it (L2).
	 *
	 * <p><b>Truncated toward zero, never rounded.</b> The GE site computes
	 * {@code trunc_toward_zero((daily[D] - daily[D-N]) / daily[D-N] * 100)}: measured against 26 live figures,
	 * truncation matched 26/26 and rounding only 15/26 (L-B). Ours truncates at {@value #PCT_DECIMALS} decimal
	 * instead of at a whole percent, so "-12.44" reads "-12.4%" - one digit shorter than the value, never one
	 * digit larger than it. {@link BigDecimal#valueOf(double)} goes through the double's SHORTEST decimal
	 * representation, so 0.7 truncates to "0.7" rather than to the "0.6" that {@code (long) (0.7 * 10)} yields
	 * from 6.999999999999999.
	 *
	 * <p><b>Why the sign is the gp change's and not the percentage's.</b> A fall of a hundredth of a percent
	 * truncates to a bare zero, and the site still prints it with a minus and a red arrow ("Amulet of fury",
	 * 30 d, -0.10 % shown as "-0.0%", L-B). So a row whose gp change is negative reads "-0.0%" and stays red,
	 * a row whose gp change is positive reads "+0.0%", and only a genuinely unmoved row reads "0.0%" in grey -
	 * the three states {@code MovementRowPanel.changeColor} already paints from the same gp figure.
	 *
	 * @param pct     the move in percent, or null / non-finite for {@link #DASH}
	 * @param deltaGp the gp change the percentage was computed from; null takes the sign from {@code pct}
	 */
	public static String formatPct(@Nullable final Double pct, @Nullable final Long deltaGp)
	{
		if (pct == null || !Double.isFinite(pct))
		{
			return DASH;
		}

		final BigDecimal truncated = BigDecimal.valueOf(pct).setScale(PCT_DECIMALS, RoundingMode.DOWN);
		// toPlainString, not toString: a percentage this large is nonsense data rather than "1.0E+2" on a row.
		return signedPct(truncated.abs().toPlainString(), pct, deltaGp);
	}

	/**
	 * The percentage as a ROW'S FACE prints it (addendum AT): {@link #formatPct(Double, Long)} below a hundred,
	 * and shorter above it, because the face's column is 54 px at a 15 px bold face and "+100.0%" measures 58 -
	 * a minus is narrower than a plus, so "-100.0%" (54) held whole while every RISE of a hundred percent or
	 * more was cut to "+157..." (the user's Elemental shield, 2026-09-24). Whole percents from 100 ("+157%",
	 * "+9999%" is 54), thousands from 10,000 ("+12k%", "+999k%"), millions from a million ("+1m%") and
	 * billions after that - every one truncated toward zero, as the one-decimal form is, and every one inside the
	 * column. The sign is the gp change's, as in {@link #formatPct}. The exact one-decimal figure is still in
	 * the block a row opens into, which uses {@link #formatPct} directly.
	 *
	 * @param pct     the move in percent, or null / non-finite for {@link #DASH}
	 * @param deltaGp the gp change the percentage was computed from; null takes the sign from {@code pct}
	 */
	public static String formatPctCompact(@Nullable final Double pct, @Nullable final Long deltaGp)
	{
		if (pct == null || !Double.isFinite(pct))
		{
			return DASH;
		}

		final double size = Math.abs(pct);
		if (size < 100d)
		{
			return formatPct(pct, deltaGp);
		}

		// Whole units of 1, 1,000, 1,000,000 or 1,000,000,000 percent, truncated toward zero like the decimal
		// form: the face never prints a move larger than it is.
		final String digits;
		if (size < 10_000d)
		{
			digits = Long.toString((long) size);
		}
		else if (size < 1_000_000d)
		{
			digits = (long) (size / 1_000d) + "k";
		}
		else if (size < 1_000_000_000d)
		{
			digits = (long) (size / 1_000_000d) + "m";
		}
		else
		{
			digits = (long) (size / 1_000_000_000d) + "b";
		}
		return signedPct(digits, pct, deltaGp);
	}

	/** {@code digits} with a percent sign and the sign of {@code deltaGp} (or of {@code pct} without one), L2. */
	private static String signedPct(final String digits, final double pct, @Nullable final Long deltaGp)
	{
		final int sign = deltaGp != null ? Long.signum(deltaGp) : signum(pct);
		if (sign > 0)
		{
			return "+" + digits + "%";
		}

		if (sign < 0)
		{
			return "-" + digits + "%";
		}

		return digits + "%";
	}

	/**
	 * The sign of a double as -1, 0 or 1, with negative zero counted as zero - {@code Math.signum} answers
	 * {@code -0.0} for it, which would print a minus in front of an unmoved row.
	 */
	private static int signum(final double value)
	{
		if (value > 0.0d)
		{
			return 1;
		}

		return value < 0.0d ? -1 : 0;
	}

	/**
	 * A timestamp as the header's "Prices HH:mm" clock, in the viewer's own zone (contract C10).
	 *
	 * @param millis epoch millis; 0 or less - the "never fetched" reading of every timestamp in this plugin -
	 *               gives {@link #DASH} rather than 1970
	 */
	public static String formatTime(final long millis)
	{
		if (millis <= 0L)
		{
			return DASH;
		}

		return CLOCK.format(Instant.ofEpochMilli(millis).atZone(ZoneId.systemDefault()));
	}

	/**
	 * A guide-price DAY as the status line and every row tooltip stamp it - "07 Sep" (addendum L, L7).
	 *
	 * <p>This is what a baseline is labelled with since addendum L; addendum K's {@code formatDayTime} - a local
	 * "07 Sep 19:55" built from the wiki revision's publication clock - went with the label it printed, so no
	 * caller can reach for a zone-shifted day by mistake (removed by the checker, 2026-09-09). The
	 * series steps ONCE A DAY at a variable UTC hour (L-A: the Jagex rollover was observed between 00:47 and
	 * 02:06 UTC, not at midnight) and the wiki's bot republishes it at a random hour of that day (02:11-22:20 UTC,
	 * L-C), so the publication CLOCK says nothing about which day's prices are in the table - the table's own
	 * {@code %LAST_UPDATE%} does (L-E), and that is a date. Printing a clock beside it invited exactly the
	 * misreading addendum L exists to end.
	 *
	 * <p>The date is printed as it stands, in no zone at all: it was derived in UTC (L9), and re-interpreting it
	 * in the viewer's zone would name the wrong day for anyone west of Greenwich.
	 *
	 * @param day the UTC calendar date; null - no baseline day known yet - gives {@link #DASH}
	 */
	public static String formatDay(@Nullable final LocalDate day)
	{
		if (day == null)
		{
			return DASH;
		}

		return DAY.format(day);
	}

	/**
	 * A guide TABLE's time - "06 Oct 21:35 UTC" - as the open row block and the card's hover print it beside the day
	 * (contract 1.1.2). Since 30 Sep 2026 the wiki saves Jagex's table about eight times a day, so a date no longer
	 * names one table and the time is what tells two of them apart. The day is {@link #formatDay}'s, the UTC date of
	 * the same instant, and the clock is in UTC too and SAYS so: printed bare beside a UTC date it would read as the
	 * viewer's own clock, which is the misreading the paragraph above warns of.
	 *
	 * @param seconds the table's own {@code %LAST_UPDATE%}, unix seconds; 0 or less gives {@link #DASH}
	 */
	public static String formatTableTime(final long seconds)
	{
		if (seconds <= 0L)
		{
			return DASH;
		}

		final OffsetDateTime at = Instant.ofEpochSecond(seconds).atOffset(ZoneOffset.UTC);
		return DAY.format(at) + " " + CLOCK.format(at) + " UTC";
	}

	/**
	 * A trade's time of day - "14:02 UTC" (contract 1.2.0, L5: the open block's "last sold 1,250 at 14:02 UTC"). In UTC and
	 * SAYING so, for the reason {@link #formatTableTime} gives: the dates beside it are UTC dates, and a bare clock would
	 * read as the viewer's own.
	 *
	 * @param seconds the print's own time, unix seconds; 0 or less gives {@link #DASH}
	 */
	public static String formatUtcClock(final long seconds)
	{
		if (seconds <= 0L)
		{
			return DASH;
		}

		return CLOCK.format(Instant.ofEpochSecond(seconds).atOffset(ZoneOffset.UTC)) + " UTC";
	}

	/**
	 * The hero card's baseline phrase - "since 08 Sep" (addendum N sections 3.1 and 4.4, the sub-line under
	 * the bank total and the Ticker card's provenance footnote).
	 *
	 * <p>Its whole job is the null. {@code " since " + formatDay(null)} would read "since -", a sentence
	 * that claims a baseline and then fails to name it; a card with no baseline day shows the one
	 * {@link #DASH} the rest of the panel shows instead, and the problem row says why (N 3.6).
	 *
	 * @param day the baseline's UTC calendar date; null - no baseline settled - gives {@link #DASH}
	 */
	public static String formatSince(@Nullable final LocalDate day)
	{
		return day == null ? DASH : "since " + formatDay(day);
	}

	/**
	 * Lower-cases a trailing K/M/B so a stack size reads as a price.
	 */
	private static String lowerSuffix(final String text)
	{
		final int last = text.length() - 1;
		if (last >= 0 && Character.isLetter(text.charAt(last)))
		{
			return text.substring(0, last) + Character.toLowerCase(text.charAt(last));
		}

		return text;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * One line of the sidebar: a bank stack with its guide price now, its guide price at the baseline revision,
 * and the move between them (contract C6, sources per addendum K line K6). Immutable, because a row list is
 * computed on the service's executor and then handed to the EDT to draw - a value the panel can hold without
 * a lock.
 *
 * <p>Every price is a nullable {@link Long} rather than a primitive, and that is the whole point of the class:
 * "no price" and "price of zero" are different answers. A bank item whose name is in neither the wiki's
 * id-to-name table nor the guide table has no baseline, so a null {@link #thenPrice()} is ordinary, renders as
 * "-" and sorts LAST under every sort (design D6, contract C9).
 *
 * <p>Since addendum Y line Y3 a row is not only the bank's: with "Include inventory and worn gear" on, one row
 * carries the whole of what the player owns of that item - {@link #quantity()} is the bank's, the inventory's and
 * the worn gear's added - and {@link #bankQuantity()}, {@link #inventoryQuantity()} and {@link #wornQuantity()} say
 * where it is, for the one hover line that names the parts ("3 in bank, 1 in inventory, 1 worn"). All three are 0
 * with the switch off, which is what makes such a row byte-identical to the pre-Y one. Since 1.0.9 part 3 the row
 * can hold a fourth part, the items in the player's Grand Exchange offers ({@link #exchangeQuantity()}, "2 in the
 * Grand Exchange"), added into {@link #quantity()} while "Include Grand Exchange offers" is on and 0 otherwise.
 *
 * <p>{@link #deltaGp()} and {@link #deltaPct()} are set together or not at all, and only for a GUIDE row with
 * both ends present (contract C8 as rewritten by K13) - or, since addendum R, for a {@link PriceSource#PARTS} row,
 * whose two ends are the same two sums over the same guide series: both ends are then the same Jagex series -
 * RuneLite's copy of the guide table now, the wiki's copy of it at the baseline revision - so the difference is
 * exactly the "today" figure the GE web site shows.
 */
public final class MovementRow
{
	/**
	 * Where {@link MovementRow#unitPrice()} came from, which the row shows so a reader always knows which
	 * series a number belongs to.
	 */
	public enum PriceSource
	{
		/**
		 * The Jagex Grand Exchange GUIDE price - every priced row since addendum K. Normally RuneLite's own table
		 * ({@code ItemManager.getItemPriceWithSource(id, false)}, K1); for the handful of ids RuneLite rewrites
		 * through {@code ItemMapping} - Black mask (10), Ring of wealth (5), the two Crystal 2h axes - and for
		 * L3's degraded mode, the newest guide TABLE from the wiki instead, which is the same Jagex series
		 * (see {@code PriceService}'s class javadoc). Either way it is the guide price of THIS item.
		 */
		GUIDE,
		/**
		 * A price from the OSRS Wiki's TRADED series - since contract 1.2.0 (L4) the graded figure's mark: yesterday's
		 * two-sided average moved by the last 24 hours' same-side move ({@link GradedMove#price()}) - or, for a figure
		 * reported on one side only, that side's own price - or yesterday's average when nothing traded in the last 24
		 * hours - for a stack with a 1d figure while the {@code livePrices} switch was on. Addendum T's
		 * five liquidity checks no longer decide this; how far the figure can be trusted is its {@link Grade}
		 * ({@link MovementRow#graded()}).
		 *
		 * <p>A different series from {@link #GUIDE}, and the only one in this plugin that moves between two Jagex
		 * days. A LIVE row paints exactly as a GUIDE row does (T6) and carries a real {@link MovementRow#thenPrice()},
		 * {@link MovementRow#deltaGp()} and {@link MovementRow#deltaPct()}; which SERIES the two ends of a given
		 * window came from is {@link MovementRow#windowSource(MovementWindow)}, because a window whose traded bucket
		 * is missing or thin falls back to the guide's own two ends (T4) while the row still prints the live unit
		 * price. Everything a reader needs to see why - the two sides, yesterday's volume, or the check that
		 * refused - is on {@link MovementRow#liveFacts()}.
		 *
		 * <p>Never produced while the switch is off: that is exactly the guide-only behaviour of addenda K to S.
		 */
		LIVE,
		/**
		 * The item's HIGH ALCHEMY value ({@code ItemComposition.getHaPrice()}, carried on the stack as
		 * {@link BankItem#haPrice}) - the only price an item the Grand Exchange does not list has (addendum Q,
		 * line Q5). Produced whatever "Include alch-only untradeables" says since 1.1.0 part G - the switch now decides only
		 * whether the stack is in the bank value; the list shows the row by its own tick - and never with a
		 * baseline: an alch value is a constant of the item, not a series, so such a row has no
		 * {@link MovementRow#thenPrice()}, {@link MovementRow#deltaGp()} or {@link MovementRow#deltaPct()} and the
		 * panel prints a small grey "alch" tag where the move would go.
		 */
		ALCH,
		/**
		 * The sum of what the item's TRADEABLE PARTS are worth at the guide prices - three Crystal armour seeds for
		 * a Crystal body, marks of grace for a graceful piece - as RuneLite's {@code ItemMapping} names them
		 * (addendum R, lines R1 and R2; the parts themselves are on {@link MovementRow#parts()}).
		 *
		 * <p>A guide price like any other, only summed: every part's "now" comes from the same rule a
		 * {@link #GUIDE} row's does and every part's "then" from the same baseline, so such a row carries a real
		 * {@link MovementRow#thenPrice()}, {@link MovementRow#deltaGp()} and {@link MovementRow#deltaPct()} and is
		 * painted exactly as a GUIDE row is (R4). The "then" is null - the dash - when ANY part has no baseline
		 * value, because a sum of some of the parts is not the item's price. Produced whatever the switches say since
		 * addendum AV, only for a stack whose every part could be priced; one that could not falls to {@link #ALCH}.
		 */
		PARTS,
		/**
		 * The OSRS Wiki real-time {@code /latest} mid. Legacy (pre-addendum-K): the service no longer produces
		 * it; kept while the panel and the bridge of the first build still name it (K6 lets it go once nothing
		 * references it).
		 */
		WIKI,
		/**
		 * {@code ItemManager.getItemPrice} as a FALLBACK with no history behind it. Legacy (pre-addendum-K):
		 * only {@code MovementMath.row}'s fallback parameter can still produce it, and the service passes 0 there
		 * since K1 made RuneLite's price the primary series.
		 */
		RUNELITE,
		/**
		 * No price at all.
		 */
		NONE
	}

	/**
	 * What a row can say about the TRADED series (addendum T, lines T3 and T6, with addendum V's two extra
	 * checks), carried only while the
	 * {@code livePrices} switch is on and null on every row computed without it - which is what keeps a row built
	 * with the switch off byte-identical to the pre-T one.
	 *
	 * <p>Two shapes, told apart by {@link #live()}:
	 * <ul>
	 * <li>a LIVE row: {@link #reason()} null, and the two sides and yesterday's volume behind the price the row is
	 * printing - the tooltip's "Live traded price: 63,437,264 gp (buy 63.6m, sell 63.3m; 517 traded yesterday)";</li>
	 * <li>a row that stayed on the guide: {@link #reason()} is why - since contract 1.2.0 the 1d grade's word, which
	 * for a row priced at the guide is "no trades" ({@link GradeWords#NO_TRADES}); before it, the first of addendum T's
	 * five checks that refused it. The sides and the volume are whatever WAS known.</li>
	 * </ul>
	 *
	 * <p>Immutable, like the row that holds it.
	 */
	public static final class LiveFacts
	{
		@Nullable
		private final Long buy;
		@Nullable
		private final Long sell;
		private final long volumeYesterday;
		@Nullable
		private final String reason;

		/**
		 * @param buy             the newest instant-buy price from {@code /latest}, or null when there was none
		 * @param sell            the newest instant-sell price, or null
		 * @param volumeYesterday units traded in yesterday's bulk bucket, both sides; 0 when none or unknown
		 * @param reason          why the live price was NOT used, or null for a live row
		 */
		public LiveFacts(@Nullable final Long buy, @Nullable final Long sell, final long volumeYesterday,
			@Nullable final String reason)
		{
			this.buy = buy;
			this.sell = sell;
			this.volumeYesterday = Math.max(0L, volumeYesterday);
			this.reason = reason;
		}

		/** The newest instant-buy price ({@code high}), or null when the feed had none for this item. */
		@Nullable
		public Long buy()
		{
			return buy;
		}

		/** The newest instant-sell price ({@code low}), or null. */
		@Nullable
		public Long sell()
		{
			return sell;
		}

		/** Units traded in yesterday's bulk bucket, both sides added; 0 when the bucket named none. */
		public long volumeYesterday()
		{
			return volumeYesterday;
		}

		/** Why the live price was not used, one short phrase; null exactly when the row IS live. */
		@Nullable
		public String reason()
		{
			return reason;
		}

		/** True when this row's unit price is the live traded mid - equivalently, when {@link #reason()} is null. */
		public boolean live()
		{
			return reason == null;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof LiveFacts))
			{
				return false;
			}
			final LiveFacts other = (LiveFacts) o;
			return Objects.equals(buy, other.buy)
				&& Objects.equals(sell, other.sell)
				&& volumeYesterday == other.volumeYesterday
				&& Objects.equals(reason, other.reason);
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(buy, sell, volumeYesterday, reason);
		}

		@Override
		public String toString()
		{
			return "LiveFacts{buy=" + buy + ", sell=" + sell + ", volumeYesterday=" + volumeYesterday
				+ (reason == null ? ", live" : ", reason='" + reason + '\'') + '}';
		}
	}

