 * Discord mark beside the settings icon - and the settings menu's header, the plugin's name and build over a row of
 * four brand marks (Discord, X, the 2hBuilds GitHub profile and this plugin's own GitHub page). The one place any of it
 * is drawn, and the one place its links are written.
 *
 * <p><b>Written to be copied.</b> This file is the same in every 2hBuilds plugin, with nothing changed but its
 * {@code package} line: it names no class of the plugin it sits in - no panel, no widget helper, no version class,
 * no config - only RuneLite's own ({@link ColorScheme}, {@link FontManager}, {@link ImageUtil}) and the JDK's. What a
 * plugin has to say about itself comes in through the constructor: the name it is shown under, its build, its own
 * GitHub page, what opens a link ({@link net.runelite.client.util.LinkBrowser#browse} in the client, a recorder in
 * a test) and what takes the settings menu down after a link has been pressed. The four mark files are the
 * brands' own, white on transparent and never redrawn, in the resource folder of the copy's package
 * ({@link #markIcon} loads them beside this class).
 *
 * <p>Every hover here is ONE word (or a few) and is always on: an icon with no text beside it has nothing else on
 * the screen to say what it is, so it names itself whatever a plugin's "Show hover text" switch says. The hovers are
 * set on the labels directly and are never offered to a switch.
 */
final class SupportLinks
{
	/** Where the Discord mark goes: the 2hBuilds Discord server, opened through the browser hook. */
	static final String DISCORD_URL = "https://discord.gg/nsam4CfWzf";
	/** Where the X mark goes: the 2hBuilds account. */
	static final String X_URL = "https://x.com/2hBuilds";
	/** Where the first GitHub mark goes: the 2hBuilds profile. */
	static final String GITHUB_PROFILE_URL = "https://github.com/2hBuilds";

	/** The settings icon's hover: one word, because the menu under it says the rest. */
	static final String SETTINGS_TIP = "Settings";
	/** The Discord mark's hover: one word. */
	static final String DISCORD_TIP = "Discord";
	/** The X mark's hover in the menu's header: one word. */
	static final String X_TIP = "X";
	/** The first GitHub mark's hover in the menu's header: the 2hBuilds profile. */
	static final String GITHUB_PROFILE_TIP = "2hBuilds on GitHub";
	/** The second GitHub mark's hover in the menu's header: the plugin's own page. */
	static final String GITHUB_TIP = "This plugin on GitHub";

	/** The brand marks' files, in the resource folder of this class's package; see {@link #markIcon}. */
	static final String DISCORD_12 = "discord_12.png";
	static final String DISCORD_16 = "discord_16.png";
	static final String X_16 = "x_16.png";
	static final String GITHUB_16 = "github_16.png";

	/** The gap between the Discord mark and the settings icon on a card, in px. */
	static final int PAIR_GAP = 8;
	/** The gap between two marks in the menu's header row, in px; the marks themselves are 16 px files. */
	static final int LINK_GAP = 6;
	/**
	 * The alpha a brand's mark rests at: 165 of 255, so a white mark reads as the grey 165 the settings icon and the
	 * captions are drawn in ({@link ColorScheme#LIGHT_GRAY_COLOR}).
	 */
	static final float MARK_REST_ALPHA = 165f / 255f;
	/**
	 * The header's version line's grey: a shade darker than the captions' {@link ColorScheme#LIGHT_GRAY_COLOR} (165),
	 * still about 4.6 : 1 against the menu's ground.
	 */
	static final Color HEADER_GREY = new Color(135, 135, 135);
	/** The header's title face: bold, one size up from the menu's 12 px. */
	static final int HEADER_TITLE_SIZE = 13;
	/**
	 * The part of a display name drawn in the brand orange, when the name opens with it and a space: the 2hBuilds mark,
	 * as on the sidebar icon. A name without it is drawn whole in white.
	 */
	static final String FAMILY_MARK = "2h";
	/** The menu's own type size, the version line's. */
	static final int MENU_FONT_SIZE = 12;

	/**
	 * The sidebar's 6 px: the header's left and right padding - the column the captions under it start at - and the
	 * hit area an icon buys on the side the pointer arrives from. {@link #iconBorder} is where the second is written.
	 */
	private static final int INSET = 6;

	/** The marks already loaded, by file name: each PNG is read once (see {@link #markIcon}). */
	private static final Map<String, BufferedImage> MARKS = new ConcurrentHashMap<>();

	private final String displayName;
	private final String version;
	private final String pluginGitHubUrl;
	private final Consumer<String> browser;
	private final Runnable closeMenu;

	/**
	 * @param displayName     the name the plugin is shown under, e.g. "2h Bank Portfolio Tracker"
	 * @param version         the plugin's build, e.g. "1.0.9"; printed as "Version 1.0.9"
	 * @param pluginGitHubUrl the plugin's own repository page, what the fourth mark opens
	 * @param browser         what a pressed mark hands its URL to: RuneLite's {@code LinkBrowser::browse} in the client
	 * @param closeMenu       what takes the settings menu down once a header mark has been pressed, as OK does
	 */
	SupportLinks(String displayName, String version, String pluginGitHubUrl, Consumer<String> browser,
		Runnable closeMenu)
	{
		this.displayName = Objects.requireNonNull(displayName, "displayName");
		this.version = Objects.requireNonNull(version, "version");
		this.pluginGitHubUrl = Objects.requireNonNull(pluginGitHubUrl, "pluginGitHubUrl");
		this.browser = Objects.requireNonNull(browser, "browser");
		this.closeMenu = Objects.requireNonNull(closeMenu, "closeMenu");
	}

	/**
	 * The support pair, the top-right corner of a card: the Discord mark, {@link #PAIR_GAP} px of clear ground, then
	 * {@code settingsIcon} - the settings icon is the right-most thing. The gap is measured between the two ink boxes,
	 * so the strip between the labels is {@link #PAIR_GAP} less the 6 px inset the settings icon carries on its left
	 * ({@link #iconBorder}).
	 *
	 * <p>The pair is as tall as the icons with their 2 px insets, 16 px, and exactly as wide as the two labels and the
	 * strip between them, so a bar that holds it at its east end gives it no more room than that.
	 *
	 * @param settingsIcon the plugin's settings icon, a label carrying {@link #iconBorder}
	 */
	JPanel supportPair(JLabel settingsIcon)
	{
		final JLabel discord = discordMark();
		final JPanel pair = new JPanel();
		pair.setLayout(new BoxLayout(pair, BoxLayout.X_AXIS));
		pair.setOpaque(false);
		pair.add(discord);
		pair.add(Box.createHorizontalStrut(PAIR_GAP - INSET));
		pair.add(settingsIcon);
		final int width = discord.getPreferredSize().width + PAIR_GAP - INSET + settingsIcon.getPreferredSize().width;
		final int height = Math.max(discord.getPreferredSize().height, settingsIcon.getPreferredSize().height);
		pair.setPreferredSize(new Dimension(width, height));
		return pair;
	}

	/**
	 * The Discord mark beside the settings icon: 12 px, with the settings icon's own insets ({@link #iconBorder}), so
	 * the two read as a pair and each has the same 6 px of hit area on the side the pointer arrives from.
	 */
	JLabel discordMark()
	{
		final JLabel mark = brandMark(DISCORD_12, DISCORD_TIP, DISCORD_URL);
		mark.setBorder(iconBorder());
		return mark;
	}

	/**
	 * The settings menu's header: the title line - the family mark in the brand orange and the rest of the display name
	 * in white, both bold at {@link #HEADER_TITLE_SIZE} px, two labels side by side because one label has one colour;
	 * a name that does not open with {@link #FAMILY_MARK} and a space is one white label - over "Version" and the
	 * build in {@link #HEADER_GREY} at the menu's own {@link #MENU_FONT_SIZE} px, over the links row: four 16 px brand
	 * marks, {@link #LINK_GAP} px apart, the Discord mark, the X mark, the GitHub mark for the 2hBuilds profile and the
	 * same GitHub mark for this plugin's own page. Every line at the header's left edge, like the captions below it,
	 * with no hover but the marks' and no click but theirs.
	 *
	 * <p>The two GitHub marks are identical on purpose; only their hovers tell them apart. A press on a mark hands
	 * its URL to the browser and then takes the menu down, the way OK does: a reader who has clicked a link has
	 * finished with the menu. The header is ONE panel, so a menu that holds it counts it as one component.
	 */
	JPanel header()
	{
		final JPanel row = new JPanel(new DynamicGridLayout(0, 1, 0, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(2, INSET, 2, INSET));
		row.add(titleRow());
		final JLabel versionLine = label("Version " + version, sans(MENU_FONT_SIZE), HEADER_GREY);
		versionLine.setHorizontalAlignment(SwingConstants.LEFT);
		versionLine.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.add(versionLine);
		row.add(linksRow());
		return row;
	}

	/** The header's title line, see {@link #header}. */
	private JPanel titleRow()
	{
		final JPanel title = new JPanel();
		title.setLayout(new BoxLayout(title, BoxLayout.X_AXIS));
		title.setOpaque(false);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (displayName.startsWith(FAMILY_MARK + " "))
		{
			title.add(label(FAMILY_MARK, sansBold(HEADER_TITLE_SIZE), ColorScheme.BRAND_ORANGE));
			title.add(label(displayName.substring(FAMILY_MARK.length()), sansBold(HEADER_TITLE_SIZE), Color.WHITE));
		}
		else
		{
			title.add(label(displayName, sansBold(HEADER_TITLE_SIZE), Color.WHITE));
		}
		title.add(Box.createHorizontalGlue());
		return title;
	}

	/** The header's links row, see {@link #header}: 2 px of air over it and the marks from the left edge. */
	private JPanel linksRow()
	{
		final JPanel links = new JPanel();
		links.setLayout(new BoxLayout(links, BoxLayout.X_AXIS));
		links.setOpaque(false);
		links.setAlignmentX(Component.LEFT_ALIGNMENT);
		links.setBorder(new EmptyBorder(2, 0, 0, 0));
		addLink(links, DISCORD_16, DISCORD_TIP, DISCORD_URL, false);
		addLink(links, X_16, X_TIP, X_URL, true);
		addLink(links, GITHUB_16, GITHUB_PROFILE_TIP, GITHUB_PROFILE_URL, true);
		addLink(links, GITHUB_16, GITHUB_TIP, pluginGitHubUrl, true);
		links.add(Box.createHorizontalGlue());
		return links;
	}

	/** One mark of {@link #linksRow}, after {@link #LINK_GAP} px of clear ground unless it is the first. */
	private void addLink(JPanel links, String resource, String name, String url, boolean gapBefore)
	{
		final JLabel mark = namedIconButton(markIcon(resource, MARK_REST_ALPHA), markIcon(resource, 1f), name, () ->
		{
			browser.accept(url);
			closeMenu.run();
		});
		if (gapBefore)
		{
			links.add(Box.createHorizontalStrut(LINK_GAP));
		}
		links.add(mark);
	}

	/**
	 * One brand mark: {@code resource} at the settings icon's grey by alpha at rest ({@link #MARK_REST_ALPHA}) and at
	 * full white under the mouse, {@code name} for an always-on hover, and a LEFT press hands {@code url} to the
	 * browser.
	 */
	private JLabel brandMark(String resource, String name, String url)
	{
		return namedIconButton(markIcon(resource, MARK_REST_ALPHA), markIcon(resource, 1f), name,
			() -> browser.accept(url));
	}

	/**
	 * The border a card's settings icon and the Discord mark beside it share: 2 px above and below and, on the
	 * left, the 6 px of hit area on the side the pointer arrives from - a 12 px glyph is a 12 px target otherwise,
	 * and a settings button is not a decoration.
	 */
	static Border iconBorder()
	{
		return new EmptyBorder(2, INSET, 2, 0);
	}

	/**
	 * An icon-only control that names itself: {@link #pressable}'s look and press, with a ONE-WORD hover that is
	 * always on. The word is set on the label directly and is never offered to a "Show hover text" switch, so the
	 * exemption is in how the label is made, not in a special case where a switch is applied.
	 */
	static JLabel namedIconButton(ImageIcon rest, ImageIcon hot, String name, Runnable onClick)
	{
		final JLabel label = pressable(rest, hot, onClick);
		label.setToolTipText(name);
		return label;
	}

	/**
	 * The look and the press of an icon button, with no hover yet: {@code rest} at rest, {@code hot} while the mouse is
	 * over it, a hand cursor, and a LEFT press runs {@code onClick} - a right-button press is a menu gesture
	 * everywhere in a sidebar, never a press, and so is a ctrl-click of the left button on macOS.
	 */
	static JLabel pressable(ImageIcon rest, ImageIcon hot, Runnable onClick)
	{
		final JLabel label = new JLabel(rest);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && !e.isPopupTrigger())
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setIcon(hot);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setIcon(rest);
			}
		});
		return label;
	}

	/**
	 * A brand's own mark, loaded from the classpath and never redrawn: the Discord symbol, the X logo and GitHub's
	 * Invertocat are white on transparent PNGs in this package's resource folder, resized and nothing else, because
	 * the brands allow white and none allows a mark drawn by somebody else. Loaded with RuneLite's
	 * {@link ImageUtil#loadImageResource} - the ordinary plugin way; a classpath resource is not file I/O - and each
	 * file ONCE, however many icons are made from it.
	 *
	 * <p>The look is chosen by {@code alpha}, never by recolouring: at 1 the mark is the file as it is (white), and
	 * below 1 {@link ImageUtil#alphaOffset(java.awt.Image, float)} scales only the alpha, so a white mark at
	 * {@link #MARK_REST_ALPHA} reads on the card as the settings icon's grey.
	 *
	 * @param resource a file name in this class's package's resource folder, e.g. {@code "discord_12.png"}
	 * @param alpha    1 for the mark at full white, less for it fainter
	 */
	static ImageIcon markIcon(String resource, float alpha)
	{
		final BufferedImage mark = MARKS.computeIfAbsent(resource,
			r -> ImageUtil.loadImageResource(SupportLinks.class, r));
		return new ImageIcon(alpha >= 1f ? mark : ImageUtil.alphaOffset(mark, alpha));
	}

	/** The Swing sans at {@code size} px: RuneLite's default font, derived, so the shared constant is never mutated. */
	private static Font sans(int size)
	{
		return FontManager.getDefaultFont().deriveFont((float) size);
	}

	/** The bold Swing sans at {@code size} px. */
	private static Font sansBold(int size)
	{
		return FontManager.getDefaultBoldFont().deriveFont((float) size);
	}

	/** A label with its font and colour set explicitly, never left to the look and feel. */
	private static JLabel label(String text, Font font, Color colour)
	{
		final JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(colour);
		return label;
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Insets;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import javax.swing.DefaultButtonModel;
import javax.swing.JCheckBoxMenuItem;
import javax.swing.JComponent;
import javax.swing.event.MenuDragMouseEvent;

/**
 * One of the settings menu's rows that carries a swatch of a colour at its right end (1.1.0): "Up colour", "Down colour"
 * and "Single chart colour". All three are {@link JCheckBoxMenuItem}s, because the look and feel lays a check item's
 * words out in the menu's own check column - the column every tick in the menu sits in - and a row that is not one
 * stands its words about 4 px to the left of it, whatever blank icon it is handed (found under RuneLite's look and feel,
 * 1.1.0 part C: the two colour rows of part B read left of the Include items around them).
 *
 * <p><b>Two kinds.</b> A colour row ({@code ticks} false) is a way into the colour picker and not a switch: its model
 * never selects, so no tick is ever drawn and no press can leave one behind, and a press ANYWHERE on it - words, gap or
 * swatch - is its action (Swing takes the menu down and fires the action listener). "Single chart colour" ({@code ticks}
 * true) is an ordinary check item whose swatch shows only while it is ticked, and there a press on the swatch opens the
 * picker ({@code onSwatch}) while a press anywhere else on the row ticks or unticks it as any check item does.
 *
 * <p><b>Telling the two presses apart.</b> Swing hands a menu item its click through {@link #doClick} with no position,
 * from either of its two mouse roads (the plain mouse event, and the menu-drag event the popup's own grabber builds), so
 * the row notes where the pointer last was from both and reads that when the click comes. The note is dropped on exit and
 * after every click, so a key press on the row (which has no pointer) always ticks.
 */
final class SwatchRow extends JCheckBoxMenuItem
{
	/** The gap a row keeps between its words and its swatch, at the least, in px. */
	private static final int SWATCH_GAP = 8;
	/** The swatch's 1 px frame: grey 110, so a swatch as dark as the menu still reads as a box. */
	private static final Color SWATCH_BORDER = new Color(110, 110, 110);

	private final Supplier<Color> colour;
	private final boolean ticks;
	@Nullable
	private final Runnable onSwatch;
	/** Where the pointer last was over this row, in its own coordinates; null when it has left or just clicked. */
	@Nullable
	private Point pointer;

	/**
	 * @param colour   the swatch's colour, asked at every paint
	 * @param ticks    true for a check item (swatch only while ticked), false for a colour row that never selects
	 * @param onSwatch what a press on a ticked check item's swatch does instead of ticking it; null for none
	 */
	SwatchRow(String text, Supplier<Color> colour, boolean ticks, @Nullable Runnable onSwatch)
	{
		super(text);
		this.colour = colour;
		this.ticks = ticks;
		this.onSwatch = onSwatch;
		if (!ticks)
		{
			setModel(new NeverSelected());
		}
		setFont(Widgets.sans(12));
	}

	/**
	 * A button model that cannot be selected: the colour rows' - a press fires the action and leaves no tick. The colour
	 * preset rows ({@link SetRow}) share this class's way of standing in the check items' column.
	 */
	static final class NeverSelected extends DefaultButtonModel
	{
		@Override
		public void setSelected(boolean selected)
		{
		}
	}

	/** Whether the swatch is drawn: always for a colour row, only while ticked for a check item. */
	private boolean swatchShown()
	{
		return !ticks || isSelected();
	}

	/** The swatch, 24 x 12, inset from the row's right as the menu's captions are and centred between its insets. */
	private Rectangle swatch()
	{
		return swatchBounds(this);
	}

	/**
	 * The swatch's place in a swatch row ({@code row}'s own size and insets): 24 x 12, {@link BankPriceMovementPanel#ROW_GAP}
	 * in from the row's right end as the menu's captions are, and centred between the row's insets. One rule for the rows
	 * of this class and the colour preset rows ({@link SetRow}), so every swatch in the menu ends on the same column.
	 */
	static Rectangle swatchBounds(JComponent row)
	{
		final Insets in = row.getInsets();
		final int x = row.getWidth() - BankPriceMovementPanel.ROW_GAP - BankPriceMovementPanel.SWATCH_WIDTH;
		final int y = in.top + (row.getHeight() - in.top - in.bottom - BankPriceMovementPanel.SWATCH_HEIGHT) / 2;
		return new Rectangle(x, y, BankPriceMovementPanel.SWATCH_WIDTH, BankPriceMovementPanel.SWATCH_HEIGHT);
	}

	/** {@code words}, the look and feel's size for a row's text, widened for the swatch's gap and its width. */
	static Dimension withSwatchRoom(Dimension words)
	{
		return new Dimension(words.width + SWATCH_GAP + BankPriceMovementPanel.SWATCH_WIDTH, words.height);
	}

	/** One box of colour: {@code colour} filled over {@code x, y, w, h} with the swatch's 1 px frame drawn inside it. */
	static void paintBox(Graphics g, int x, int y, int w, int h, Color colour)
	{
		g.setColor(colour);
		g.fillRect(x, y, w, h);
		g.setColor(SWATCH_BORDER);
		g.drawRect(x, y, w - 1, h - 1);
	}

	/** The swatch's end of the row, full height: a press a little beside the swatch is still aimed at it. */
	private boolean overSwatch(@Nullable Point p)
	{
		return p != null && p.x >= swatch().x && p.x < getWidth() && p.y >= 0 && p.y < getHeight();
	}

	/** The look and feel's size for the words, and room for the swatch beside them whether it is drawn or not. */
	@Override
	public Dimension getPreferredSize()
	{
		return withSwatchRoom(super.getPreferredSize());
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (!swatchShown())
		{
			return;
		}
		final Rectangle s = swatch();
		paintBox(g, s.x, s.y, s.width, s.height, colour.get());
	}

	/** A click on a ticked check item's swatch is the swatch's action and ticks nothing; every other click is Swing's. */
	@Override
	public void doClick(int pressTime)
	{
		final Runnable swatchAction = onSwatch;
		final boolean aimed = swatchAction != null && ticks && isSelected() && overSwatch(pointer);
		pointer = null;
		if (aimed)
		{
			swatchAction.run();
			return;
		}
		super.doClick(pressTime);
	}

	@Override
	protected void processMouseEvent(MouseEvent e)
	{
		note(e);
		super.processMouseEvent(e);
	}

	@Override
	public void processMenuDragMouseEvent(MenuDragMouseEvent e)
	{
		note(e);
		super.processMenuDragMouseEvent(e);
	}

	private void note(MouseEvent e)
	{
		pointer = e.getID() == MouseEvent.MOUSE_EXITED ? null : e.getPoint();
	}
}

package com.bankpricemovement;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The TRADED price feeds of addendum T line T2 - the OSRS Wiki's real-time prices, which is a different series
 * from the Jagex guide table {@link GuidePriceClient} reads. Since contract 1.2.0 every stack the feeds name is graded
 * from them ({@link GradeMath}): today's prints and the last closed hour against the days' side averages.
 *
 * <p>Three endpoints, and nothing else:
 * <ul>
 * <li>{@value #LATEST_URL} - the newest instant-buy and instant-sell per item, each with the second it was
 * traded at: {@code {"data":{"4151":{"high":1700000,"highTime":1788859512,"low":1690000,"lowTime":1788859480}}}}.
 * Any of the four members may be null (an item nobody has bought, or nobody has sold, since the API's own
 * horizon). Fetched on every accepted Refresh, on the thirty-minute tick and at start-up, and only while the
 * {@code livePrices} switch is on;</li>
 * <li>{@value #DAILY_URL}{@code ?timestamp=<UTC midnight of day D in seconds>} - the BULK daily bucket, one
 * entry per item traded that day: {@code {"data":{"4151":{"avgHighPrice":1699000,"avgLowPrice":1688000,
 * "highPriceVolume":213,"lowPriceVolume":304}},"timestamp":1788825600}}. A price may be null; a volume is 0 when
 * the side saw no trade. Fetched once per UTC day per window, for the day that window counts back to from the
 * live snapshot's own date ({@code liveDay - N}, addendum U line U1), and never for TODAY - the running day
 * answers an empty bucket, and every window is at least one day back. An EMPTY answer for a past day means the
 * wiki has not closed that day yet, and {@code PriceService} then asks once for the day before it (U2);</li>
 * <li>{@value #HOUR_URL}{@code ?timestamp=<the hour's start in UTC seconds>} - one CLOSED hour's bucket, the same
 * shape as a day's with the hour's start in {@code timestamp} (contract 1.2.0, line L1). The hour is always named:
 * the same URL WITHOUT a timestamp is a CDN object regenerated at hh:00:10 that holds the hour starting two hours
 * back (live-checked 2026-10-07), so it is never the latest closed hour. An hour the wiki has not cut yet answers
 * {@code {"data":{},"timestamp":<the one asked for>}} - read as "not yet", not as a failure. Fetched once per closed
 * hour while the sidebar shows (and retried a few minutes later while that answer is empty), and never while it is
 * hidden or the switch is off.</li>
 * </ul>
 *
 * <p><b>Why this is a second client and not three more methods on {@link GuidePriceClient}.</b> That class is
 * the GUIDE series - one host, one page, one set of failure shapes, and a class comment that promises every
 * printed figure comes from Jagex's daily table. The traded series answers a different question (what someone
 * actually paid, minutes ago), has its own hosts and its own fail gate, and is switched off entirely by one
 * config item. Keeping them apart is what makes "the switch off is byte-identical to today" a property of the
 * wiring rather than a promise about branches.
 *
 * <p><b>What leaves the client, exactly.</b> As with {@link GuidePriceClient}, neither URL carries anything
 * derived from the player: {@link #latestUrl()} is a bare GET, and {@link #dayUrl(LocalDate)} carries one UTC
 * midnight the plugin computed from a date it derived itself. No item id, no quantity, no account. Every user
 * of this plugin issues byte-identical requests, and the hosts learn only an IP and that the plugin is
 * installed. {@code theRequestUrlsCarryNothingDerivedFromThePlayer} in the tests keeps that true.
 *
 * <p><b>Why the client and the Gson are injected, and why enqueue.</b> Both for the reasons spelled out on
 * {@link GuidePriceClient}: RuneLite's {@code @Provides OkHttpClient} is the only one whose requests carry a
 * usable User-Agent and transparent gzip, constructing an OkHttpClient or a Gson in plugin code is a Plugin Hub
 * packaging blocker, and {@code RuneLiteModule} throws for a blocking call made on the client thread or the EDT.
 * The User-Agent string is {@link GuidePriceClient#USER_AGENT} itself rather than a second spelling of it, so an
 * operator reading either wiki host's logs sees one plugin.
 *
 * <p><b>One failure type</b> ({@link WikiPriceException}), exactly as the guide client has: a non-2xx, a body
 * that is not the expected shape, an empty feed and a transport {@code IOException} all complete the future
 * exceptionally, and the future never completes with null. {@code PriceService} keeps whatever it last stored
 * and carries on with the guide prices (T7).
 *
 * <p>This class holds no cache and no schedule: staleness, the six-hour rule and one-in-flight-per-feed are
 * {@code PriceService}'s. Its only state is {@link #setEnabled(boolean)}, the calls still on the wire for
 * {@link #cancelInFlight()}, and the "a failure has already been logged loudly" flag.
 */
public class TradedPriceClient
{
	private static final Logger log = LoggerFactory.getLogger(TradedPriceClient.class);

	/** The newest instant-buy / instant-sell per item (T2 a). */
	public static final String LATEST_URL = "https://prices.runescape.wiki/api/v1/osrs/latest";

	/** The bulk daily bucket (T2 b); one {@code timestamp} parameter names the UTC day. */
	public static final String DAILY_URL = "https://prices.runescape.wiki/api/v1/osrs/24h";

	/** One closed hour's bucket (contract 1.2.0, L1); one {@code timestamp} parameter names the hour's start. */
	public static final String HOUR_URL = "https://prices.runescape.wiki/api/v1/osrs/1h";

	/** The same descriptive User-Agent the guide client sends - one plugin, one string. */
	public static final String USER_AGENT = GuidePriceClient.USER_AGENT;

	/** Header name, spelled once so the request builder and the tests cannot drift apart. */
	public static final String USER_AGENT_HEADER = GuidePriceClient.USER_AGENT_HEADER;

	/** Seconds in a UTC calendar day - what {@link #midnightSeconds(LocalDate)} multiplies by. */
	public static final long SECONDS_PER_DAY = 86_400L;

	/** Error and diagnostic text is cut to this many characters before it reaches a message or the log. */
	private static final int MAX_DETAIL_CHARS = 200;

	private final OkHttpClient client;
	private final Gson gson;

	/**
	 * Developer-mode switch, the twin of {@link GuidePriceClient#setEnabled(boolean)}: when false every fetch
	 * fails immediately without touching the network, so T7's "live prices unavailable" state can be exercised in
	 * a live client. Volatile because it is written from the bridge/EDT and read on whichever thread starts a
	 * fetch. Never flipped by user-facing code.
	 */
	private volatile boolean enabled = true;

	/** Every call enqueued and not yet answered, so {@link #cancelInFlight()} can drop them when the plugin stops. */
	private final List<Call> inFlight = new CopyOnWriteArrayList<>();

	/** Whether {@link #report} has already logged a failure loudly this session. */
	private volatile boolean reported;

	/**
	 * @param client RuneLite's injected OkHttpClient; constructing one here is a Plugin Hub blocker
	 * @param gson   RuneLite's injected Gson, for the same reason
	 */
	public TradedPriceClient(final OkHttpClient client, final Gson gson)
	{
		if (client == null)
		{
			throw new IllegalArgumentException("client is required (inject RuneLite's OkHttpClient)");
		}
		if (gson == null)
		{
			throw new IllegalArgumentException("gson is required (inject RuneLite's Gson)");
		}
		this.client = client;
		this.gson = gson;
	}

	// ---------------------------------------------------------------- the two fetches (T2)

	/**
	 * The newest traded quote per item (T2 a).
	 *
	 * @param nowMillis the caller's clock; not part of the request, but taken so the SERVICE's settable clock -
	 *                  never {@code System.currentTimeMillis()} in here - decides what "six hours old" means (T7)
	 * @return a future completing with item id to {@link Quote}, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<Map<Integer, Quote>> fetchLatest(final long nowMillis)
	{
		log.debug("bank-portfolio-tracker: fetching the traded /latest snapshot at {}", nowMillis);
		return request(latestUrl(), this::parseLatest);
	}

	/**
	 * One whole UTC calendar day's traded bucket (T2 b).
	 *
	 * @param day       the day; must be in the past - the running day answers an empty bucket, and
	 *                  {@code PriceService} never asks for it. Null is refused rather than turned into "today"
	 * @param nowMillis stamped by the caller onto whatever it stores; not part of the request
	 * @return a future completing with item id to {@link Bucket}, or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<Map<Integer, Bucket>> fetchDay(final LocalDate day, final long nowMillis)
	{
		if (day == null)
		{
			// Deliberately a failure and not an empty success: a caller with no day has a bug, and an empty map
			// would look like "that day traded nothing" to the code that stores buckets.
			return failed(new WikiPriceException("no day to fetch a traded bucket for"));
		}
		log.debug("bank-portfolio-tracker: fetching the traded bucket of {} at {}", day, nowMillis);
		return request(dayUrl(day), this::parseDay);
	}

	/**
	 * One CLOSED hour's traded bucket (contract 1.2.0, L1): {@value #HOUR_URL}{@code ?timestamp=<startSeconds>}. The hour
	 * is named because the URL without a timestamp answers the hour two back, not the latest closed one. An hour the wiki
	 * has not cut yet answers an EMPTY {@link PriceStore.TradedHour} (its start, no items) - the caller reads that as "not
	 * yet" and asks again a few minutes later - while a transport or HTTP failure is a failed future.
	 *
	 * @param startSeconds the hour's start, UTC unix seconds; must be positive
	 * @param nowMillis    stamped onto the answer as its fetch time; not part of the request
	 * @return a future completing with the hour (possibly empty), or exceptionally with {@link WikiPriceException}
	 */
	public CompletableFuture<PriceStore.TradedHour> fetchHour(final long startSeconds, final long nowMillis)
	{
		if (startSeconds <= 0L)
		{
			return failed(new WikiPriceException("no hour to fetch a traded bucket for"));
		}
		log.debug("bank-portfolio-tracker: fetching the traded /1h bucket of {} at {}", startSeconds, nowMillis);
		return request(hourUrl(startSeconds), body -> parseHour(body, nowMillis));
	}

	/**
	 * Developer-mode kill switch, the twin of {@link GuidePriceClient#setEnabled(boolean)}; true is the shipped
	 * state. User-facing behaviour must never depend on this (workspace rule: no user feature may need a dev hook).
	 */
	public void setEnabled(final boolean enabled)
	{
		this.enabled = enabled;
	}

	/** @see #setEnabled(boolean) */
	public boolean isEnabled()
	{
		return enabled;
	}

	/**
	 * Cancels every call still on the wire, from {@code PriceService.stop()}. {@code Call.cancel()} is safe from
	 * any thread; a cancelled call's {@code onFailure} completes its future as an ordinary failure.
	 */
	public void cancelInFlight()
	{
		for (final Call call : new ArrayList<>(inFlight))
		{
			inFlight.remove(call);
			try
			{
				call.cancel();
			}
			catch (final RuntimeException e)
			{
				log.debug("bank-portfolio-tracker: a traded-price call refused to cancel", e);
			}
		}
	}

	// ---------------------------------------------------------------- the exact URLs

	/** {@value #LATEST_URL}, with no parameters at all. */
	static String latestUrl()
	{
		return LATEST_URL;
	}

	/**
	 * {@value #HOUR_URL}{@code ?timestamp=<the hour's start, in unix seconds>} (contract 1.2.0, L1) - a number the plugin
	 * derived from its own clock, like {@link #dayUrl}'s, and nothing about the player.
	 */
	static String hourUrl(final long startSeconds)
	{
		return HOUR_URL + "?timestamp=" + startSeconds;
	}

	/**
	 * {@value #DAILY_URL}{@code ?timestamp=<UTC midnight of the day, in seconds>} - the only parameter this
	 * plugin ever sends to either wiki host, and it is a date the plugin derived from the guide tables rather
	 * than anything about the player.
	 */
	static String dayUrl(final LocalDate day)
	{
		return DAILY_URL + "?timestamp=" + midnightSeconds(day);
	}

	/**
	 * The UTC midnight that opens a calendar day, in unix seconds - the {@code timestamp} the bulk endpoint
	 * indexes a day by.
	 *
	 * <p>{@link LocalDate#toEpochDay()} times {@value #SECONDS_PER_DAY} rather than a zoned conversion: every
	 * date in this plugin is already a UTC date (addendum L line L9), and a day here has exactly 86,400 seconds -
	 * there are no leap seconds in unix time and no zone to shift it.
	 */
	static long midnightSeconds(final LocalDate day)
	{
		Objects.requireNonNull(day, "day");
		return day.toEpochDay() * SECONDS_PER_DAY;
	}

	// ---------------------------------------------------------------- parsers (package-private, pure)

	/**
	 * The {@code /latest} body as item id to {@link Quote}. Shape:
	 * {@code {"data":{"2":{"high":193,"highTime":1616682200,"low":186,"lowTime":1616682209}, ...}}}.
	 *
	 * <p>Any of the four members may be null or absent, and an entry with NEITHER price is dropped: it names no
	 * traded price, so nothing downstream could do anything with it but skip it. An id that is not an integer is
	 * skipped rather than thrown, for the same reason the guide parsers skip an odd entry - one bad row must not
	 * cost the other four thousand.
	 *
	 * @throws WikiPriceException on a non-object body, a missing {@code data} object, or a feed with no usable
	 *                            entry in it (a route change, as opposed to one odd item)
	 */
	Map<Integer, Quote> parseLatest(final String json) throws WikiPriceException
	{
		final JsonObject data = dataOf(readObject(json), "latest");
		final Map<Integer, Quote> quotes = new LinkedHashMap<>();
		for (final Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			final Integer id = parseId(entry.getKey());
			final JsonObject value = objectOf(entry.getValue());
			if (id == null || value == null)
			{
				continue;
			}
			final Long high = optLong(value, "high");
			final Long low = optLong(value, "low");
			if (high == null && low == null)
			{
				continue;
			}
			quotes.put(id, new Quote(high, seconds(value, "highTime"), low, seconds(value, "lowTime")));
		}
		if (quotes.isEmpty())
		{
			throw new WikiPriceException("the wiki traded /latest feed carried no prices");
		}
		return quotes;
	}

	/**
	 * A {@code /24h?timestamp=} body as item id to {@link Bucket}. Shape:
	 * {@code {"data":{"2":{"avgHighPrice":190,"avgLowPrice":186,"highPriceVolume":100,"lowPriceVolume":200},
	 * ...},"timestamp":1615766400}}.
	 *
	 * <p>Either price may be null while the volumes stand - an item bought but never sold that day - and that
	 * entry is KEPT, because T3's volume check reads the volumes and T4's own rule reads the price separately.
	 * An entry with no price and no volume names nothing and is dropped.
	 *
	 * @throws WikiPriceException on a non-object body, a missing {@code data} object, or an empty bucket - which
	 *                            is what the RUNNING day answers, and which is why a caller must only ever ask
	 *                            for a day that has closed
	 */
	Map<Integer, Bucket> parseDay(final String json) throws WikiPriceException
	{
		final Map<Integer, Bucket> buckets = bucketsOf(dataOf(readObject(json), "24h"));
		if (buckets.isEmpty())
		{
			throw new WikiPriceException("the wiki traded daily bucket carried no entries");
		}
		return buckets;
	}

	/**
	 * A {@code /1h?timestamp=} body as the hour it is (contract 1.2.0, L1): the same shape as a day's -
	 * {@code {"data":{"2":{"avgHighPrice":190,...}},"timestamp":1615766400}} - with the hour's START in
	 * {@code timestamp}, which this answer needs and a day's does not. An hour the wiki has not cut yet answers
	 * {@code {"data":{},"timestamp":<the one asked for>}}: that is an EMPTY {@link PriceStore.TradedHour} here, not a
	 * failure, because it means "ask again in a few minutes".
	 *
	 * @param fetchedAtMillis stamped onto the hour as its fetch time
	 * @throws WikiPriceException on a non-object body, a missing {@code data} object, or no usable {@code timestamp}
	 */
	PriceStore.TradedHour parseHour(final String json, final long fetchedAtMillis) throws WikiPriceException
	{
		final JsonObject root = readObject(json);
		final Map<Integer, Bucket> buckets = bucketsOf(dataOf(root, "1h"));
		final Long start = optLong(root, "timestamp");
		if (start == null || start <= 0L)
		{
			throw new WikiPriceException("the wiki traded hourly bucket names no hour");
		}
		return new PriceStore.TradedHour(start, buckets, fetchedAtMillis);
	}

	/** The {@code data} object of a day's or an hour's body as item id to {@link Bucket} - the two share a shape. */
	private static Map<Integer, Bucket> bucketsOf(final JsonObject data)
	{
		final Map<Integer, Bucket> buckets = new LinkedHashMap<>();
		for (final Map.Entry<String, JsonElement> entry : data.entrySet())
		{
			final Integer id = parseId(entry.getKey());
			final JsonObject value = objectOf(entry.getValue());
			if (id == null || value == null)
			{
				continue;
			}
			final Long avgHigh = optLong(value, "avgHighPrice");
			final Long avgLow = optLong(value, "avgLowPrice");
			final long highVolume = Math.max(0L, orZero(optLong(value, "highPriceVolume")));
			final long lowVolume = Math.max(0L, orZero(optLong(value, "lowPriceVolume")));
			if (avgHigh == null && avgLow == null && highVolume == 0L && lowVolume == 0L)
			{
				continue;
			}
			buckets.put(id, new Bucket(avgHigh, highVolume, avgLow, lowVolume));
		}
		return buckets;
	}

	// ---------------------------------------------------------------- the two value types

	/**
	 * One item's newest traded pair from {@code /latest}: the instant-BUY price someone paid ({@code high}), the
	 * instant-SELL price someone accepted ({@code low}), and the second each was traded at. Either price may be
	 * absent; a quote with neither never reaches here ({@link #parseLatest}).
	 *
	 * <p>Immutable and shared: built on OkHttp's dispatcher thread, stored on the service's executor, read while
	 * the rows are computed.
	 */
	public static final class Quote
	{
		private final Long buy;
		private final Long sell;
		private final long buySeconds;
		private final long sellSeconds;

		/**
		 * @param buy         the newest instant-buy price ({@code high}), or null
		 * @param buySeconds  when it was traded, unix seconds; 0 when unknown
		 * @param sell        the newest instant-sell price ({@code low}), or null
		 * @param sellSeconds when it was traded, unix seconds; 0 when unknown
		 */
		public Quote(final Long buy, final long buySeconds, final Long sell, final long sellSeconds)
		{
			this.buy = buy;
			this.sell = sell;
			this.buySeconds = buySeconds;
			this.sellSeconds = sellSeconds;
		}

		/** The newest instant-buy price ({@code high}), or null when nobody has bought since the API's horizon. */
		public Long buy()
		{
			return buy;
		}

		/** The newest instant-sell price ({@code low}), or null when nobody has sold. */
		public Long sell()
		{
			return sell;
		}

		/** When {@link #buy()} was traded, unix seconds; 0 when there is no buy side. */
		public long buySeconds()
		{
			return buySeconds;
		}

		/** When {@link #sell()} was traded, unix seconds; 0 when there is no sell side. */
		public long sellSeconds()
		{
			return sellSeconds;
		}

		/** Both sides present - the first half of T3's spread check. */
		public boolean hasBothSides()
		{
			return buy != null && sell != null;
		}

		/**
		 * The live price of one item: the mean of the two sides, rounded HALF UP, in integer arithmetic (T3).
		 * Null when a side is missing - a one-sided quote is never a live price, because T3 refuses it anyway and
		 * inventing a mid from it would make the refusal look like a number.
		 *
		 * <p>The halves are added separately so a pair near {@link Long#MAX_VALUE} cannot overflow the way
		 * {@code (buy + sell) / 2} would; every real price is far below that.
		 */
		public Long mid()
		{
			if (!hasBothSides())
			{
				return null;
			}
			final long half = buy / 2L + sell / 2L;
			final long remainder = (buy % 2L) + (sell % 2L);
			return half + (remainder + 1L) / 2L;
		}

		/**
		 * The gap between the two sides, as an absolute figure - T3's spread numerator. Null when a side is
		 * missing. Absolute rather than {@code buy - sell}: the two sides are the newest trade on each side of
		 * the book and nothing guarantees which is larger, and a negative gap would sail through the check.
		 */
		public Long spread()
		{
			return hasBothSides() ? Long.valueOf(Math.abs(buy - sell)) : null;
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Quote))
			{
				return false;
			}
			final Quote other = (Quote) o;
			return Objects.equals(buy, other.buy) && Objects.equals(sell, other.sell)
				&& buySeconds == other.buySeconds && sellSeconds == other.sellSeconds;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(buy, sell, buySeconds, sellSeconds);
		}

		@Override
		public String toString()
		{
			return "Quote{buy=" + buy + "@" + buySeconds + ", sell=" + sell + "@" + sellSeconds + '}';
		}
	}

	/**
	 * One item's whole-day traded bucket from {@code /24h}: the day's average on each side and how many units
	 * changed hands on each. Either price may be absent while its volume stands.
	 *
	 * <p>Immutable and shared, like {@link Quote}.
	 */
	public static final class Bucket
	{
		private final Long avgHigh;
		private final Long avgLow;
		private final long highVolume;
		private final long lowVolume;

		/**
		 * @param avgHigh    the day's average instant-buy price, or null when nobody bought
		 * @param highVolume how many units were bought; never negative
		 * @param avgLow     the day's average instant-sell price, or null when nobody sold
		 * @param lowVolume  how many units were sold; never negative
		 */
		public Bucket(final Long avgHigh, final long highVolume, final Long avgLow, final long lowVolume)
		{
			this.avgHigh = avgHigh;
			this.avgLow = avgLow;
			this.highVolume = Math.max(0L, highVolume);
			this.lowVolume = Math.max(0L, lowVolume);
		}

		/** The day's average instant-buy price, or null. */
		public Long avgHigh()
		{
			return avgHigh;
		}

		/** The day's average instant-sell price, or null. */
		public Long avgLow()
		{
			return avgLow;
		}

		/** How many units were bought that day. */
		public long highVolume()
		{
			return highVolume;
		}

		/** How many units were sold that day. */
		public long lowVolume()
		{
			return lowVolume;
		}

		/** Units traded that day, both sides - the tooltip's "517 traded yesterday". */
		public long volume()
		{
			return PortfolioMath.clampedAdd(highVolume, lowVolume);
		}

		@Override
		public boolean equals(final Object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o instanceof Bucket))
			{
				return false;
			}
			final Bucket other = (Bucket) o;
			return Objects.equals(avgHigh, other.avgHigh) && Objects.equals(avgLow, other.avgLow)
				&& highVolume == other.highVolume && lowVolume == other.lowVolume;
		}

		@Override
		public int hashCode()
		{
			return Objects.hash(avgHigh, avgLow, highVolume, lowVolume);
		}

		@Override
		public String toString()
		{
			return "Bucket{avgHigh=" + avgHigh + "x" + highVolume + ", avgLow=" + avgLow + "x" + lowVolume + '}';
		}
	}

	// ---------------------------------------------------------------- internals (the guide client's shapes)

	/**
	 * Builds the request, enqueues it and adapts OkHttp's callback pair onto one future - the same shape as
	 * {@code GuidePriceClient.request}, including the reason the future is completed on every path and BEFORE an
	 * {@link Error} is rethrown: OkHttp 3.14.9 rethrows a Throwable from inside {@code onResponse} on its own
	 * dispatcher thread rather than routing it to {@code onFailure}, so a rethrow first would leave the caller's
	 * in-flight flag claimed for the rest of the session.
	 */
	private <T> CompletableFuture<T> request(final String url, final BodyParser<T> parser)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();

		if (!enabled)
		{
			future.completeExceptionally(new WikiPriceException("traded price fetches are switched off (developer mode)"));
			return future;
		}

		final Request request;
		try
		{
			request = new Request.Builder()
				.url(url)
				.header(USER_AGENT_HEADER, USER_AGENT)
				.get()
				.build();
		}
		catch (final RuntimeException e)
		{
			future.completeExceptionally(new WikiPriceException("could not build the traded-price request for " + url, e));
			return future;
		}

		try
		{
			final Call call = client.newCall(request);
			inFlight.add(call);
			future.whenComplete((value, error) -> inFlight.remove(call));
			call.enqueue(new Callback()
			{
				@Override
				public void onFailure(final Call call, final IOException e)
				{
					fail(future, url, new WikiPriceException("traded-price request failed: " + messageOf(e), e));
				}

				@Override
				public void onResponse(final Call call, final Response response)
				{
					final T value;
					try (Response closing = response)
					{
						final String body = bodyText(closing);
						if (!closing.isSuccessful())
						{
							fail(future, url, httpFailure(closing.code()));
							return;
						}
						value = parser.parse(body);
					}
					catch (final IOException e)
					{
						fail(future, url, e instanceof WikiPriceException
							? (WikiPriceException) e
							: new WikiPriceException("could not read the traded-price response: " + messageOf(e), e));
						return;
					}
					catch (final Throwable t)
					{
						failAndRethrow(future, url, new WikiPriceException(
							"could not parse the traded-price response: " + messageOf(t), t), t);
						return;
					}
					future.complete(value);
				}
			});
		}
		catch (final Throwable t)
		{
			failAndRethrow(future, url, new WikiPriceException("could not queue the traded-price request: " + messageOf(t), t), t);
		}

		return future;
	}

	/** The one way a request fails: {@link #report} it, THEN complete the future with it. */
	private <T> void fail(final CompletableFuture<T> future, final String url, final WikiPriceException failure)
	{
		report(url, failure);
		future.completeExceptionally(failure);
	}

	/** {@link #fail} for a {@code catch} on {@link Throwable}: complete first, rethrow an {@link Error} after. */
	private <T> void failAndRethrow(final CompletableFuture<T> future, final String url,
		final WikiPriceException failure, final Throwable cause)
	{
		fail(future, url, failure);
		if (cause instanceof Error)
		{
			throw (Error) cause;
		}
	}

	/**
	 * Logs one failure: the FIRST of the session loudly, with the url and any HTTP status, every one after it at
	 * debug - the same rule {@code GuidePriceClient.report} follows, and for the same reason (an outage lasts
	 * hours, the tick is thirty minutes, and a repeated line is noise in someone else's log).
	 */
	private void report(final String url, final WikiPriceException failure)
	{
		final String status = failure.hasHttpCode() ? " (HTTP " + failure.getHttpCode() + ")" : "";
		if (reported)
		{
			log.debug("bank-portfolio-tracker: traded-price request to {} failed{}", url, status, failure);
			return;
		}
		reported = true;
		log.warn("bank-portfolio-tracker: traded-price request to {} failed{} - live prices will fall back to the"
			+ " guide prices until it recovers", url, status, failure);
	}

	/** A future that has already failed - the shape {@link #fetchDay} refuses a bad argument with. */
	private static <T> CompletableFuture<T> failed(final WikiPriceException failure)
	{
		final CompletableFuture<T> future = new CompletableFuture<>();
		future.completeExceptionally(failure);
		return future;
	}

	/** The {@code data} member of either feed, or a failure naming which feed it was. */
	private static JsonObject dataOf(final JsonObject root, final String feed) throws WikiPriceException
	{
		final JsonElement data = root.get("data");
		if (data == null || !data.isJsonObject())
		{
			throw new WikiPriceException("the wiki traded " + feed + " response has no data object");
		}
		return data.getAsJsonObject();
	}

	/** Reads the whole body as text, tolerating a null body (a HEAD-shaped or synthetic response). */
	private static String bodyText(final Response response) throws IOException
	{
		final ResponseBody body = response.body();
		return body == null ? "" : body.string();
	}

	/**
	 * A body as a {@link JsonObject}, or a failure. Parsed as {@link JsonElement} first so a non-object body
	 * becomes a clean failure rather than a ClassCastException, and with the INJECTED Gson - constructing one in
	 * plugin code is a Plugin Hub blocker.
	 */
	private JsonObject readObject(final String json) throws WikiPriceException
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new WikiPriceException("empty response from the wiki traded prices");
		}

		final JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (final RuntimeException e)
		{
			throw new WikiPriceException("malformed JSON from the wiki traded prices: " + messageOf(e), e);
		}

		if (root == null || root.isJsonNull() || !root.isJsonObject())
		{
			throw new WikiPriceException("the wiki traded-price response was not a JSON object");
		}
		return root.getAsJsonObject();
	}

	/** One JSON value as an object, or null when it is anything else. Never throws. */
	private static JsonObject objectOf(final JsonElement value)
	{
		return value != null && value.isJsonObject() ? value.getAsJsonObject() : null;
	}

	/** A nullable numeric member as a {@code Long}; absent, JSON null or non-numeric all read as null. */
	private static Long optLong(final JsonObject object, final String key)
	{
		final JsonElement value = object.get(key);
		if (value == null || value.isJsonNull() || !value.isJsonPrimitive())
		{
			return null;
		}
		try
		{
			return Long.valueOf(value.getAsLong());
		}
		catch (final RuntimeException e)
		{
			// A boolean primitive, or a string that is not a number: skip the member, never fail the fetch.
			return null;
		}
	}

	/** A trade time member in unix seconds; absent or negative reads as 0, which {@link Quote} treats as unknown. */
	private static long seconds(final JsonObject object, final String key)
	{
		return Math.max(0L, orZero(optLong(object, key)));
	}

	private static long orZero(final Long value)
	{
		return value == null ? 0L : value;
	}

	/** An item id key, or null when the text is not an integer (skip the entry, never fail the fetch). */
	private static Integer parseId(final String key)
	{
		if (key == null)
		{
			return null;
		}
		try
		{
			final int id = Integer.parseInt(key.trim());
			return id > 0 ? Integer.valueOf(id) : null;
		}
		catch (final NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * A non-2xx answer. The status is carried on the exception because 403 is diagnosable on its own (the prices
	 * host pre-emptively blocks default user agents) while the body for it is unhelpful.
	 */
	private static WikiPriceException httpFailure(final int code)
	{
		return new WikiPriceException("traded-price request failed with HTTP " + code, code);
	}

	/** {@code Throwable.getMessage()} is null for plenty of IO failures; fall back to the type name. */
	private static String messageOf(final Throwable t)
	{
		final String message = t.getMessage();
		return truncate(message == null || message.isEmpty() ? t.getClass().getSimpleName() : message);
	}

	private static String truncate(final String text)
	{
		if (text == null)
		{
			return null;
		}
		return text.length() <= MAX_DETAIL_CHARS ? text : text.substring(0, MAX_DETAIL_CHARS) + "...";
	}

	/** The one thing that differs between the two requests once the bytes are in hand. */
	@FunctionalInterface
	private interface BodyParser<T>
	{
		T parse(String body) throws WikiPriceException;
	}
}

package com.bankpricemovement;

/**
 * The plugin's version, in one place: the settings menu's last row prints it, the plugin's description ends with it,
 * and the start-up line in the client log names it.
 *
 * <p>It is bumped BY HAND each release, in step with {@code version=} in the export's
 * {@code runelite-plugin.properties} (the Hub reads that one). The export's {@code publish.py} refuses to commit when
 * the two differ, so a release cannot go out saying one thing to the Hub and another to the player.
 */
public final class Version
{
	/** The version this build ships as, {@code major.minor.patch}. */
	public static final String CURRENT = "1.2.0";

	private Version()
	{
	}
}

package com.bankpricemovement;

import java.util.LinkedHashMap;
import java.util.Objects;

/**
 * The five view switches, carried as one immutable value the way {@link HeroVisibility} carries the card's three
 * figures: the two addendum Q still has - whether coins and platinum tokens count in the bank value
 * ({@code countCash}, config item {@code countCash}, default on) and whether untradeable stacks are listed and
 * counted at their High Alchemy value when they have no tradeable parts ({@code countUntradeables}, default off;
 * narrowed by addendum AV) - addendum T's, whether an actively
 * traded item is priced from the wiki's live traded series ({@code livePrices}, default ON) - addendum Y's,
 * whether the stacks the player is CARRYING and WEARING are counted and listed beside the bank's
 * ({@code countInventory}, default ON) - and 1.0.9 part 3's, whether what the player has in the Grand Exchange's
 * offers is counted and listed beside them ({@code countGrandExchange}, default ON). The settings menu on the hero
 * card, RuneLite's settings page and the dev verb {@code opt=} all read and write the same five switches through
 * the plugin's config.
 *
 * <p><b>Addendum AO line AO1 took one away</b>: {@code holdingOnRows}, addendum Q's third, which chose
 * whether a row printed the per-ITEM reading or the per-STACK one. Addendum AN's three-line row prints BOTH - line
 * 2 is the stack, line 3 is one item - so the switch no longer reached anything drawn, and the user, asked whether
 * to keep it, answered "if it doesnt do anything anymore then remove it". The one thing it still did was pick
 * {@link SortMode#GP_MOVE}'s comparison key, which is the STACK's gp move permanently now.
 *
 * <p><b>Release 1.2.0 took a second away</b>: {@code showHoverText}, addendum AH's, whether the sidebar's hovers were
 * shown at all. It was the last field, so no constructor call could silently change its meaning - the old
 * six-argument calls simply stop compiling. Every hover left in the sidebar is one short line, and the user
 * (2026-10-08) decided that a switch to hide them was one setting more than the plugin needs: the hovers are always on.
 */
public final class ViewOptions
{
	/**
	 * Every switch at its default: cash counted, untradeables left out, live prices on, the inventory and worn
	 * gear counted, and the Grand Exchange offers counted.
	 */
	public static final ViewOptions DEFAULT = new ViewOptions(true, false, true, true, true);

	private final boolean countCash;
	private final boolean countUntradeables;
	private final boolean livePrices;
	private final boolean countInventory;
	private final boolean countGrandExchange;

	/**
	 * The one constructor, and since addendum AO the ONLY one: this class carried a ladder of shorter overloads
	 * that defaulted the switches added after them, and every rung of it became a trap the moment a field was
	 * removed from the MIDDLE of the list. Five booleans that used to mean
	 * {@code (cash, untradeables, holding, live, inventory)} would still compile against that day's five-argument
	 * {@code (cash, untradeables, live, inventory, hover)} and mean three different things, with no error anywhere
	 * to say so. Deleting the ladder makes the compiler name every call site instead. 1.0.9 part 3 added the
	 * Grand Exchange switch and kept to the rule: the one constructor grew, no overload was added, and every call
	 * site was rewritten. Release 1.2.0 removed the last field, {@code showHoverText}, the same way: the constructor
	 * shrank by its last argument, and a six-argument call no longer compiles.
	 */
	public ViewOptions(final boolean countCash, final boolean countUntradeables, final boolean livePrices,
		final boolean countInventory, final boolean countGrandExchange)
	{
		this.countCash = countCash;
		this.countUntradeables = countUntradeables;
		this.livePrices = livePrices;
		this.countInventory = countInventory;
		this.countGrandExchange = countGrandExchange;
	}

	/** Coins and platinum tokens (1,000 gp each) count in the bank value and in the percentage's basis. */
	public boolean countCash()
	{
		return countCash;
	}

	/** Untradeable stacks are listed and counted at their High Alchemy value, with no movement figures. */
	public boolean countUntradeables()
	{
		return countUntradeables;
	}

	/**
	 * Actively traded items use the wiki's live traded prices for every figure (addendum T); thin items keep the daily
	 * guide price. Off means exactly the guide-only behaviour of addenda K to S.
	 */
	public boolean livePrices()
	{
		return livePrices;
	}

	/**
	 * The stacks in the player's INVENTORY and on their WORN gear count in the bank value and are listed beside the
	 * bank's, one row per item with the quantities added (addendum Y, lines Y1 to Y3). Off means exactly the
	 * bank-only behaviour of addenda K to W, figure for figure.
	 *
	 * <p>Both containers are read at the two moments the bank itself is read - a bank container event and Refresh -
	 * so what the sidebar shows is what the player was carrying then (Y2).
	 */
	public boolean countInventory()
	{
		return countInventory;
	}

	/**
	 * The items and coins in the player's eight Grand Exchange offers count in the bank value and are listed beside
	 * the bank's stacks, one row per item with the quantities added (1.0.9 part 3). Off means exactly the behaviour
	 * without them, figure for figure.
	 *
	 * <p>The offers are read at the moments the inventory and the worn gear are read - a bank event, the bank's
	 * close, Refresh - and never when an offer changes, so an offer that fills with the bank closed shows at the
	 * next of those, not at once.
	 */
	public boolean countGrandExchange()
	{
		return countGrandExchange;
	}

	public ViewOptions withCountCash(final boolean value)
	{
		return new ViewOptions(value, countUntradeables, livePrices, countInventory, countGrandExchange);
	}

	public ViewOptions withCountUntradeables(final boolean value)
	{
		return new ViewOptions(countCash, value, livePrices, countInventory, countGrandExchange);
	}

	public ViewOptions withLivePrices(final boolean value)
	{
		return new ViewOptions(countCash, countUntradeables, value, countInventory, countGrandExchange);
	}

	public ViewOptions withCountInventory(final boolean value)
	{
		return new ViewOptions(countCash, countUntradeables, livePrices, value, countGrandExchange);
	}

	public ViewOptions withCountGrandExchange(final boolean value)
	{
		return new ViewOptions(countCash, countUntradeables, livePrices, countInventory, value);
	}

	/**
	 * The switches in the order the dev bridge prints them: {@code cash}, {@code untradeables}, {@code live},
	 * {@code inventory}, {@code ge}. Addendum AO line AO1 removed {@code holding} from between the second and the
	 * third with the switch it echoed; 1.0.9 part 3 put {@code ge} directly after {@code inventory}; release 1.2.0
	 * removed {@code hover}, the sixth, with the switch behind it.
	 */
	public LinkedHashMap<String, Boolean> asMap()
	{
		final LinkedHashMap<String, Boolean> map = new LinkedHashMap<>();
		map.put("cash", countCash);
		map.put("untradeables", countUntradeables);
		map.put("live", livePrices);
		map.put("inventory", countInventory);
		map.put("ge", countGrandExchange);
		return map;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof ViewOptions))
		{
			return false;
		}
		final ViewOptions other = (ViewOptions) o;
		return countCash == other.countCash
			&& countUntradeables == other.countUntradeables
			&& livePrices == other.livePrices
			&& countInventory == other.countInventory
			&& countGrandExchange == other.countGrandExchange;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(countCash, countUntradeables, livePrices, countInventory, countGrandExchange);
	}

	@Override
	public String toString()
	{
		return "ViewOptions{cash=" + countCash + ", untradeables=" + countUntradeables + ", live=" + livePrices
			+ ", inventory=" + countInventory + ", ge=" + countGrandExchange + '}';
	}
}

