	private static final String KEY_LINK_HOVER = "bpm.link.hover";

	private Widgets()
	{
	}

	// ------------------------------------------------------- addendum N: the sans scale (N section 3 §2, §7)

	/**
	 * The plain Swing sans at {@code size} px: {@code FontManager.getDefaultFont()} - the logical
	 * {@code Font.DIALOG} at 16 ({@code runelite-client/src/main/java/net/runelite/client/ui/FontManager.java:93})
	 * - derived to the size asked for.
	 *
	 * <p><b>Why every new label sets its font through this.</b> {@code RuneLiteLAF} installs the 16 px bitmap
	 * RuneScape face as the look-and-feel default, so a label that is given no font inherits a face with no
	 * size between 11 px and 14 px of ink and no triangle, tick or chevron glyph (playbook 7.5 - a missing
	 * glyph is drawn as a box). Addendum N's type scale is 28 / 18 / 14 / 13 / 12 / 11 px of ONE family, and
	 * that family has to be the logical one, because it is the only one with those sizes.
	 *
	 * <p>{@link Font#deriveFont(float)} answers a NEW font, so the shared {@code FontManager} constant is
	 * never mutated by a caller here.
	 *
	 * @param size the point size, e.g. 28 for the bank total, 12 for the control row
	 */
	static Font sans(float size)
	{
		return FontManager.getDefaultFont().deriveFont(size);
	}

	/** {@link #sans(float)} for the whole-number sizes the panel actually asks for. */
	static Font sans(int size)
	{
		return sans((float) size);
	}

	/**
	 * The bold Swing sans at {@code size} px - {@code FontManager.getDefaultBoldFont()}
	 * ({@code FontManager.java:94}) derived. See {@link #sans(float)} for why the new code never leaves a
	 * label's font to the look and feel.
	 */
	static Font sansBold(float size)
	{
		return FontManager.getDefaultBoldFont().deriveFont(size);
	}

	/** {@link #sansBold(float)} for the whole-number sizes the panel actually asks for. */
	static Font sansBold(int size)
	{
		return sansBold((float) size);
	}

	/**
	 * A label with its font and colour set explicitly - the one-line form of "never inherit the LAF's face"
	 * (N section 7). A null text is an empty label, which still has a font, so a probe measured from it
	 * reports the height a filled one will have.
	 */
	static JLabel label(String text, Font font, Color colour)
	{
		final JLabel label = new JLabel(text == null ? "" : text);
		label.setFont(font);
		label.setForeground(colour);
		return label;
	}

	/**
	 * {@code text} cut to what {@code width} px of {@code font} can hold, ending in {@link #ELLIPSIS} when it
	 * had to be cut; the whole text when it fits. Measured with the same {@link FontMetrics} a label paints
	 * with, so "fits" here is "fits on the screen".
	 */
	static String fit(Font font, @Nullable String text, int width)
	{
		return fit(metrics(font), text, width);
	}

	/**
	 * {@link #fit(Font, String, int)} against metrics the caller already holds. Every label owns the metrics it
	 * will paint with ({@link JComponent#getFontMetrics}), so the fitters take a {@link FontMetrics} rather than
	 * building a throwaway {@link JLabel} per call - {@link #fitName} used to build three for one name.
	 */
	private static String fit(FontMetrics fm, @Nullable String text, int width)
	{
		final String full = text == null ? "" : text;
		final int room = Math.max(10, width);
		if (fm.stringWidth(full) <= room)
		{
			return full;
		}
		final int dots = fm.stringWidth(ELLIPSIS);
		// Backwards, one prefix at a time, MEASURED with the same call the render will make: summing per-character
		// advances instead would round once per character where stringWidth rounds once per string, and the cut
		// would land on a different character on a face this machine does not have.
		for (int i = full.length() - 1; i > 0; i--)
		{
			if (fm.stringWidth(full.substring(0, i)) + dots <= room)
			{
				return full.substring(0, i) + ELLIPSIS;
			}
		}
		return ELLIPSIS;
	}

	/** The metrics a plain label of {@code font} paints with, for a caller that has no label to ask. */
	private static FontMetrics metrics(Font font)
	{
		return new JLabel().getFontMetrics(font);
	}

	/**
	 * Sets a label's text truncated to {@code width}, with the full text as its tooltip - the width rule in one
	 * call, for every label whose text comes from an item name, a status line or a number the user cannot be
	 * expected to keep short.
	 */
	static void setFitted(JLabel label, @Nullable String text, int width)
	{
		setFitted(label, text, width, Widgets::fit);
	}

	/**
	 * {@link #fit} for an ITEM NAME: the same cut, except that a dose suffix is kept whole.
	 *
	 * <p>Why this exists. The four doses of a potion differ only in their last three characters, and at the
	 * row's bold 14 they are all too wide for its 156 px text block - "Super combat potion(1..4)" measures 164 px
	 * each - so the plain fitter cuts every one of them to the SAME string, "Super combat potio...", and four
	 * consecutive rows lose the only thing that told them apart. Fitting the stem into what is left after the
	 * suffix gives "Super combat pot...(4)" (154 px), which is still one line and still says which potion it is.
	 *
	 * <p>The rule is deliberately narrow: only a trailing {@code (<digit>)}, which in OSRS is a dose and never a
	 * qualifier - a qualifier carries a space before its bracket ("Toxic blowpipe (empty)") and is left to the
	 * plain cut, where losing it costs nothing a reader needs. A name that fits is untouched, and a name whose
	 * stem cannot survive the cut at all falls back to {@link #fit} rather than printing "...(4)".
	 */
	static String fitName(Font font, @Nullable String text, int width)
	{
		return fitName(metrics(font), text, width);
	}

	/** {@link #fitName(Font, String, int)} against metrics the caller already holds; see {@link #fit}. */
	private static String fitName(FontMetrics fm, @Nullable String text, int width)
	{
		final String full = text == null ? "" : text;
		final int room = Math.max(10, width);
		if (fm.stringWidth(full) <= room || !hasDoseSuffix(full))
		{
			return fit(fm, full, width);
		}
		final String suffix = full.substring(full.length() - 3);
		final String stem = fit(fm, full.substring(0, full.length() - 3), room - fm.stringWidth(suffix));
		if (stem.isEmpty() || ELLIPSIS.equals(stem))
		{
			return fit(fm, full, width);
		}
		return stem + suffix;
	}

	/** Whether {@code name} ends in a dose bracket - "(1)" to "(9)" with no space before it. */
	private static boolean hasDoseSuffix(String name)
	{
		final int n = name.length();
		return n > 4 && name.charAt(n - 1) == ')' && name.charAt(n - 2) >= '0' && name.charAt(n - 2) <= '9'
			&& name.charAt(n - 3) == '(' && name.charAt(n - 4) != ' ';
	}

	/** {@link #setFitted} through {@link #fitName}: for a label whose text is an item name. */
	static void setFittedName(JLabel label, @Nullable String text, int width)
	{
		setFitted(label, text, width, Widgets::fitName);
	}

	/**
	 * The body of both setters: cut with {@code fitter}, keep the whole text on the tooltip - measured with the
	 * metrics of the LABEL, which are the metrics it will paint with.
	 */
	private static void setFitted(JLabel label, @Nullable String text, int width, Fitter fitter)
	{
		final String full = text == null ? "" : text;
		final Font font = label.getFont() == null ? FontManager.getRunescapeSmallFont() : label.getFont();
		label.setText(fitter.cut(label.getFontMetrics(font), full, width));
		label.setToolTipText(full.isEmpty() ? null : full);
	}

	/** How a text is cut to its room: {@link #fit} plainly, {@link #fitName} keeping a dose bracket. */
	private interface Fitter
	{
		String cut(FontMetrics fm, String text, int width);
	}

	/**
	 * The five characters HTML gives a meaning that an item name must not - a tooltip is HTML so it can hold
	 * several lines, and "Zulrah's scales" or a name with an ampersand has to survive the trip.
	 */
	static String escapeHtml(@Nullable String text)
	{
		if (text == null)
		{
			return "";
		}
		final StringBuilder sb = new StringBuilder(text.length() + 8);
		for (int i = 0; i < text.length(); i++)
		{
			final char c = text.charAt(i);
			switch (c)
			{
				case '&':
					sb.append("&amp;");
					break;
				case '<':
					sb.append("&lt;");
					break;
				case '>':
					sb.append("&gt;");
					break;
				case '"':
					sb.append("&quot;");
					break;
				case '\'':
					sb.append("&#39;");
					break;
				default:
					sb.append(c);
			}
		}
		return sb.toString();
	}

	// ---------------------------------------------------------------- the move colours (N sections 2 and 3.1, B045)

	/** What a move colour is FOR - the three roles the one sign rule is painted in; see {@link #move}. */
	enum Kind
	{
		/**
		 * A number: a row's gp change and percentage, the hero card's move line. A fall takes
		 * {@link #MOVE_DOWN_TEXT}, the lifted red, because those are 12 to 18 px of small text (B045).
		 */
		FIGURE,
		/** A direction mark: the card's move triangle. The {@code ColorScheme} constants, undimmed and unlifted. */
		MARK,
		/**
		 * A coloured edge: the hero card's left border and a row's 3 px rail. The constants DARKENED, and the
		 * card's own grey for a flat or absent move - an edge that is invisible without changing any width.
		 */
		EDGE,
		/**
		 * A number that must not out-shout the one beside it: a row's gp change, which shares its line with the
		 * percentage (addendum AL). {@link #FIGURE}'s colour mixed {@value #QUIET_MIX_PERCENT}% into the row's
		 * own background - still plainly green or red, so the figure keeps saying which way the price went, but
		 * no longer competing with the percentage for the same glance.
		 *
		 * <p>A FLAT move takes the quiet grey UNDIMMED, exactly as {@link #FIGURE} does: there is nothing there
		 * to out-shout, and pushing a dash toward the background only makes it hard to read.
		 */
		QUIET
	}

	/**
	 * How far {@link Kind#QUIET} is pushed toward the background, as a percentage (addendum AL). Measured by
	 * eye against the real list at 213 px: below about 40 the two figures still read as one, and above about 70
	 * the gp figure stops reading as green at all and the row loses half its direction cue.
	 */
	static final int QUIET_MIX_PERCENT = 55;

	/**
	 * The colour of a rise the reader chose (1.1.0 part B), or null for the built-in green. One palette for the whole
	 * process, because {@link #move} is a static rule that a dozen painters call with a sign and a role and nothing else:
	 * the plugin sets it at startUp and clears it at shutDown, and the sidebar changes it as the reader moves the colour
	 * picker. Volatile - the EDT writes it and nothing promises that it alone reads it.
	 */
	@Nullable
	private static volatile Color moveUp;

	/** The colour of a fall the reader chose, or null for the built-in red; see {@link #moveUp}. */
	@Nullable
	private static volatile Color moveDown;

	/** The colour a rise is drawn in when the reader has chosen none: the client's own green. */
	static final Color MOVE_UP_DEFAULT = ColorScheme.PROGRESS_COMPLETE_COLOR;

	/**
	 * The net worth chart's colour while "Single chart colour" is on and the reader has chosen none (1.1.0 part C): the
	 * logo gold, the face of the 2h coin ({@code CoinGlyph}'s own, which that kit file keeps private).
	 */
	static final Color CHART_COLOUR_DEFAULT = new Color(196, 156, 58);

	/**
	 * Sets the colours {@link #move} draws a rise and a fall in; null for a direction means the built-in colour. A colour
	 * EQUAL to the built-in one (the config's defaults: {@link #MOVE_UP_DEFAULT} and {@link #MOVE_DOWN_TEXT}) is stored
	 * as null, so a reader who never touched the setting - or who put the default back - gets the sidebar exactly as it was
	 * drawn before the setting existed, down to the pixel (the built-in red is a deeper one for a mark than for a figure,
	 * and a chosen colour is one colour for both). Any transparency is dropped: a rise is not see-through.
	 *
	 * <p>Not a rule on the neutral colour: a flat move or none at all is drawn as it always was.
	 */
	static void setMoveColours(@Nullable Color up, @Nullable Color down)
	{
		moveUp = chosen(up, MOVE_UP_DEFAULT);
		moveDown = chosen(down, MOVE_DOWN_TEXT);
	}

	/** {@code colour} made opaque, or null when it is null or is the built-in one it would stand in for. */
	@Nullable
	private static Color chosen(@Nullable Color colour, Color builtIn)
	{
		if (colour == null)
		{
			return null;
		}
		final Color opaque = new Color(colour.getRGB());
		return opaque.equals(builtIn) ? null : opaque;
	}

	/** {@code from} mixed {@code amount} of the way into {@code to}; 0 is unchanged, 1 is {@code to}. */
	private static Color towards(Color from, Color to, double amount)
	{
		final double a = Math.max(0.0, Math.min(1.0, amount));
		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * a),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * a),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * a));
	}

	/**
	 * The one move rule, in whichever role is asking: green for a rise, red for a fall, and the quiet grey - or,
	 * for an {@link Kind#EDGE}, the card grey - for a flat move or none at all. Every colour in this sidebar that
	 * says which way a price went comes from here, so a row's rail, its figures and the hero card's edge cannot
	 * drift apart. Since 1.1.0 part B the green and the red are the reader's to choose ({@link #setMoveColours}); with a
	 * colour chosen for a direction its figure and its mark ARE that colour, its quiet figure is that colour mixed
	 * {@value #QUIET_MIX_PERCENT}% into the card, and its edge is {@code darker()} of it.
	 *
	 * @param signum which way it went: +1 up, -1 down, 0 for a flat move or no baseline at all - the caller reads
	 *               it off its own gp figure ({@code Long.signum}), which is what signs the percentage too (L2)
	 */
	static Color move(int signum, Kind kind)
	{
		if (signum == 0)
		{
			return kind == Kind.EDGE ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR;
		}
		final Color chosen = signum > 0 ? moveUp : moveDown;
		if (chosen != null)
		{
			// The reader's own colour for this direction (1.1.0 part B): a figure and a mark are the colour itself, the
			// quiet figure is that colour pushed toward the card exactly as the built-in ones are, and an edge is its
			// darker() - the same three relations the built-in green and red stand in.
			switch (kind)
			{
				case QUIET:
					return towards(chosen, ColorScheme.DARKER_GRAY_COLOR, QUIET_MIX_PERCENT / 100.0);
				case EDGE:
					return chosen.darker();
				default:
					return chosen;
			}
		}
		final Color colour = signum > 0 ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR;
		switch (kind)
		{
			case FIGURE:
				return liftRed(colour);
			case QUIET:
				return towards(liftRed(colour), ColorScheme.DARKER_GRAY_COLOR, QUIET_MIX_PERCENT / 100.0);
			case EDGE:
				return colour.darker();
			default:
				return colour;
		}
	}

	/**
	 * {@link #MOVE_DOWN_TEXT} for the falling constant, {@code colour} untouched for anything else - the "as
	 * TEXT" half of {@link #move}, kept apart so the pairing is stated once and the marks are visibly not lifted.
	 */
	static Color liftRed(Color colour)
	{
		return ColorScheme.PROGRESS_ERROR_COLOR.equals(colour) ? MOVE_DOWN_TEXT : colour;
	}

	// ---------------------------------------------------------------- controls

	/**
	 * A compact button for header actions (small face, tight margins). The EMPTY card's "Clear price range" is
	 * the one left: the Ticker sidebar's other controls are text links and segments, because a
	 * {@code JButton} is painted by whatever {@code ButtonUI} the client's look and feel installs (see
	 * {@link #segment}), and this one is deliberately a button - it is the way out of a filter that hid
	 * everything, and it should look like the platform's own control.
	 */
	static JButton smallButton(String text, @Nullable String tooltip, ActionListener onClick)
	{
		final JButton b = new JButton(text);
		b.setToolTipText(tooltip);
		b.setFocusPainted(false);
		b.addActionListener(onClick);
		b.setFont(FontManager.getRunescapeSmallFont());
		b.setMargin(new Insets(1, 5, 1, 5));
		return b;
	}

	// ------------------------------------------- addendum N: segments, the underline chip, and text links

	/**
	 * One cell of a segmented strip - a window chip inside the hero card, or a preset in the price fold (N 4.4
	 * control 1, N 3.5): a {@link JLabel} with a hand cursor, centred text at the chip size, and a hover that
	 * follows what {@link #chip} last painted it as.
	 *
	 * <p><b>A JLabel and not a JButton.</b> This is {@code MaterialTab}'s own idiom
	 * ({@code runelite-client/src/main/java/net/runelite/client/ui/components/materialtabs/MaterialTab.java:51,
	 * :123-142} - a {@code JLabel} given a border, a foreground and a {@code MouseAdapter}), and it is the
	 * only way to be sure of the face: a {@code JButton} is painted by whatever {@code ButtonUI} the client's
	 * look and feel installs, which is free to ignore the colours entirely.
	 *
	 * <p>The size is NOT pinned here - a window chip is {@code fixed(38, 22)} inside the card's 191 px and a
	 * preset {@code fixed(49, 24)} in the fold (N 4.2, 3.5).
	 *
	 * <p>{@code onClick} does not fire while the segment is lit: re-selecting the window you are already on,
	 * or the price preset you already have, is a no-op by definition (N 3.2), and swallowing it here means no
	 * caller has to remember. Nor does it fire for anything but a LEFT-button press ({@link #isPress}): the
	 * chips sit inside the hero card, whose right-click is the card's own menu (N 3.1, O4), and a right-click
	 * that also changed the window would be two answers to one gesture.
	 *
	 * @param onClick run on a left press of an UNLIT segment; may be null for a segment that is only a light
	 */
	static JLabel segment(String text, @Nullable String tooltip, @Nullable Runnable onClick)
	{
		final JLabel cell = new JLabel(text == null ? "" : text);
		cell.setHorizontalAlignment(SwingConstants.CENTER);
		cell.setVerticalAlignment(SwingConstants.CENTER);
		cell.setToolTipText(tooltip);
		cell.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		chip(cell, false);
		cell.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (onClick != null && isPress(e) && !isLit(cell))
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				hoverChip(cell, true);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hoverChip(cell, false);
			}
		});
		return cell;
	}

	/**
	 * Paints a segment lit or unlit in the Ticker style (N 4.4 control 1, the only style since O1) and records
	 * it on the label so {@link #isLit} and the hover can read it back: transparent (the hero card's or the
	 * fold's ground shows through), lit = bold {@code BRAND_ORANGE} over a {@link #CHIP_UNDERLINE} px orange
	 * {@link MatteBorder}, unlit = plain {@code LIGHT_GRAY} over an {@link EmptyBorder} of the same height, so
	 * lighting a cell never moves the strip.
	 */
	static void chip(JLabel label, boolean lit)
	{
		chip(label, lit, false);
	}

	/**
	 * {@link #chip(JLabel, boolean)} with the third state addendum AU gives a window chip on the History view's card
	 * (plan 7.2 item 5, contract amendment 9.6): DIMMED - a window with no reading old enough behind it - drawn in
	 * {@link ColorScheme#MEDIUM_GRAY_COLOR}, the grey the mock called "a chip with no history behind it", in the
	 * unlit face and with the unlit border, so dimming a chip never moves the strip either.
	 *
	 * <p>A dimmed chip is still a chip: it answers a press like any unlit one ({@link #segment} gates on
	 * {@link #isLit} alone) and the mouse still lights its text orange. LIT wins over dimmed - the window the reader
	 * chose stays the orange one, and the card's footnote says when it fills.
	 */
	static void chip(JLabel label, boolean lit, boolean dim)
	{
		final boolean dimmed = dim && !lit;
		final Color colour = lit ? ColorScheme.BRAND_ORANGE : dimmed ? ColorScheme.MEDIUM_GRAY_COLOR
			: ColorScheme.LIGHT_GRAY_COLOR;
		// Already painted exactly this way: setFont and setBorder each fire a property change and invalidate the
		// label, and renderChips repaints all nine cells on every publish. The foreground is part of the test
		// because hoverChip paints an UNLIT cell orange without changing what is recorded here - a repaint under
		// the mouse must still put the resting colour back, as it always did.
		if (Boolean.valueOf(lit).equals(label.getClientProperty(KEY_LIT)) && dimmed == isDim(label)
			&& colour.equals(label.getForeground()))
		{
			return;
		}
		label.putClientProperty(KEY_LIT, lit);
		label.putClientProperty(KEY_DIM, dimmed);
		label.setOpaque(false);
		label.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		label.setForeground(colour);
		label.setFont(lit ? CHIP_LIT_FONT : CHIP_UNLIT_FONT);
		label.setBorder(lit ? CHIP_LIT_BORDER : CHIP_UNLIT_BORDER);
	}

	/**
	 * Whether {@link #chip} last lit {@code label} - read by the tests, the bridge and the segment's own
	 * click gate. A label this class never painted is not lit.
	 */
	static boolean isLit(JLabel label)
	{
		final Object lit = label.getClientProperty(KEY_LIT);
		return lit instanceof Boolean && (Boolean) lit;
	}

	/**
	 * The hover half of {@link #segment}, exposed so a test can drive it without synthesising a
	 * {@link MouseEvent}: an UNLIT cell's text goes {@code BRAND_ORANGE} under the mouse and back to
	 * {@code LIGHT_GRAY} after. A LIT segment does not react - it is already the answer, and nothing about it
	 * is clickable (N 3.2).
	 */
	static void hoverChip(JLabel label, boolean entered)
	{
		if (isLit(label))
		{
			return;
		}
		// A dimmed chip (AU) goes back to its own grey when the mouse leaves, not to the unlit one.
		label.setForeground(entered ? ColorScheme.BRAND_ORANGE
			: isDim(label) ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
	}

	/** Whether {@link #chip(JLabel, boolean, boolean)} last drew {@code label} dimmed (AU); never while it is lit. */
	static boolean isDim(JLabel label)
	{
		final Object dim = label.getClientProperty(KEY_DIM);
		return dim instanceof Boolean && (Boolean) dim;
	}

	// ------------------------------------------------ addendum AU: the Items | Net Worth History toggle

	/**
	 * The toggle's height, in px, its 1 px border included - the mock's segmented box (plan 7.2 item 12,
	 * {@code mock-items-toggle-2x.png}): room for a face of up to {@link #TOGGLE_TEXT_MAX} px with air above and below it.
	 */
	static final int TOGGLE_HEIGHT = 20;

	/**
	 * The least air, in px, left and right of a half's word, lit or unlit (2026-09-29: the user asked for larger tab
	 * names, so the words take the strip's largest size wherever they fit, and they are never cut).
	 */
	static final int TOGGLE_AIR = 2;

	/**
	 * The largest size, in px, the toggle's words are ever set in - the strip's first face, which "Items" and "Net worth"
	 * fit at 213 px but "Net Worth History" does not.
	 */
	static final int TOGGLE_TEXT_MAX = 12;

	/** The smallest size the toggle's words are ever set in, so a box far narrower than the sidebar still ends. */
	private static final int TOGGLE_TEXT_MIN = 6;

	/**
	 * Two halves side by side in one bordered box, the LIT half filled {@link ColorScheme#BRAND_ORANGE} with its word
	 * in dark bold and the other the card grey with its word in light grey (addendum AU, plan 7.2 items 1 and 12) -
	 * deliberately unlike the underlined chips on the card above it, because it switches what the whole sidebar is
	 * showing rather than a figure on it.
	 *
	 * <p>It behaves like a {@link #segment}: a LEFT press ({@link #isPress}) on the UNLIT half runs {@code onPress}
	 * with that half's index, and a press on the lit half does nothing - it is already the answer. It carries NO hover
	 * text (the contract's ruling 9.7: no hover is invented for it), and the mouse over the unlit half lights its word
	 * orange as it does on a chip.
	 *
	 * <p>Nothing here decides which half is lit: the caller says so through {@link Toggle#setLit}, from its own state,
	 * so the toggle can never show one view while the sidebar shows the other.
	 *
	 * @param onPress run with 0 or 1 on a left press of the unlit half; may be null for a toggle that is only a light
	 */
	static Toggle toggle(String first, String second, @Nullable IntConsumer onPress)
	{
		return new Toggle(first, second, onPress);
	}

	/**
	 * The box {@link #toggle} builds: two opaque labels of EQUAL width in a 1 px {@link ColorScheme#MEDIUM_GRAY_COLOR}
	 * frame, both words in the one size {@link Toggle#doLayout} fits them to.
	 */
	static final class Toggle extends JPanel
	{
		private final JLabel[] halves = new JLabel[2];
		/** Which half is lit: 0, 1, or -1 before the caller first says. */
		private int lit = -1;
		/** The size both words are set in; {@link #doLayout} fits it to the halves. */
		private int textSize = TOGGLE_TEXT_MAX;
		private Font litFont = sansBold(TOGGLE_TEXT_MAX);
		private Font unlitFont = sans(TOGGLE_TEXT_MAX);

		private Toggle(String first, String second, @Nullable IntConsumer onPress)
		{
			super(null);
			setBorder(new MatteBorder(1, 1, 1, 1, ColorScheme.MEDIUM_GRAY_COLOR));
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			final String[] words = {first, second};
			for (int i = 0; i < halves.length; i++)
			{
				final int index = i;
				final JLabel half = new JLabel(words[i] == null ? "" : words[i]);
				half.setHorizontalAlignment(SwingConstants.CENTER);
				half.setVerticalAlignment(SwingConstants.CENTER);
				half.setOpaque(true);
				half.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mousePressed(MouseEvent e)
					{
						if (onPress != null && isPress(e) && !isLit(index))
						{
							onPress.accept(index);
						}
					}

					@Override
					public void mouseEntered(MouseEvent e)
					{
						if (!isLit(index))
						{
							half.setForeground(ColorScheme.BRAND_ORANGE);
						}
					}

					@Override
					public void mouseExited(MouseEvent e)
					{
						paintHalf(index);
					}
				});
				halves[i] = half;
				add(half);
			}
			fixed(this, CONTENT_WIDTH, TOGGLE_HEIGHT);
			setLit(0);
		}

		/** Lights half {@code index} (0 or 1) and unlights the other; the same half again repaints nothing. */
		void setLit(int index)
		{
			final int want = index == 1 ? 1 : 0;
			if (want == lit)
			{
				return;
			}
			lit = want;
			for (int i = 0; i < halves.length; i++)
			{
				paintHalf(i);
			}
		}

		/**
		 * THE one rule for the toggle's halves and its words (2026-09-29, the user choosing look b from pictures,
		 * "equal halves, smaller text"): the two halves are EQUAL - the second takes the odd pixel - and both words
		 * are set in ONE size, the largest whole size up to {@link #TOGGLE_TEXT_MAX} at which each word, measured in the
		 * bold lit face and the plain one and the wider taken, fits its half with {@link #TOGGLE_AIR} px on each side. So
		 * "Net Worth History" in bold decides it, and neither half nor size moves when the light changes sides.
		 */
		@Override
		public void doLayout()
		{
			final Insets in = getInsets();
			final int inner = getWidth() - in.left - in.right;
			final int height = getHeight() - in.top - in.bottom;
			final int first = inner / 2;
			final int[] widths = {first, inner - first};
			int size = TOGGLE_TEXT_MAX;
			while (size > TOGGLE_TEXT_MIN && !fits(size, widths))
			{
				size--;
			}
			if (size != textSize)
			{
				textSize = size;
				litFont = sansBold(size);
				unlitFont = sans(size);
				for (int i = 0; i < halves.length; i++)
				{
					paintHalf(i);
				}
			}
			halves[0].setBounds(in.left, in.top, widths[0], height);
			halves[1].setBounds(in.left + widths[0], in.top, widths[1], height);
		}

		/** Whether both words, at {@code size} in the wider of their two faces, keep {@link #TOGGLE_AIR} a side. */
		private boolean fits(int size, int[] widths)
		{
			final FontMetrics bold = getFontMetrics(sansBold(size));
			final FontMetrics plain = getFontMetrics(sans(size));
			for (int i = 0; i < halves.length; i++)
			{
				final String word = halves[i].getText();
				final int text = Math.max(bold.stringWidth(word), plain.stringWidth(word));
				if (text + 2 * TOGGLE_AIR > widths[i])
				{
					return false;
				}
			}
			return true;
		}

		/** Whether half {@code index} is the lit one - the press gate: pressing the answer changes nothing. */
		boolean isLit(int index)
		{
			return index == lit;
		}

		private void paintHalf(int index)
		{
			final JLabel half = halves[index];
			final boolean on = isLit(index);
			half.setBackground(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
			half.setForeground(on ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
			half.setFont(on ? litFont : unlitFont);
			// A hand only where a press does something.
			half.setCursor(on ? Cursor.getDefaultCursor() : Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		}
	}

	/**
	 * A text control that behaves like a link: a {@link JLabel} in {@code base}, repainted in {@code hover}
	 * while the mouse is over it, with a hand cursor and a press that runs {@code onClick} (N section 7).
	 * The sort word-button, the band button, "Refresh" and "Show 279 more" are all this.
	 *
	 * <p>A label rather than a borderless {@code JButton} for the same reason {@link #segment} is: under the
	 * client's look and feel a button paints a ground of its own choosing, and every one of these sits
	 * directly on the sidebar's ground.
	 *
	 * <p>The two colours are stored on the label so {@link #setLinkColors} can re-tint a link whose meaning
	 * has changed - without the next mouse-exit painting the old colour back. The Ticker sidebar never re-tints
	 * one (its band button states its band in words instead, N 4.4 control 3, and
	 * {@code BankPriceMovementPanelTest} pins that button in the ordinary text colour with a band set); the
	 * mechanism is kept because it is the only correct way to change a link's resting colour.
	 */
	static JLabel linkLabel(String text, Font font, Color base, Color hover, @Nullable Runnable onClick)
	{
		final JLabel link = new JLabel(text == null ? "" : text);
		link.setFont(font);
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setLinkColors(link, base, hover);
		link.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (onClick != null && isPress(e))
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				link.setForeground(linkColor(link, KEY_LINK_HOVER, ColorScheme.BRAND_ORANGE));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				link.setForeground(linkColor(link, KEY_LINK_BASE, ColorScheme.LIGHT_GRAY_COLOR));
			}
		});
		return link;
	}

	/**
	 * Re-tints a link made by {@link #linkLabel}: paints it {@code base} now and remembers both colours for
	 * the hover, so the next mouse-exit paints the NEW resting colour. Safe on any label - one that was never a
	 * link simply gains the two properties. {@link #linkLabel} itself calls this to record the pair.
	 */
	static void setLinkColors(JLabel link, Color base, Color hover)
	{
		link.putClientProperty(KEY_LINK_BASE, base);
		link.putClientProperty(KEY_LINK_HOVER, hover);
		link.setForeground(base);
	}

	private static Color linkColor(JLabel link, String key, Color fallback)
	{
		final Object colour = link.getClientProperty(key);
		return colour instanceof Color ? (Color) colour : fallback;
	}

	/**
	 * Whether a mouse-down is a PRESS of the control under it: the left button, and not the platform's popup
	 * trigger. Every clickable label in the sidebar - {@link #segment}, {@link #linkLabel}, the panel's icon
	 * buttons - asks this before acting, because the hero card answers a right-click with its own menu
	 * (Refresh and the three show / hide items, N 3.1, O4) and keeps its window chips and its "Refresh" link
	 * INSIDE that card: without the gate a right-click on "7d" would switch the window AND open the menu.
	 *
	 * <p>Both halves are needed. Windows raises the popup trigger on the RELEASE, so on the press only the
	 * button tells; macOS raises it on a ctrl-click of the LEFT button, so there only the trigger tells.
	 * {@code MaterialTab} (the idiom the segment borrows) has no such gate, but no {@code MaterialTab} sits
	 * inside a component with a popup menu.
	 */
	static boolean isPress(MouseEvent e)
	{
		return SwingUtilities.isLeftMouseButton(e) && !e.isPopupTrigger();
	}

	/**
	 * A 7 px code-drawn triangle in the brand colour - the sort direction on the active sort chip (contract
	 * C29). Drawn rather than typed because the bitmap RuneScape fonts have no triangle glyph (playbook 7.5).
	 *
	 * @param down true for descending (point down), false for ascending (point up)
	 */
	static ImageIcon triangle(boolean down)
	{
		return triangle(down, TRIANGLE_SIZE, ColorScheme.BRAND_ORANGE);
	}

	/**
	 * {@link #triangle(boolean)} at a chosen size and colour (addendum N section 7). Same geometry, so the
	 * one-argument call above still draws exactly the icon it drew before this overload existed - a test
	 * compares the two images pixel for pixel.
	 *
	 * @param down   true to point down (descending / "open this menu"), false to point up
	 * @param size   the square icon's side in px; anything under 3 is raised to 3, below which the 1 px
	 *               inset would invert the path
	 * @param colour the fill
	 */
	static ImageIcon triangle(boolean down, int size, Color colour)
	{
		final int s = Math.max(3, size);
		return icon(s, s, g ->
		{
			g.setColor(colour);
			final Path2D p = new Path2D.Double();
			if (down)
			{
				p.moveTo(0, 1);
				p.lineTo(s, 1);
				p.lineTo(s / 2.0, s - 1);
			}
			else
			{
				p.moveTo(0, s - 1);
				p.lineTo(s, s - 1);
				p.lineTo(s / 2.0, 1);
			}
			p.closePath();
			g.fill(p);
		});
	}

	/** The 7 px triangle pointing down, in a colour of the caller's choosing (N section 5). */
	static ImageIcon triangleDown(Color colour)
	{
		return triangle(true, TRIANGLE_SIZE, colour);
	}

	/** The 7 px triangle pointing up, in a colour of the caller's choosing (N section 5). */
	static ImageIcon triangleUp(Color colour)
	{
		return triangle(false, TRIANGLE_SIZE, colour);
	}

	/**
	 * The 11 px "x" that clears both gp bounds in the price fold (addendum N section 3.5). Two strokes, not
	 * the letter: at 11 px a typed x in the bitmap face is a smudge, and the cross has to read as a control.
	 */
	static ImageIcon clearIcon(Color colour)
	{
		final int s = 11;
		return icon(s, s, g ->
		{
			g.setColor(colour);
			g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(2, 2, s - 3, s - 3);
			g.drawLine(s - 3, 2, 2, s - 3);
		});
	}

	/**
	 * The mark on a sort-menu entry (addendum N section 3.4): a filled 7 px {@code BRAND_ORANGE} dot on the
	 * ordering in force, a 5 px {@code LIGHT_GRAY} ring on the other five. Both are drawn into the same 7 px
	 * box so the six labels line up, and neither depends on the look-and-feel's radio-button mark - which is
	 * why these are plain {@code JMenuItem}s and not {@code JRadioButtonMenuItem}s.
	 */
	static ImageIcon dotIcon(boolean filled)
	{
		final int s = TRIANGLE_SIZE;
		return icon(s, s, g ->
		{
			if (filled)
			{
				g.setColor(ColorScheme.BRAND_ORANGE);
				g.fill(new Ellipse2D.Double(0, 0, s, s));
				return;
			}

			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g.setStroke(new BasicStroke(1f));
			g.draw(new Ellipse2D.Double(1.5, 1.5, s - 3.0, s - 3.0));
		});
	}

	/**
	 * The options gear (addendum Q, line Q1): a ring with {@value #GEAR_TEETH} teeth and a HOLE through the
	 * middle, drawn in code at the size and colour the caller asks for - {@code LIGHT_GRAY} at rest on the hero
	 * card's total line, {@code BRAND_ORANGE} under the mouse. Drawn and not loaded, exactly as
	 * {@link NavIcon} draws the sidebar button, because the bitmap RuneScape faces have no gear glyph to type. (This
	 * package shipped no image files at all until 1.0.9; the only ones it carries now are the brands' own marks,
	 * {@link SupportLinks#markIcon}, which are not ours to redraw.)
	 *
	 * <p>The ring is a STROKE and not a filled disc, so the middle stays transparent and the glyph reads as a
	 * gear at 12 px rather than as a cogged blob; the teeth are eight round-capped spokes every 45 degrees,
	 * starting on the ring's own circle so each one is rooted inside the ring's metal and none of them reaches
	 * into the hole. Every length is a fraction of {@code size}, so the same shape comes out at any size.
	 *
	 * @param size   the square icon's side in px; anything under {@value #GEAR_MIN} is raised to it, below
	 *               which the hole closes and the teeth merge
	 * @param colour the ink; null falls back to the sidebar's quiet grey
	 */
	static ImageIcon gearIcon(int size, @Nullable Color colour)
	{
		final int s = Math.max(GEAR_MIN, size);
		return icon(s, s, g ->
		{
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the
			// last one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < GEAR_TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / GEAR_TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		});
	}

	/**
	 * Paints one code-drawn icon into an off-screen image with antialiasing on, and hands back an
	 * {@link ImageIcon} of it. A {@link BufferedImage} rather than a live {@code Icon} implementation so the
	 * drawing happens ONCE, headless, at build time - which is also what lets the tests paint every glyph in
	 * a JVM with no display.
	 */
	private static ImageIcon icon(int width, int height, Painter painter)
	{
		final BufferedImage img = new BufferedImage(Math.max(1, width), Math.max(1, height),
			BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			painter.paint(g);
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}

	/** What {@link #icon} hands its prepared {@link Graphics2D} to. */
	private interface Painter
	{
		void paint(Graphics2D g);
	}

	// ---------------------------------------------------------------- addendum N: the card border

	/**
	 * The hero card's border (addendum N section 3.1): a {@link #EDGE_WIDTH} px left edge in the move's
	 * colour over the card's padding. Re-set with {@code setBorder} whenever the move changes sign, which is
	 * why the edge is a border and not a painted rectangle - it survives every repaint the panel does not
	 * own.
	 *
	 * @param edge the edge colour; null, or {@code DARKER_GRAY} for a flat or absent move, makes the edge
	 *             invisible against the card without changing the card's width
	 */
	static Border card(Color edge)
	{
		return card(edge, CARD_INSETS);
	}

	/** {@link #card(Color)} with padding of the caller's choosing. */
	static Border card(Color edge, Insets padding)
	{
		final Insets in = padding == null ? CARD_INSETS : padding;
		return new CompoundBorder(
			new MatteBorder(0, EDGE_WIDTH, 0, 0, edge == null ? ColorScheme.DARKER_GRAY_COLOR : edge),
			new EmptyBorder(in.top, in.left, in.bottom, in.right));
	}

	/**
	 * A {@link FlatTextField} for a gp bound: small face, the sidebar's field colours, a thin border that
	 * {@link #markInvalid} turns red, and {@code placeholder} drawn in grey while the field is empty and not
	 * being typed in. The placeholder is painted by the field itself (see {@link PlaceholderField}) so it
	 * needs no look-and-feel support and never becomes part of the text.
	 */
	static PlaceholderField gpField(String placeholder)
	{
		return field(placeholder);
	}

	/**
	 * The box the Items list is searched through (1.0.9 part 4): exactly the look of {@link #gpField} - the
	 * small RuneScape face, the sidebar's field colours and the thin border - because it stands directly above the
	 * rows beside Min and Max and a box that looked different would read as a different kind of control. Both go
	 * through the one builder below, so the two can never drift apart. Nothing about it is numeric: it takes any
	 * text, and it has no invalid state to turn red.
	 *
	 * <p>Since 1.1.1 part X it is also the one box that carries a {@link ClearX}, a small "x" at its right end while it
	 * holds any text; the gp boxes ({@link #gpField}) never do.
	 */
	static PlaceholderField searchField(String placeholder)
	{
		final PlaceholderField f = field(placeholder);
		f.addClearX();
		return f;
	}

	/** The one builder behind {@link #gpField} and {@link #searchField}. */
	private static PlaceholderField field(String placeholder)
	{
		final PlaceholderField f = new PlaceholderField(placeholder);
		final JTextField tf = f.getTextField();
		tf.setFont(FontManager.getRunescapeSmallFont());
		tf.setForeground(ColorScheme.TEXT_COLOR);
		tf.setCaretColor(ColorScheme.TEXT_COLOR);
		f.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		f.setHoverBackgroundColor(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		markInvalid(f, false);
		return f;
	}

	/**
	 * A red ring on a field whose text did not parse (contract C29: "an invalid entry turns the field border
	 * red and leaves the filter unchanged"), the normal thin border otherwise. The inner padding keeps the text
	 * where {@code FlatTextField}'s own 10 px inset ({@code FlatTextField.java:64}) puts it.
	 */
	static void markInvalid(FlatTextField f, boolean invalid)
	{
		f.setBorder(new CompoundBorder(
			new LineBorder(invalid ? ColorScheme.PROGRESS_ERROR_COLOR : FIELD_BORDER, 1),
			new EmptyBorder(1, 9, 1, 3)));
	}

	/** Whether {@link #markInvalid} last painted {@code f} red. */
	static boolean isMarkedInvalid(FlatTextField f)
	{
		final Border b = f.getBorder();
		if (!(b instanceof CompoundBorder))
		{
			return false;
		}
		final Border outer = ((CompoundBorder) b).getOutsideBorder();
		return outer instanceof LineBorder && ColorScheme.PROGRESS_ERROR_COLOR.equals(((LineBorder) outer).getLineColor());
	}

	/**
	 * A {@link FlatTextField} that paints a grey placeholder over its (transparent) text field while the text
	 * is empty and the field is not focused. Painted in {@code paintChildren} after the children, so it sits
	 * above the text field whatever look and feel is installed; a Swing client property would need the
	 * look-and-feel's cooperation, which the client's does not give.
	 */
	static final class PlaceholderField extends FlatTextField
	{
		private final String placeholder;

		@Nullable
		private ClearX clear;

		PlaceholderField(String placeholder)
		{
			this.placeholder = placeholder == null ? "" : placeholder;
		}

		String placeholder()
		{
			return placeholder;
		}

		/** Whether the placeholder would be painted right now: empty and not being typed in. */
		boolean placeholderShowing()
		{
			return getText().isEmpty() && !getTextField().isFocusOwner();
		}

		/** The clear "x" this box carries (1.1.1 part X), or null: only the search box has one, never a gp bound. */
		@Nullable
		ClearX clearX()
		{
			return clear;
		}

		/**
		 * Puts a {@link ClearX} on the box's east side (the box lays out as a BorderLayout, the text field in the middle, so
		 * the text field is shortened by the x's width while it stands there and by nothing while it does not) and has the
		 * text's own document say when it stands: any text, and it shows; none, and it goes. Called once, by
		 * {@link Widgets#searchField}.
		 */
		void addClearX()
		{
			final ClearX x = new ClearX(this);
			clear = x;
			add(x, BorderLayout.EAST);
			getDocument().addDocumentListener(new DocumentListener()
			{
				@Override
				public void insertUpdate(DocumentEvent e)
				{
					x.sync();
				}

				@Override
				public void removeUpdate(DocumentEvent e)
				{
					x.sync();
				}

				@Override
				public void changedUpdate(DocumentEvent e)
				{
					x.sync();
				}
			});
			x.sync();
		}

		@Override
		protected void paintChildren(Graphics g)
		{
			super.paintChildren(g);
			if (!placeholderShowing() || placeholder.isEmpty())
			{
				return;
			}
			final JTextField tf = getTextField();
			final Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setFont(tf.getFont());
				g2.setColor(PLACEHOLDER_COLOR);
				final FontMetrics fm = g2.getFontMetrics();
				final Insets in = tf.getInsets();
				final int x = tf.getX() + in.left + 1;
				final int y = tf.getY() + (tf.getHeight() - fm.getHeight()) / 2 + fm.getAscent();
				g2.drawString(placeholder, x, y);
			}
			finally
			{
				g2.dispose();
			}
		}
	}

	/**
	 * The search box's clear "x" (1.1.1 part X, the user's ask): a plain x of two 1 px diagonals corner to corner of a
	 * {@value #GLYPH} x {@value #GLYPH} px box, in the grey the placeholder is painted in ({@link #PLACEHOLDER_COLOR}) at rest
	 * and white under the mouse, standing at the box's right end while the box holds any text and absent - taking no room - while
	 * it does not. Pressing it empties the box through the text's own document, so the list, the "n of m items" count and the
	 * bridge's echo follow as they do for a keystroke, and then gives the box the focus so the caret is in it and the next
	 * character typed is the first. It is drawn pixel by pixel and never typed, because the bitmap RuneScape faces box a
	 * character they lack (playbook 7.5).
	 *
	 * <p>The component is {@value #WIDTH} px wide - {@value #AIR_LEFT} px of air so the text never runs under the x, the glyph,
	 * and {@value #AIR_RIGHT} px of air - and as tall as the box's inside; with the box's 1 px line and 3 px of padding the
	 * glyph's right edge stands 5 px in from the box's right border, and it is centred between the box's top and bottom. The
	 * cursor stays the default (no hand).
	 */
	static final class ClearX extends JComponent
	{
		/** The glyph's side in px: the user's pick from 3, 4 and 5 px. */
		static final int GLYPH = 5;
		/** Air between the text field's right end and the glyph, so typed text never runs under it. */
		static final int AIR_LEFT = 3;
		/** Air between the glyph and the box's inner right edge (past the box's line and padding it is 5 px from the border). */
		static final int AIR_RIGHT = 1;
		/** The component's width: the glyph and its air. */
		static final int WIDTH = AIR_LEFT + GLYPH + AIR_RIGHT;

		private final PlaceholderField owner;
		private boolean hot;
		/** How many presses have asked the text field for the focus: what a headless JVM, with no focus owner, can read instead. */
		int focusRequests;

		ClearX(PlaceholderField owner)
		{
			this.owner = owner;
			setOpaque(false);
			setFocusable(false);
			setVisible(false);
			setPreferredSize(new Dimension(WIDTH, GLYPH));
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (isPress(e))
					{
						press();
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					setHot(true);
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					setHot(false);
				}
			});
		}

		/** The x is drawn white while the mouse is on it. */
		private void setHot(boolean on)
		{
			if (hot != on)
			{
				hot = on;
				repaint();
			}
		}

		/**
		 * The press: empties the box - through the text's own document, the road a keystroke and Escape take - and then asks the
		 * text field for the focus. The x goes with the text, from {@link #sync}.
		 */
		void press()
		{
			owner.setText("");
			focusRequests++;
			owner.getTextField().requestFocusInWindow();
		}

		/**
		 * Shows the x while the box holds any text and hides it while it is empty; a layout follows either way, because the
		 * text field's room is the box's width less the x's while it stands. An x that goes is no longer under the mouse as far
		 * as it knows.
		 */
		void sync()
		{
			final boolean show = !owner.getText().isEmpty();
			if (show == isVisible())
			{
				return;
			}
			if (!show)
			{
				hot = false;
			}
			setVisible(show);
			owner.revalidate();
			owner.repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			final Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
				g2.setColor(hot ? Color.WHITE : PLACEHOLDER_COLOR);
				final int top = (getHeight() - GLYPH) / 2;
				for (int i = 0; i < GLYPH; i++)
				{
					g2.fillRect(AIR_LEFT + i, top + i, 1, 1);
					g2.fillRect(AIR_LEFT + GLYPH - 1 - i, top + i, 1, 1);
				}
			}
			finally
			{
				g2.dispose();
			}
		}
	}

	// ---------------------------------------------------------------- layout

	/**
	 * Pins a component's width and height. The width rule only holds if the components that could grow -
	 * icons, fields, chips - are pinned, because a column stretches its rows to the widest one and the panel's
	 * scroll pane never scrolls sideways.
	 */
	static <T extends JComponent> T fixed(T c, int width, int height)
	{
		final Dimension d = new Dimension(width, height);
		c.setPreferredSize(d);
		c.setMinimumSize(d);
		c.setMaximumSize(d);
		return c;
	}

	/** A vertical stack (top to bottom, full width) on the panel background, 3 px between rows. */
	static JPanel column()
	{
		return column(3);
	}

	/**
	 * {@link #column()} with a chosen gap. {@link DynamicGridLayout} gives every row its preferred height and
	 * scales widths to the column's own width ({@code DynamicGridLayout.java:97-113}), which is what lets a
	 * 213 px design fill the 225 or 242 px the sidebar actually has.
	 */
	static JPanel column(int vgap)
	{
		final JPanel p = new JPanel();
		p.setLayout(new DynamicGridLayout(0, 1, 0, vgap));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return p;
	}

	/** One line: something on the left, something filling the middle, something on the right. Any may be null. */
	static JPanel bar(int gap, @Nullable JComponent west, @Nullable JComponent centre, @Nullable JComponent east)
	{
		final JPanel p = new JPanel(new BorderLayout(gap, 0));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		if (west != null)
		{
			p.add(west, BorderLayout.WEST);
		}
		if (centre != null)
		{
			p.add(centre, BorderLayout.CENTER);
		}
		if (east != null)
		{
			p.add(east, BorderLayout.EAST);
		}
		return p;
	}

	/** Equal-width cells in one line, for the chip rows. */
	static JPanel grid(int gap, JComponent... items)
	{
		final JPanel p = new JPanel(new GridLayout(1, items.length, gap, 0));
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		for (JComponent c : items)
		{
			p.add(c);
		}
		return p;
	}

	/**
	 * Anchors {@code c} to the top of a BorderLayout holder. A scroll pane stretches a plain view to its
	 * viewport ({@code javax.swing.ViewportLayout}), and {@link DynamicGridLayout} would then scale every row
	 * TALLER to fill it; anchored north, the column keeps its rows' heights and the holder takes the slack.
	 */
	static JPanel north(JComponent c)
	{
		final JPanel holder = new JPanel(new BorderLayout());
		holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		holder.add(c, BorderLayout.NORTH);
		return holder;
	}

	/**
	 * The width the widest row inside {@code c} asks for, in px: the width rule measured rather than trusted.
	 * Descends into nested columns (their own preferred width is only their widest row) and takes every other
	 * child at its preferred width - a chip row counts as its three chips plus gaps, which is exactly the
	 * width its cells need.
	 */
	static int widest(Container c)
	{
		int w = 0;
		for (Component child : c.getComponents())
		{
			if (child instanceof JPanel && ((JPanel) child).getLayout() instanceof DynamicGridLayout)
			{
				w = Math.max(w, widest((Container) child));
			}
			else
			{
				w = Math.max(w, child.getPreferredSize().width);
			}
		}
		return w;
	}
}

package com.bankpricemovement;

import java.io.IOException;

/**
 * The single failure type every {@link GuidePriceClient} future completes exceptionally with (contract C14/C15,
 * carried forward unchanged by K5: "keep {@code WikiPriceException}").
 *
 * <p>It extends {@link IOException} on purpose: the injected OkHttpClient already signals every one of its own
 * refusals as a plain {@code IOException} through {@code Callback.onFailure} - "Blocking network calls are not
 * allowed on the client thread", "...on the event dispatch thread" and "Network call to ... blocked outside of
 * LIVE environment" are all raised by the interceptor at
 * {@code runelite-client/src/main/java/net/runelite/client/RuneLiteModule.java:182-205} (clone tag
 * runelite-parent-1.12.37). Wrapping HTTP failures, wiki {@code {"error": ...}} bodies and malformed JSON in one
 * IOException subtype lets {@code PriceService} catch a single type and never string-match a message
 * (research C4 precision 1: "handle IOException generally and never string-match").</p>
 *
 * <p>{@link #getHttpCode()} is {@link #NO_HTTP_CODE} (0) whenever the failure happened without a status line -
 * a transport {@code IOException}, a malformed body, or an {@code {"error": ...}} body that arrived with HTTP 200
 * (MediaWiki reports every API error that way, and the prices API did the same for a misaligned timestamp -
 * research C10 addition 2 - so the code alone can never be the failure test).</p>
 */
public class WikiPriceException extends IOException
{
	private static final long serialVersionUID = 1L;

	/**
	 * The {@link #getHttpCode()} value meaning "this failure carries no HTTP status" - a transport error, a body
	 * that would not parse, or an error body that arrived with a 2xx status.
	 */
	public static final int NO_HTTP_CODE = 0;

	private final int httpCode;

	public WikiPriceException(final String message)
	{
		this(message, NO_HTTP_CODE, null);
	}

	public WikiPriceException(final String message, final int httpCode)
	{
		this(message, httpCode, null);
	}

	public WikiPriceException(final String message, final Throwable cause)
	{
		this(message, NO_HTTP_CODE, cause);
	}

	public WikiPriceException(final String message, final int httpCode, final Throwable cause)
	{
		super(message, cause);
		this.httpCode = httpCode;
	}

	/**
	 * The HTTP status the wiki answered with, or {@link #NO_HTTP_CODE} when the failure carried no status line.
	 * 403 is the one worth branching on: the prices API pre-emptively blocks default user agents (research C3),
	 * so a 403 means the User-Agent never reached it, not that the item data is missing.
	 */
	public int getHttpCode()
	{
		return httpCode;
	}

	/**
	 * True when {@link #getHttpCode()} is a real status. Kept separate from {@code getHttpCode() != 0} so callers
	 * do not have to know that 0 is the sentinel.
	 */
	public boolean hasHttpCode()
	{
		return httpCode != NO_HTTP_CODE;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * The whole bank's guide-price move over ONE window, on a consistent basis (addendum M, line M1/M2;
 * {@code docs/bank-price-movement-addendum-M-2026-09-09.md}): only the stacks priced on BOTH days count, so
 * {@link #valueThen()} and {@link #valueNowCovered()} are sums over the same stacks and their difference is a real
 * move rather than the arrival or departure of a price. {@link #itemsCovered()} says how many stacks that was, and
 * the panel shows it beside {@code itemsPriced} so a reader can see when a window's coverage is thin.
 *
 * <p>Since addendum P line P1 the bank's cash ({@link BankSnapshot#currencyGp}) sits inside {@link #valueThen()} and
 * {@link #valueNowCovered()} alike, so {@link #deltaGp()} is exactly what it always was and {@link #deltaPct()} is
 * measured against the whole bank. A window that covers no stack carries no cash and keeps its zeros - see
 * {@link PortfolioMath}, which computes all of this; this class stays a value holder.
 *
 * <p>Immutable, like {@link MovementRow}: built on the service's executor and read on the EDT and by the dev bridge.
 * Sums are {@code long} clamped at {@link Long#MAX_VALUE} by {@link PortfolioMath}, never wrapped.
 */
public final class WindowMove
{
	private final MovementWindow window;
	@Nullable
	private final LocalDate thenDay;
	private final long valueThen;
	private final long valueNowCovered;
	private final long deltaGp;
	@Nullable
	private final Double deltaPct;
	private final int itemsCovered;

	/**
	 * @param window          the window this move is measured over; null reads as {@link MovementWindow#DEFAULT}
	 * @param thenDay         the UTC day the window's baseline table claims (its own {@code %LAST_UPDATE%}, L7), or
	 *                        null when the baseline carries no day marker
	 * @param valueThen       the sum of {@code then x quantity} over the covered stacks plus the bank's cash (P1),
	 *                        clamped; the cash is left off when nothing is covered
	 * @param valueNowCovered the sum of {@code now x quantity} over the SAME stacks plus the same cash, clamped
	 * @param deltaGp         {@code valueNowCovered - valueThen}
	 * @param deltaPct        {@code deltaGp x 100 / valueThen}, or null when {@code valueThen} is 0 (M1)
	 * @param itemsCovered    how many stacks were priced on both days
	 */
	public WindowMove(@Nullable final MovementWindow window, @Nullable final LocalDate thenDay, final long valueThen,
		final long valueNowCovered, final long deltaGp, @Nullable final Double deltaPct, final int itemsCovered)
	{
		this.window = window == null ? MovementWindow.DEFAULT : window;
		this.thenDay = thenDay;
		this.valueThen = valueThen;
		this.valueNowCovered = valueNowCovered;
		this.deltaGp = deltaGp;
		this.deltaPct = deltaPct;
		this.itemsCovered = itemsCovered;
	}

	/** Never null. */
	public MovementWindow window()
	{
		return window;
	}

	/** The baseline table's own UTC day (L7), the day the tooltip prints ("1d vs 07 Sep"); null when unknown. */
	@Nullable
	public LocalDate thenDay()
	{
		return thenDay;
	}

	/** The covered stacks' worth at the baseline day's guide prices, plus the bank's cash (P1). */
	public long valueThen()
	{
		return valueThen;
	}

	/**
	 * The SAME stacks' worth at today's guide prices, plus the same cash - still not the whole bank's
	 * {@link PortfolioSummary#valueNow()}, which counts every priced stack rather than only the covered ones.
	 */
	public long valueNowCovered()
	{
		return valueNowCovered;
	}

	/**
	 * {@link #valueNowCovered()} minus {@link #valueThen()}; the sign that colours the line (L2). The cash cancels,
	 * so this is the covered stacks' move and nothing else (P1).
	 */
	public long deltaGp()
	{
		return deltaGp;
	}

	/**
	 * The move as a percentage of {@link #valueThen()} - cash included in that base since P1 - untruncated; null
	 * when nothing was worth anything then, which is also the case of a window that covers no stack at all.
	 */
	@Nullable
	public Double deltaPct()
	{
		return deltaPct;
	}

	/** How many stacks were priced on both days - the basis of the three sums. */
	public int itemsCovered()
	{
		return itemsCovered;
	}

	@Override
	public boolean equals(final Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof WindowMove))
		{
			return false;
		}
		final WindowMove other = (WindowMove) o;
		return window == other.window
			&& Objects.equals(thenDay, other.thenDay)
			&& valueThen == other.valueThen
			&& valueNowCovered == other.valueNowCovered
			&& deltaGp == other.deltaGp
			&& Objects.equals(deltaPct, other.deltaPct)
			&& itemsCovered == other.itemsCovered;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(window, thenDay, valueThen, valueNowCovered, deltaGp, deltaPct, itemsCovered);
	}

	@Override
	public String toString()
	{
		return "WindowMove{window=" + window.name()
			+ ", thenDay=" + thenDay
			+ ", valueThen=" + valueThen
			+ ", valueNowCovered=" + valueNowCovered
			+ ", deltaGp=" + deltaGp
			+ ", deltaPct=" + deltaPct
			+ ", itemsCovered=" + itemsCovered + '}';
	}
}

package com.bankpricemovement;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * {@link BandPresets} (addendum Z line Z1): the immutable carrier of the fold's three quick bands, the pure half
 * of the gear menu's three boxes, of the {@code bandPresets} config line and of the {@code presets=} dev verb.
 *
 * <p>Four groups: what the DEFAULT is (the trio the fold has drawn since addendum N, so a profile that never
 * touches the new line sees today's chips byte for byte), what {@link BandPresets#parse(String)} reads, the three
 * refusals - not three values, not positive, not distinct - and what the value writes back out.
 */
public class BandPresetsTest
{
	/** The trio {@code PRESET_MINS} held before addendum Z made it a config line. */
	@Test
	public void theDefaultIsTheTrioTheFoldHasAlwaysDrawn()
	{
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L}, BandPresets.DEFAULT.mins());
		assertEquals("100k, 1m, 10m", BandPresets.DEFAULT.format());
		assertEquals("the config line's default parses back to the default", BandPresets.DEFAULT,
			BandPresets.parse("100k, 1m, 10m"));
	}

	/**
	 * Z1 pins these three strings: they are what the fold's chips have read since addendum N, and a default
	 * profile must draw the W pictures byte for byte.
	 */
	@Test
	public void theDefaultLabelsAreExactlyTheChipsTheFoldDraws()
	{
		assertArrayEquals(new String[]{"100k+", "1m+", "10m+"}, BandPresets.DEFAULT.labels());
	}

	/** Every shorthand {@code MovementMath.parseGp} takes - the Min / Max fields' own reader - works here too. */
	@Test
	public void parseReadsEveryGpShorthandTheBandFieldsRead()
	{
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L},
			BandPresets.parse("100k, 1m, 10m").mins());
		assertArrayEquals("upper case suffixes are the same suffixes",
			new long[]{100_000L, 1_000_000L, 10_000_000L}, BandPresets.parse("100K, 1M, 10M").mins());
		assertArrayEquals("a fraction and a billion", new long[]{1_500_000L, 100_000_000L, 2_000_000_000L},
			BandPresets.parse("1.5m, 100m, 2b").mins());
		assertArrayEquals("bare gp, under the shorthand threshold", new long[]{850L, 1_000L, 9_999L},
			BandPresets.parse("850, 1000, 9999").mins());
	}

	/** Z1's three separators, and any run of them - so ", " is one gap and not a gap with an empty band in it. */
	@Test
	public void parseSplitsOnCommasSlashesAndWhitespace()
	{
		final long[] expected = {100_000L, 1_000_000L, 10_000_000L};
		final String[] lines =
		{
			"100k, 1m, 10m",
			"100k,1m,10m",
			"100k/1m/10m",
			"100k / 1m / 10m",
			"100k 1m 10m",
			"100k\t1m\n10m",
			"  100k ,  1m ,  10m  ",
			", 100k, 1m, 10m",
		};

		for (final String line : lines)
		{
			final BandPresets parsed = BandPresets.parse(line);
			assertEquals("'" + line + "' should have parsed", BandPresets.DEFAULT, parsed);
			assertArrayEquals("'" + line + "'", expected, parsed.mins());
		}
	}

	/**
	 * The one comma that is NOT a separator: the thousands grouping comma of "1,000", which
	 * {@code MovementMath.parseGp} reads as part of the number. Without this rule a band under 10,000 could be
	 * typed but never read back, since {@link BandPresets#format()} writes those with grouping commas itself.
	 */
	@Test
	public void parseKeepsAThousandsGroupingCommaInsideOneBand()
	{
		final long[] small = {1_000L, 2_000L, 3_000L};
		assertArrayEquals(small, BandPresets.parse("1,000 2,000 3,000").mins());
		assertArrayEquals(small, BandPresets.parse("1,000, 2,000, 3,000").mins());
		assertArrayEquals(small, BandPresets.parse("1,000/2,000/3,000").mins());

		// A comma between digits that does NOT introduce a group of exactly three is still a separator.
		assertArrayEquals(new long[]{1_000L, 2_000L, 30_000L}, BandPresets.parse("1000,2000,30000").mins());
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 1_234_567L},
			BandPresets.parse("1,234,567 1m 100k").mins());
	}

	/** Z1: the trio is held ascending however it was typed, so the chips read smallest first. */
	@Test
	public void parseSortsWhateverOrderItIsGiven()
	{
		final long[] expected = {100_000L, 1_000_000L, 10_000_000L};
		assertArrayEquals(expected, BandPresets.parse("10m, 1m, 100k").mins());
		assertArrayEquals(expected, BandPresets.parse("1m, 10m, 100k").mins());
		assertArrayEquals(expected, BandPresets.parse("10m 100k 1m").mins());
		assertEquals("100k, 1m, 10m", BandPresets.parse("10m, 1m, 100k").format());
	}

	/** Refusal one: a line that does not name exactly three bands - including no line at all. */
	@Test
	public void parseRefusesAnythingButThreeValues()
	{
		final String[] wrong = {null, "", "   ", "100k", "100k, 1m", "100k, 1m, 10m, 100m", "1 2 3 4 5"};

		for (final String line : wrong)
		{
			assertNull("'" + line + "' should have been refused", BandPresets.parse(line));
		}
	}

	/** Refusal two: a band that is not a price. A zero would admit every row and is not a band at all. */
	@Test
	public void parseRefusesAValueThatIsNotPositive()
	{
		assertNull(BandPresets.parse("0, 1m, 10m"));
		assertNull(BandPresets.parse("100k, 0, 10m"));
		assertNull(BandPresets.parse("100k, 1m, 0"));
		// parseGp itself refuses a negative (a price cannot be negative), so this arrives as unreadable text.
		assertNull(BandPresets.parse("-1, 1m, 10m"));
		assertNull(BandPresets.parse("100k, -1m, 10m"));
	}

	/** Refusal three: two equal bands would draw two identical chips, only one of which could ever light. */
	@Test
	public void parseRefusesTwoBandsTheSame()
	{
		assertNull(BandPresets.parse("1m, 1m, 10m"));
		assertNull(BandPresets.parse("100k, 1m, 100k"));
		assertNull(BandPresets.parse("1m, 10m, 10m"));
		assertNull("the same amount written two ways is still the same amount",
			BandPresets.parse("1m, 1000000, 10m"));
	}

	/** A part that names no number refuses the whole line: half a trio is never half applied. */
	@Test
	public void parseRefusesTextThatNamesNoNumber()
	{
		final String[] rubbish = {"abc", "100k, abc, 10m", "100k, 1.5x, 10m", "k, m, b", "100k, 1e6, 10m"};

		for (final String line : rubbish)
		{
			assertNull("'" + line + "' should have been refused", BandPresets.parse(line));
		}
	}

	/**
	 * {@link BandPresets#of(long, long, long)} sorts, and enforces the same invariant {@link
	 * BandPresets#parse(String)} does - by throwing, because a caller holding three longs has already done the
	 * reading. A panel reading three boxes catches this beside the boxes' own {@code ParseException}.
	 */
	@Test
	public void ofSortsAndRefusesWhatParseRefuses()
	{
		assertEquals(BandPresets.DEFAULT, BandPresets.of(10_000_000L, 100_000L, 1_000_000L));
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L},
			BandPresets.of(1_000_000L, 10_000_000L, 100_000L).mins());

		final long[][] refused =
		{
			{0L, 1_000_000L, 10_000_000L},
			{100_000L, -1L, 10_000_000L},
			{1_000_000L, 1_000_000L, 10_000_000L},
			{100_000L, 10_000_000L, 100_000L},
		};

		for (final long[] trio : refused)
		{
			try
			{
				fail(Arrays.toString(trio) + " should not have built a trio, gave "
					+ BandPresets.of(trio[0], trio[1], trio[2]));
			}
			catch (IllegalArgumentException expected)
			{
				assertTrue("the refusal names the three values: " + expected.getMessage(),
					expected.getMessage().contains(String.valueOf(trio[0])));
			}
		}
	}

	/** Z1: a label is the band in gp shorthand plus the "+" that says "and everything dearer". */
	@Test
	public void aLabelIsTheBandInShorthandWithAPlus()
	{
		assertArrayEquals(new String[]{"1.5m+", "100m+", "2b+"},
			BandPresets.of(1_500_000L, 100_000_000L, 2_000_000_000L).labels());
		assertArrayEquals("under 10,000 the game writes every digit, so the label does too",
			new String[]{"1,000+", "2,000+", "30k+"}, BandPresets.of(1_000L, 2_000L, 30_000L).labels());
	}

	/** What the config line holds is what the value reads back: the round trip is the whole point of format(). */
	@Test
	public void formatRoundTripsThroughParse()
	{
		final BandPresets[] trios =
		{
			BandPresets.DEFAULT,
			BandPresets.of(1_000_000L, 10_000_000L, 100_000_000L),
			BandPresets.of(1_500_000L, 100_000_000L, 2_000_000_000L),
			BandPresets.of(500_000L, 5_000_000L, 50_000_000L),
			BandPresets.of(10_000L, 100_000L, 1_000_000L),
		};

		for (final BandPresets trio : trios)
		{
			assertEquals(trio.format(), trio, BandPresets.parse(trio.format()));
		}

		assertEquals("1.5m, 100m, 2b", BandPresets.of(2_000_000_000L, 1_500_000L, 100_000_000L).format());
	}

	/**
	 * The round trip has to survive the commas {@link BandPresets#format()} writes itself: a band under 10,000 is
	 * spelled "1,000" rather than "1k", so a blind split on commas would refuse the line the value had just
	 * written.
	 */
	@Test
	public void formatRoundTripsEvenWhenABandIsWrittenWithGroupingCommas()
	{
		final BandPresets small = BandPresets.of(1_000L, 2_000L, 3_000L);
		assertEquals("1,000, 2,000, 3,000", small.format());
		assertEquals(small, BandPresets.parse(small.format()));
	}

	/**
	 * Shorthand is lossy where the game's own stack text is lossy, and the boxes print shorthand: a band of
	 * 1,234,567 gp is written "1.23m" and comes back as 1,230,000. Pinned because it is the one case where the
	 * round trip does NOT return the same trio, and because the boxes re-print what was saved.
	 */
	@Test
	public void formatIsShorthandAndRoundsABandItCannotWriteExactly()
	{
		final BandPresets odd = BandPresets.of(1_234_567L, 1_000_000L, 10_000_000L);
		assertEquals("1m, 1.23m, 10m", odd.format());

		final BandPresets returned = BandPresets.parse(odd.format());
		assertNotEquals("the odd band does not survive the shorthand", odd, returned);
		assertArrayEquals(new long[]{1_000_000L, 1_230_000L, 10_000_000L}, returned.mins());
		// What a user typed IS read exactly; only what format() wrote is rounded.
		assertArrayEquals(new long[]{1_000_000L, 1_234_567L, 10_000_000L},
			BandPresets.parse("1,234,567, 1m, 10m").mins());
	}

	/** The value is immutable, so the two arrays it hands out are copies and not its insides. */
	@Test
	public void minsAndLabelsAreFreshArraysTheCallerCannotMutate()
	{
		final long[] mins = BandPresets.DEFAULT.mins();
		mins[0] = 42L;
		assertArrayEquals(new long[]{100_000L, 1_000_000L, 10_000_000L}, BandPresets.DEFAULT.mins());

		final String[] labels = BandPresets.DEFAULT.labels();
		labels[2] = "wrong";
		assertArrayEquals(new String[]{"100k+", "1m+", "10m+"}, BandPresets.DEFAULT.labels());
	}

	/** Value semantics, so the panel can tell an incoming trio from the one it is already drawing. */
	@Test
	public void equalTriosAreEqualWhateverOrderTheyWereBuiltIn()
	{
		final BandPresets a = BandPresets.of(100_000L, 1_000_000L, 10_000_000L);
		final BandPresets b = BandPresets.of(10_000_000L, 100_000L, 1_000_000L);

		assertEquals(a, b);
		assertEquals(a.hashCode(), b.hashCode());
		assertEquals(a, BandPresets.DEFAULT);
		assertNotEquals(a, BandPresets.of(100_000L, 1_000_000L, 100_000_000L));
		assertNotEquals(a, null);
		assertNotEquals(a, "100k, 1m, 10m");
		assertEquals(a, a);

		final Set<BandPresets> seen = new HashSet<>();
		assertTrue(seen.add(a));
		assertFalse("an equal trio is the same key", seen.add(b));
		assertTrue(seen.add(BandPresets.of(1_000_000L, 10_000_000L, 100_000_000L)));
	}

	/** {@code toString} is a debugging line and prints gp, not the shorthand a log would have to un-round. */
	@Test
	public void toStringNamesTheThreeBandsInGp()
	{
		final String text = BandPresets.DEFAULT.toString();
		assertTrue(text, text.contains("BandPresets"));
		assertTrue(text, text.contains("100000"));
		assertTrue(text, text.contains("1000000"));
		assertTrue(text, text.contains("10000000"));
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static com.bankpricemovement.BankHistoryChartTest.paint;
import static com.bankpricemovement.BankHistoryMountainTest.assertSameImage;
import static com.bankpricemovement.BankHistoryMountainTest.dated;
import static com.bankpricemovement.BankHistoryMountainTest.lineY;
import static com.bankpricemovement.BankHistoryMountainTest.near;
import static com.bankpricemovement.BankHistoryMountainTest.ys;
import static com.bankpricemovement.BankHistoryViewTest.press;
import static com.bankpricemovement.BankHistoryViewTest.rangeCell;
import static com.bankpricemovement.HistoryViewRenderer.HOVER_DAY;
import static com.bankpricemovement.HistoryViewRenderer.TODAY;
import static com.bankpricemovement.HistoryViewRenderer.chart;
import static com.bankpricemovement.HistoryViewRenderer.fixture;
import static com.bankpricemovement.HistoryViewRenderer.hover;
import static com.bankpricemovement.HistoryViewRenderer.indexOf;
import static com.bankpricemovement.HistoryViewRenderer.layOut;
import static com.bankpricemovement.HistoryViewRenderer.view;
import static com.bankpricemovement.MovementRowPanelTest.onEdt;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The mountain chart's pins added after the review and mutation pass of 2026-09-29: the first of two equal readings
 * takes the high (and the low), new data at the same size lays the chart out again, the hover ring takes the line's
 * colour, the fill's alpha is 70 on a rise and 80 on a fall, and the last point stands where the target puts it.
 */
public class BankHistoryChartPinsTest
{
	/** Two readings share the range's highest total: the FIRST of them carries the high's mark. */
	@Test
	public void theFirstOfTwoEqualHighsTakesTheMark() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView view = view(dated(6, 700, 4, 500, 2, 700, 0, 600), BankHistoryRange.D7);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			final List<BankHistoryChart.Figure> figures = chart.figures();
			assertEquals(2, figures.size());
			assertEquals("700m", figures.get(0).text);
			assertEquals("the high is the first 700m", TODAY.minusDays(6), chart.days().get(figures.get(0).index).day());
		});
	}

	/** Two readings share the range's lowest total: the FIRST of them carries the low's mark. */
	@Test
	public void theFirstOfTwoEqualLowsTakesTheMark() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView view = view(dated(6, 500, 4, 800, 2, 500, 0, 700), BankHistoryRange.D7);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			final List<BankHistoryChart.Figure> figures = chart.figures();
			assertEquals(2, figures.size());
			assertEquals("500m", figures.get(1).text);
			assertEquals("the low is the first 500m", TODAY.minusDays(6), chart.days().get(figures.get(1).index).day());
		});
	}

	/**
	 * A press on the range bar hands the chart new days at the SAME size: it lays them out again rather than painting
	 * them on the old range's coordinates - 7d to 30d (more days than the old layout had) and back (fewer).
	 */
	@Test
	public void newDataAtTheSameSizeIsLaidOutAgain() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryRange[][] moves = {{BankHistoryRange.D7, BankHistoryRange.D30},
				{BankHistoryRange.D30, BankHistoryRange.D7}};
			for (BankHistoryRange[] move : moves)
			{
				final BankHistoryView view = view(fixture(), move[0]);
				layOut(view, 213);
				final BankHistoryChart chart = chart(view);
				paint(chart);
				final int size = chart.getWidth() * 1000 + chart.getHeight();
				press(rangeCell(view, move[1]));
				assertEquals("the premise: the chart keeps its size", size, chart.getWidth() * 1000 + chart.getHeight());
				final BankHistoryView fresh = view(fixture(), move[1]);
				layOut(fresh, 213);
				assertEquals(chart(fresh).days().size(), chart.days().size());
				assertSameImage(move[0] + " then " + move[1], paint(chart(fresh)), paint(chart));
				assertEquals(chart(fresh).figures().get(0).left, chart.figures().get(0).left);
				assertEquals(chart(fresh).figures().get(1).index, chart.figures().get(1).index);
			}
		});
	}

	/** The hover ring is stroked in the line's colour round a disc of the card grey - green on a rise, red on a fall. */
	@Test
	public void theHoverRingTakesTheLinesColour() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView rise = view(fixture(), BankHistoryRange.D30);
			layOut(rise, 213);
			final BankHistoryChart up = chart(rise);
			assertRing(up, indexOf(up, HOVER_DAY), ColorScheme.PROGRESS_COMPLETE_COLOR);

			final BankHistoryView fall = view(dated(6, 900, 4, 880, 2, 700, 0, 690), BankHistoryRange.D7);
			layOut(fall, 213);
			final BankHistoryChart down = chart(fall);
			assertEquals("the premise: a fall", Widgets.MOVE_DOWN_TEXT, down.lineColour());
			assertRing(down, 2, Widgets.MOVE_DOWN_TEXT);
		});
	}

	/** The fill's tint under the line's highest point: alpha 70 on a rise, 80 on a fall, fading to 0 at the bottom. */
	@Test
	public void theFillIsAlpha70OnARiseAnd80OnAFall() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView rise = view(fixture(), BankHistoryRange.D30);
			layOut(rise, 213);
			assertFillAlpha(chart(rise), ColorScheme.PROGRESS_COMPLETE_COLOR, BankHistoryChart.FILL_ALPHA);
			assertEquals(70, BankHistoryChart.FILL_ALPHA);

			final BankHistoryView fall = view(dated(6, 900, 4, 880, 2, 700, 0, 690), BankHistoryRange.D7);
			layOut(fall, 213);
			assertFillAlpha(chart(fall), Widgets.MOVE_DOWN_TEXT, BankHistoryChart.FILL_ALPHA_FALL);
			assertEquals(80, BankHistoryChart.FILL_ALPHA_FALL);
		});
	}

	/**
	 * The last point stands 9 px in from the chart's right edge: at 213 at x 204, so its 3 px dot ends on the range
	 * bar's right edge (207) and its 6 px halo 3 px inside the block; at 230 at x 221.
	 */
	@Test
	public void theLastPointStandsWhereTheTargetPutsIt()
	{
		assertEquals(204.0, BankHistoryChart.xAt(30, 31, 213), 1e-9);
		assertEquals(221.0, BankHistoryChart.xAt(7, 8, 230), 1e-9);
		assertEquals(6.0, BankHistoryChart.xAt(0, 31, 213), 1e-9);
		assertEquals("the dot ends on the bar's right edge", 207.0,
			BankHistoryChart.xAt(30, 31, 213) + BankHistoryChart.DOT_RADIUS, 1e-9);
		assertEquals("the halo ends 3 px inside the block", 213 - 3.0,
			BankHistoryChart.xAt(30, 31, 213) + BankHistoryChart.HALO_RADIUS, 1e-9);
	}

	// ---------------------------------------------------------------------------------------- helpers

	private static void assertRing(final BankHistoryChart chart, final int index, final Color expected)
	{
		assertTrue("the premise: a point to hover", index >= 0 && index != chart.readoutIndex());
		hover(chart, BankHistoryChartTest.x(chart, index));
		assertEquals("the premise: the hover is on it", index, chart.readoutIndex());
		final BufferedImage image = paint(chart);
		final double cx = BankHistoryChart.xAt(index, chart.days().size(), chart.getWidth());
		final double cy = ys(chart)[index];
		int ring = 0;
		int coloured = 0;
		for (int y = (int) cy - 7; y <= (int) cy + 7; y++)
		{
			for (int x = (int) cx - 7; x <= (int) cx + 7; x++)
			{
				final double r = Math.hypot(x + 0.5 - cx, y + 0.5 - cy);
				if (r >= 4.1 && r <= 4.9)
				{
					ring++;
					coloured += near(new Color(image.getRGB(x, y)), expected, 40) ? 1 : 0;
				}
			}
		}
		assertTrue("the ring is the line's colour: " + coloured + " of " + ring + " px", ring >= 20
			&& coloured * 4 >= ring * 3);
		assertEquals("inside the ring, the card grey", ColorScheme.DARKER_GRAY_COLOR.getRGB() & 0xFFFFFF,
			image.getRGB((int) Math.floor(cx), (int) Math.floor(cy)) & 0xFFFFFF);
	}

	private static void assertFillAlpha(final BankHistoryChart chart, final Color line, final int alpha)
	{
		final BufferedImage image = paint(chart);
		final double[] ys = ys(chart);
		int hi = 0;
		for (int i = 1; i < ys.length; i++)
		{
			hi = ys[i] < ys[hi] ? i : hi;
		}
		final double top = ys[hi];
		final int h = chart.getHeight();
		final int x = (int) Math.max(8, Math.min(chart.getWidth() - 12,
			Math.round(BankHistoryChart.xAt(hi, ys.length, chart.getWidth()))));
		final int y = (int) Math.ceil(lineY(chart, ys, x + 0.5) + 5);
		final double a = alpha * (1 - (y + 0.5 - top) / (h - top)) / 255.0;
		final Color card = ColorScheme.DARKER_GRAY_COLOR;
		final Color want = new Color((int) Math.round(card.getRed() + (line.getRed() - card.getRed()) * a),
			(int) Math.round(card.getGreen() + (line.getGreen() - card.getGreen()) * a),
			(int) Math.round(card.getBlue() + (line.getBlue() - card.getBlue()) * a));
		final Color got = new Color(image.getRGB(x, y));
		assertTrue("the fill at (" + x + ", " + y + ") is the line's colour at alpha " + alpha + " there: " + got
			+ " want " + want, near(got, want, 3));
	}
}

package com.bankpricemovement;

