/**
 * Addendum AU, builder C: the chart (plan 7.2 item 10) - a continuous line, the thinning above 120 points, and the
 * hover that moves the readout. Its look since 2026-09-29 - the mountain, the plain line, the high and the low - is
 * pinned by {@link BankHistoryMountainTest}.
 *
 * <p>The pixel tests paint the chart alone into an image on the card grey and read each column: how far its most-drawn
 * pixel is from the card grey.
 */
public class BankHistoryChartTest
{
	/** Greener than this: some line is drawn in the column. */
	private static final int INK = 25;

	@Test
	public void theLineIsContinuousEverySegmentIsDrawn() throws Exception
	{
		onEdt(() ->
		{
			for (BankHistoryRange range : BankHistoryRange.values())
			{
				final BankHistoryView view = view(fixture(), range);
				layOut(view, 213);
				final BankHistoryChart chart = chart(view);
				final BufferedImage image = paint(chart);
				final int n = chart.days().size();
				for (int i = 0; i + 1 < n; i++)
				{
					int best = 0;
					for (int x = x(chart, i); x <= x(chart, i + 1); x++)
					{
						best = Math.max(best, ink(image, x));
					}
					assertTrue(range + ": segment " + i + " -> " + (i + 1) + " is drawn (" + best + ")", best > INK);
				}
			}
		});
	}

	@Test
	public void oneReadingIsADotAndNoLine() throws Exception
	{
		onEdt(() ->
		{
			// One reading three days ago: four days drawn, three of them carried - and still no line and no fill, just
			// the dot in its halo, every drawn pixel inside the halo's box round the reading's point.
			final BankHistoryView view = view(BankHistorySeries.of(Arrays.asList(point(TODAY.minusDays(3), 5L))),
				BankHistoryRange.D7);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			assertEquals(4, chart.days().size());
			final BufferedImage image = paint(chart);
			final double px = BankHistoryChart.xAt(0, 4, chart.getWidth());
			final double py = chart.getHeight() / 2.0;
			final double reach = BankHistoryChart.HALO_RADIUS + 1;
			int drawn = 0;
			for (int y = 0; y < image.getHeight(); y++)
			{
				for (int x = 0; x < image.getWidth(); x++)
				{
					if ((image.getRGB(x, y) & 0xFFFFFF) != (ColorScheme.DARKER_GRAY_COLOR.getRGB() & 0xFFFFFF))
					{
						drawn++;
						assertTrue("(" + x + ", " + y + ") is inside the halo round the reading",
							Math.abs(x + 0.5 - px) <= reach && Math.abs(y + 0.5 - py) <= reach);
					}
				}
			}
			assertTrue("the dot and its halo are drawn: " + drawn + " px", drawn > 20);
			assertTrue("no high or low with one reading", chart.figures().isEmpty());
			assertNotNull("its readout names it", label(view, "Wed 23 Sep"));
		});
	}

	@Test
	public void aRangeOfMoreThan120DaysIsThinned() throws Exception
	{
		onEdt(() ->
		{
			for (int n : new int[]{120, 121, 400})
			{
				final List<BankHistoryPoint> points = new ArrayList<>();
				for (int i = 0; i < n; i++)
				{
					points.add(point(TODAY.minusDays(i), 1_000_000L + i));
				}
				final BankHistorySeries s = BankHistorySeries.of(points);
				final BankHistoryView view = view(s, BankHistoryRange.ALL);
				final List<BankHistoryMath.Day> drawn = chart(view).days();
				final List<BankHistoryMath.Day> all = BankHistoryMath.days(s, null, TODAY, ViewOptions.DEFAULT);
				assertEquals(n, all.size());
				assertEquals(n + " days", BankHistoryMath.thin(all, BankHistoryView.MAX_POINTS), drawn);
				assertTrue(n + " days: at most 120 points, " + drawn.size(), drawn.size() <= 120);
				assertEquals("the last point is today", TODAY, drawn.get(drawn.size() - 1).day());
				if (n > 120)
				{
					assertTrue("thinned", drawn.size() < n);
				}
				else
				{
					assertEquals(n, drawn.size());
				}
				assertEquals("the list is not thinned: one page of it", Math.min(n, 250), view.describe().get("rows"));
			}
		});
	}

	@Test
	public void theReadoutAndDotNameTheLatestReadingNotACarriedToday() throws Exception
	{
		onEdt(() ->
		{
			// One reading three days ago, 7d: four days drawn, the last three carried. The readout and the dot stand on
			// the reading (index 0), never on today's carried point (index 3).
			final BankHistoryView view = view(BankHistorySeries.of(Arrays.asList(point(TODAY.minusDays(3), 5L))),
				BankHistoryRange.D7);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			assertEquals(4, chart.days().size());
			assertEquals(0, chart.readoutIndex());
			assertEquals("the readout itself, by its place", "Wed 23 Sep",
				BankHistoryViewTest.chartLabel(view, BankHistoryViewTest.READOUT_DAY));
			final BufferedImage image = paint(chart);
			assertTrue("the dot is at the reading", ink(image, x(chart, 0)) > INK);
			assertTrue("nothing at today's carried point", ink(image, x(chart, 3)) <= INK);
		});
	}

	@Test
	public void aThinnedBucketIsDrawnAsItsLastReadingAndTheReadoutNamesIt() throws Exception
	{
		onEdt(() ->
		{
			// 400 days with a reading every third day and none today (review C-TEST-1): buckets of four days, the last
			// of them 23-26 Sep with its one reading on the 25th - the point drawn is that reading, not carried today.
			final List<BankHistoryPoint> points = new ArrayList<>();
			for (int i = 1; i < 400; i += 3)
			{
				points.add(point(TODAY.minusDays(i), 1_000_000L + i * 1_000L));
			}
			final BankHistorySeries s = BankHistorySeries.of(points);
			final BankHistoryView view = view(s, BankHistoryRange.ALL);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			final List<BankHistoryMath.Day> all = BankHistoryMath.days(s, null, TODAY, ViewOptions.DEFAULT);
			assertTrue("today is carried", all.get(all.size() - 1).carried());
			assertEquals(BankHistoryMath.thin(all, BankHistoryView.MAX_POINTS), chart.days());
			final BankHistoryMath.Day last = chart.days().get(chart.days().size() - 1);
			assertTrue("the last bucket's point is its reading", !last.carried());
			assertEquals(TODAY.minusDays(1), last.day());
			for (BankHistoryMath.Day d : chart.days())
			{
				assertTrue("every bucket here holds a reading: " + d, !d.carried());
			}

			hover(chart, x(chart, 3));
			leave(chart);
			assertEquals(BankHistoryDayRow.weekday(TODAY.minusDays(1)),
				BankHistoryViewTest.chartLabel(view, BankHistoryViewTest.READOUT_DAY));
		});
	}

	@Test
	public void theReadoutFollowsTheHoverAndLeavingRestoresTheLatestReading() throws Exception
	{
		onEdt(() ->
		{
			final BankHistoryView view = view(fixture(), BankHistoryRange.D30);
			layOut(view, 213);
			final BankHistoryChart chart = chart(view);
			assertNull(view.describe().get("hoverDay"));
			assertNotNull("with no hover, the latest reading", label(view, "Sat 26 Sep"));
			assertNotNull(label(view, "736,412,683 gp"));

			final LocalDate sep9 = LocalDate.of(2026, 9, 9);
			hover(chart, x(chart, indexOf(chart, sep9)));
			assertEquals("2026-09-09", view.describe().get("hoverDay"));
			assertNotNull(label(view, "Wed 09 Sep"));
			final long v = fixture().on(sep9).valueFor(ViewOptions.DEFAULT);
			assertNotNull(label(view, MovementMath.formatExact(v) + " gp"));

			// The nearest point by x: a pointer 2 px right of the 9th is still the 9th.
			hover(chart, x(chart, indexOf(chart, sep9)) + 2);
			assertEquals("2026-09-09", view.describe().get("hoverDay"));

			// A carried day can be hovered: its readout names it, at the carried total.
			final LocalDate sep8 = LocalDate.of(2026, 9, 8);
			hover(chart, x(chart, indexOf(chart, sep8)));
			assertEquals("2026-09-08", view.describe().get("hoverDay"));
			// Found by its place: the list's own row for the 8th reads "Tue 08 Sep" too, its date alone.
			assertEquals("Tue 08 Sep", BankHistoryViewTest.chartLabel(view, BankHistoryViewTest.READOUT_DAY));
			assertNotNull(label(view, MovementMath.formatExact(fixture().on(sep8.minusDays(1)).valueFor(null)) + " gp"));

			leave(chart);
			assertNull(view.describe().get("hoverDay"));
			assertNotNull(label(view, "Sat 26 Sep"));
			assertNotNull(label(view, "736,412,683 gp"));
			assertEquals("Sat 26 Sep", BankHistoryViewTest.chartLabel(view, BankHistoryViewTest.READOUT_DAY));
		});
	}

	@Test
	public void theChartTellsItsListenerOnlyWhenTheHoveredPointChanges() throws Exception
	{
		onEdt(() ->
		{
			final AtomicInteger told = new AtomicInteger();
			final BankHistoryChart chart = new BankHistoryChart(i -> told.incrementAndGet());
			final List<BankHistoryMath.Day> days = BankHistoryMath.days(fixture(), TODAY.minusDays(30), TODAY, null);
			chart.setData(days, true, 1);
			chart.setSize(213, BankHistoryChart.PLOT_HEIGHT);
			final int x5 = (int) Math.round(BankHistoryChart.xAt(5, days.size(), chart.getWidth()));
			hover(chart, x5);
			hover(chart, x5 + 1);
			hover(chart, x5 - 1);
			assertEquals("three moves over one point: one change", 1, told.get());
			hover(chart, (int) Math.round(BankHistoryChart.xAt(6, days.size(), chart.getWidth())));
			assertEquals(2, told.get());
			leave(chart);
			leave(chart);
			assertEquals(3, told.get());
			assertTrue("one listener serves both roles", chart.getMouseListeners().length == 1
				&& chart.getMouseMotionListeners().length == 1
				&& (Object) chart.getMouseListeners()[0] == chart.getMouseMotionListeners()[0]);
		});
	}

	@Test
	public void theChartHitTestsFromItsOwnWidth() throws Exception
	{
		onEdt(() ->
		{
			for (int width : new int[]{213, 230})
			{
				final BankHistoryView view = view(fixture(), BankHistoryRange.D30);
				layOut(view, width);
				final BankHistoryChart chart = chart(view);
				assertEquals("the chart spans the block's whole width", width, chart.getWidth());
				final int last = chart.days().size() - 1;
				hover(chart, chart.getWidth() - 1);
				assertEquals(width + ": the right edge is today", TODAY.toString(), view.describe().get("hoverDay"));
				hover(chart, 0);
				assertEquals(width + ": the left edge is the range's first day", "2026-08-27",
					view.describe().get("hoverDay"));
				assertEquals(last, chart.indexAt(chart.getWidth()));
			}
		});
	}

	// ---------------------------------------------------------------------------------------- helpers

	/** The chart alone, on the card grey it sits on. */
	static BufferedImage paint(final BankHistoryChart chart)
	{
		final BufferedImage image = new BufferedImage(chart.getWidth(), chart.getHeight(), BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			g.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g.fillRect(0, 0, image.getWidth(), image.getHeight());
			chart.paint(g);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	static int x(final BankHistoryChart chart, final int i)
	{
		return (int) Math.round(BankHistoryChart.xAt(i, chart.days().size(), chart.getWidth()));
	}

	/** How far the most-drawn pixel in column {@code x} is from the card grey, in any channel: any line, any colour. */
	static int ink(final BufferedImage image, final int x)
	{
		final Color ground = ColorScheme.DARKER_GRAY_COLOR;
		int best = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			final Color c = new Color(image.getRGB(x, y));
			best = Math.max(best, Math.max(Math.abs(c.getRed() - ground.getRed()),
				Math.max(Math.abs(c.getGreen() - ground.getGreen()), Math.abs(c.getBlue() - ground.getBlue()))));
		}
		return best;
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Addendum AU, THE invariant (contract section 2 and amendment 9.17, plan 7.7 item 6): a bank-history reading is
 * saved in ten parts (eight until 1.0.9 part 3 added the Grand Exchange offers' two) so that it can be drawn under
 * whatever counting switches are on NOW, and the parts the switches pick add up to the Bank value card's figure to
 * the gp.
 *
 * <p>One fixture holds every kind of stack the cells tell apart: the bank, the inventory and the worn gear; coins in
 * the bank and in hand; a parts stack (the Crystal body, banked AND worn); a parts stack with one part no table
 * prices (so it ends on the alch rule); an alch-only stack (the Dramen staff); a carried-only stack (the Karambwan
 * vessel, worn) and a carried-only alch stack (the Graceful cape); a stack in the bank, the inventory AND a
 * Grand Exchange offer ("Item 3"); one live row (the Abyssal whip, in the bank and in an offer); one id
 * {@code ItemMapping} rewrites (the Ring of wealth (5)); and coins in the Grand Exchange offers.
 * It is {@link PriceServiceTest}'s own, used by composition.
 */
public class BankHistoryInvariantTest
{
	/** An untradeable with two parts, one of which nothing prices: it ends on the alch rule (R2's all-or-nothing). */
	private static final int HALF_PRICED = 90_001;
	private static final long HALF_PRICED_ALCH = 700_000L;
	private static final int UNPRICED_PART = 99_001;
	private static final long CASH_IN_BANK = 200_000_000L;
	private static final long CASH_IN_HAND = 791_078L;
	private static final long CASH_IN_OFFERS = 52_000_000L;

	private final PriceServiceTest f = new PriceServiceTest();

	@Before
	public void setUp()
	{
		f.setUp();
		f.nameTheSeed();
		f.nameTheRing();
		f.warmUpLiveWith(fixture(), Collections.<Integer, TradedPriceClient.Quote>emptyMap());
		f.answerDay(PriceServiceTest.SEP_7, PriceServiceTest.tradedSep7());
	}

	/** The one fixture (class javadoc). */
	static BankSnapshot fixture()
	{
		final BankSnapshot bank = PriceServiceTest.bank(PriceServiceTest.T0);
		bank.currencyGp = CASH_IN_BANK;
		bank.items.add(new BankItem(PriceServiceTest.RING_OF_WEALTH_5, 2, "Ring of wealth (5)", false));
		bank.items.add(crystalBody());
		bank.items.add(halfPriced());
		bank.items.add(new BankItem(PriceServiceTest.DRAMEN, 2, "Dramen staff", false, true, 1_500));
		final List<BankItem> inventory = Arrays.asList(
			new BankItem(PriceServiceTest.item(3), 1, "Item 3", true),
			new BankItem(PriceServiceTest.GRACEFUL, 1, "Graceful cape", false, true, 500),
			halfPriced());
		final List<BankItem> worn = Arrays.asList(
			new BankItem(PriceServiceTest.VESSEL, 1, "Karambwan vessel", false),
			crystalBody());
		// 1.0.9 part 3: two of Item 3 for sale and one more whip bought and not collected - both merge into rows the
		// bank already holds - and the coins the offers hold.
		final List<BankItem> exchange = Arrays.asList(
			new BankItem(PriceServiceTest.item(3), 2, "Item 3", true),
			new BankItem(PriceServiceTest.WHIP, 1, "Abyssal whip", false));
		return bank.withCarried(new BankReader.Carried(inventory, worn, exchange, CASH_IN_HAND, CASH_IN_OFFERS,
			PriceServiceTest.T0));
	}

	private static BankItem crystalBody()
	{
		return new BankItem(PriceServiceTest.CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000,
			Collections.singletonList(new BankItem.Part(PriceServiceTest.ARMOUR_SEED, 3L, PriceServiceTest.SEED_NAME)));
	}

	private static BankItem halfPriced()
	{
		return new BankItem(HALF_PRICED, 1, "Half-priced thing", false, true, (int) HALF_PRICED_ALCH,
			Arrays.asList(new BankItem.Part(PriceServiceTest.ARMOUR_SEED, 1L, PriceServiceTest.SEED_NAME),
				new BankItem.Part(UNPRICED_PART, 1L, "Unpriced part")));
	}

	/**
	 * The 32 option sets: the four counting switches by live prices on and off (amendment 9.17 had sixteen, before
	 * 1.0.9 part 3 added the Grand Exchange switch).
	 */
	static List<ViewOptions> allThirtyTwo()
	{
		final List<ViewOptions> sets = new ArrayList<>();
		for (final boolean live : new boolean[]{true, false})
		{
			for (final boolean cash : new boolean[]{true, false})
			{
				for (final boolean untradeables : new boolean[]{true, false})
				{
					for (final boolean inventory : new boolean[]{true, false})
					{
						for (final boolean offers : new boolean[]{true, false})
						{
							sets.add(ViewOptions.DEFAULT.withLivePrices(live).withCountCash(cash)
								.withCountUntradeables(untradeables).withCountInventory(inventory)
								.withCountGrandExchange(offers));
						}
					}
				}
			}
		}
		return sets;
	}

	/** The reading the last publish carries: today's, which is the only one there is. */
	private BankHistoryPoint reading()
	{
		final PriceService.Status status = f.lastStatus();
		assertEquals("one reading, today's", 1, status.bankHistory().size());
		return status.bankHistory().last();
	}

	/** The fixture really is the one the contract names - every cell has something in it, and one row is live. */
	@Test
	public void theFixtureFillsAllTenCellsAndHasALiveRow()
	{
		f.service.setOptions(ViewOptions.DEFAULT.withCountUntradeables(true));
		final BankHistoryPoint point = reading();
		for (int cell = 0; cell < BankHistoryPoint.CELLS; cell++)
		{
			assertTrue("cell " + cell + " holds something", point.card(cell) > 0L);
		}
		assertTrue("a live row", f.lastStatus().live().liveRows() >= 1);
		final MovementRow whip = PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.WHIP);
		assertNotNull(whip);
		assertTrue("the whip is the live row", whip.isLive());
		assertNotEquals("so the card figures and the guide figures differ", point.card(BankHistoryPoint.BANK_TRADEABLE),
			point.guide(BankHistoryPoint.BANK_TRADEABLE));
		assertTrue(point.hasGuide());
		assertEquals("the rewritten ring is priced", Long.valueOf(PriceServiceTest.RING_GP),
			PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.RING_OF_WEALTH_5).unitPrice());
		assertEquals(CASH_IN_BANK, point.card(BankHistoryPoint.BANK_CASH));
		assertEquals(CASH_IN_HAND, point.card(BankHistoryPoint.CARRIED_CASH));
		assertEquals(CASH_IN_OFFERS, point.card(BankHistoryPoint.GE_CASH));
		assertEquals(CASH_IN_OFFERS, point.guide(BankHistoryPoint.GE_CASH));
		assertEquals("the half-priced stack ends on its alch value, in the bank and in hand",
			HALF_PRICED_ALCH, point.card(BankHistoryPoint.CARRIED_ALCH) - 500L);
		assertEquals(3L * PriceServiceTest.SEED_NOW, point.guide(BankHistoryPoint.BANK_PARTS));
		assertEquals(3L * PriceServiceTest.SEED_NOW, point.guide(BankHistoryPoint.CARRIED_PARTS));
	}

	/**
	 * Amendment 9.17, the first form: for each of the 32 option sets X, the reading recorded by the computation run
	 * under X adds up, under X, to that same computation's Bank value, to the gp.
	 */
	@Test
	public void underEachOfTheThirtyTwoOptionSetsTheReadingEqualsTheCardToTheGp()
	{
		for (final ViewOptions options : allThirtyTwo())
		{
			f.service.setOptions(options);
			final PriceService.Status status = f.lastStatus();
			assertEquals(options, status.options());
			assertFalse(options + ": not degraded", status.anchorDegraded());
			assertEquals(options.toString(), status.portfolio().valueNow(), reading().valueFor(options));
		}
	}

	/**
	 * Amendment 9.17, the second form, with degraded mode off: the reading recorded under every switch on (live
	 * prices on) adds up, under ANY X, to the Bank value of a computation run under X - so a flipped switch redraws
	 * every past day at exactly the figure the card would have shown that day.
	 */
	@Test
	public void theReadingRecordedWithEverySwitchOnEqualsTheCardUnderAnyOptionSet()
	{
		final ViewOptions allOn = ViewOptions.DEFAULT.withCountCash(true).withCountUntradeables(true)
			.withCountInventory(true).withCountGrandExchange(true).withLivePrices(true);
		f.service.setOptions(allOn);
		final BankHistoryPoint recorded = reading();
		assertEquals(f.lastStatus().portfolio().valueNow(), recorded.valueFor(allOn));

		for (final ViewOptions options : allThirtyTwo())
		{
			f.service.setOptions(options);
			final PriceService.Status status = f.lastStatus();
			assertFalse(options + ": not degraded", status.anchorDegraded());
			assertEquals(options.toString(), status.portfolio().valueNow(), recorded.valueFor(options));
		}
	}

	/**
	 * The cells follow the contract's arithmetic stack by stack: "Item 3" is 3 in the bank and 1 carried, the
	 * Crystal body 1 and 1, and a stack's bank cell plus its carried cell is its whole holding.
	 */
	@Test
	public void aStackHeldInTwoPlacesIsSplitByQuantity()
	{
		f.service.setOptions(ViewOptions.DEFAULT.withLivePrices(false));
		final BankHistoryPoint point = reading();
		final long seedsPerBody = 3L * PriceServiceTest.SEED_NOW;
		assertEquals("one body banked", seedsPerBody, point.card(BankHistoryPoint.BANK_PARTS));
		assertEquals("one body worn", seedsPerBody, point.card(BankHistoryPoint.CARRIED_PARTS));
		assertEquals("2 Dramen staffs and one half-priced thing in the bank", 2L * 1_500L + HALF_PRICED_ALCH,
			point.card(BankHistoryPoint.BANK_ALCH));
		final MovementRow three = PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.item(3));
		final MovementRow vessel = PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.VESSEL);
		assertEquals("one of Item 3 and the vessel are carried", three.unitPrice() + vessel.unitPrice(),
			point.card(BankHistoryPoint.CARRIED_TRADEABLE));
		assertFalse("live prices off: the guide is the card", point.hasGuide());
	}

	/**
	 * 1.0.9 part 3: the offers' items are the third part of a stack held in three places. "Item 3" is 3 in the bank, 1
	 * carried and 2 in offers, the whip 1 and 1: the bank cell and the carried cell are what they were without the
	 * offers, the Grand Exchange cell is exactly the offers' items at the row's unit - and the same snapshot without
	 * its offers gives the same bank and carried cells.
	 */
	@Test
	public void theOffersItemsFillTheirOwnCellAndLeaveTheBankAndCarriedCellsAlone()
	{
		f.service.setOptions(ViewOptions.DEFAULT.withLivePrices(false));
		final BankHistoryPoint point = reading();
		final MovementRow three = PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.item(3));
		final MovementRow whip = PriceServiceTest.rowFor(f.lastRows(), PriceServiceTest.WHIP);
		assertEquals("2 of Item 3 and 1 whip in the offers, each at its unit",
			2L * three.unitPrice() + whip.unitPrice(), point.card(BankHistoryPoint.GE_TRADEABLE));
		assertEquals(CASH_IN_OFFERS, point.card(BankHistoryPoint.GE_CASH));
		assertEquals("the merged row is 3 + 1 + 2", 6, three.quantity());
		assertEquals(2, three.exchangeQuantity());
		assertEquals(3, three.bankQuantity());
		assertEquals(1, three.inventoryQuantity());

		// The same snapshot with no offers at all: every other cell is what it was.
		final BankSnapshot full = fixture();
		final BankSnapshot bare = full.withCarried(new BankReader.Carried(full.inventory, full.worn, CASH_IN_HAND,
			PriceServiceTest.T0));
		f.service.setBank(bare);
		final BankHistoryPoint without = reading();
		for (int cell = 0; cell < BankHistoryPoint.GE_TRADEABLE; cell++)
		{
			assertEquals("cell " + cell, without.card(cell), point.card(cell));
		}
		assertEquals(0L, without.card(BankHistoryPoint.GE_TRADEABLE));
		assertEquals(0L, without.card(BankHistoryPoint.GE_CASH));
	}
}

package com.bankpricemovement;

import static com.bankpricemovement.BankHistorySeriesTest.p;
import static com.bankpricemovement.BankHistorySeriesTest.sep;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * {@link BankHistoryMath} (addendum AU, contract sections 3, 9.5 and 9.6): the window change and the card's move,
 * the change against the previous reading, the calendar days with their carried gaps, the thinning, and the day a
 * greyed chip fills - with 0 and 1 readings, a window with no reading old enough (null, never 0), the span when the
 * reading used is older than the window's day, and the day boundary at local midnight.
 */
public class BankHistoryMathTest
{
	private static final ZoneId TORONTO = ZoneId.of("America/Toronto");

	/** Readings on 1, 2, 5 and 10 Sep worth 100, 110, 150, 200 (bank-tradeable only). */
	private static BankHistorySeries fourReadings()
	{
		return BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(2), 2, 110), p(sep(5), 5, 150),
			p(sep(10), 10, 200)));
	}

	private static long millis(final LocalDateTime local, final ZoneId zone)
	{
		return local.atZone(zone).toInstant().toEpochMilli();
	}

	// ---- dayOf

	@Test
	public void aReadingIsFiledUnderTheLocalDateAndTheDayTurnsAtLocalMidnight()
	{
		final long lastMilli = millis(LocalDateTime.of(2026, 9, 28, 23, 59, 59, 999_000_000), TORONTO);
		assertEquals(sep(28), BankHistoryMath.dayOf(lastMilli, TORONTO));
		assertEquals(sep(29), BankHistoryMath.dayOf(lastMilli + 1, TORONTO));

		// 9 pm in Toronto is 1 am UTC the next day: the player's day, not UTC's (plan 7.1 item 2).
		final long nineInTheEvening = millis(LocalDateTime.of(2026, 9, 28, 21, 0), TORONTO);
		assertEquals(sep(28), BankHistoryMath.dayOf(nineInTheEvening, TORONTO));
		assertEquals(sep(29), BankHistoryMath.dayOf(nineInTheEvening, ZoneOffset.UTC));
	}

	// ---- overDays

	@Test
	public void overDaysComparesTheLastReadingWithTheLastOneOnOrBeforeTheWindowsDay()
	{
		final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(10), 5, null);
		assertNotNull(c);
		assertEquals(sep(5), c.fromDay());
		assertEquals(sep(10), c.toDay());
		assertEquals("from 150 to 200", new BankHistoryMath.Change(sep(5), sep(10), 150L, 200L), c);
		assertEquals(50L, c.deltaGp());
		assertEquals(50 * 100.0d / 150, c.pct(), 0.0d);
		assertEquals(5, c.spanDays());
	}

	@Test
	public void theSpanSaysWhenTheReadingUsedIsOlderThanTheWindowsDay()
	{
		// 1d on the 10th wants the 9th; the 9th has none, so the 5th is used and the span is 5 days, not 1.
		final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(10), 1, null);
		assertEquals(sep(5), c.fromDay());
		assertEquals(5, c.spanDays());
	}

	@Test
	public void aWindowWithNoReadingOldEnoughIsNullNeverZero()
	{
		assertNull(BankHistoryMath.overDays(fourReadings(), sep(10), 10, null));
		assertNotNull("the 9th boundary: 9 days back is the 1st", BankHistoryMath.overDays(fourReadings(), sep(10),
			9, null));
		assertNull(BankHistoryMath.overDays(fourReadings(), sep(10), 30, null));
	}

	@Test
	public void overDaysWithNoOrOneReadingIsNull()
	{
		assertNull(BankHistoryMath.overDays(BankHistorySeries.EMPTY, sep(10), 7, null));
		assertNull(BankHistoryMath.overDays(null, sep(10), 7, null));
		final BankHistorySeries one = BankHistorySeries.EMPTY.with(p(sep(3), 3, 100));
		assertNull(BankHistoryMath.overDays(one, sep(10), 7, null));
		assertNull(BankHistoryMath.overDays(one, sep(10), 1, null));
		assertNull("all, over one reading: from is to", BankHistoryMath.overDays(one, sep(10), 0, null));
	}

	@Test
	public void overDaysIsNullWhenFromIsTheSameReadingAsTo()
	{
		// Readings on the 1st and 5th; on the 7th, 1d wants the 6th, whose last reading is the 5th - which is also
		// the latest. That is no measured change, so no figure.
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(5), 5, 150)));
		assertNull(BankHistoryMath.overDays(s, sep(7), 1, null));
		assertNotNull(BankHistoryMath.overDays(s, sep(7), 6, null));
	}

	@Test
	public void overDaysWithZeroOrFewerDaysMeansFromTheFirstReading()
	{
		for (final int days : new int[]{0, -1})
		{
			final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(10), days, null);
			assertEquals(sep(1), c.fromDay());
			assertEquals("from the first reading's 100", new BankHistoryMath.Change(sep(1), sep(10), 100L, 200L), c);
			assertEquals(9, c.spanDays());
		}
	}

	@Test
	public void overDaysIgnoresReadingsAfterToday()
	{
		// On the 7th the 10th has not happened: to is the 5th.
		final BankHistoryMath.Change c = BankHistoryMath.overDays(fourReadings(), sep(7), 5, null);
		assertEquals(sep(2), c.fromDay());
		assertEquals(sep(5), c.toDay());
		assertEquals(40L, c.deltaGp());
	}

	@Test
	public void theChangeFollowsTheSwitches()
	{
		final long[] a = new long[BankHistoryPoint.CELLS];
		a[BankHistoryPoint.BANK_TRADEABLE] = 100L;
		a[BankHistoryPoint.BANK_CASH] = 1_000L;
		final long[] b = a.clone();
		b[BankHistoryPoint.BANK_TRADEABLE] = 200L;
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(new BankHistoryPoint(sep(1), 1, 1, a, null),
			new BankHistoryPoint(sep(2), 2, 2, b, null)));
		final BankHistoryMath.Change withCash = BankHistoryMath.overDays(s, sep(2), 1, ViewOptions.DEFAULT);
		final BankHistoryMath.Change without = BankHistoryMath.overDays(s, sep(2), 1,
			ViewOptions.DEFAULT.withCountCash(false));
		assertEquals(new BankHistoryMath.Change(sep(1), sep(2), 1_100L, 1_200L), withCash);
		assertEquals(new BankHistoryMath.Change(sep(1), sep(2), 100L, 200L), without);
		assertEquals("the same gp move", withCash.deltaGp(), without.deltaGp());
		assertEquals(100 * 100.0d / 1_100, withCash.pct(), 0.0d);
		assertEquals(100.0d, without.pct(), 0.0d);
		assertEquals("a null options is the default", withCash, BankHistoryMath.overDays(s, sep(2), 1, null));
	}

	@Test
	public void aChangeFromZeroHasNoPercentage()
	{
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 0), p(sep(2), 2, 50)));
		final BankHistoryMath.Change c = BankHistoryMath.overDays(s, sep(2), 1, null);
		assertEquals(50L, c.deltaGp());
		assertNull(c.pct());
	}

	// ---- sinceDay

	@Test
	public void sinceDayComparesNowWithTheLastReadingOnOrBeforeTheWindowsDay()
	{
		final BankHistoryMath.Change c = BankHistoryMath.sinceDay(fourReadings(), sep(12), 7, null, 260L);
		assertEquals(sep(5), c.fromDay());
		assertEquals(sep(12), c.toDay());
		assertEquals("from 150 to now's 260", new BankHistoryMath.Change(sep(5), sep(12), 150L, 260L), c);
		assertEquals(110L, c.deltaGp());
		assertEquals(7, c.spanDays());
	}

	@Test
	public void sinceDaySpansTheGapWhenTheReadingUsedIsOlder()
	{
		// 1d on the 8th wants the 7th; the 5th is the reading used - "(3 days)" on the card.
		final BankHistoryMath.Change c = BankHistoryMath.sinceDay(fourReadings(), sep(8), 1, null, 170L);
		assertEquals(sep(5), c.fromDay());
		assertEquals(3, c.spanDays());
		assertTrue("older than the window's day", c.fromDay().isBefore(sep(8).minusDays(1)));
	}

	@Test
	public void sinceDayIsNullExactlyWhenTheChipIsGreyed()
	{
		final BankHistorySeries s = fourReadings();
		for (final MovementWindow window : MovementWindow.values())
		{
			for (int d = 1; d <= 40; d++)
			{
				final LocalDate today = sep(1).plusDays(d - 1);
				final LocalDate fills = BankHistoryMath.fillsOn(s.upTo(today), window.days());
				final boolean greyed = fills == null || fills.isAfter(today);
				assertEquals(window + " on " + today, greyed,
					BankHistoryMath.sinceDay(s, today, window.days(), null, 1L) == null);
			}
		}
		assertNull(BankHistoryMath.sinceDay(BankHistorySeries.EMPTY, sep(10), 1, null, 5L));
		assertNull(BankHistoryMath.sinceDay(null, sep(10), 1, null, 5L));
	}

	@Test
	public void sinceDayIgnoresReadingsAfterToday()
	{
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(20), 20, 999)));
		final BankHistoryMath.Change c = BankHistoryMath.sinceDay(s, sep(10), 0, null, 120L);
		assertEquals(sep(1), c.fromDay());
		assertNull("a future reading is never old enough", BankHistoryMath.sinceDay(
			BankHistorySeries.EMPTY.with(p(sep(20), 20, 1)), sep(10), 0, null, 1L));
	}

	@Test
	public void whenTodayHasAReadingSinceDayEqualsOverDaysToTheGp()
	{
		final BankHistorySeries s = fourReadings();
		for (final int days : new int[]{1, 5, 7, 9})
		{
			final BankHistoryMath.Change over = BankHistoryMath.overDays(s, sep(10), days, null);
			final BankHistoryMath.Change since = BankHistoryMath.sinceDay(s, sep(10), days, null,
				s.on(sep(10)).valueFor(null));
			assertEquals("days " + days, over, since);
			assertEquals(over.deltaGp(), since.deltaGp());
			assertEquals(over.spanDays(), since.spanDays());
		}
	}

	// ---- vsPrevious

	@Test
	public void vsPreviousComparesADaysReadingWithTheOneBeforeItAcrossAGap()
	{
		final BankHistorySeries s = fourReadings();
		final BankHistoryMath.Change c = BankHistoryMath.vsPrevious(s, sep(5), null);
		assertEquals(sep(2), c.fromDay());
		assertEquals(sep(5), c.toDay());
		assertEquals(40L, c.deltaGp());
		assertEquals("vs 02 Sep, 3 days", 3, c.spanDays());
		assertEquals(1, BankHistoryMath.vsPrevious(s, sep(2), null).spanDays());
		assertNull("the first reading ever", BankHistoryMath.vsPrevious(s, sep(1), null));
		assertNull("a day with no reading", BankHistoryMath.vsPrevious(s, sep(4), null));
		assertNull(BankHistoryMath.vsPrevious(null, sep(5), null));
		assertNull(BankHistoryMath.vsPrevious(s, null, null));
	}

	// ---- days

	@Test
	public void daysCarriesTheLastReadingForwardAcrossEveryGap()
	{
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(3), 3, 300)));
		final List<BankHistoryMath.Day> days = BankHistoryMath.days(s, null, sep(5), null);
		assertEquals(5, days.size());
		final long[] values = {100, 100, 300, 300, 300};
		final boolean[] carried = {false, true, false, true, true};
		for (int i = 0; i < 5; i++)
		{
			final BankHistoryMath.Day day = days.get(i);
			assertEquals(sep(1 + i), day.day());
			assertEquals(values[i], day.valueGp());
			assertEquals(carried[i], day.carried());
			assertEquals("a day is its reading, or none", new BankHistoryMath.Day(sep(1 + i), values[i],
				carried[i] ? null : s.on(sep(1 + i))), day);
		}
	}

	@Test
	public void daysStartAtTheFirstReadingOrInsideAGap()
	{
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(5), 5, 100), p(sep(9), 9, 900)));
		final List<BankHistoryMath.Day> fromBefore = BankHistoryMath.days(s, sep(1), sep(9), null);
		assertEquals("never a day before the first reading", sep(5), fromBefore.get(0).day());
		assertEquals(5, fromBefore.size());

		final List<BankHistoryMath.Day> fromInside = BankHistoryMath.days(s, sep(7), sep(9), null);
		assertEquals(3, fromInside.size());
		assertTrue("a range starting in a gap starts carried", fromInside.get(0).carried());
		assertEquals(100L, fromInside.get(0).valueGp());
		assertEquals(900L, fromInside.get(2).valueGp());
	}

	@Test
	public void daysIgnoreReadingsAfterTheLastDayAndAnswerEmptyWhenThereIsNothing()
	{
		final BankHistorySeries s = BankHistorySeries.of(Arrays.asList(p(sep(1), 1, 100), p(sep(3), 3, 300)));
		final List<BankHistoryMath.Day> days = BankHistoryMath.days(s, null, sep(2), null);
		assertEquals(2, days.size());
		assertEquals(100L, days.get(1).valueGp());
		assertTrue(days.get(1).carried());

		assertTrue(BankHistoryMath.days(s, null, LocalDate.of(2026, 8, 31), null).isEmpty());
		assertTrue(BankHistoryMath.days(BankHistorySeries.EMPTY, null, sep(3), null).isEmpty());
		assertTrue(BankHistoryMath.days(null, null, sep(3), null).isEmpty());
		assertTrue(BankHistoryMath.days(s, sep(4), sep(3), null).isEmpty());
		try
		{
			days.add(days.get(0));
			fail("the list was modifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// the point of the test
		}
	}

	@Test
	public void daysFollowTheSwitches()
	{
		final long[] card = new long[BankHistoryPoint.CELLS];
		card[BankHistoryPoint.BANK_TRADEABLE] = 100L;
		card[BankHistoryPoint.CARRIED_TRADEABLE] = 5L;
		final BankHistorySeries s = BankHistorySeries.EMPTY.with(new BankHistoryPoint(sep(1), 1, 1, card, null));
		assertEquals(105L, BankHistoryMath.days(s, null, sep(2), null).get(1).valueGp());
		assertEquals(100L, BankHistoryMath.days(s, null, sep(2), ViewOptions.DEFAULT.withCountInventory(false))
			.get(1).valueGp());
	}

	@Test
	public void oneReadingIsOneDayAndZeroReadingsNone()
	{
		final BankHistorySeries one = BankHistorySeries.EMPTY.with(p(sep(28), 1, 735));
		final List<BankHistoryMath.Day> days = BankHistoryMath.days(one, sep(28).minusDays(7), sep(28), null);
		assertEquals(1, days.size());
		assertFalse(days.get(0).carried());
		assertEquals(735L, days.get(0).valueGp());
