					assertTrue(width + ": " + c.getClass().getSimpleName() + " " + r + " stays inside the view",
						r.x >= 0 && r.x + r.width <= width);
				}
				for (BankHistoryDayRow row : BankHistoryViewTest.rows(view))
				{
