	// ---------------------------------------------------------------------------------------- helpers

	static BankHistoryDayRow.Model row(final String date, final String sub, final String total, final String exact,
		final String pct, final String gp, final int sign)
	{
		return new BankHistoryDayRow.Model(LocalDate.of(2026, 9, 30), false, date, sub, total, exact, pct, gp, sign,
			false);
	}

	static List<JLabel> labels(final Container c)
	{
		final List<JLabel> out = new ArrayList<>();
		for (Component child : c.getComponents())
		{
			if (child instanceof JLabel)
			{
				out.add((JLabel) child);
			}
		}
		return out;
	}

	/**
	 * Every label is at least as wide as its own text in its own font plus its icon (nothing cut), inside its
	 * parent's insets, and no two of them overlap.
	 */
	static void assertFits(final String what, final Container parent, final List<JLabel> labels)
	{
		final Insets in = parent.getInsets();
		for (JLabel l : labels)
		{
			if (l.getText().isEmpty())
			{
				continue;
			}
			final FontMetrics fm = l.getFontMetrics(l.getFont());
			final int need = fm.stringWidth(l.getText())
				+ (l.getIcon() == null ? 0 : l.getIcon().getIconWidth() + l.getIconTextGap());
			assertTrue(what + ": '" + l.getText() + "' needs " + need + " px, has " + l.getWidth(), l.getWidth() >= need);
			assertTrue(what + ": '" + l.getText() + "' starts inside at " + l.getX(), l.getX() >= in.left);
			assertTrue(what + ": '" + l.getText() + "' ends inside at " + (l.getX() + l.getWidth()),
				l.getX() + l.getWidth() <= parent.getWidth() - in.right);
			assertTrue(what + ": '" + l.getText() + "' is tall enough", l.getHeight() >= fm.getHeight());
		}
		for (int i = 0; i < labels.size(); i++)
		{
			for (int j = i + 1; j < labels.size(); j++)
			{
				final JLabel a = labels.get(i);
				final JLabel b = labels.get(j);
				if (a.getText().isEmpty() || b.getText().isEmpty())
				{
					continue;
				}
				assertTrue(what + ": '" + a.getText() + "' " + a.getBounds() + " and '" + b.getText() + "' "
					+ b.getBounds() + " overlap", !a.getBounds().intersects(b.getBounds()));
			}
		}
	}
}

package com.bankpricemovement;

import java.awt.image.BufferedImage;
import java.io.File;
import java.util.List;
import javax.imageio.ImageIO;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Addendum AU, builder C: the History view's own pictures ({@link HistoryViewRenderer}) are drawn into
 * {@code build/history-view/} on every run - the pinned copies under {@code docs/handoff/lab/} are written by the
 * harness's {@code main} - and each is the picture it claims to be.
 */
public class BankHistoryViewPicturesTest
{
	@Test
	public void theFivePicturesAreDrawnAtTheirWidths() throws Exception
	{
		final List<File> files = HistoryViewRenderer.write(new File("build/history-view"));
		assertEquals(5, files.size());
		final BufferedImage at213 = ImageIO.read(files.get(0));
		final BufferedImage at230 = ImageIO.read(files.get(1));
		final BufferedImage empty = ImageIO.read(files.get(2));
		final BufferedImage one = ImageIO.read(files.get(3));
		final BufferedImage hover = ImageIO.read(files.get(4));
		assertEquals(213, at213.getWidth());
		assertEquals(230, at230.getWidth());
		assertEquals("the same content at both widths, so the same height", at213.getHeight(), at230.getHeight());
		assertEquals("the hover changes nothing's size", at213.getHeight(), hover.getHeight());
		assertTrue("the whole list is drawn: 40 days of rows", at213.getHeight() > 1_200);
		assertTrue("the empty view is one short sentence", empty.getHeight() < 60);
		assertTrue("one reading: the block and one row", one.getHeight() < 250);
		assertTrue("the lit chip is orange", count(at213, ColorScheme.BRAND_ORANGE) > 20);
		assertTrue("the hover is a different picture", differ(at213, hover));
	}

	static int count(final BufferedImage image, final java.awt.Color colour)
	{
		int n = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) & 0xFFFFFF) == (colour.getRGB() & 0xFFFFFF))
				{
					n++;
				}
			}
		}
		return n;
	}

	static boolean differ(final BufferedImage a, final BufferedImage b)
	{
		for (int y = 0; y < Math.min(a.getHeight(), b.getHeight()); y++)
		{
			for (int x = 0; x < Math.min(a.getWidth(), b.getWidth()); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.bankpricemovement;

import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

/**
 * Addendum AU, amendment 9.12: the four semantics of {@link BankHistoryView#describe()} the panel relies on across the
 * seam - {@code range}, {@code readings}, {@code first}, {@code last} - which the view must keep whatever it draws; plus
 * the seven keys and their types (amendment 9.11). {@code SidebarHistorySeamTest} drives the same view through the real
 * panel.
 */
public class BankHistoryViewSeamTest
{
	private static final ZoneId TORONTO = ZoneId.of("America/Toronto");

	/** Local noon of a September day in Toronto, as amendment 9.1 tells the panel's tests to build stamps. */
	private static long noon(final int day)
	{
		return LocalDate.of(2026, 9, day).atTime(12, 0).atZone(TORONTO).toInstant().toEpochMilli();
	}

	private static BankHistorySeries series(final int... days)
	{
		final BankHistoryPoint[] points = new BankHistoryPoint[days.length];
		for (int i = 0; i < days.length; i++)
		{
			points[i] = BankHistorySeriesTest.p(BankHistorySeriesTest.sep(days[i]), noon(days[i]), 1_000L * days[i]);
		}
		return BankHistorySeries.of(Arrays.asList(points));
	}

	@Test
	public void theRangeStartsAtTheDefaultWindowsAndFollowsSetRange()
	{
		final BankHistoryView view = new BankHistoryView(() -> noon(20), TORONTO);
		assertEquals("7d", view.describe().get("range"));

		view.setRange(BankHistoryRange.D90);
		assertEquals("90d", view.describe().get("range"));
		view.setRange(BankHistoryRange.ALL);
		assertEquals("all", view.describe().get("range"));
		view.setRange(null);
		assertEquals("null is ignored", "all", view.describe().get("range"));
	}

	@Test
	public void readingsFirstAndLastComeFromTheLastShowCutToToday()
	{
		final AtomicLong clock = new AtomicLong(noon(20));
		final BankHistoryView view = new BankHistoryView(clock::get, TORONTO);
		assertEquals(0, view.describe().get("readings"));
		assertNull(view.describe().get("first"));
		assertNull(view.describe().get("last"));

		view.show(series(3, 9, 20, 22), ViewOptions.DEFAULT);

		assertEquals("the 22nd is after today and is not drawn", 3, view.describe().get("readings"));
		assertEquals("2026-09-03", view.describe().get("first"));
		assertEquals("2026-09-20", view.describe().get("last"));

		clock.set(noon(22));
		view.show(series(3, 9, 20, 22), null);
		assertEquals(4, view.describe().get("readings"));
		assertEquals("2026-09-22", view.describe().get("last"));

		view.show(null, null);
		assertEquals("null reads as EMPTY", 0, view.describe().get("readings"));
		assertNull(view.describe().get("first"));
	}

	@Test
	public void todayIsTheClocksLocalDate()
	{
		// 21 Sep 01:00 UTC is still 20 Sep in Toronto.
		final long lateEvening = LocalDate.of(2026, 9, 21).atTime(1, 0).toInstant(ZoneOffset.UTC).toEpochMilli();
		final BankHistoryView view = new BankHistoryView(() -> lateEvening, TORONTO);
		view.show(series(20, 21), ViewOptions.DEFAULT);
		assertEquals(1, view.describe().get("readings"));
		assertEquals("2026-09-20", view.describe().get("last"));
	}

	@Test
	public void describeHasExactlyTheSevenKeysInOrderWithStringIntegerAndNullValues()
	{
		final BankHistoryView view = new BankHistoryView(() -> noon(20), TORONTO);
		view.show(series(19, 20), ViewOptions.DEFAULT);
		final LinkedHashMap<String, Object> map = view.describe();

		assertEquals(Arrays.asList("readings", "first", "last", "range", "rows", "carriedRows", "hoverDay"),
			Arrays.asList(map.keySet().toArray()));
		assertEquals(Integer.valueOf(2), map.get("readings"));
		assertEquals("2026-09-19", map.get("first"));
		// The rows built: the 19th and the 20th, neither carried.
		assertEquals(Integer.valueOf(2), map.get("rows"));
		assertEquals(Integer.valueOf(0), map.get("carriedRows"));
		assertNull(map.get("hoverDay"));
		assertFalse("nothing more to page", view.showMore());
	}
}

