					if (c instanceof JComponent)
					{
						assertNull(c + " has no tooltip", ((JComponent) c).getToolTipText());
					}
					if (c instanceof JLabel)
					{
						assertFalse(((JLabel) c).getText().toLowerCase().contains("<html"));
					}
				}
			}
		});
	}

	@Test
	public void theFourSemanticsThePanelReliesOnStillHold() throws Exception
	{
		onEdt(() ->
		{
			final AtomicLong clock = new AtomicLong(noon(LocalDate.of(2026, 9, 20)));
			final BankHistoryView view = new BankHistoryView(clock::get, ZONE);
			assertEquals("7d", view.describe().get("range"));
			assertEquals(0, view.describe().get("readings"));
			assertNull(view.describe().get("first"));
			assertNull(view.describe().get("last"));
			view.setRange(BankHistoryRange.D90);
			assertEquals("before any show", "90d", view.describe().get("range"));

			view.show(fixture(), null);
			assertEquals("readings up to the 20th", fixture().upTo(LocalDate.of(2026, 9, 20)).size(),
				view.describe().get("readings"));
			assertEquals("2026-08-18", view.describe().get("first"));
			assertEquals("2026-09-20", view.describe().get("last"));
			assertEquals(Arrays.asList("readings", "first", "last", "range", "rows", "carriedRows", "hoverDay"),
				new ArrayList<>(view.describe().keySet()));
		});
	}

	// ---------------------------------------------------------------------------------------- helpers

	static BankHistoryPoint cells(final LocalDate day, final long bank, final long cash)
	{
		final long[] card = new long[BankHistoryPoint.CELLS];
		card[BankHistoryPoint.BANK_TRADEABLE] = bank;
		card[BankHistoryPoint.BANK_CASH] = cash;
		return new BankHistoryPoint(day, noon(day), noon(day), card, null);
	}

	/**
	 * The chart block's children, in the order it adds them, which is its rows' order top to bottom: these five labels
	 * (the change line, then the readout line), the chart, then the range bar.
	 */
	static final int CHANGE_DAYS = 0;
	static final int CHANGE_GP = 1;
	static final int CHANGE_PCT = 2;
	static final int READOUT_DAY = 3;
	static final int READOUT_TOTAL = 4;
	static final int CHART = 5;
	static final int BAR = 6;

	/** The chart block: the chart's parent. */
	static Container chartBlock(final Container view)
	{
		return chart(view).getParent();
	}

	/** The range bar under the chart. */
	static BankHistoryView.RangeBar bar(final Container view)
	{
		return (BankHistoryView.RangeBar) chartBlock(view).getComponent(BAR);
	}

	/** The range bar's cell for {@code range}: its four cells in the ranges' order, 7d 30d 90d all. */
	static JLabel rangeCell(final Container view, final BankHistoryRange range)
	{
		return (JLabel) bar(view).getComponent(range.ordinal());
	}

	/** Whether the range bar's cell is the lit one: filled orange, its word dark. */
	static boolean lit(final JLabel cell)
	{
		return ColorScheme.BRAND_ORANGE.equals(cell.getBackground())
			&& ColorScheme.DARKER_GRAY_COLOR.equals(cell.getForeground());
	}

	/** The text of the chart block's label at {@code index} - found by its place, not by searching for a text. */
	static String chartLabel(final Container view, final int index)
	{
		return ((JLabel) chartBlock(view).getComponent(index)).getText();
	}

	static List<Component> tree(final Container c)
	{
		final List<Component> out = new ArrayList<>();
		for (Component child : c.getComponents())
		{
			out.add(child);
			if (child instanceof Container)
			{
				out.addAll(tree((Container) child));
			}
		}
		return out;
	}

	static List<BankHistoryDayRow> rows(final Container view)
	{
		final List<BankHistoryDayRow> out = new ArrayList<>();
		for (Component c : tree(view))
		{
			if (c instanceof BankHistoryDayRow)
			{
				out.add((BankHistoryDayRow) c);
			}
		}
		return out;
	}

	static BankHistoryDayRow rowOf(final Container view, final LocalDate day)
	{
		for (BankHistoryDayRow row : rows(view))
		{
			if (row.model().day().equals(day))
			{
				return row;
			}
		}
		throw new AssertionError("no row for " + day);
	}

	/** A row's label {@code i}: 0 date, 1 sub-line, 2 total, 3 exact, 4 %, 5 gp - or a carried row's words. */
	static String text(final BankHistoryDayRow row, final int i)
	{
		return ((JLabel) row.getComponent(i)).getText();
	}

	static java.awt.Color edge(final BankHistoryDayRow row)
	{
		final javax.swing.border.CompoundBorder b = (javax.swing.border.CompoundBorder) row.getBorder();
		return ((javax.swing.border.MatteBorder) b.getOutsideBorder()).getMatteColor();
	}

	static JLabel label(final Container c, final String text)
	{
		for (Component child : tree(c))
		{
			if (child instanceof JLabel && text.equals(((JLabel) child).getText()))
			{
				return (JLabel) child;
			}
		}
		return null;
	}

	static BankHistoryChart chartOrNull(final Container c)
	{
		final BankHistoryChart chart = chart(c);
		return chart == null ? new BankHistoryChart(i -> { }) : chart;
	}

	/** A left press, as a range bar cell listens for it. */
	static void press(final JLabel chip)
	{
		chip.dispatchEvent(new MouseEvent(chip, MouseEvent.MOUSE_PRESSED, System.currentTimeMillis(),
			InputEvent.BUTTON1_DOWN_MASK, 5, 5, 1, false, MouseEvent.BUTTON1));
	}

	static void hover(final JLabel chip, final int id)
	{
		chip.dispatchEvent(new MouseEvent(chip, id, System.currentTimeMillis(), 0, 5, 5, 0, false));
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * {@link BankItem}'s two addendum-Q fields (Q5), the addendum-R {@code parts} beside them (R1), and what all three
 * mean off disk.
 *
 * <p>The first test is the load-bearing one. A snapshot is a Gson bag of public fields, and every
 * {@code bank-*.json} on a user's machine was written before addendum Q existed: it names neither field. Gson
 * leaves an absent {@code boolean} at {@code false}, so the field had to be spelled {@code untradeable} rather
 * than {@code tradeable} - the other way round, every stack of every stored bank would have read as untradeable,
 * been left out of the rows while the switch was off, and emptied the sidebar of anyone who had not opened their
 * bank since updating.
 */
public class BankItemTest
{
	private static final Gson GSON = new Gson();

	/** A stack as a pre-Q file spells it: four fields, neither of the new ones. */
	private static final String PRE_Q = "{\"id\":4151,\"quantity\":3,\"name\":\"Abyssal whip\",\"stackable\":false}";

	@Test
	public void aStackFromAFileWrittenBeforeAddendumQReadsAsTradeable()
	{
		final BankItem item = GSON.fromJson(PRE_Q, BankItem.class);

		assertEquals(4151, item.id);
		assertEquals(3, item.quantity);
		assertFalse("an absent boolean is false, and false here means tradeable", item.untradeable);
		assertEquals(0, item.haPrice);
		assertNull("so it is priced by the guide table, not alched", item.alchPrice());
	}

	@Test
	public void anUntradeableStackSurvivesTheRoundTrip()
	{
		final BankItem written = new BankItem(772, 2, "Dramen staff", false, true, 1500);

		final BankItem read = GSON.fromJson(GSON.toJson(written), BankItem.class);

		assertEquals(written, read);
		assertTrue(read.untradeable);
		assertEquals(1500, read.haPrice);
		assertEquals(Long.valueOf(1500L), read.alchPrice());
	}

	/** The four-argument constructor is the tradeable one, so every existing caller keeps its meaning. */
	@Test
	public void theShortConstructorMakesATradeableStack()
	{
		final BankItem item = new BankItem(385, 500, "Shark", true);

		assertFalse(item.untradeable);
		assertEquals(0, item.haPrice);
		assertNull(item.alchPrice());
	}

	/**
	 * The one rule for "this stack is valued at its alch price", spelled once so the reader's keep rule, the row
	 * and the bank value cannot drift apart: untradeable AND worth something. Either half alone is nothing.
	 */
	@Test
	public void anAlchPriceNeedsBothTheFlagAndAPositiveValue()
	{
		assertNull("marked but worthless", new BankItem(1, 1, "Junk", false, true, 0).alchPrice());
		assertNull("a negative is not a price", new BankItem(1, 1, "Junk", false, true, -5).alchPrice());
		assertNull("a value on a tradeable stack is not what it is priced at",
			new BankItem(4151, 1, "Abyssal whip", false, false, 72_000).alchPrice());
		assertEquals(Long.valueOf(1L), new BankItem(1, 1, "Junk", false, true, 1).alchPrice());
	}

	@Test
	public void theTwoNewFieldsArePartOfTheStacksIdentity()
	{
		final BankItem tradeable = new BankItem(772, 2, "Dramen staff", false);
		final BankItem untradeable = new BankItem(772, 2, "Dramen staff", false, true, 1500);
		final BankItem cheaper = new BankItem(772, 2, "Dramen staff", false, true, 1400);

		assertNotEquals("a bank that changed which stacks it holds must be written", tradeable, untradeable);
		assertNotEquals(untradeable, cheaper);
		assertEquals(untradeable, new BankItem(772, 2, "Dramen staff", false, true, 1500));
		assertEquals(untradeable.hashCode(), new BankItem(772, 2, "Dramen staff", false, true, 1500).hashCode());
	}

	/** An ordinary stack prints what it always printed; only a marked one says more. */
	@Test
	public void toStringNamesTheAlchValueOnlyWhenThereIsOne()
	{
		assertEquals("BankItem{id=385, quantity=500, name='Shark', stackable=true}",
			new BankItem(385, 500, "Shark", true).toString());
		assertEquals("BankItem{id=772, quantity=2, name='Dramen staff', stackable=false, untradeable, haPrice=1500}",
			new BankItem(772, 2, "Dramen staff", false, true, 1500).toString());
	}

	// ---------------------------------------------------------------- R1: the tradeable parts

	/** The addendum's own example: a Crystal body reverts to three Crystal armour seeds. */
	private static final int CRYSTAL_BODY = 23_975;
	private static final int ARMOUR_SEED = 23_956;
	private static final String SEED_NAME = "Crystal armour seed";

	private static BankItem crystalBody()
	{
		return new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000,
			Collections.singletonList(new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME)));
	}

	/**
	 * The same rule the class comment makes of {@code untradeable}, for the field addendum R adds: every
	 * {@code bank-*.json} on a user's machine was written before R and names no {@code parts}, Gson leaves an
	 * absent object null, and null has to read as "no parts" - which is what those files held. The next bank open
	 * fills it in.
	 */
	@Test
	public void aStackFromAFileWrittenBeforeAddendumRHasNoParts()
	{
		final BankItem item = GSON.fromJson(PRE_Q, BankItem.class);

		assertNull(item.parts);
		assertFalse("so it is valued as it was: by the guide table or, when marked, by the alch rule", item.hasParts());
	}

	@Test
	public void aPartSurvivesTheRoundTripAsAPlainGsonValue()
	{
		final BankItem read = GSON.fromJson(GSON.toJson(crystalBody()), BankItem.class);

		assertEquals(crystalBody(), read);
		assertTrue(read.hasParts());
		assertEquals(1, read.parts.size());
		final BankItem.Part part = read.parts.get(0);
		assertEquals(ARMOUR_SEED, part.id);
		assertEquals("a long, as ItemMapping.getQuantity() is", 3L, part.quantity);
		assertEquals(SEED_NAME, part.name);
	}

	/**
	 * "No mapping" and "a mapping that named nothing" are the same answer to every reader, so only one of them is
	 * ever stored - otherwise {@code PriceService} would have to test for both before valuing a stack.
	 */
	@Test
	public void anEmptyPartsListIsStoredAsNoPartsAtAll()
	{
		assertNull(new BankItem(772, 1, "Dramen staff", false, true, 1500, Collections.emptyList()).parts);
		assertNull(new BankItem(772, 1, "Dramen staff", false, true, 1500, null).parts);
	}

	/** A file could hold {@code "parts":[null]}; that is no more a valuation than an absent field is. */
	@Test
	public void hasPartsIgnoresAListOfNothingButNulls()
	{
		final BankItem item = new BankItem(772, 1, "Dramen staff", false, true, 1500);
		item.parts = Arrays.asList((BankItem.Part) null, null);

		assertFalse(item.hasParts());
	}

	/** The six-argument constructor is the pre-R one, so every existing caller keeps its meaning. */
	@Test
	public void theSixArgumentConstructorRecordsNoParts()
	{
		assertNull(new BankItem(772, 2, "Dramen staff", false, true, 1500).parts);
		assertFalse(new BankItem(385, 500, "Shark", true).hasParts());
	}

	/**
	 * A bank whose stacks changed what they revert to has changed, and the change-only write rule (B008) compares
	 * stacks - so the parts have to be part of a stack's identity or a re-mapped item would never be re-written.
	 */
	@Test
	public void thePartsArePartOfTheStacksIdentity()
	{
		final BankItem withParts = crystalBody();
		final BankItem withNone = new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000);
		final List<BankItem.Part> two = Collections.singletonList(new BankItem.Part(ARMOUR_SEED, 2L, SEED_NAME));
		final BankItem withTwo = new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000, two);

		assertNotEquals(withParts, withNone);
		assertNotEquals("three seeds is not two seeds", withParts, withTwo);
		assertEquals(withParts, crystalBody());
		assertEquals(withParts.hashCode(), crystalBody().hashCode());
	}

	@Test
	public void aPartIsAValueOfItsOwn()
	{
		final BankItem.Part part = new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME);

		assertEquals(part, new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME));
		assertEquals(part.hashCode(), new BankItem.Part(ARMOUR_SEED, 3L, SEED_NAME).hashCode());
		assertNotEquals(part, new BankItem.Part(ARMOUR_SEED, 1L, SEED_NAME));
		assertNotEquals(part, new BankItem.Part(ARMOUR_SEED + 1, 3L, SEED_NAME));
		assertNotEquals(part, new BankItem.Part(ARMOUR_SEED, 3L, "Crystal tool seed"));
		assertEquals("a null name is \"\", as a stack's is", "", new BankItem.Part(1, 1L, null).name);
		assertEquals("Part{id=23956, quantity=3, name='Crystal armour seed'}", part.toString());
	}

	/**
	 * Y3: the merge of a banked stack and a carried one is a COPY with the quantities added - the stacks it merges
	 * belong to the persisted snapshot, and a computation that wrote to one would put a number in
	 * {@code bank-*.json} that no bank ever held. Everything but the quantity rides along.
	 */
	@Test
	public void withQuantityCopiesTheStackAndChangesNothingElse()
	{
		final BankItem body = crystalBody();

		final BankItem merged = body.withQuantity(4);

		assertEquals(4, merged.quantity);
		assertEquals("the original is untouched", 1, body.quantity);
		assertEquals(body.id, merged.id);
		assertEquals(body.name, merged.name);
		assertEquals(body.stackable, merged.stackable);
		assertEquals(body.untradeable, merged.untradeable);
		assertEquals(body.haPrice, merged.haPrice);
		assertEquals(body.parts, merged.parts);
		assertEquals(body, merged.withQuantity(1));
	}

	/** An ordinary stack still prints what it always printed; only one with parts says more. */
	@Test
	public void toStringNamesThePartsOnlyWhenThereAreSome()
	{
		assertEquals("BankItem{id=385, quantity=500, name='Shark', stackable=true}",
			new BankItem(385, 500, "Shark", true).toString());
		assertEquals("BankItem{id=23975, quantity=1, name='Crystal body', stackable=false, untradeable, "
				+ "haPrice=900000, parts=[Part{id=23956, quantity=3, name='Crystal armour seed'}]}",
			crystalBody().toString());
	}
}

package com.bankpricemovement;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards the flat shape of {@link BankPriceMovementConfig} (contract C39). RuneLite's
 * {@code ConfigManager.setDefaultConfiguration} only walks {@code getDeclaredMethods()} of the config
 * interface, while {@code ConfigManager.getConfigDescriptor} builds the panel from {@code getMethods()}.
 * An item inherited from a super-interface is therefore rendered but never gets a stored default, and
 * {@code ConfigPanel.createComboBox} then throws an uncaught NPE out of {@code Enum.valueOf(type, null)},
 * so the config panel cannot open at all. Cloned from {@code LootAndBeamConfigTest}, which guards the same
 * thing for the other plugin.
 */
public class BankPriceMovementConfigTest
{
	private static final List<String> EXPECTED_KEYS = Arrays.asList(
		"gpMin",
		"gpMax",
		// Addendum Z line Z1: it landed as the fourteenth key and is the thirteenth since addendum AO, and it is
		// the only free-text one - the three quick bands the fold's chips offer, as one line of gp shorthand. It
		// sits beside the two bounds because it is about the same thing they are.
		"bandPresets",
		// Addendum AA line AA1: it landed as the fifteenth key and is the fourteenth since addendum AO - whether
		// the fold those chips live in is open. Directly after the presets, because it decides whether they are
		// on screen at all.
		"foldOpen",
		"sortMode",
		"sortDescending",
		"window",
		// Addendum O line O2: the bank value card's three show/hide switches. Addendum N's "look" was deleted
		// with the One Bar design (O1) - BankPriceMovementPlugin.unstickLook() sweeps it off old profiles.
		"showBankValue",
		"showBankMoveGp",
		"showBankMovePct",
		// Addendum Q line Q3: the gear menu's view switches, carried as one ViewOptions. It brought THREE and has
		// two - addendum AO line AO1 deleted "holdingOnRows", the second key to go for good after addendum N's
		// "look", and theHoldingSwitchIsGone below is the guard that keeps it gone.
		"countCash",
		"countUntradeables",
		// Addendum T line T1: the live-traded-price switch, the third field of the same ViewOptions since AO
		// (it landed as the fourth).
		"livePrices",
		// Addendum Y line Y1: the carried switch, the fourth field of the same ViewOptions since AO (it landed as
		// the fifth) and the thirteenth key added to the group. On by default, unlike the two switches beside it.
		"countInventory",
		// 1.0.9 part 3: the Grand Exchange switch, the sixth field of the same ViewOptions and the seventeenth key
		// - the player's offers counted and listed beside the bank's stacks. On by default, like the carried one.
		"countGrandExchange",
		// Addendum AU: the sixteenth key and the last on the page - the tab the sidebar opens on (Items unless the
		// player chose Net Worth History). The player's choice, never the last tab used.
		"startTab",
		// 1.0.9 part 5: the eighteenth key and the only HIDDEN one - whether the Net Worth History tab shows the days
		// recorded before 1.0.9. The check box on the tab is its control; the settings page does not list it.
		"includeLegacyHistory",
		// 1.1.0 part B: the nineteenth and twentieth keys - the colour a rise and a fall are drawn in, on both tabs.
		// VISIBLE on the page (a colour needs no question asked first), and rows of the sidebar's settings menu.
		"upColour",
		"downColour",
		// 1.1.0 part C: the twenty-first and twenty-second keys - whether the Net Worth History chart is drawn in one
		// colour, and which. VISIBLE on the page, and the menu's "Single chart colour" row and its swatch.
		"singleChartColour",
		"chartColour",
		// 1.1.0 part E: the twenty-third key - whether the sidebar hides every gp amount and item quantity (the eye on
		// the hero card). VISIBLE on the page.
		"hideAmounts",
		// 1.1.0 part G: the twenty-fourth key - whether the Items list shows its alch rows (the tick in the List options
		// menu at the end of the search box). VISIBLE on the page.
		"showAlchRows",
		// 1.1.0 part J: the twenty-fifth and twenty-sixth keys - the rise and the fall the colour presets' Slot 1
		// holds. HIDDEN: the menu's "Save current colours to Slot 1" row writes them.
		"slotUpColour",
		"slotDownColour"
	);

	/** Every zero-argument {@code @ConfigItem} method visible on the interface, inherited ones included. */
	private static List<Method> itemMethods()
	{
		final List<Method> methods = new ArrayList<>();
		for (Method m : BankPriceMovementConfig.class.getMethods())
		{
			if (m.getParameterCount() == 0 && m.isAnnotationPresent(ConfigItem.class))
			{
				methods.add(m);
			}
		}
		return methods;
	}

	@Test
	public void extendsConfigDirectlyAndNothingElse()
	{
		assertEquals(
			"BankPriceMovementConfig must extend net.runelite.client.config.Config and no other interface",
			Arrays.asList(Config.class),
			Arrays.asList(BankPriceMovementConfig.class.getInterfaces()));
	}

	@Test
	public void everyItemIsDeclaredOnThisInterface()
	{
		for (Method m : itemMethods())
		{
			assertEquals(
				"inherited config items get no defaults: ConfigManager.setDefaultConfiguration uses getDeclaredMethods()",
				BankPriceMovementConfig.class,
				m.getDeclaringClass());
		}
	}

	/**
	 * The whole stored surface of the plugin in one assertion, and the place the Hub's "never rename a config key
	 * without a migration" rule is guarded: {@link #EXPECTED_KEYS} is the frozen list, so a rename shows up here as
	 * two failures at once (the old spelling missing, the new one unexpected) rather than as a silently discarded
	 * setting on every user's profile. A key ADDED must be added to the list deliberately - which is the whole of
	 * the ceremony, and the reason it is cheap enough to keep.
	 *
	 * <p>Twenty-five since release 1.2.0, which took one away and put nothing in its place: {@code showHoverText}
	 * (addendum AH) went because every hover left in the sidebar is one short line, so the hovers are always on and a
	 * switch to hide them was one setting more than the plugin needs (the user, 2026-10-08). Before it, addendum AO
	 * took {@code holdingOnRows} away (AO1) because addendum AN's three-line row prints the stack and the item both,
	 * so that switch reached nothing drawn. Both deleted keys are swept off old profiles rather than migrated
	 * ({@link BankPriceMovementPlugin#unstickHolding()}, {@link BankPriceMovementPlugin#unstickShowHoverText()}),
	 * because nothing survives them to migrate INTO.
	 */
	@Test
	public void declaresExactlyTheExpectedItems()
	{
		final List<Method> methods = itemMethods();
		final Set<String> keys = new TreeSet<>();
		for (Method m : methods)
		{
			keys.add(m.getAnnotation(ConfigItem.class).keyName());
		}
		assertEquals("unexpected set of config keys", new TreeSet<>(EXPECTED_KEYS), keys);
		// Twenty-five: addendum AU's "view" (the last tab used) was deleted before it shipped and "startTab" (the
		// player's choice) took its place; 1.0.9 part 3's "countGrandExchange" sits at position 13, 1.0.9 part 5's
		// hidden "includeLegacyHistory" at 16, 1.1.0 part B's "upColour" and "downColour" at 17 and 18, part C's
		// "singleChartColour" and "chartColour" at 19 and 20, part E's "hideAmounts" at 21, part G's "showAlchRows" at 22
		// and part J's "slotUpColour" and "slotDownColour" at 23 and 24. Release 1.2.0 took "showHoverText" out from
		// between the Grand Exchange switch and "livePrices", and everything from "livePrices" down moved up by one.
		assertEquals("unexpected number of config items", 25, methods.size());
	}

	/**
	 * Two keys may never share a spelling (a rename is a discarded setting) and two items may never share a
	 * position, because RuneLite sorts the page on it and a tie is drawn in whatever order reflection answers in.
	 *
	 * <p>The positions also have to run 0, 1, 2 ... with no gap, which is worth pinning since addendum AO line
	 * AO1: it is the first change that ever DELETED an item from the middle of the page, and the cheap version
	 * of that change - leave the hole where {@code holdingOnRows} was - is exactly the one nobody would notice by
	 * reading the interface. Positions are not frozen the way keys are, so renumbering is allowed and leaving a
	 * hole is the thing being ruled out.
	 */
	@Test
	public void keyNamesAndPositionsAreUniqueAndRunFromZeroWithNoGap()
	{
		final Set<String> keys = new HashSet<>();
		final Set<Integer> positions = new HashSet<>();
