	/** One pixel row of {@code a} against one of {@code b}. */
	private static boolean sameRow(BufferedImage a, BufferedImage b, int ya, int yb)
	{
		for (int x = 0; x < a.getWidth(); x++)
		{
			if (a.getRGB(x, ya) != b.getRGB(x, yb))
			{
				return false;
			}
		}
		return true;
	}

