	/** Sizes and lays the panel out top-down, twice: the second pass sees the scrollbar the first one created. */
	private void layout(int width, int height)
	{
		panel.setSize(width, height);
		LookRenderer.layoutTree(panel);
		LookRenderer.layoutTree(panel);
