		prefs.save(new RowFilter(250, Long.MAX_VALUE, SortMode.GP_MOVE, false, MovementWindow.D7));

		final String g = BankPriceMovementConfig.GROUP;
		verify(cm).setConfiguration(g, "gpMin", (Object) 250);
