package com.bankpricemovement;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.ColorScheme;
import org.junit.After;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * 1.1.0 part B (contract {@code docs/handoff/contract-1.1.0-settings-and-colours-2026-10-03.md}): the palette behind
 * {@link Widgets#move} - frozen tests B1 and B2 - and where the colour picker stands, B7b.
 *
 * <p>The palette is one static for the whole process, so every test that sets it clears it in {@code @After}: no other test
 * may see it.
 */
public class MoveColoursTest
{
	/** What a reader picks for a rise and for a fall: neither equals a built-in colour. */
	private static final Color UP = new Color(10, 20, 200);
	private static final Color DOWN = new Color(200, 150, 0);

	@After
	public void clearThePalette()
	{
		Widgets.setMoveColours(null, null);
	}

	/** {@code from} mixed 55 % of the way into the card's grey, as {@link Widgets.Kind#QUIET} is documented to be. */
	private static Color quiet(Color from)
	{
		final Color to = ColorScheme.DARKER_GRAY_COLOR;
		return new Color(
			(int) Math.round(from.getRed() + (to.getRed() - from.getRed()) * 0.55),
			(int) Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * 0.55),
			(int) Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * 0.55));
	}

	// ---------------------------------------------------------------- B1: no palette, today's colours

	/** B1: with no palette every {@code move(signum, kind)} is exactly what it returned before the palette existed. */
	@Test
	public void b1_withNoPaletteEveryMoveColourIsExactlyWhatItWasBefore() throws Exception
	{
		// A rise: the client's green for a figure and a mark, its darker() for an edge, the figure pushed 55 % into the card for the quiet one.
		assertEquals(new Color(55, 240, 70), Widgets.move(1, Widgets.Kind.FIGURE));
		assertEquals(new Color(55, 240, 70), Widgets.move(1, Widgets.Kind.MARK));
		assertEquals(new Color(38, 168, 49), Widgets.move(1, Widgets.Kind.EDGE));
		assertEquals(new Color(41, 124, 48), Widgets.move(1, Widgets.Kind.QUIET));
		// A fall: the lifted red for the figure, the client's own red for the mark, the darker() of THAT for the edge.
		assertEquals(new Color(240, 92, 84), Widgets.move(-1, Widgets.Kind.FIGURE));
		assertEquals(new Color(230, 30, 30), Widgets.move(-1, Widgets.Kind.MARK));
		assertEquals(new Color(161, 21, 21), Widgets.move(-1, Widgets.Kind.EDGE));
		assertEquals(new Color(124, 58, 54), Widgets.move(-1, Widgets.Kind.QUIET));
		// Flat or none: the quiet grey, the card's own grey for an edge.
		for (final Widgets.Kind kind : Widgets.Kind.values())
		{
			assertEquals(kind == Widgets.Kind.EDGE ? new Color(30, 30, 30) : new Color(165, 165, 165),
				Widgets.move(0, kind));
		}
		// The constants those numbers stand for.
		assertEquals(ColorScheme.PROGRESS_COMPLETE_COLOR, Widgets.move(1, Widgets.Kind.FIGURE));
		assertEquals(Widgets.MOVE_DOWN_TEXT, Widgets.move(-1, Widgets.Kind.FIGURE));
		assertEquals(ColorScheme.PROGRESS_ERROR_COLOR, Widgets.move(-1, Widgets.Kind.MARK));
	}

	// ---------------------------------------------------------------- B2: a palette

	/**
	 * B2: with up = c and down = d the four kinds follow the contract - a figure and a mark are the colour, the quiet figure
	 * is it 55 % toward the card, an edge is its darker() - a direction that has no colour set keeps its built-in one, and
	 * a flat move is untouched.
	 */
	@Test
	public void b2_aPaletteColoursTheFourKindsOfEachDirectionAndLeavesTheFlatOneAlone() throws Exception
	{
		Widgets.setMoveColours(UP, DOWN);

		assertEquals(UP, Widgets.move(1, Widgets.Kind.FIGURE));
		assertEquals(UP, Widgets.move(1, Widgets.Kind.MARK));
		assertEquals(UP.darker(), Widgets.move(1, Widgets.Kind.EDGE));
		assertEquals(quiet(UP), Widgets.move(1, Widgets.Kind.QUIET));

		assertEquals(DOWN, Widgets.move(-1, Widgets.Kind.FIGURE));
		assertEquals("a chosen fall is one colour for the figure AND the mark", DOWN, Widgets.move(-1, Widgets.Kind.MARK));
		assertEquals(DOWN.darker(), Widgets.move(-1, Widgets.Kind.EDGE));
		assertEquals(quiet(DOWN), Widgets.move(-1, Widgets.Kind.QUIET));

		for (final Widgets.Kind kind : Widgets.Kind.values())
		{
			assertEquals("a flat move is untouched: " + kind,
				kind == Widgets.Kind.EDGE ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR,
				Widgets.move(0, kind));
		}

		// One direction only: the other keeps today's colours.
		Widgets.setMoveColours(UP, null);
		assertEquals(UP, Widgets.move(1, Widgets.Kind.FIGURE));
		assertEquals(Widgets.MOVE_DOWN_TEXT, Widgets.move(-1, Widgets.Kind.FIGURE));
		assertEquals(ColorScheme.PROGRESS_ERROR_COLOR, Widgets.move(-1, Widgets.Kind.MARK));
		Widgets.setMoveColours(null, DOWN);
		assertEquals(ColorScheme.PROGRESS_COMPLETE_COLOR, Widgets.move(1, Widgets.Kind.FIGURE));
		assertEquals(DOWN, Widgets.move(-1, Widgets.Kind.MARK));
	}

	/**
	 * B2: setting the defaults is no palette - the config's own defaults ({@code ColorScheme.PROGRESS_COMPLETE_COLOR},
	 * {@link Widgets#MOVE_DOWN_TEXT}) are read as "nothing chosen", so the built-in red mark and edge stay the deeper red
	 * and a reader who never touched the setting sees the sidebar exactly as before - and an opaque copy of a default,
	 * or one with transparency, is the same default.
	 */
	@Test
	public void b2_settingTheDefaultsIsNoPaletteAndTransparencyIsDropped() throws Exception
	{
		Widgets.setMoveColours(ColorScheme.PROGRESS_COMPLETE_COLOR, Widgets.MOVE_DOWN_TEXT);
		assertSame("a default rise is the very constant: no palette", ColorScheme.PROGRESS_COMPLETE_COLOR,
			Widgets.move(1, Widgets.Kind.FIGURE));
		assertEquals(new Color(38, 168, 49), Widgets.move(1, Widgets.Kind.EDGE));
		assertEquals(new Color(41, 124, 48), Widgets.move(1, Widgets.Kind.QUIET));
		assertEquals(new Color(230, 30, 30), Widgets.move(-1, Widgets.Kind.MARK));
		assertEquals(new Color(161, 21, 21), Widgets.move(-1, Widgets.Kind.EDGE));
		assertEquals(new Color(124, 58, 54), Widgets.move(-1, Widgets.Kind.QUIET));
		assertEquals(new Color(240, 92, 84), Widgets.move(-1, Widgets.Kind.FIGURE));

		Widgets.setMoveColours(new Color(55, 240, 70, 90), new Color(Widgets.MOVE_DOWN_TEXT.getRGB()));
		assertEquals("a see-through default is still the default", new Color(38, 168, 49),
			Widgets.move(1, Widgets.Kind.EDGE));
		assertEquals(new Color(230, 30, 30), Widgets.move(-1, Widgets.Kind.MARK));

		// A colour that is NOT a default is drawn opaque whatever alpha it came with.
		Widgets.setMoveColours(new Color(10, 20, 200, 40), null);
		assertEquals(255, Widgets.move(1, Widgets.Kind.FIGURE).getAlpha());
		assertEquals(UP, Widgets.move(1, Widgets.Kind.FIGURE));

		// The client's own red is NOT the down default (the lifted red is): chosen, it is one colour for every kind.
		Widgets.setMoveColours(null, ColorScheme.PROGRESS_ERROR_COLOR);
		assertEquals(ColorScheme.PROGRESS_ERROR_COLOR, Widgets.move(-1, Widgets.Kind.FIGURE));
		assertEquals(ColorScheme.PROGRESS_ERROR_COLOR.darker(), Widgets.move(-1, Widgets.Kind.EDGE));

		// And clearing puts today's colours back.
		Widgets.setMoveColours(null, null);
		assertEquals(new Color(240, 92, 84), Widgets.move(-1, Widgets.Kind.FIGURE));
		assertEquals(new Color(55, 240, 70), Widgets.move(1, Widgets.Kind.FIGURE));
	}

	/** The Refresh glow keeps its own green: it marks a held bank change, not a rise, whatever the reader picks. */
	@Test
	public void theRefreshGlowKeepsItsOwnGreenWhateverTheReaderPicks() throws Exception
	{
		Widgets.setMoveColours(UP, DOWN);
		assertEquals(ColorScheme.PROGRESS_COMPLETE_COLOR, BankPriceMovementPanel.GLOW_COLOUR);
	}

	// ---------------------------------------------------------------- B7b: where the picker stands

	private static final Rectangle SCREEN = new Rectangle(0, 0, 1920, 1080);
	private static final Dimension PICKER = new Dimension(400, 300);

	private static void assertInside(Rectangle screen, Point spot, Dimension size)
	{
		assertTrue("inside the screen on the left and top: " + spot, spot.x >= screen.x && spot.y >= screen.y);
		assertTrue("inside the screen on the right and bottom: " + spot,
			spot.x + size.width <= screen.x + screen.width && spot.y + size.height <= screen.y + screen.height);
	}

	/** B7b: with room on the left the picker stands left of the panel, 8 px clear of it, its top level with the panel's. */
	@Test
	public void b7b_withRoomOnTheLeftThePickerStandsLeftOfThePanelWithTheTopsLevel()
	{
		final Rectangle panel = new Rectangle(1500, 120, 225, 800);
		final Point spot = RuneLiteColourPicker.pickerSpot(panel, PICKER, SCREEN);
		assertEquals(new Point(1500 - 400 - 8, 120), spot);
		assertEquals("its right edge is 8 px short of the panel's left", panel.x - 8, spot.x + PICKER.width);
		assertEquals("the tops are level", panel.y, spot.y);
		assertInside(SCREEN, spot, PICKER);
		assertTrue("and it does not cover the panel", spot.x + PICKER.width <= panel.x);
	}

	/** B7b: with exactly enough room on the left it is still on the left; one pixel less and it is on the right. */
	@Test
	public void b7b_theLeftSideIsTakenWhileItFitsAndTheRightOnlyWhenItDoesNot()
	{
		final Rectangle fits = new Rectangle(408, 50, 225, 800);
		assertEquals(new Point(0, 50), RuneLiteColourPicker.pickerSpot(fits, PICKER, SCREEN));
		final Rectangle short1 = new Rectangle(407, 50, 225, 800);
		final Point right = RuneLiteColourPicker.pickerSpot(short1, PICKER, SCREEN);
		assertEquals("one pixel short on the left: the right of the panel", new Point(407 + 225 + 8, 50), right);
		assertInside(SCREEN, right, PICKER);
	}

	/** B7b: no room on the left puts it to the right of the panel, 8 px clear, the tops still level. */
	@Test
	public void b7b_withNoRoomOnTheLeftItStandsRightOfThePanel()
	{
		final Rectangle panel = new Rectangle(300, 100, 225, 800);
		final Point spot = RuneLiteColourPicker.pickerSpot(panel, PICKER, SCREEN);
		assertEquals(new Point(300 + 225 + 8, 100), spot);
		assertEquals(panel.y, spot.y);
		assertTrue("and it does not cover the panel", spot.x >= panel.x + panel.width);
		assertInside(SCREEN, spot, PICKER);
	}

	/** B7b: with room on neither side it falls back to the screen's left edge, inside the screen. */
	@Test
	public void b7b_withRoomOnNeitherSideItFallsBackToTheScreensLeftEdge()
	{
		final Rectangle panel = new Rectangle(100, 100, 1700, 800);
		final Point spot = RuneLiteColourPicker.pickerSpot(panel, PICKER, SCREEN);
		assertEquals(new Point(0, 100), spot);
		assertInside(SCREEN, spot, PICKER);

		// The same on a second monitor, whose left edge is not 0.
		final Rectangle second = new Rectangle(1920, 0, 1920, 1080);
		final Rectangle onSecond = new Rectangle(2000, 40, 1700, 800);
		final Point there = RuneLiteColourPicker.pickerSpot(onSecond, PICKER, second);
		assertEquals(new Point(1920, 40), there);
		assertInside(second, there, PICKER);
	}

	/** B7b: always inside the screen - the top follows the panel's but is pulled up or down as far as the screen needs. */
	@Test
	public void b7b_theTopIsThePanelsButNeverLeavesTheScreen()
	{
		// A panel whose top is below where a 300 px picker would still fit: the picker is pulled up to the bottom edge.
		final Rectangle low = new Rectangle(1500, 900, 225, 800);
		final Point pulledUp = RuneLiteColourPicker.pickerSpot(low, PICKER, SCREEN);
		assertEquals(new Point(1092, 1080 - 300), pulledUp);
		assertInside(SCREEN, pulledUp, PICKER);

		// A panel scrolled partly off the top of the screen: the picker is pushed down to the screen's top.
		final Rectangle high = new Rectangle(1500, -60, 225, 800);
		final Point pushedDown = RuneLiteColourPicker.pickerSpot(high, PICKER, SCREEN);
		assertEquals(new Point(1092, 0), pushedDown);
		assertInside(SCREEN, pushedDown, PICKER);

		// A second monitor above the first, whose top is negative.
		final Rectangle above = new Rectangle(0, -1080, 1920, 1080);
		final Rectangle panelAbove = new Rectangle(1500, -1200, 225, 800);
		final Point up = RuneLiteColourPicker.pickerSpot(panelAbove, PICKER, above);
		assertEquals(new Point(1092, -1080), up);
		assertInside(above, up, PICKER);
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.text.ParseException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.Test;

/**
 * {@link MovementMath} (contract C8-C10): every number the sidebar shows.
 *
 * <p>Four things are worth the length. (1) The SOURCE ladder - the guide price now (addendum K, source GUIDE),
 * else the fallback price the service no longer offers, else no price - because a fallback price must never be
 * subtracted from a baseline to invent a move (D9, C8, K13). (2) NULLS LAST under both directions, because a
 * bank item whose name is in neither the mapping nor the guide table has no baseline, and flipping the arrow
 * must not fill the top of the list with dashes. (3) The gp BAND
 * edges, which are the user's headline feature. (4) {@code parseGp}, which is the one place user typing
 * becomes a number. (5) Since addendum L, the PRINTED percentage: truncation toward zero and a sign taken from
 * the gp change (L2), because the number on the row is compared against the Grand Exchange site's own by the
 * user, item by item.
 */
public class MovementMathTest
{
	/**
	 * A stack of one, priced by a point whose two sides are equal, so the mid is exactly the number written
	 * here and the sort tests read as their own expectations.
	 */
	private static MovementRow guideRow(final int id, final String name, final long unit, final Long then)
	{
		return MovementMath.row(new BankItem(id, 1, name, false), new PricePoint(unit, unit),
			then == null ? null : new PricePoint(then, then), 0);
	}

	private static List<String> names(final List<MovementRow> rows)
	{
		final List<String> names = new ArrayList<>();
		for (final MovementRow row : rows)
		{
			names.add(row.name());
		}

		return names;
	}

	// ---------------------------------------------------------------- row: where the price comes from (C8)

	@Test
	public void aGuidePriceIsTheMidOfTheNowPoint()
	{
		final MovementRow row = MovementMath.row(new BankItem(4151, 2, "Abyssal whip", false),
			new PricePoint(1_600_000L, 1_500_000L), new PricePoint(1_500_000L, 1_400_000L), 999);

		assertEquals(4151, row.id());
		assertEquals("Abyssal whip", row.name());
		assertEquals(2, row.quantity());
		assertFalse(row.stackable());
		assertEquals(Long.valueOf(1_550_000L), row.unitPrice());
		assertEquals(Long.valueOf(1_450_000L), row.thenPrice());
		assertSame("a guide price wins over the fallback", MovementRow.PriceSource.GUIDE, row.source());
		assertEquals(3_100_000L, row.holdingValue());
	}

	@Test
	public void oneSidedNowStillPricesTheRow()
	{
		assertEquals(Long.valueOf(180L),
			MovementMath.row(new BankItem(2, 1, "Cannonball", true), new PricePoint(null, 180L), null, 0)
				.unitPrice());
		assertEquals(Long.valueOf(190L),
			MovementMath.row(new BankItem(2, 1, "Cannonball", true), new PricePoint(190L, null), null, 0)
				.unitPrice());
	}

	@Test
	public void noGuidePriceFallsBackToRuneliteAndSaysSo()
	{
		final MovementRow row = MovementMath.row(new BankItem(4151, 3, "Abyssal whip", false), null,
			new PricePoint(1_000_000L, 1_000_000L), 1_234_567);

		assertEquals(Long.valueOf(1_234_567L), row.unitPrice());
		assertSame(MovementRow.PriceSource.RUNELITE, row.source());
		assertEquals(3_703_701L, row.holdingValue());
		assertNull("a fallback price is not the guide series - no move can be computed from it", row.deltaGp());
		assertNull(row.deltaPct());
		assertFalse(row.hasMovement());
		assertEquals("the baseline is still shown", Long.valueOf(1_000_000L), row.thenPrice());
	}

	/**
	 * A point that exists but carries NEITHER side is "no price", not zero - the defensive case of C3.
	 */
	@Test
	public void anEmptyNowPointIsTreatedAsNoPrice()
	{
		final MovementRow row = MovementMath.row(new BankItem(2, 1, "Cannonball", true), PricePoint.EMPTY,
			null, 500);

		assertEquals(Long.valueOf(500L), row.unitPrice());
		assertSame(MovementRow.PriceSource.RUNELITE, row.source());
	}

	@Test
	public void noPriceAnywhereIsSourceNone()
	{
		final MovementRow row = MovementMath.row(new BankItem(2, 7, "Cannonball", true), null, null, 0);

		assertNull(row.unitPrice());
		assertSame(MovementRow.PriceSource.NONE, row.source());
		assertEquals("no price, no holding value", 0L, row.holdingValue());
		assertFalse(row.hasMovement());
	}

	@Test
	public void aZeroFallbackIsNotAPrice()
	{
		assertSame(MovementRow.PriceSource.NONE,
			MovementMath.row(new BankItem(2, 1, "Cannonball", true), null, null, 0).source());
		assertSame("a negative fallback is not a price either", MovementRow.PriceSource.NONE,
			MovementMath.row(new BankItem(2, 1, "Cannonball", true), null, null, -5).source());
	}

	@Test
	public void aNullItemIsAProgrammingError()
	{
		try
		{
			MovementMath.row(null, PricePoint.EMPTY, PricePoint.EMPTY, 0);
			fail("a row without an item should not be constructible");
		}
		catch (NullPointerException expected)
		{
			// the point of the test
		}
	}

	// ---------------------------------------------------------------- row: the move (C8)

	@Test
	public void aRiseAndAFallAreSignedGpAndPercent()
	{
		final MovementRow rise = guideRow(1, "Rise", 1_550_000L, 1_450_000L);
		assertEquals(Long.valueOf(100_000L), rise.deltaGp());
		assertNotNull(rise.deltaPct());
		assertEquals(6.8966d, rise.deltaPct(), 0.0001d);
		assertTrue(rise.hasMovement());

		final MovementRow fall = guideRow(2, "Fall", 900L, 1_000L);
		assertEquals(Long.valueOf(-100L), fall.deltaGp());
		assertEquals(-10.0d, fall.deltaPct(), 0.0001d);

		final MovementRow flat = guideRow(3, "Flat", 1_000L, 1_000L);
		assertEquals(Long.valueOf(0L), flat.deltaGp());
		assertEquals(0.0d, flat.deltaPct(), 0.0001d);
		assertTrue("a flat row still HAS a movement - it is zero, not unknown", flat.hasMovement());
	}

	@Test
	public void noBaselineIsNoMove()
	{
		final MovementRow row = guideRow(1, "Alpha", 1_000L, null);

		assertNull(row.thenPrice());
		assertNull(row.deltaGp());
		assertNull(row.deltaPct());
		assertFalse(row.hasMovement());
		assertSame("the price itself is still a guide price", MovementRow.PriceSource.GUIDE, row.source());
	}

	/**
	 * A baseline of zero would make the percentage infinite; the row shows the price and no move instead.
	 */
	@Test
	public void aZeroBaselineIsNoMove()
	{
		final MovementRow row = guideRow(1, "Alpha", 1_000L, 0L);

		assertEquals(Long.valueOf(0L), row.thenPrice());
		assertNull(row.deltaGp());
		assertNull(row.deltaPct());
	}

	/**
	 * L1 spells 0 as "there is no price for this item", and the two other places that decide what counts as a
	 * price - the service's own {@code price > 0} and {@code PortfolioMath}'s {@code priced} - already say so. A
	 * "now" of 0 reaches here through L3's degraded mode, where the side comes from a guide TABLE rather than
	 * from RuneLite; a row priced at 0 would pass the band, count as priced, read "-100.0%" at the top of the
	 * losers, and be left out of the bank-value card that the same list is published beside.
	 */
	@Test
	public void aZeroGuidePriceIsNoPriceAtAll()
	{
		final MovementRow zero = MovementMath.row(new BankItem(1, 5, "Alpha", false),
			new PricePoint(0L, 0L), new PricePoint(1_000L, 1_000L), 0);

		assertNull(zero.unitPrice());
		assertEquals(MovementRow.PriceSource.NONE, zero.source());
		assertNull("and no move against a baseline it cannot be compared with", zero.deltaGp());
		assertEquals(0L, zero.holdingValue());

		final MovementRow negative = MovementMath.row(new BankItem(2, 1, "Bravo", false),
			new PricePoint(-5L, -5L), null, 0);
		assertNull("a negative is not a price either", negative.unitPrice());

		final MovementRow fallback = MovementMath.row(new BankItem(3, 1, "Charlie", false),
			new PricePoint(0L, 0L), null, 700);
		assertEquals("the ladder falls through to the caller's fallback, as it does for a null point",
			Long.valueOf(700L), fallback.unitPrice());
		assertEquals(MovementRow.PriceSource.RUNELITE, fallback.source());
	}

	@Test
	public void anEmptyBaselinePointIsNoMove()
	{
		final MovementRow row = MovementMath.row(new BankItem(1, 1, "Alpha", false),
			new PricePoint(100L, 100L), PricePoint.EMPTY, 0);

		assertNull(row.thenPrice());
		assertNull(row.deltaGp());
	}

	// ---------------------------------------------------------------- holding value (C8)

	@Test
	public void aHoldingIsThePriceTimesTheStack()
	{
		assertEquals(3_100_000L, MovementMath.holdingValue(1_550_000L, 2));
		assertEquals(0L, MovementMath.holdingValue(null, 5));
		assertEquals(0L, MovementMath.holdingValue(100L, 0));
		assertEquals(0L, MovementMath.holdingValue(100L, -3));
	}

	/**
	 * A bank can hold billions of a billion-gp item on paper; the product is clamped, never wrapped into a
	 * negative fortune.
	 */
	@Test
	public void anImpossibleHoldingClampsRatherThanWraps()
	{
		assertEquals(Long.MAX_VALUE, MovementMath.holdingValue(Long.MAX_VALUE, 2));
		assertEquals(Long.MAX_VALUE, MovementMath.holdingValue(Long.MAX_VALUE / 2L, 5));
		assertTrue(MovementMath.holdingValue(Long.MAX_VALUE, Integer.MAX_VALUE) > 0L);

		final MovementRow row = MovementMath.row(new BankItem(2, 2, "Cannonball", true),
			new PricePoint(Long.MAX_VALUE, Long.MAX_VALUE), null, 0);
		assertEquals(Long.MAX_VALUE, row.holdingValue());
	}

	// ---------------------------------------------------------------- the gp band (C9, C10)

	@Test
	public void theBandIsInclusiveAtBothEnds()
	{
		assertTrue(MovementMath.inBand(100L, 100L, 200L));
		assertTrue(MovementMath.inBand(200L, 100L, 200L));
		assertTrue(MovementMath.inBand(150L, 100L, 200L));
		assertFalse(MovementMath.inBand(99L, 100L, 200L));
		assertFalse(MovementMath.inBand(201L, 100L, 200L));
	}

	@Test
	public void aMaximumOfZeroIsNoUpperBound()
	{
		assertTrue(MovementMath.inBand(Long.MAX_VALUE, 0L, 0L));
		assertTrue(MovementMath.inBand(0L, 0L, 0L));
		assertTrue(MovementMath.inBand(2_000_000_000L, 1_000_000L, 0L));
		assertFalse("the minimum still bites", MovementMath.inBand(999_999L, 1_000_000L, 0L));
	}

	@Test
	public void applyKeepsOnlyTheBand()
	{
		final List<MovementRow> rows = Arrays.asList(
			guideRow(1, "Under", 99L, 50L),
			guideRow(2, "AtMin", 100L, 50L),
			guideRow(3, "Between", 150L, 50L),
			guideRow(4, "AtMax", 200L, 50L),
			guideRow(5, "Over", 201L, 50L));

		final List<MovementRow> kept = MovementMath.apply(rows,
			new RowFilter(100L, 200L, SortMode.UNIT_PRICE, false, MovementWindow.D1));

		assertEquals(Arrays.asList("AtMin", "Between", "AtMax"), names(kept));
	}

	/**
	 * An item with no price at all cannot be judged against a gp band, so it leaves the list entirely rather
	 * than sitting at the bottom and inflating the count line.
	 */
	@Test
	public void applyDropsRowsWithNoUnitPrice()
	{
		final List<MovementRow> rows = Arrays.asList(
			MovementMath.row(new BankItem(1, 1, "Priceless", false), null, null, 0),
			guideRow(2, "Priced", 100L, 50L));

		final List<MovementRow> kept = MovementMath.apply(rows, RowFilter.DEFAULT);

		assertEquals(Collections.singletonList("Priced"), names(kept));
	}

	@Test
	public void applyToleratesNullsAndReturnsANewUnmodifiableList()
	{
		final List<MovementRow> rows = new ArrayList<>();
		rows.add(null);
		rows.add(guideRow(1, "Alpha", 100L, 50L));

		final List<MovementRow> kept = MovementMath.apply(rows, null);
		assertEquals("a null filter reads as the default, and the null row is skipped", 1, kept.size());
		assertEquals("the caller's list is left as it was", 2, rows.size());

		try
		{
			kept.add(guideRow(2, "Bravo", 100L, 50L));
			fail("the published row list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// the point of the test
		}

		assertTrue(MovementMath.apply(null, RowFilter.DEFAULT).isEmpty());
		assertTrue(MovementMath.apply(Collections.emptyList(), RowFilter.DEFAULT).isEmpty());
	}

	// ---------------------------------------------------------------- the search box (1.0.9 part 4)

	/**
	 * What the box matches: any PART of the name, whatever the case, the query trimmed, a blank query everything and a
	 * name that is not there nothing. The contract's own example - "rune" finding "Rune platebody" and "Runite ore" - is
	 * not a plain substring ("runite" does not contain "rune"), so "run" is the query that finds both and "rune" finds
	 * the one.
	 */
	@Test
	public void matchesAnyPartOfTheNameWhateverTheCase()
	{
		assertTrue(MovementMath.matches("Rune platebody", "rune"));
		assertTrue(MovementMath.matches("Rune platebody", "RUNE"));
		assertTrue(MovementMath.matches("Rune platebody", "plate"));
		assertTrue("the end of the name too", MovementMath.matches("Rune platebody", "body"));
		assertTrue("across a space", MovementMath.matches("Rune platebody", "e p"));
		assertTrue(MovementMath.matches("Runite ore", "run"));
		assertTrue(MovementMath.matches("Rune platebody", "run"));
		assertFalse("a plain substring: runite is not rune", MovementMath.matches("Runite ore", "rune"));
		assertFalse(MovementMath.matches("Dragon claws", "run"));
		assertFalse(MovementMath.matches("Rune platebody", "rune platebodyx"));
	}

	@Test
	public void matchesTrimsTheQueryAndReadsABlankOneAsEverything()
	{
		assertTrue(MovementMath.matches("Rune platebody", "  rune  "));
		assertTrue("a space inside is a space inside", MovementMath.matches("Rune platebody", " e p "));
		assertFalse(MovementMath.matches("Dragon claws", "  rune  "));
		assertTrue(MovementMath.matches("Dragon claws", ""));
		assertTrue(MovementMath.matches("Dragon claws", "   "));
		assertTrue(MovementMath.matches("Dragon claws", null));
		assertTrue("a blank query matches even a row with no name", MovementMath.matches(null, ""));
		assertFalse("a null name matches nothing", MovementMath.matches(null, "rune"));
		assertFalse(MovementMath.matches(null, "x"));
	}

	/** The case-fold is the root locale's: the Turkish dotted capital I does not break a search for "iron". */
	@Test
	public void matchesFoldsCaseWithTheRootLocale()
	{
		final Locale before = Locale.getDefault();
		try
		{
			Locale.setDefault(new Locale("tr", "TR"));
			assertTrue(MovementMath.matches("Iron platebody", "IRON"));
			assertTrue(MovementMath.matches("Iron platebody", "iron"));
			assertTrue(MovementMath.matches("IRON PLATEBODY", "iron"));
		}
		finally
		{
