		assertEquals("the same fixture the other way round under the stack column",
			Arrays.asList("Hat", "Whip"), names(MovementMath.apply(rows,
				new RowFilter(0L, 0L, SortMode.STACK_VALUE, true, MovementWindow.D1))));
