	/**
	 * Lays a row out for real, off-screen and top down. {@link Container#validate()} does nothing without a peer
	 * and there is no display here, so each container is handed its preferred size and told to lay itself out -
	 * the same {@code layoutContainer} calls {@code validate} would make, without the peer.
	 */
	private static void layOut(MovementRowPanel p)
	{
		p.setSize(p.getPreferredSize());
		layOut((Container) p);
	}

	private static void layOut(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				layOut((Container) child);
			}
		}
	}

	/** Where {@code c}'s left edge stands in the ROW's own coordinates, after {@link #layOut(MovementRowPanel)}. */
	private static int leftEdge(Component c, MovementRowPanel row)
	{
		return SwingUtilities.convertPoint(c, 0, 0, row).x;
	}

	/**
	 * What line 2's gp column prints for a move of {@code deltaGp}, read off a built row. The stack is ONE item,
	 * so the stack's move and the item's are the same figure and this is the compacting on its own.
	 */
	private static String faceGp(long deltaGp)
	{
		return new MovementRowPanel(stack("Coins", 1, 2_000_000_000L, deltaGp, 0.1), null, MovementWindow.D1,
			THEN_DAY).gpText();
	}

	private static JLabel label(Container c, String text)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof JLabel && text.equals(((JLabel) child).getText()))
			{
				return (JLabel) child;
			}
			if (child instanceof Container)
			{
				final JLabel found = label((Container) child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private static void collect(Container c, List<JComponent> into)
	{
		for (Component child : c.getComponents())
		{
			if (child instanceof JComponent)
			{
				into.add((JComponent) child);
			}
			if (child instanceof Container)
			{
				collect((Container) child, into);
			}
		}
	}

	private static void enter(Component target, MovementRowPanel row)
	{
		for (MouseListener l : target.getMouseListeners())
		{
			l.mouseEntered(new MouseEvent(target, MouseEvent.MOUSE_ENTERED, 0L, 0, 1, 1, 0, false));
		}
		assertTrue(row.hovered());
	}

	/**
	 * A left click on one of the row's own mouse targets, driven the way {@link #enter} drives a hover: the
	 * listeners the row installed on that component are handed a real {@link MouseEvent}. Synthesising the event
	 * rather than calling {@code toggleExpanded} directly is what keeps the WIRING under test - that the listener
	 * is on the component at all, and that both of the handler's guards (the left button, and never a popup
	 * trigger) are the ones deciding.
	 */
	private static void leftClick(Component target)
	{
		click(target, MouseEvent.BUTTON1, false);
	}

	/** {@link #leftClick} with the button and the popup-trigger flag spelled out, for the right-click rule. */
	private static void click(Component target, int button, boolean popupTrigger)
	{
		final MouseEvent e = new MouseEvent(target, MouseEvent.MOUSE_CLICKED, 0L, 0, 3, 3, 1, popupTrigger,
			button);
		for (MouseListener l : target.getMouseListeners())
		{
			l.mouseClicked(e);
		}
	}

	/**
	 * A {@link MovementRowPanel.Expansion} of the test's own, standing in for the one the panel holds: it
	 * records what a click wrote, and counts the writes so a test can prove that BUILDING a row only reads.
	 */
	private static final class RecordingExpansion implements MovementRowPanel.Expansion
	{
		private final Map<Integer, Boolean> state = new HashMap<>();
		private int writes;

		@Override
		public boolean isExpanded(int itemId)
		{
			return Boolean.TRUE.equals(state.get(itemId));
		}

		@Override
		public void setExpanded(int itemId, boolean expanded)
		{
			state.put(itemId, expanded);
			writes++;
		}
	}

	private static void exit(Component target, MovementRowPanel row)
	{
		for (MouseListener l : target.getMouseListeners())
		{
			l.mouseExited(new MouseEvent(target, MouseEvent.MOUSE_EXITED, 0L, 0, 1, 1, 0, false));
		}
		assertFalse(row.hovered());
	}

	/** Runs the body on the EDT (where the row lives) and re-throws whatever it failed with. */
	static void onEdt(Runnable body) throws Exception
	{
		final AtomicReference<Throwable> failure = new AtomicReference<>();
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				body.run();
			}
			catch (Throwable t)
			{
				failure.set(t);
			}
		});
		final Throwable t = failure.get();
		if (t instanceof Error)
		{
			throw (Error) t;
		}
		if (t instanceof Exception)
		{
			throw (Exception) t;
		}
		if (t != null)
		{
			throw new RuntimeException(t);
		}
	}

	/**
	 * The opened block's text starts {@link MovementRowPanel#DETAIL_LEFT} (2) px in from its label's left edge, so
	 * the first letter of "Worth now" and "Was" keeps its left stroke (the client cut it at the edge). Measured
	 * from the component and from ink: the border, then the painted pixels of the block.
	 */
	@Test
	public void anOpenedBlocksTextStartsTwoPxInAndItsFirstLetterKeepsItsStroke() throws Exception
	{
		onEdt(() ->
		{
			final MovementRowPanel p = new MovementRowPanel(whip(), null, MovementWindow.D1, THEN_DAY);
			leftClick(p);
			p.setSize(p.getPreferredSize());
			p.doLayout();
			final JLabel block = detail(p);
			assertEquals("the row's text column and the block share one left edge", face(p).getX(), block.getX());
			assertEquals("the block's text starts 2 px inside it", 2, block.getInsets().left);
			assertEquals("...and the top gap did not move", 4, block.getInsets().top);
			assertEquals("the block is as wide as the face's box", MovementRowPanel.INNER_WIDTH, block.getWidth());

			final int leftmost = firstInkColumn(block);
			// The reference: the same text with 8 px of air, where nothing can be cut. Its first ink shows how far the
			// glyph reaches left of its origin (the W's slanted stroke reaches one px), so the real block's ink must
			// sit exactly 6 px nearer the edge - all of the stroke drawn, none of it at a negative x.
			final JLabel reference = new JLabel(block.getText());
			reference.setFont(block.getFont());
			reference.setForeground(block.getForeground());
			reference.setVerticalAlignment(SwingConstants.TOP);
			reference.setBorder(new javax.swing.border.EmptyBorder(4, 8, 0, 0));
			reference.setSize(block.getWidth(), block.getHeight());
			assertEquals("the whole of the first letter is inside the label", firstInkColumn(reference) - 6, leftmost);
			assertTrue("and it does not touch the label's own edge at x = 0, first ink at " + leftmost, leftmost >= 1);
		});
	}

	private static int firstInkColumn(JLabel label)
	{
		final BufferedImage img = new BufferedImage(label.getWidth(), label.getHeight(), BufferedImage.TYPE_INT_RGB);
		final java.awt.Graphics2D g = img.createGraphics();
		g.setColor(Color.BLACK);
		g.fillRect(0, 0, img.getWidth(), img.getHeight());
		label.paint(g);
		g.dispose();
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				final int rgb = img.getRGB(x, y);
				if (((rgb >> 16) & 0xFF) + ((rgb >> 8) & 0xFF) + (rgb & 0xFF) > 60)
				{
					return x;
				}
			}
		}
		return -1;
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * {@link MovementRow}'s addendum-Q additions (Q5, Q6): the {@link MovementRow.PriceSource#ALCH} source an
 * untradeable stack is priced by, and {@link MovementRow#holdingDeltaGp()} - the change over the WHOLE stack,
 * which is what a row prints and what the gp orderings sort on while "Show stack value on rows" is on.
 *
 * <p>And the addendum-R seam beside them (R2, R4): {@link MovementRow.PriceSource#PARTS} and
 * {@link MovementRow#parts()}, the row the panel paints as a GUIDE row and tells the reader what it was valued
 * from.
 */
public class MovementRowTest
{
	private static MovementRow row(final int quantity, final Long deltaGp)
	{
		return new MovementRow(4151, "Abyssal whip", quantity, false, 1_500_000L,
			deltaGp == null ? null : 1_500_000L - deltaGp, deltaGp, deltaGp == null ? null : 1.0d,
			1_500_000L * quantity, MovementRow.PriceSource.GUIDE);
	}

	@Test
	public void theStacksChangeIsTheUnitChangeTimesTheQuantity()
	{
		assertEquals(30_000L, row(3, 10_000L).holdingDeltaGp());
		assertEquals("a fall stays a fall", -30_000L, row(3, -10_000L).holdingDeltaGp());
		assertEquals(10_000L, row(1, 10_000L).holdingDeltaGp());
		assertEquals(0L, row(7, 0L).holdingDeltaGp());
	}

	/**
	 * A row with no baseline has no change to multiply. It answers a plain 0 rather than a null so a caller can
	 * print and compare it without unboxing; {@link MovementRow#hasMovement()} is what tells "no move" from
	 * "unmoved", exactly as it does for the unit change.
	 */
	@Test
	public void aRowWithNoMoveHasNoStackChangeEither()
	{
		final MovementRow dash = row(500, null);

		assertFalse(dash.hasMovement());
		assertEquals(0L, dash.holdingDeltaGp());
	}

	@Test
	public void anEmptyStackIsWorthNoChange()
	{
		assertEquals(0L, row(0, 10_000L).holdingDeltaGp());
		assertEquals(0L, row(-3, 10_000L).holdingDeltaGp());
	}

	/**
	 * The clamp picks an END by the sign rather than always {@link Long#MAX_VALUE}: a collapse clamped upwards
	 * would sort to the top of "Biggest gp gain", which is the one place this figure decides anything.
	 */
	@Test
	public void anImpossibleStackClampsToTheRightEnd()
	{
		assertEquals(Long.MAX_VALUE, row(Integer.MAX_VALUE, Long.MAX_VALUE / 2L).holdingDeltaGp());
		assertEquals(Long.MIN_VALUE, row(Integer.MAX_VALUE, Long.MIN_VALUE / 2L).holdingDeltaGp());
	}

	/** Q5: an alch row is a real row with a price, and it says where that price came from. */
	@Test
	public void anAlchRowCarriesItsOwnSource()
	{
		final MovementRow alch = MovementMath.alchRow(new BankItem(772, 2, "Dramen staff", false, true, 1500));

		assertSame(MovementRow.PriceSource.ALCH, alch.source());
		assertEquals(Long.valueOf(1500L), alch.unitPrice());
		assertEquals(3000L, alch.holdingValue());
		assertFalse("an alch value is a constant of the item, not a series", alch.hasMovement());
		assertEquals(0L, alch.holdingDeltaGp());
		assertTrue("and it is not one of the guide-priced rows",
			alch.source() != MovementRow.PriceSource.GUIDE);
	}

	// ---------------------------------------------------------------- R2/R4: the parts row

	private static final int CRYSTAL_BODY = 23_975;
	private static final int ARMOUR_SEED = 23_956;
	private static final String SEED_NAME = "Crystal armour seed";

	private static List<BankItem.Part> seeds(final long quantity)
	{
		return Collections.singletonList(new BankItem.Part(ARMOUR_SEED, quantity, SEED_NAME));
	}

	private static MovementRow crystalBodyRow()
	{
		final BankItem item = new BankItem(CRYSTAL_BODY, 1, "Crystal body", false, true, 900_000, seeds(3L));
		// The service hands the two SUMS to MovementMath.row as an ordinary guide "now" and "then" (R2), then says
		// where the price came from: 3 x 5,564,922 against 3 x 5,500,000.
		return MovementMath.row(item, new PricePoint(16_694_766L, 16_694_766L),
			new PricePoint(16_500_000L, 16_500_000L), 0).asParts(item.parts);
	}

	/**
	 * R2/R4: a parts row is an ordinary movement row that says where its price came from - a real baseline, a real
	 * move, the same arithmetic as a GUIDE row - and carries the parts the tooltip's one extra line is built from.
	 */
	@Test
	public void aPartsRowKeepsTheGuideArithmeticAndNamesItsParts()
	{
		final MovementRow row = crystalBodyRow();

		assertSame(MovementRow.PriceSource.PARTS, row.source());
		assertEquals(Long.valueOf(16_694_766L), row.unitPrice());
		assertEquals(Long.valueOf(16_500_000L), row.thenPrice());
		assertEquals("the move a GUIDE row would have had", Long.valueOf(194_766L), row.deltaGp());
		assertTrue(row.hasMovement());
		assertEquals(seeds(3L), row.parts());
		assertTrue("never the alch tag", row.source() != MovementRow.PriceSource.ALCH);
	}

	/** Every other row says it has none, so a reader can tell a parts row by the list alone. */
	@Test
	public void everyOtherRowCarriesNoParts()
	{
		assertNull(row(3, 10_000L).parts());
		assertNull(MovementMath.alchRow(new BankItem(772, 2, "Dramen staff", false, true, 1500)).parts());
	}

	/**
	 * {@code asParts} is a re-sourcing, not a valuation: it must not be able to turn a row that names no price into
	 * one "valued as its parts", and it has nothing to say when there are no parts to name.
	 */
	@Test
	public void asPartsAnswersTheRowUnchangedWhenThereIsNothingToSay()
	{
		final MovementRow guide = row(3, 10_000L);
		assertSame(guide, guide.asParts(null));
		assertSame(guide, guide.asParts(Collections.emptyList()));

		final MovementRow unpriced = MovementMath.alchRow(new BankItem(1, 1, "Junk", false, true, 0));
		assertNull(unpriced.unitPrice());
		assertSame("no price is not a parts price", unpriced, unpriced.asParts(seeds(3L)));
	}

	/** The parts are part of a row's identity: the panel republishes on a changed row list, and this changes one. */
	@Test
	public void thePartsArePartOfTheRowsIdentity()
	{
		final MovementRow row = crystalBodyRow();

		assertEquals(row, crystalBodyRow());
		assertEquals(row.hashCode(), crystalBodyRow().hashCode());
		assertNotEquals("the same numbers, a different reason for them",
			row, new MovementRow(CRYSTAL_BODY, "Crystal body", 1, false, 16_694_766L, 16_500_000L, 194_766L,
				1.180400d, 16_694_766L, MovementRow.PriceSource.GUIDE));
	}

	/** The list is the row's own: a caller cannot reach in and change what a published row says it is worth. */
	@Test
	public void thePartsListIsACopyTheCallerCannotChange()
	{
		final List<BankItem.Part> mutable = new ArrayList<>(seeds(3L));
		final MovementRow row = crystalBodyRow().asParts(mutable);

		mutable.clear();

		assertEquals(1, row.parts().size());
		try
		{
			row.parts().add(new BankItem.Part(1, 1L, "x"));
			fail("a published row's parts must be unmodifiable");
		}
		catch (final UnsupportedOperationException expected)
		{
			// the point of the test
		}
	}

	// ---------------------------------------------------------------- T4/T6: the live seam (S1)

	private static MovementRow.LiveFacts liveFacts()
	{
		return new MovementRow.LiveFacts(63_600_000L, 63_300_000L, 517L, null);
	}

	private static Map<MovementWindow, MovementRow.PriceSource> mixedSources()
	{
		final Map<MovementWindow, MovementRow.PriceSource> sources = new EnumMap<>(MovementWindow.class);
		sources.put(MovementWindow.D1, MovementRow.PriceSource.LIVE);
		sources.put(MovementWindow.D7, MovementRow.PriceSource.GUIDE);
		return sources;
	}

	/** T4: a live row is an ordinary row that says which series priced it and carries the numbers behind that. */
	@Test
	public void aLiveRowCarriesTheSourceTheFactsAndItsWindowSources()
	{
		final MovementRow live = row(1, 10_000L).asLive(null, mixedSources(), liveFacts());

		assertSame(MovementRow.PriceSource.LIVE, live.source());
		assertTrue(live.isLive());
		assertEquals(Long.valueOf(63_600_000L), live.liveFacts().buy());
		assertEquals(Long.valueOf(63_300_000L), live.liveFacts().sell());
		assertEquals(517L, live.liveFacts().volumeYesterday());
		assertNull("a live row names no refusal", live.liveFacts().reason());
		assertSame(MovementRow.PriceSource.LIVE, live.windowSource(MovementWindow.D1));
		assertSame("the window that fell back says so", MovementRow.PriceSource.GUIDE,
			live.windowSource(MovementWindow.D7));
	}

	/**
	 * T4's awkward case: a live row whose CURRENT window fell back is built from the guide pair - so its gp and
	 * percent are the guide's move - and still prints the live traded price, with the holding following the price
	 * it prints. The move must not be recomputed from the new unit: that would be live-now against guide-then,
	 * which is precisely the comparison addendum T's study refuted.
	 */
	@Test
	public void aLivePriceCanBePrintedOverAGuideMove()
	{
		final MovementRow guide = new MovementRow(4151, "Abyssal whip", 3, false, 1_500_000L, 1_490_000L,
			10_000L, 0.671140d, 4_500_000L, MovementRow.PriceSource.GUIDE);

		final MovementRow live = guide.asLive(1_600_000L, mixedSources(), liveFacts());

		assertEquals("the price it prints is the live mid", Long.valueOf(1_600_000L), live.unitPrice());
		assertEquals("the holding follows the price it prints", 4_800_000L, live.holdingValue());
		assertEquals("the move is untouched - still the guide's", Long.valueOf(10_000L), live.deltaGp());
		assertEquals(Long.valueOf(1_490_000L), live.thenPrice());
		assertEquals("and the stack change with it", 30_000L, live.holdingDeltaGp());
	}

	/** A parts stack keeps the source that tells a reader what it was valued from, and is still live (T4/R4). */
	@Test
	public void aLivePartsRowKeepsThePartsSourceAndStillAnswersLive()
	{
		final MovementRow live = crystalBodyRow().asLive(null, mixedSources(), liveFacts());

		assertSame("\"valued as its parts\" is what a reader has to be told first", MovementRow.PriceSource.PARTS,
			live.source());
		assertTrue("and isLive() is the one test that covers both", live.isLive());
		assertEquals(seeds(3L), live.parts());
	}

	/** T6: a row that stayed on the guide keeps everything it had and gains the check that refused it. */
	@Test
	public void aRefusedRowKeepsItsGuideSourceAndNamesTheFirstFailingCheck()
	{
		final MovementRow.LiveFacts refused = new MovementRow.LiveFacts(1_000L, 900L, 12L, "12 traded yesterday");

		final MovementRow guide = row(1, 10_000L).withLiveRefusal(refused);

		assertSame(MovementRow.PriceSource.GUIDE, guide.source());
		assertFalse(guide.isLive());
		assertEquals("12 traded yesterday", guide.liveFacts().reason());
		assertEquals("the numbers the refusal was made on are still there", Long.valueOf(1_000L),
			guide.liveFacts().buy());
		assertSame("every window of a guide row is the guide's", MovementRow.PriceSource.GUIDE,
			guide.windowSource(MovementWindow.D30));
	}

	/**
	 * The two builders are re-sourcings, not valuations - the rule {@code asParts} already obeys. A row with no
	 * price cannot become "the live traded price", facts that name a refusal cannot make a row live, and facts
	 * that name none cannot be a refusal.
	 */
	@Test
	public void theLiveBuildersAnswerTheRowUnchangedWhenThereIsNothingToSay()
	{
		final MovementRow guide = row(3, 10_000L);

		assertSame(guide, guide.asLive(null, mixedSources(), null));
		assertSame(guide, guide.asLive(null, mixedSources(),
			new MovementRow.LiveFacts(1L, 1L, 1L, "no live data")));
		assertSame(guide, guide.withLiveRefusal(null));
		assertSame(guide, guide.withLiveRefusal(liveFacts()));

		final MovementRow unpriced = MovementMath.alchRow(new BankItem(1, 1, "Junk", false, true, 0));
		assertNull(unpriced.unitPrice());
		assertSame(unpriced, unpriced.asLive(1_000L, mixedSources(), liveFacts()));
	}

	/**
	 * The pre-T shape, exactly: a row built by any caller that knows nothing of live prices carries no window
	 * sources and no facts, and every window answers the row's own source. This is what "the switch off is
	 * byte-identical to today" rests on at the row level.
	 */
	@Test
	public void aRowBuiltWithTheSwitchOffCarriesNoLiveStateAtAll()
	{
		final MovementRow guide = row(3, 10_000L);

		assertNull(guide.liveFacts());
		assertFalse(guide.isLive());
		for (final MovementWindow window : MovementWindow.values())
		{
			assertSame(MovementRow.PriceSource.GUIDE, guide.windowSource(window));
		}
		assertSame("a null window is not a reason to guess", MovementRow.PriceSource.GUIDE, guide.windowSource(null));

		final MovementRow alch = MovementMath.alchRow(new BankItem(772, 2, "Dramen staff", false, true, 1500));
		assertSame("an alch row's windows are the alch rule", MovementRow.PriceSource.ALCH,
			alch.windowSource(MovementWindow.D1));
	}

	/** A LIVE row asked about a window nothing recorded must not claim a comparison that was never made. */
	@Test
	public void aLiveRowNeverClaimsLiveForAnUnrecordedWindow()
	{
		final Map<MovementWindow, MovementRow.PriceSource> only1d = new EnumMap<>(MovementWindow.class);
		only1d.put(MovementWindow.D1, MovementRow.PriceSource.LIVE);

		final MovementRow live = row(1, 10_000L).asLive(null, only1d, liveFacts());

		assertSame(MovementRow.PriceSource.LIVE, live.windowSource(MovementWindow.D1));
		assertSame(MovementRow.PriceSource.GUIDE, live.windowSource(MovementWindow.D180));
		assertSame(MovementRow.PriceSource.GUIDE, live.windowSource(null));
	}

	/** The live state is part of a row's identity: two rows with the same figures and different series differ. */
	@Test
	public void theLiveStateIsPartOfTheRowsIdentity()
	{
		final MovementRow guide = row(1, 10_000L);
		final MovementRow live = guide.asLive(null, mixedSources(), liveFacts());

		assertNotEquals(guide, live);
		assertEquals(live, guide.asLive(null, mixedSources(), liveFacts()));
		assertEquals(live.hashCode(), guide.asLive(null, mixedSources(), liveFacts()).hashCode());
		assertNotEquals("a different window split is a different row",
			live, guide.asLive(null, Collections.singletonMap(MovementWindow.D1, MovementRow.PriceSource.LIVE),
				liveFacts()));
	}

	/** An empty window map is stored as the pre-T null, so an empty map and no map are one row. */
	@Test
	public void anEmptyWindowMapIsTheSameAsNone()
	{
		final MovementRow a = row(1, 10_000L).asLive(null, Collections.emptyMap(), liveFacts());
		final MovementRow b = row(1, 10_000L).asLive(null, null, liveFacts());

		assertEquals(a, b);
		assertSame(MovementRow.PriceSource.GUIDE, a.windowSource(MovementWindow.D1));
	}

	/** A negative volume cannot become a negative count on a tooltip. */
	@Test
	public void liveFactsRefuseANegativeVolume()
	{
		assertEquals(0L, new MovementRow.LiveFacts(1L, 1L, -5L, null).volumeYesterday());
	}

	// ---------------------------------------------------------------- U3: the day each window used (seam S1)

	private static final LocalDate SEP_11 = LocalDate.of(2026, 9, 11);
	private static final LocalDate SEP_5 = LocalDate.of(2026, 9, 5);

	/** The days beside {@link #mixedSources()}: 1d off the traded bucket, 7d off the guide baseline it fell to. */
	private static Map<MovementWindow, LocalDate> mixedDays()
	{
		final Map<MovementWindow, LocalDate> days = new EnumMap<>(MovementWindow.class);
		days.put(MovementWindow.D1, SEP_11);
		days.put(MovementWindow.D7, SEP_5);
		return days;
	}

	/**
	 * U3: a live row carries the day each window really compared against - the traded bucket's own day where the
	 * window is live, the guide baseline's where it fell back - so a tooltip line's day and its figure always come
	 * from the same place.
	 */
	@Test
	public void aLiveRowCarriesTheDayEachWindowComparedAgainst()
	{
		final MovementRow live = row(1, 10_000L).asLive(null, mixedSources(), mixedDays(), liveFacts());

		assertEquals(SEP_11, live.windowDay(MovementWindow.D1));
		assertEquals("the window that fell back stamps the guide's day", SEP_5, live.windowDay(MovementWindow.D7));
		assertNull("a window nothing recorded stamps nothing", live.windowDay(MovementWindow.D180));
		assertNull(live.windowDay(null));
	}

	/** The day travels with the row through both re-sourcings, because the figures it belongs to do. */
	@Test
	public void theDaysSurviveAsPartsAndARefusal()
	{
		final MovementRow live = crystalBodyRow().asLive(null, mixedSources(), mixedDays(), liveFacts());

		assertEquals(SEP_11, live.asParts(seeds(3L)).windowDay(MovementWindow.D1));

		final MovementRow.LiveFacts refused = new MovementRow.LiveFacts(1_000L, 900L, 12L, "12 traded yesterday");
		assertEquals(SEP_11, live.withLiveRefusal(refused).windowDay(MovementWindow.D1));
	}

	/** A row built with the switch off records no day at all - the pre-addendum-U shape, byte for byte. */
	@Test
	public void aRowBuiltWithTheSwitchOffRecordsNoDay()
	{
		final MovementRow guide = row(3, 10_000L);

		for (final MovementWindow window : MovementWindow.values())
		{
			assertNull(guide.windowDay(window));
		}
		assertEquals("an empty map is stored as no map", guide.asLive(null, mixedSources(),
			Collections.<MovementWindow, LocalDate>emptyMap(), liveFacts()),
			guide.asLive(null, mixedSources(), liveFacts()));
	}

	/** Two rows that compared against different days are different rows, whatever their figures look like. */
	@Test
	public void theDaysArePartOfTheRowsIdentity()
	{
		final MovementRow guide = row(1, 10_000L);
		final MovementRow live = guide.asLive(null, mixedSources(), mixedDays(), liveFacts());

		assertEquals(live, guide.asLive(null, mixedSources(), mixedDays(), liveFacts()));
		assertEquals(live.hashCode(), guide.asLive(null, mixedSources(), mixedDays(), liveFacts()).hashCode());
		assertNotEquals("one day apart is one row apart", live, guide.asLive(null, mixedSources(),
			Collections.singletonMap(MovementWindow.D1, SEP_5), liveFacts()));
		assertNotEquals(live, guide.asLive(null, mixedSources(), liveFacts()));
	}

	// ---------------------------------------------------------------- addendum Y: where the quantity is

	/** Y3: the three figures say where the stack is, and they add up to the quantity the row prints. */
	@Test
	public void theSplitSaysWhereTheQuantityIs()
	{
		final MovementRow all = row(5, 10_000L).withSplit(3, 1, 1, 0);

		assertEquals(3, all.bankQuantity());
		assertEquals(1, all.inventoryQuantity());
		assertEquals(1, all.wornQuantity());
		assertEquals("they add up to what the row prints", all.quantity(),
			all.bankQuantity() + all.inventoryQuantity() + all.wornQuantity());
		assertTrue(all.split());
		assertFalse("something is carried, so the hover line is drawn", all.allInBank());
	}

	/** A stack the player only WEARS is a row with no bank quantity at all - "1 worn". */
	@Test
	public void aWornOnlyStackHasNoBankQuantity()
	{
		final MovementRow worn = row(1, 10_000L).withSplit(0, 0, 1, 0);

		assertEquals(0, worn.bankQuantity());
		assertEquals(0, worn.inventoryQuantity());
		assertEquals(1, worn.wornQuantity());
		assertTrue("it still knows where it is", worn.split());
		assertFalse(worn.allInBank());
	}

	/** A stack held only in the bank knows it, and says so - which is what keeps the hover line off it. */
	@Test
	public void aBankOnlyStackIsAllInBank()
	{
		final MovementRow banked = row(3, 10_000L).withSplit(3, 0, 0, 0);

		assertEquals(3, banked.bankQuantity());
		assertTrue(banked.split());
		assertTrue(banked.allInBank());
	}

	/** Y3: with the switch off a row carries three zeros - no split, and no hover line about one. */
	@Test
	public void aRowBuiltWithTheSwitchOffCarriesNoSplit()
	{
		final MovementRow guide = row(3, 10_000L);

		assertEquals(0, guide.bankQuantity());
		assertEquals(0, guide.inventoryQuantity());
		assertEquals(0, guide.wornQuantity());
		assertFalse(guide.split());
		assertTrue(guide.allInBank());
		assertSame("three zeros answer the row itself", guide, guide.withSplit(0, 0, 0, 0));
		assertEquals("and a negative is no split either", guide, guide.withSplit(-2, 0, 0, 0));
	}

	/** The split says where the stack lives, never what it is worth: every figure is untouched. */
	@Test
	public void theSplitChangesNoFigure()
	{
		final MovementRow guide = row(5, 10_000L);
		final MovementRow split = guide.withSplit(3, 1, 1, 0);

		assertEquals(guide.unitPrice(), split.unitPrice());
		assertEquals(guide.thenPrice(), split.thenPrice());
		assertEquals(guide.deltaGp(), split.deltaGp());
		assertEquals(guide.deltaPct(), split.deltaPct());
		assertEquals(guide.holdingValue(), split.holdingValue());
		assertEquals(guide.holdingDeltaGp(), split.holdingDeltaGp());
		assertEquals(guide.source(), split.source());
	}

	/** The split travels with the row through every re-sourcing, exactly as the parts and the days do. */
	@Test
	public void theSplitSurvivesAsPartsAsLiveAndARefusal()
	{
		final MovementRow body = crystalBodyRow().withSplit(2, 0, 1, 0);

		assertEquals(2, body.asParts(seeds(3L)).bankQuantity());
		assertEquals(1, body.asParts(seeds(3L)).wornQuantity());

		final MovementRow live = body.asLive(2_000_000L, mixedSources(), mixedDays(), liveFacts());
		assertEquals(2, live.bankQuantity());
		assertEquals(1, live.wornQuantity());

		final MovementRow.LiveFacts refused = new MovementRow.LiveFacts(1_000L, 900L, 12L, "12 traded yesterday");
		assertEquals(2, body.withLiveRefusal(refused).bankQuantity());
	}

	/** Two rows of the same five that live in different places are two different rows. */
	@Test
	public void theSplitIsPartOfTheRowsIdentity()
	{
		final MovementRow banked = row(5, 10_000L).withSplit(5, 0, 0, 0);

		assertEquals(banked, row(5, 10_000L).withSplit(5, 0, 0, 0));
		assertEquals(banked.hashCode(), row(5, 10_000L).withSplit(5, 0, 0, 0).hashCode());
		assertNotEquals("four banked and one worn is not five banked", banked, row(5, 10_000L).withSplit(4, 0, 1, 0));
		assertNotEquals("and neither is a row that does not know", banked, row(5, 10_000L));
	}

	/** A row with no split prints exactly what it printed before addendum Y. */
	@Test
	public void toStringNamesTheSplitOnlyWhenThereIsOne()
	{
		assertFalse(row(5, 10_000L).toString().contains("bank="));
		assertTrue(row(5, 10_000L).withSplit(3, 1, 1, 0).toString()
			.contains(", bank=3, inventory=1, worn=1"));
		assertFalse("the exchange part is printed only when there is one",
			row(5, 10_000L).withSplit(3, 1, 1, 0).toString().contains("exchange="));
		assertTrue(row(7, 10_000L).withSplit(3, 1, 1, 2).toString()
			.contains(", bank=3, inventory=1, worn=1, exchange=2"));
	}

	// ---------------------------------------------------------------- 1.0.9 part 3: the Grand Exchange offers

	/** The fourth figure says how many are in the player's offers, and the four add up to the quantity. */
	@Test
	public void theSplitSaysHowManyAreInTheOffersToo()
	{
		final MovementRow all = row(7, 10_000L).withSplit(3, 1, 1, 2);

		assertEquals(3, all.bankQuantity());
		assertEquals(1, all.inventoryQuantity());
		assertEquals(1, all.wornQuantity());
		assertEquals(2, all.exchangeQuantity());
		assertEquals("the four add up to what the row prints", all.quantity(),
			all.bankQuantity() + all.inventoryQuantity() + all.wornQuantity() + all.exchangeQuantity());
		assertTrue(all.split());
		assertFalse("something is in an offer, so the hover line is drawn", all.allInBank());
	}

	/** A stack only in an offer is a row with no bank quantity at all - "2 in the Grand Exchange". */
	@Test
	public void anOfferOnlyStackHasNoBankQuantityAndStillKnowsWhereItIs()
	{
		final MovementRow offer = row(2, 10_000L).withSplit(0, 0, 0, 2);

		assertEquals(0, offer.bankQuantity());
		assertEquals(2, offer.exchangeQuantity());
		assertTrue("a split of nothing but offers is still a split", offer.split());
		assertFalse(offer.allInBank());
		assertNotEquals("and it is not the row that knows nothing of the split", offer, row(2, 10_000L));
	}

	/** The row built with the three-int split and the one built with no split carry no offers. */
	@Test
	public void aRowWithoutOffersCarriesZeroThere()
	{
		assertEquals(0, row(5, 10_000L).exchangeQuantity());
		assertEquals(0, row(5, 10_000L).withSplit(3, 1, 1, 0).exchangeQuantity());
		assertTrue("a bank-only split with no offers is all in the bank", row(3, 10_000L).withSplit(3, 0, 0, 0)
			.allInBank());
		final MovementRow guide = row(3, 10_000L);
		assertSame(guide, guide.withSplit(0, 0, 0, 0));
		assertEquals("a negative offer figure is no offer", guide, guide.withSplit(0, 0, 0, -3));
	}

	/** The offers' figure travels with the row through every re-sourcing and is part of its identity. */
	@Test
	public void theOffersFigureSurvivesAsPartsAsLiveAndARefusalAndIsPartOfTheIdentity()
	{
		final MovementRow body = crystalBodyRow().withSplit(1, 0, 0, 2);

		assertEquals(2, body.asParts(seeds(3L)).exchangeQuantity());
		assertEquals(2, body.asLive(2_000_000L, mixedSources(), mixedDays(), liveFacts()).exchangeQuantity());
		final MovementRow.LiveFacts refused = new MovementRow.LiveFacts(1_000L, 900L, 12L, "12 traded yesterday");
		assertEquals(2, body.withLiveRefusal(refused).exchangeQuantity());

		final MovementRow banked = row(5, 10_000L).withSplit(3, 0, 0, 2);
		assertEquals(banked, row(5, 10_000L).withSplit(3, 0, 0, 2));
		assertEquals(banked.hashCode(), row(5, 10_000L).withSplit(3, 0, 0, 2).hashCode());
		assertNotEquals("three banked and two in offers is not three banked and two worn", banked,
			row(5, 10_000L).withSplit(3, 0, 2, 0));
		assertNotEquals(banked, row(5, 10_000L).withSplit(5, 0, 0, 0));
		final MovementRow viaConstructor = new MovementRow(4151, "Abyssal whip", 5, false, 1_500_000L, null, null, null,
			7_500_000L, MovementRow.PriceSource.GUIDE, null, null, null, null, 3, 0, 0, 2);
		assertEquals(2, viaConstructor.exchangeQuantity());
		assertEquals(0, new MovementRow(4151, "Abyssal whip", 5, false, 1_500_000L, null, null, null, 7_500_000L,
			MovementRow.PriceSource.GUIDE, null, null, null, null, 3, 0, 0).exchangeQuantity());
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

/**
 * {@link MovementWindow} after contract 1.1.2 (T1): the five Grand Exchange windows, the TIME arithmetic that names
 * the latest moment a baseline table may carry, and the legacy spellings a first-build profile still holds.
 *
 * <p><b>Why seconds again.</b> Addendum L (L9) made a window a count of calendar DAYS off an anchor date, because the
 * wiki's price bot saved one table a day at a random hour (L-C). Since 30 Sep 2026 it saves about eight a day, and
 * "the table of the day before the anchor" became a table a couple of hours old. The "now" end is now the TIME of the
 * table RuneLite's prices match (or the clock while RuneLite is ahead of the index), and the "then" end the newest
 * table at least {@code days() x 24 h} older - {@code PriceService} picks it, this class only does the subtraction.
 *
 * <p>The legacy parse tests are the other load-bearing ones. A user who ran the first build has
 * {@code window=H24} written into their RuneLite config; {@code ConfigManager} reads an enum back with
 * {@code Enum.valueOf}, and an unknown constant there is how this workspace has already NPE'd a config panel
 * once (CLAUDE.md, "Config interfaces must be FLAT"). Every one of the four old spellings has to land on a
 * window that exists.
 */
public class MovementWindowTest
{
	@Test
	public void theFiveWindowsCarryTheirLabelAndSpan()
	{
		assertEquals("1d", MovementWindow.D1.label());
		assertEquals("7d", MovementWindow.D7.label());
		assertEquals("30d", MovementWindow.D30.label());
		assertEquals("90d", MovementWindow.D90.label());
		assertEquals("180d", MovementWindow.D180.label());

		assertEquals(1, MovementWindow.D1.days());
		assertEquals(7, MovementWindow.D7.days());
		assertEquals(30, MovementWindow.D30.days());
		assertEquals(90, MovementWindow.D90.days());
		assertEquals(180, MovementWindow.D180.days());

		assertEquals("the GE site's own spans: today, a week, 1 month, 3 months, 6 months",
			5, MovementWindow.values().length);
	}

	/**
	 * The label a chip draws and the number the arithmetic uses have to agree: "30d" that looked back 90 days
	 * would be a silently wrong figure on every row, not a failure anybody would see.
	 */
	@Test
	public void everyLabelIsItsOwnDayCountAndTheyIncrease()
	{
		int previous = 0;
		for (final MovementWindow window : MovementWindow.values())
		{
			assertEquals(window + " must look back exactly as far as its label says",
				window.label(), window.days() + "d");
			assertTrue(window + " must be longer than the window before it", window.days() > previous);
			previous = window.days();
		}
	}

	/**
	 * The hourly windows are gone with the trade API: the guide table is a step function stamped once a DAY, so
	 * an hour-wide window would put both ends on the same step and read 0.0 % for every item in the bank.
	 */
	@Test
	public void noWindowIsShorterThanADay()
	{
		for (final MovementWindow window : MovementWindow.values())
		{
			assertTrue(window + " is shorter than one guide-price step", window.days() >= 1);
		}
	}

	/**
	 * The config combo box and the sidebar chip both read {@code toString()}; the STORED value is the constant
	 * name, which {@code ConfigManager.java:1279-1281} writes and {@code :1205-1207} reads.
	 */
	@Test
	public void toStringIsTheLabelWhileTheNameIsUnchanged()
	{
		assertEquals("1d", MovementWindow.D1.toString());
		assertEquals("D1", MovementWindow.D1.name());
		assertSame(MovementWindow.D1, MovementWindow.valueOf("D1"));
		assertEquals("180d", MovementWindow.D180.toString());
		assertEquals("D180", MovementWindow.D180.name());
	}

	@Test
	public void theDefaultIsTheGeSitesTodayFigure()
	{
		assertSame(MovementWindow.D1, MovementWindow.DEFAULT);
	}

	// ---- targetSeconds (contract 1.1.2, T1)

	/** The now time of the 1.1.2 finding: 2026-10-07T16:25:00Z, the table RuneLite's prices matched. */
	private static final long NOW = 1_791_390_300L;
	private static final long DAY = 86_400L;

	@Test
	public void theTargetIsThatManyTimesTwentyFourHoursBeforeTheNowTime()
	{
		assertEquals("06 Oct 16:25", NOW - DAY, MovementWindow.D1.targetSeconds(NOW));
		assertEquals(NOW - 7 * DAY, MovementWindow.D7.targetSeconds(NOW));
		assertEquals(NOW - 30 * DAY, MovementWindow.D30.targetSeconds(NOW));
		assertEquals(NOW - 90 * DAY, MovementWindow.D90.targetSeconds(NOW));
		assertEquals(NOW - 180 * DAY, MovementWindow.D180.targetSeconds(NOW));
		assertEquals("the same hour of the day, a day back: the table in force then, not the last of its date",
			RevisionRef.dayOf(NOW).minusDays(1), RevisionRef.dayOf(MovementWindow.D1.targetSeconds(NOW)));
	}

	@Test
	public void everyWindowLooksBackwardsAndTheLongerOneLooksFurther()
	{
		long previous = NOW;
		for (final MovementWindow window : MovementWindow.values())
		{
			final long target = window.targetSeconds(NOW);
			assertTrue(window + " must look BACKWARDS", target < NOW);
			assertTrue(window + " must look further back than the window before it", target < previous);
			assertEquals(window + " looks back exactly its span", window.days() * DAY, NOW - target);
			previous = target;
		}
	}

	/**
	 * No now time yet means no target, which means no baseline and a "-" in the change column. Guessing one from the
	 * wall clock here is exactly what the service decides against unless RuneLite is ahead of the index (T1).
	 */
	@Test
	public void noNowTimeMeansNoTarget()
	{
		for (final MovementWindow window : MovementWindow.values())
		{
			assertEquals(window + " must not invent a now", 0L, window.targetSeconds(0L));
			assertEquals(0L, window.targetSeconds(-5L));
		}
	}

	// ---- parse (K4)

	@Test
	public void parseTakesLabelsNamesAndCasing()
	{
		assertSame(MovementWindow.D1, MovementWindow.parse("1d"));
		assertSame(MovementWindow.D7, MovementWindow.parse("7d"));
		assertSame(MovementWindow.D30, MovementWindow.parse("30d"));
		assertSame(MovementWindow.D90, MovementWindow.parse("90d"));
		assertSame(MovementWindow.D180, MovementWindow.parse("180d"));

		assertSame(MovementWindow.D1, MovementWindow.parse("D1"));
		assertSame(MovementWindow.D30, MovementWindow.parse("d30"));
		assertSame(MovementWindow.D180, MovementWindow.parse("  D180  "));
	}

	/**
	 * The reason this method exists at all: {@code window=H24} is sitting in the user's RuneLite profile from
	 * the first build, and H1 / H24 name nothing now. All four spellings collapse onto 1d - an hour is below the
	 * resolution of the guide series, and 24 h IS the new 1d.
	 */
	@Test
	public void theFourPreAddendumKSpellingsAllLandOnOneDay()
	{
		assertSame("the stored config value from the first build", MovementWindow.D1, MovementWindow.parse("H24"));
		assertSame(MovementWindow.D1, MovementWindow.parse("h24"));
		assertSame("the old chip text", MovementWindow.D1, MovementWindow.parse("24h"));
		assertSame(MovementWindow.D1, MovementWindow.parse("H1"));
		assertSame(MovementWindow.D1, MovementWindow.parse("h1"));
		assertSame(MovementWindow.D1, MovementWindow.parse("1h"));
		assertSame(MovementWindow.D1, MovementWindow.parse("  24H  "));
	}

	/** "7d" and "D7" meant the same window before addendum K and still do - the one value that carries over. */
	@Test
	public void theOldSevenDayWindowSurvivesUnchanged()
	{
		assertSame(MovementWindow.D7, MovementWindow.parse("7d"));
		assertSame(MovementWindow.D7, MovementWindow.parse("D7"));
		assertEquals(7, MovementWindow.D7.days());
	}

	@Test
	public void parseAnswersNullRatherThanGuessing()
	{
		assertNull(MovementWindow.parse(null));
		assertNull(MovementWindow.parse(""));
		assertNull(MovementWindow.parse("   "));
		assertNull(MovementWindow.parse("1"));
		assertNull(MovementWindow.parse("d"));
		assertNull(MovementWindow.parse("12h"));
		assertNull(MovementWindow.parse("2d"));
		assertNull(MovementWindow.parse("365d"));
		assertNull(MovementWindow.parse("week"));
	}

	@Test
	public void parseRoundTripsEveryLabelAndName()
	{
		for (final MovementWindow window : MovementWindow.values())
		{
			assertSame(window, MovementWindow.parse(window.label()));
			assertSame(window, MovementWindow.parse(window.name()));
			assertSame(window, MovementWindow.parse(window.toString()));
		}
	}

	/** Two windows sharing a label or a name would make the chips and the stored value ambiguous. */
	@Test
	public void everyLabelAndNameIsUnique()
	{
		final Set<String> seen = new HashSet<>();
		for (final MovementWindow window : MovementWindow.values())
		{
			assertTrue("duplicate label " + window.label(), seen.add(window.label()));
			assertTrue("duplicate name " + window.name(), seen.add(window.name()));
		}
	}
}

package com.bankpricemovement;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

/**
 * {@link NavIcon} (contract C34): the sidebar button's icon - the ONLY way a user reaches this plugin.
 *
 * <p><b>Why this file exists.</b> Its whole coverage was one {@code assertNotNull} on
 * {@code NavigationButton.getIcon()} in the wiring test, which a fully transparent 16 x 16 image satisfies. A
 * {@code setColor} moved after the fills, an alpha-0 colour or coordinates pushed off the raster while redrawing
 * the coin would leave the user relaunching to a blank square in the sidebar with nothing to tell it from a
 * broken plugin, and every test would pass. So the ink is counted, and counted WHERE the four bars and the coin
 * are drawn - a global count alone would survive one bar going missing.
 *
 * <p>No golden bitmap: the coin is filled with antialiasing, whose exact edge pixels drift between JDK builds.
 * The bars and the letters are not antialiased, so their pixels are pinned exactly; the coin is pinned by its
 * colours and by where it lives. This is the same idiom {@code WidgetsTest} uses for the panel's drawn glyphs,
 * and like that one it proves the drawing needs no display.
 */
public class NavIconTest
{
	/** The coin's face gold and the ink of its "2h", the colours Why Lag's icon carries too. */
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color LETTER_INK = new Color(52, 36, 8);

	@Test
	public void theIconIsSixteenSquareArgbWithTheCoinAndFourOrangeBars()
	{
		final BufferedImage img = NavIcon.create();
		assertEquals(NavIcon.SIZE, img.getWidth());
		assertEquals(NavIcon.SIZE, img.getHeight());
		assertEquals("16 x 16 ARGB, what NavigationButton.builder().icon(...) takes",
			BufferedImage.TYPE_INT_ARGB, img.getType());

		// The four fillRects alone are 3x2 + 3x4 + 3x6 + 3x9 = 63 opaque pixels, and fillRect is not antialiased, so
		// 63 is a hard floor before the coin adds anything: 60 leaves real slack and still catches a blank icon.
		assertTrue("the icon put " + ink(img) + " px of ink down", ink(img) > 60);

		// One bar at a time: the four columns the bars stand in, on the bottom row they all reach.
		assertTrue("the first bar is missing", opaque(img, 1, 4, 15, 16));
		assertTrue("the second bar is missing", opaque(img, 5, 8, 15, 16));
		assertTrue("the third bar is missing", opaque(img, 9, 12, 15, 16));
		assertTrue("the fourth bar is missing", opaque(img, 13, 16, 15, 16));

		// ...and their heights, 2, 4, 6 and 9: the top pixel of each is ink and the one above it is ground, so a
		// bar drawn too short or too tall fails.
		assertTrue("the first bar is too short", opaque(img, 2, 3, 14, 15));
		assertFalse("the first bar is too tall", opaque(img, 2, 3, 13, 14));
		assertTrue("the second bar is too short", opaque(img, 6, 7, 12, 13));
		assertFalse("the second bar is too tall", opaque(img, 6, 7, 11, 12));
		assertTrue("the third bar is too short", opaque(img, 10, 11, 10, 11));
		assertFalse("the third bar is too tall", opaque(img, 10, 11, 9, 10));
		assertTrue("the fourth bar is too short", opaque(img, 14, 15, 7, 8));
		assertFalse("the fourth bar is too tall", opaque(img, 14, 15, 6, 7));

		// The coin: its face gold and the dark brown of its letters are both there, and it lives in the top-left.
		assertTrue("the coin's face is missing", hasColour(img, FACE));
		assertTrue("the coin's letters are missing", hasColour(img, LETTER_INK));
		assertTrue("the coin is not in the top-left corner", opaque(img, 2, 7, 2, 7));

		// The arrow this icon used to carry is gone: three pixels that were its head are ground now.
		assertEquals("the arrow head is still drawn at (12, 2)", 0, img.getRGB(12, 2) >>> 24);
		assertEquals("the arrow head is still drawn at (13, 2)", 0, img.getRGB(13, 2) >>> 24);
		assertEquals("the arrow head is still drawn at (9, 1)", 0, img.getRGB(9, 1) >>> 24);

		assertTrue("nothing is drawn in the brand colour", hasColour(img, ColorScheme.BRAND_ORANGE));
		// (15, 0), not (0, 0): the coin covers the top-left corner now, and the top-right is the clear ground.
		assertEquals("the ground stays transparent", 0, img.getRGB(15, 0) >>> 24);
	}

	/**
	 * The javadoc's promise: a fresh image per call, so a plugin restart never shares a bitmap with a button
	 * already removed. Proved by writing into one and reading the other, not by {@code !=} - which any
	 * {@code new BufferedImage} satisfies and which therefore pins nothing.
	 */
	@Test
	public void everyCallDrawsItsOwnImage()
	{
		final BufferedImage first = NavIcon.create();
		final BufferedImage second = NavIcon.create();
		assertNotSame(first, second);
		// (15, 0), a pixel the coin does not cover: the read-back is of ground, not of the coin's rim.
		final int was = second.getRGB(15, 0);
		first.setRGB(15, 0, Color.WHITE.getRGB());
		assertEquals("the two share no raster", was, second.getRGB(15, 0));
	}

	/**
	 * The whole 16 x 16, pinned as one number: {@link Arrays#hashCode(int[])} over the ARGB of every pixel, row by row.
	 * Computed on the code as it stood before the coin moved out into {@code CoinGlyph}, so the extraction is proved
	 * to have changed not one pixel - the antialiased rim included, which the per-pixel checks above leave free. A
	 * deliberate redraw of the icon updates this constant in the same commit; nothing else should.
	 */
	private static final int ICON_CHECKSUM = 966175792;

	@Test
	public void theWholeIconIsThePixelsItWasBeforeTheCoinMovedOut()
	{
		final BufferedImage img = NavIcon.create();
		final int[] pixels = img.getRGB(0, 0, NavIcon.SIZE, NavIcon.SIZE, null, 0, NavIcon.SIZE);
		assertEquals("the 16 x 16 ARGB checksum", ICON_CHECKSUM, Arrays.hashCode(pixels));
	}

	/** How many pixels are not fully transparent. */
	private static int ink(BufferedImage img)
	{
		int n = 0;
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					n++;
				}
			}
		}
		return n;
	}

	/** Whether any pixel in [x0, x1) x [y0, y1) has ink in it. */
	private static boolean opaque(BufferedImage img, int x0, int x1, int y0, int y1)
	{
		for (int x = x0; x < x1; x++)
		{
			for (int y = y0; y < y1; y++)
			{
				if ((img.getRGB(x, y) >>> 24) != 0)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static boolean hasColour(BufferedImage img, Color colour)
	{
		for (int x = 0; x < img.getWidth(); x++)
		{
			for (int y = 0; y < img.getHeight(); y++)
			{
				final int argb = img.getRGB(x, y);
				if (((argb >>> 24) & 0xff) == 0xff && (argb & 0xffffff) == (colour.getRGB() & 0xffffff))
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.bankpricemovement;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Test helper: an {@link OkHttpClient} whose every call is answered with HTTP 200 and an empty body, inline on the
 * calling thread, so a test that wants the network to be fine does not have to set the harness of the client tests up.
 */
final class OkHttpFakes
{
	private OkHttpFakes()
	{
	}

	/** A client whose every {@code enqueue} ends in {@code onResponse} with a 200 and a {@code Date} header. */
	static OkHttpClient answeringEverything()
	{
		final OkHttpClient http = mock(OkHttpClient.class);
		when(http.newCall(any(Request.class))).thenAnswer(invocation ->
		{
			final Request request = invocation.getArgument(0);
			final Call call = mock(Call.class);
			doAnswer(enqueued ->
			{
				final Callback callback = enqueued.getArgument(0);
				callback.onResponse(call, new Response.Builder().request(request).protocol(Protocol.HTTP_1_1).code(200)
					.message("OK").header("Date", "Wed, 30 Sep 2026 14:05:04 GMT")
					.body(ResponseBody.create(MediaType.parse("application/json"), "")).build());
				return null;
			}).when(call).enqueue(any(Callback.class));
			return call;
		});
		return http;
	}
}

