	// ---------------------------------------------------------------- R3: untradeable stacks valued at their parts

	/** The addendum's own example: a Crystal body, worth three Crystal armour seeds (16,694,766 gp) and not 900k. */
	private static final int CRYSTAL_BODY = 23_975;
	private static final int ARMOUR_SEED = 23_956;
	private static final long BODY_NOW = 16_694_766L;
	private static final long BODY_THEN = 16_500_000L;

	private static BankItem crystalBody(final int quantity)
	{
		return new BankItem(CRYSTAL_BODY, quantity, "Crystal body", false, true, 900_000,
			Collections.singletonList(new BankItem.Part(ARMOUR_SEED, 3L, "Crystal armour seed")));
	}

	/**
	 * The caller has already summed the parts and answers that sum under the STACK's id, on both sides (R2) - which
	 * is what these resolvers do. PortfolioMath's own rule is only "a stack with parts is asked, and counts".
	 */
	private static PortfolioSummary withCrystalBody(final int quantity, @Nullable final Long now,
		@Nullable final Long then)
	{
		final List<BankItem> items = new ArrayList<>(bank());
		items.add(crystalBody(quantity));
		final Map<Integer, Long> nowById = new HashMap<>(now());
		if (now != null)
		{
			nowById.put(CRYSTAL_BODY, now);
		}
		final Map<Integer, Long> thenById = new HashMap<>(oneDayAgo());
		if (then != null)
		{
			thenById.put(CRYSTAL_BODY, then);
		}
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D1, thenById::get);
		thens.put(MovementWindow.D7, sevenDaysAgo()::get);
		return PortfolioMath.summariseResolved(items, nowById::get, thens, days(), 0L);
	}

	/**
	 * R3, in one test: a stack valued at its tradeable parts counts in the total, in {@code itemsTotal} AND in
	 * {@code itemsPriced} - every gp of that sum is a guide price - and it is in the window's covered set on both
	 * sides, so the crystal set moves the bank value with the seed price.
	 */
	@Test
	public void aStackValuedAtItsPartsIsCountedAndCoveredLikeAnyGuideRow()
	{
		final PortfolioSummary s = withCrystalBody(2, BODY_NOW, BODY_THEN);

		assertEquals("2,030,000 of stacks + 2 x 16,694,766, never 2 x 900,000",
			2_030_000L + 2L * BODY_NOW, s.valueNow());
		assertEquals("its price is a market price", 4, s.itemsPriced());
		assertEquals(4, s.itemsTotal());

		final WindowMove d1 = s.move(MovementWindow.D1);
		assertEquals("the whip, the sharks and the crystal body", 3, d1.itemsCovered());
		assertEquals(2_007_600L + 2L * BODY_THEN, d1.valueThen());
		assertEquals(2_020_000L + 2L * BODY_NOW, d1.valueNowCovered());
		assertEquals(12_400L + 2L * (BODY_NOW - BODY_THEN), d1.deltaGp());
	}

	/**
	 * The other half of R2's fallback, seen from here: when the caller could not price every part it answers null
	 * for the stack, and null IS the alch rule - the stack drops back to its High Alchemy value, out of
	 * {@code itemsPriced} and out of every window, exactly as a stack with no mapping does.
	 */
	@Test
	public void aStackWhosePartsCouldNotBePricedFallsBackToItsAlchValue()
	{
		final PortfolioSummary s = withCrystalBody(2, null, null);

		assertEquals("2,030,000 + 2 x 900,000", 2_030_000L + 1_800_000L, s.valueNow());
		assertEquals("an alch value is not a market price", 3, s.itemsPriced());
		assertEquals(4, s.itemsTotal());
		assertEquals("and it is in no window", 2, s.move(MovementWindow.D1).itemsCovered());
	}

	/** Covered means priced on BOTH days here too: a parts stack with no baseline counts in the total alone. */
	@Test
	public void aStackValuedAtItsPartsWithNoBaselineIsInTheTotalButInNoWindow()
	{
		final PortfolioSummary s = withCrystalBody(1, BODY_NOW, null);

		assertEquals(2_030_000L + BODY_NOW, s.valueNow());
		assertEquals(4, s.itemsPriced());
		assertEquals("the whip and the sharks, as without it", 2, s.move(MovementWindow.D1).itemsCovered());
		assertEquals(12_400L, s.move(MovementWindow.D1).deltaGp());
	}

	/**
	 * The pre-R pin, kept by construction: a stack with NO parts is never asked for a price, so a name collision in
	 * some table can still never quietly price an item the exchange does not list (the Q5 rule above), and a bank
	 * of pre-R stacks answers exactly what it answered before.
	 */
	@Test
	public void aStackWithoutPartsIsNeverAskedForAPrice()
	{
		final List<Integer> asked = new ArrayList<>();
		final List<BankItem> items = new ArrayList<>(bank());
		items.add(new BankItem(DRAMEN, 2, "Dramen staff", false, true, 1_500));
		final Function<Integer, Long> recording = id ->
		{
			asked.add(id);
			return now().get(id);
		};

		final PortfolioSummary s = PortfolioMath.summariseResolved(items, recording, thens(), days(), 0L);

		assertFalse("nothing can answer for a stack with no parts", asked.contains(DRAMEN));
		assertEquals(2_030_000L + 3_000L, s.valueNow());
		assertEquals(3, s.itemsPriced());
	}

	/** Alch values clamp with everything else: a bank cannot be worth a negative fortune. */
	@Test
	public void anAbsurdAlchHoldingClampsRatherThanWrapping()
	{
		final List<BankItem> items = Arrays.asList(
			new BankItem(DRAMEN, Integer.MAX_VALUE, "Dramen staff", false, true, Integer.MAX_VALUE),
			new BankItem(GRACEFUL, Integer.MAX_VALUE, "Graceful cape", false, true, Integer.MAX_VALUE),
			new BankItem(GRACEFUL + 2, Integer.MAX_VALUE, "Graceful top", false, true, Integer.MAX_VALUE));

		final PortfolioSummary s = PortfolioMath.summariseResolved(items, now()::get, thens(), days(), 0L);

		assertEquals("three stacks of 4.6 x 10^18 each: clamped, never a negative fortune", Long.MAX_VALUE, s.valueNow());
		assertTrue(s.valueStacks() > 0L);
	}

	// ---------------------------------------------------------------- T5: a "now" per window, and the live count

	/** The per-window "now" of a live whip: the guide price for the window whose traded bucket was too thin. */
	private static Map<MovementWindow, Function<Integer, Long>> guideNowFor1d()
	{
		final Map<MovementWindow, Function<Integer, Long>> m = new EnumMap<>(MovementWindow.class);
		m.put(MovementWindow.D1, Collections.singletonMap(WHIP, 1_500_000L)::get);
		return m;
	}

	/**
	 * T5: the headline counts each stack at the price its own row prints, while a window whose traded bucket was
	 * missing or thin compares the GUIDE's two ends - "never live-now against guide-then". So the whip can be worth
	 * 1,520,000 in the total and be compared at 1,500,000 over 1d, and the two are not a contradiction.
	 */
	@Test
	public void aWindowCanCompareADifferentNowFromTheOneTheTotalCounts()
	{
		final PortfolioSummary s = PortfolioMath.summariseResolved(bank(), now()::get, thens(), guideNowFor1d(),
			days(), 0L, 1);

		assertEquals("the total is unchanged: it counts what the rows print", 2_030_000L, s.valueNow());
		final WindowMove d1 = s.move(MovementWindow.D1);
		assertEquals("the whip enters 1d at its GUIDE price", 1_500_000L + 500_000L, d1.valueNowCovered());
		assertEquals("its baseline is untouched", 2_007_600L, d1.valueThen());
		assertEquals(-7_600L, d1.deltaGp());
		assertEquals("and 7d, which has no per-window now, still reads the headline's", 2_030_000L,
			s.move(MovementWindow.D7).valueNowCovered());
	}

	/** A per-window resolver that cannot answer for an id falls back to the headline's "now", never to nothing. */
	@Test
	public void aWindowNowThatCannotAnswerFallsBackToTheSharedOne()
	{
		final Map<MovementWindow, Function<Integer, Long>> empty = new EnumMap<>(MovementWindow.class);
		empty.put(MovementWindow.D1, id -> null);

		final PortfolioSummary s = PortfolioMath.summariseResolved(bank(), now()::get, thens(), empty, days(), 0L, 0);

		assertEquals("identical to the fixture, id for id", fixture().move(MovementWindow.D1), s.move(MovementWindow.D1));
		assertEquals(2, s.move(MovementWindow.D1).itemsCovered());
	}

	/**
	 * The BASIS is untouched by any of this: a window still covers the stacks the shared "now" prices and its own
	 * "then" names, so an untradeable stack on the alch rule stays out of every window even when a per-window
	 * resolver would happily answer for it.
	 */
	@Test
	public void aPerWindowNowCannotDragAnUncoveredStackIntoAWindow()
	{
		final List<BankItem> items = new ArrayList<>(bank());
		items.add(new BankItem(DRAMEN, 2, "Dramen staff", false, true, 1_500));
		final Map<MovementWindow, Function<Integer, Long>> pushy = new EnumMap<>(MovementWindow.class);
		pushy.put(MovementWindow.D1, Collections.singletonMap(DRAMEN, 9_000_000L)::get);
		final Map<MovementWindow, Function<Integer, Long>> thens = new EnumMap<>(MovementWindow.class);
		thens.put(MovementWindow.D1, id -> id == DRAMEN ? Long.valueOf(8_000_000L) : oneDayAgo().get(id));

		final PortfolioSummary s = PortfolioMath.summariseResolved(items, now()::get, thens, pushy, days(), 0L, 0);

		final WindowMove d1 = s.move(MovementWindow.D1);
		assertEquals("the alch stack is in the total at its alch value", 2_030_000L + 3_000L, s.valueNow());
		assertEquals("but in no window: the shared now never priced it", 2, d1.itemsCovered());
		assertEquals(2_020_000L, d1.valueNowCovered());
	}

	/** T5: how many stacks the caller priced live, carried through to the card's "N of M stacks live". */
	@Test
	public void theLiveRowCountIsCarriedOnTheSummary()
	{
		assertEquals(7, PortfolioMath.summariseResolved(bank(), now()::get, thens(), null, days(), 0L, 7).liveRows());
		assertEquals("a negative count is not a count", 0,
			new PortfolioSummary(1L, 1, 1, null, 0L, -3).liveRows());
		assertEquals("and it is part of the value: two summaries that priced differently are different",
			false, new PortfolioSummary(1L, 1, 1, null, 0L, 1).equals(new PortfolioSummary(1L, 1, 1, null, 0L, 2)));
	}

	/**
	 * The switch OFF, pinned where it matters most: the pre-T arity and the new one with no per-window resolvers
	 * and no live rows are the SAME summary, to the gp and to the field - which is what lets the whole engine
	 * carry one code path for both.
	 */
	@Test
	public void theNewArityWithNothingLiveIsTheOldOneExactly()
	{
		final PortfolioSummary before = PortfolioMath.summariseResolved(bank(), now()::get, thens(), days(), CASH);
		final PortfolioSummary after = PortfolioMath.summariseResolved(bank(), now()::get, thens(), null, days(),
			CASH, 0);

		assertEquals(before, after);
		assertEquals(before.hashCode(), after.hashCode());
		assertEquals(0, before.liveRows());
		assertEquals("an empty map is the same as none",
			before, PortfolioMath.summariseResolved(bank(), now()::get, thens(),
				Collections.<MovementWindow, Function<Integer, Long>>emptyMap(), days(), CASH, 0));
	}
}

package com.bankpricemovement;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * {@link BankPriceMovementPanel.Prefs} - the seam between the sidebar and where its choices are kept (contract
 * C28; the hero pair is addendum O line O2, the options pair addendum Q line Q3, the presets pair addendum Z
 * line Z1, the fold pair addendum AA line AA1,
 * {@code docs/bank-price-movement-addendum-AA-2026-09-13.md}, and the view pair addendum AU, the phase-0 contract's
 * amendment 9.15).
 *
 * <p>Only the FILTER pair is abstract. Every pair added since has a default, so a caller with nothing to
 * remember - the headless renderer, a throwaway test seam - need not care, and the panel draws exactly what it
 * drew before that pair existed. This file pins that: what a bare implementation answers, and that the writes it
 * does not want are no-ops rather than errors.
 *
 * <p>The plugin's own implementation over {@code ConfigManager} is a different thing and is pinned in
 * {@code BankPriceMovementWiringTest}; what a null from any of the three READS as is the panel's business and is
 * pinned in {@code BankPriceMovementPanelTest}.
 */
public class PrefsTest
{
	/** The least a {@code Prefs} can be: the filter pair, and not one line more. */
	private static final class Bare implements BankPriceMovementPanel.Prefs
	{
		final List<RowFilter> saved = new ArrayList<>();

		@Override
		public RowFilter load()
		{
			return null;
		}

		@Override
		public void save(RowFilter filter)
		{
			saved.add(filter);
		}
	}

	@Test
	public void aPrefsThatRemembersOnlyTheFilterAnswersNullToEverythingElse()
	{
		final Bare prefs = new Bare();
		assertNull("a fresh install has no filter", prefs.load());
		assertNull("O2: no stored hero switches", prefs.loadHero());
		assertNull("Q3/T1/Y1: no stored view switches", prefs.loadOptions());
		assertNull("Z1: no stored price presets", prefs.loadPresets());
		assertNull("AA1: no stored fold state", prefs.loadFoldOpen());
		assertNull("AU: no stored start tab", prefs.loadStartTab());
	}

	/**
	 * AA1: the fold pair answers a {@code Boolean} and not a {@code boolean}, because "nothing stored" and
	 * "stored closed" are different answers and only the first may be read as the shipped default (open). A
	 * primitive here would make every bare implementation - the renderer, a throwaway seam - claim the reader had
	 * chosen to shut the fold.
	 */
	@Test
	public void theFoldPairAnswersNullRatherThanFalseWhenNothingIsStored()
	{
		final Bare prefs = new Bare();
		assertNull(prefs.loadFoldOpen());
		assertNotEquals("a stored FALSE would be a choice, and this is not one", Boolean.FALSE, prefs.loadFoldOpen());
	}

	@Test
	public void theWritesItDoesNotWantAreNoOps()
	{
		final Bare prefs = new Bare();
		prefs.saveHero(HeroVisibility.NONE);
		prefs.saveOptions(ViewOptions.DEFAULT);
		prefs.savePresets(BandPresets.DEFAULT);
		prefs.saveFoldOpen(false);
		prefs.saveFoldOpen(true);
		prefs.saveStartTab(SidebarView.HISTORY);
		assertTrue("the defaults write nothing anywhere", prefs.saved.isEmpty());

		prefs.save(RowFilter.DEFAULT);
		assertEquals("...and the one pair that is abstract is the implementation's own", 1, prefs.saved.size());
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * {@link PriceMap} (contract C4, extended by K11): a set of prices as an immutable index, and the round trip
 * through the stock Gson that {@code PriceStore} writes to disk.
 *
 * <p>The immutability tests are not ceremony: a map is built on an OkHttp thread, kept by the service and read
 * while rows are computed on the executor, so anything that could mutate it after publication is a data race.
 *
 * <p>Addendum K adds {@code revId} - the wiki revision of {@code Module:GEPrices/data.json} the prices came
 * from. It has to survive disk (it is what the status line and the tooltip name) and it has to be ABSENT-safe:
 * a baseline file written by the first build has no such key, and reading it back as 0 is exactly what
 * {@code PriceStore.deleteStaleFiles()} uses to recognise a pre-K trade map and sweep it away.
 *
 * <p>The round trip is tested against a plain {@code new Gson()} - which a TEST may construct, while main code
 * may not (hub blocker C46) - because the injected client Gson is a stock builder for these types.
 */
public class PriceMapTest
{
	private static Map<Integer, PricePoint> points()
	{
		final Map<Integer, PricePoint> points = new HashMap<>();
		points.put(4151, new PricePoint(1_600_000L, 1_500_000L));
		points.put(2, new PricePoint(null, 180L));
		points.put(995, new PricePoint(1L, null));
		return points;
	}

	/** 2026-09-07T19:55:12Z, when revision 15333448 of the guide table was published (calibration doc). */
	private static final long REVISION_SECONDS = 1_788_810_912L;
	/** 2026-09-07T19:45:22Z - that revision's own {@code %LAST_UPDATE%}, the day marker L7 stores here. */
	private static final long DATA_SECONDS = 1_788_810_322L;
	private static final long REV_ID = 15_333_448L;

	@Test
	public void aMapAnswersItsPointsAndStamps()
	{
		final PriceMap map = new PriceMap(points(), 1_700_000_000_000L, 0L);

		assertEquals(3, map.size());
		assertFalse(map.isEmpty());
		assertEquals(1_700_000_000_000L, map.fetchedAtMillis());
		assertEquals("a map with no revision behind it carries no moment", 0L, map.bucketSeconds());
		assertEquals("and no revision id", 0L, map.revId());
		assertEquals(new PricePoint(1_600_000L, 1_500_000L), map.get(4151));
	}

	/**
	 * A guide baseline: both sides of every point hold the same figure (the guide price is one number, K1), the
	 * moment is the wiki revision's publication time and the revision id rides along.
	 */
	@Test
	public void aGuideBaselineCarriesTheRevisionItWasReadFrom()
	{
		final Map<Integer, PricePoint> points = new HashMap<>();
		points.put(658, new PricePoint(1124L, 1124L));

		final PriceMap map = new PriceMap(points, 1_788_909_600_123L, REVISION_SECONDS, REV_ID);

		assertEquals(REV_ID, map.revId());
		assertEquals(REVISION_SECONDS, map.bucketSeconds());
		assertEquals(1_788_909_600_123L, map.fetchedAtMillis());
		assertEquals("Green hat's guide price a day before the live session",
			Long.valueOf(1124L), map.get(658).mid());
	}

	/**
	 * Addendum L (L7) changed what {@code bucketSeconds} holds: the table's own {@code %LAST_UPDATE%} rather
	 * than the revision's save time, because a human maintenance edit republishes the previous day's prices
	 * under a later timestamp (L-E). {@link PriceMap#dataDay()} is the DAY the status line and the tooltip print;
	 * whether a stored baseline is still the right one is the time rule's call since contract 1.1.2
	 * ({@code RevisionRef.pickThen} on {@code MovementWindow.targetSeconds(nowSeconds)}), not a comparison of days.
	 */
	@Test
	public void theStoredMomentIsADayMarkerAndReadsBackAsAUtcDate()
	{
		final Map<Integer, PricePoint> points = new HashMap<>();
		points.put(658, new PricePoint(1124L, 1124L));

		assertEquals(LocalDate.of(2026, 9, 7),
			new PriceMap(points, 1L, DATA_SECONDS, REV_ID).dataDay());
		assertNull("a map with no marker has no day", PriceMap.EMPTY.dataDay());
		assertNull(new PriceMap(points, 1L, 0L).dataDay());

		// Midnight UTC is the day boundary wherever the client runs (L9); this box is four hours behind it.
		assertEquals(LocalDate.of(2026, 9, 9), new PriceMap(points, 1L, 1_788_912_000L).dataDay());
		assertEquals(LocalDate.of(2026, 9, 8), new PriceMap(points, 1L, 1_788_911_999L).dataDay());
	}

	/** The three-argument constructor is the "no revision behind this" case, and must say so, not guess. */
	@Test
	public void theShortConstructorMeansNoRevision()
	{
		assertEquals(0L, new PriceMap(points(), 5L, 3600L).revId());
		assertEquals(new PriceMap(points(), 5L, 3600L), new PriceMap(points(), 5L, 3600L, 0L));
	}

	/**
	 * A missing id is the ORDINARY case for a bucket map: one {@code /1h} bucket covered only 63-74 % of the
	 * items {@code /latest} knows (research C1/C10), so "no baseline for this item" must read as null, not as
	 * an exception and not as a zero.
	 */
	@Test
	public void anIdTheResponseDidNotCarryIsNull()
	{
		final PriceMap map = new PriceMap(points(), 1L, 0L);
		assertNull(map.get(4152));
		assertNull(map.get(0));
		assertNull(map.get(-1));
	}

	@Test
	public void theMapIsCopiedAtConstructionAndHandedOutUnmodifiable()
	{
		final Map<Integer, PricePoint> source = points();
		final PriceMap map = new PriceMap(source, 1L, 0L);

		source.put(9999, new PricePoint(5L, 5L));
		source.remove(4151);
		assertEquals("the map does not follow the caller's map", 3, map.size());
		assertNull(map.get(9999));
		assertEquals(new PricePoint(1_600_000L, 1_500_000L), map.get(4151));

		try
		{
			map.points().put(1, PricePoint.EMPTY);
			throw new AssertionError("points() must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// the point of the test
		}
	}

	@Test
	public void nullKeysAndValuesAreDroppedRatherThanStored()
	{
		final Map<Integer, PricePoint> source = new HashMap<>();
		source.put(4151, new PricePoint(10L, 8L));
		source.put(null, new PricePoint(1L, 1L));
		source.put(2, null);

		final PriceMap map = new PriceMap(source, 1L, 0L);
		assertEquals(1, map.size());
		assertNull(map.get(2));
	}

	@Test
	public void aNullSourceMapIsAnEmptyMap()
	{
		final PriceMap map = new PriceMap(null, 5L, 3600L);
		assertTrue(map.isEmpty());
		assertEquals(0, map.size());
		assertEquals(5L, map.fetchedAtMillis());
		assertEquals(3600L, map.bucketSeconds());
	}

	@Test
	public void emptyIsTheNothingFetchedYetMap()
	{
		assertTrue(PriceMap.EMPTY.isEmpty());
		assertEquals(0, PriceMap.EMPTY.size());
		assertEquals(0L, PriceMap.EMPTY.fetchedAtMillis());
		assertEquals(0L, PriceMap.EMPTY.bucketSeconds());
		assertEquals(0L, PriceMap.EMPTY.revId());
		assertNull(PriceMap.EMPTY.get(4151));
	}

	// ---------------------------------------------------------------- the on-disk form

	@Test
	public void theDtoRoundTripsThroughStockGson()
	{
		final PriceMap map = new PriceMap(points(), 1_700_000_000_000L, REVISION_SECONDS, REV_ID);
		final Gson gson = new Gson();

		final String json = gson.toJson(map.toDto());
		final PriceMap back = PriceMap.fromDto(gson.fromJson(json, PriceMapDto.class));

		assertEquals("the whole value survives disk", map, back);
		assertEquals(3, back.size());
		assertEquals(1_700_000_000_000L, back.fetchedAtMillis());
		assertEquals(REVISION_SECONDS, back.bucketSeconds());
		assertEquals("the revision id is what tells a later launch this file is from the guide era (K11)",
			REV_ID, back.revId());
		assertTrue("and it must actually be written, not just defaulted", json.contains("15333448"));
	}

	/**
	 * B028, the migration lever. Every document this build writes says which SHAPE it is, because a revision id
	 * cannot: addendum K and addendum L both write one, and yet {@code bucketSeconds} means the revision's save
	 * time in a K-era file and the table's own {@code %LAST_UPDATE%} in an L-era one. A file written before the
	 * marker existed reads as 0 - and that absence IS the marker, which is why the number goes in before v1.
	 */
	@Test
	public void aSavedBaselineCarriesItsSchemaAndAFileWrittenBeforeTheMarkerReadsAsZero()
	{
		final Gson gson = new Gson();
		final PriceMap map = new PriceMap(points(), 1_700_000_000_000L, REVISION_SECONDS, REV_ID);
		assertEquals("a map built in memory is this build's shape", PriceMapDto.SCHEMA, map.schema());

		final String json = gson.toJson(map.toDto());
		assertTrue("and the number has to be written, not defaulted on the way back in",
			json.contains("\"schema\":" + PriceMapDto.SCHEMA));
		assertEquals(PriceMapDto.SCHEMA, PriceMap.fromDto(gson.fromJson(json, PriceMapDto.class)).schema());

		final PriceMap older = PriceMap.fromDto(gson.fromJson(
			"{\"fetchedAtMillis\":1788909600123,\"bucketSeconds\":1788822000,\"revId\":15333448,"
				+ "\"points\":{\"658\":[1124,1124]}}", PriceMapDto.class));
		assertEquals("a key the file has not got is what marks the build that wrote it", 0, older.schema());
		assertEquals("and it still parses WHOLE - refusing it is the service's call, not the reader's",
			1, older.size());
		assertEquals(15_333_448L, older.revId());
	}

	/**
	 * The reason for the sentinel: a side the wiki did not give must still be missing after the file has been
	 * written and read, whatever the Gson instance does with nulls (the injected client Gson drops them -
	 * playbook 7.8).
	 */
	@Test
	public void aMissingSideSurvivesTheRoundTripAsNull()
	{
		final Gson gson = new Gson();
		final Map<Integer, PricePoint> source = new HashMap<>();
		source.put(2, new PricePoint(null, 180L));
		source.put(3, new PricePoint(180L, null));
		source.put(4, new PricePoint(null, null));

		final PriceMap back = PriceMap.fromDto(
			gson.fromJson(gson.toJson(new PriceMap(source, 7L, 0L).toDto()), PriceMapDto.class));

		assertNull(back.get(2).high());
		assertEquals(Long.valueOf(180L), back.get(2).low());
		assertEquals(Long.valueOf(180L), back.get(3).high());
		assertNull(back.get(3).low());
		assertTrue(back.get(4).isEmpty());
	}

	@Test
	public void aZeroPriceIsKeptWhileTheSentinelReadsAsAbsent()
	{
		final Map<Integer, PricePoint> source = new HashMap<>();
		source.put(2, new PricePoint(0L, 0L));

		final PriceMap back = PriceMap.fromDto(new PriceMap(source, 1L, 0L).toDto());
		assertEquals(Long.valueOf(0L), back.get(2).high());
		assertEquals(Long.valueOf(0L), back.get(2).low());

		assertEquals(PriceMapDto.ABSENT, PriceMapDto.encode(null));
		assertEquals(Long.valueOf(0L), PriceMapDto.decode(0L));
		assertNull(PriceMapDto.decode(PriceMapDto.ABSENT));
		assertNull("anything negative reads as absent", PriceMapDto.decode(-99L));
	}

	/**
	 * A price file is read on the executor at start-up (C22): every kind of damage a hand-edited or truncated
	 * file can carry has to be skipped, because a stale price file must never stop the panel opening (D9).
	 */
	@Test
	public void damagedDtoContentIsSkippedRatherThanThrown()
	{
		final PriceMapDto dto = new PriceMapDto();
		dto.fetchedAtMillis = 12L;
		dto.bucketSeconds = 3600L;
		dto.points = new HashMap<>();
		dto.points.put("4151", new long[]{10L, 8L});
		dto.points.put("not-an-id", new long[]{1L, 1L});
		dto.points.put("7", null);
		dto.points.put("8", new long[]{5L});
		dto.points.put("9", new long[0]);

		final PriceMap map = PriceMap.fromDto(dto);
		assertEquals(1, map.size());
		assertEquals(new PricePoint(10L, 8L), map.get(4151));
		assertEquals(12L, map.fetchedAtMillis());
		assertEquals(3600L, map.bucketSeconds());
	}

	@Test
	public void aNullOrEmptyDtoIsTheEmptyMap()
	{
		assertSame(PriceMap.EMPTY, PriceMap.fromDto(null));

		final PriceMapDto dto = new PriceMapDto();
		final PriceMap map = PriceMap.fromDto(dto);
		assertTrue("a dto with no points map at all still reads", map.isEmpty());
		assertEquals(0L, map.fetchedAtMillis());
	}

	/**
	 * A file written before some future field existed must still parse - the back-compat rule every persisted
	 * class in this workspace carries.
	 */
	@Test
	public void jsonWithOnlyThePointsParses()
	{
		final PriceMap map = PriceMap.fromDto(
			new Gson().fromJson("{\"points\":{\"4151\":[100,90]}}", PriceMapDto.class));

		assertEquals(1, map.size());
		assertEquals(Long.valueOf(95L), map.get(4151).mid());
		assertEquals("a file with no stamp reads as never fetched", 0L, map.fetchedAtMillis());
		assertEquals(0L, map.bucketSeconds());
		assertEquals(0L, map.revId());
	}

	/**
	 * The exact shape the FIRST build wrote: {@code fetchedAtMillis}, {@code bucketSeconds} (an hourly trade
	 * bucket) and {@code points}, with no {@code revId} key at all. It must parse, and it must read back as
	 * revision 0 - that is the signal {@code PriceStore.deleteStaleFiles()} acts on to sweep a trade-era
	 * baseline away before it can show "+12845.5 %" again.
	 */
	@Test
	public void aBaselineFileFromBeforeAddendumKParsesAndReadsAsRevisionZero()
	{
		final PriceMap map = PriceMap.fromDto(new Gson().fromJson(
			"{\"fetchedAtMillis\":1788909600123,\"bucketSeconds\":1788822000,\"points\":{\"658\":[11,-1]}}",
			PriceMapDto.class));

		assertEquals(1, map.size());
		assertEquals("the 1h bucket that produced the absurd figure: nine units at an average high of 11",
			Long.valueOf(11L), map.get(658).mid());
		assertEquals(1_788_822_000L, map.bucketSeconds());
		assertEquals("no revId key means revision 0, which marks the file as pre-addendum-K", 0L, map.revId());
	}

	@Test
	public void theMapCompares()
	{
		assertEquals(new PriceMap(points(), 1L, 0L), new PriceMap(points(), 1L, 0L));
		assertEquals(new PriceMap(points(), 1L, 0L).hashCode(), new PriceMap(points(), 1L, 0L).hashCode());
		assertNotEquals(new PriceMap(points(), 2L, 0L), new PriceMap(points(), 1L, 0L));
		assertNotEquals(new PriceMap(points(), 1L, 3600L), new PriceMap(points(), 1L, 0L));
		assertNotEquals("two maps from different revisions are different maps",
			new PriceMap(points(), 1L, 0L, REV_ID), new PriceMap(points(), 1L, 0L, 0L));
		assertEquals(new PriceMap(points(), 1L, 0L, REV_ID).hashCode(),
			new PriceMap(points(), 1L, 0L, REV_ID).hashCode());
		assertNotEquals(PriceMap.EMPTY, new PriceMap(points(), 1L, 0L));
	}
}

package com.bankpricemovement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * {@link PricePoint} (contract C3): the mid rule, branch by branch.
 *
 * <p>Every branch is a real case, not a defensive one: the live {@code /1h} bucket measured on 2026-09-08 had
 * about 20 % of entries with no {@code avgHighPrice} and about 16 % with no {@code avgLowPrice} (research C10),
 * so "one side only" is roughly a third of the market and the mid rule has to be symmetric. The both-null case
 * was never observed and is the defensive one.
 */
public class PricePointTest
{
	@Test
	public void bothSidesGiveTheMean()
	{
		assertEquals(Long.valueOf(150L), new PricePoint(200L, 100L).mid());
		assertEquals(Long.valueOf(1_550_000L), new PricePoint(1_600_000L, 1_500_000L).mid());
		assertEquals(Long.valueOf(99L), new PricePoint(100L, 98L).mid());
	}

	/**
	 * Half-up, so an odd sum does not silently round the price down every time.
	 */
	@Test
	public void anOddSumRoundsUp()
	{
		assertEquals(Long.valueOf(3L), new PricePoint(3L, 2L).mid());
		assertEquals(Long.valueOf(2L), new PricePoint(2L, 1L).mid());
		assertEquals(Long.valueOf(101L), new PricePoint(101L, 100L).mid());
	}

	@Test
	public void oneSideStandsAloneWhicheverSideItIs()
	{
		assertEquals("no low: the high is the price", Long.valueOf(100L), new PricePoint(100L, null).mid());
		assertEquals("no high: the low is the price", Long.valueOf(80L), new PricePoint(null, 80L).mid());
	}

	@Test
	public void neitherSideIsNoPriceRatherThanZero()
	{
		assertNull(new PricePoint(null, null).mid());
		assertTrue(new PricePoint(null, null).isEmpty());
		assertTrue(PricePoint.EMPTY.isEmpty());
		assertNull(PricePoint.EMPTY.mid());
	}

	@Test
	public void aPointWithEitherSideIsNotEmpty()
	{
		assertFalse(new PricePoint(1L, null).isEmpty());
		assertFalse(new PricePoint(null, 1L).isEmpty());
		assertFalse(new PricePoint(1L, 1L).isEmpty());
	}

	/**
	 * A price of zero is a price. Only null means "no price".
	 */
	@Test
	public void zeroIsAPrice()
	{
		final PricePoint zero = new PricePoint(0L, 0L);
		assertFalse(zero.isEmpty());
		assertEquals(Long.valueOf(0L), zero.mid());
	}

	/**
	 * Prices may exceed int (research), so the sides are longs - and the mid of two huge sides must not
	 * overflow the way {@code (high + low) / 2} would.
	 */
	@Test
	public void aHugePairDoesNotOverflow()
	{
		final Long mid = new PricePoint(Long.MAX_VALUE, Long.MAX_VALUE).mid();
		assertTrue("the mid of two maximums is still positive, not a wrapped negative", mid > 0L);
		assertEquals(Long.valueOf(Long.MAX_VALUE), mid);

		assertEquals(Long.valueOf(3_000_000_000L), new PricePoint(4_000_000_000L, 2_000_000_000L).mid());
	}

	@Test
	public void sidesAreReadableAndTheValueCompares()
	{
		final PricePoint point = new PricePoint(200L, 100L);
		assertEquals(Long.valueOf(200L), point.high());
		assertEquals(Long.valueOf(100L), point.low());

		assertEquals(new PricePoint(200L, 100L), point);
		assertEquals(new PricePoint(200L, 100L).hashCode(), point.hashCode());
		assertNotEquals(new PricePoint(100L, 200L), point);
		assertNotEquals(new PricePoint(200L, null), point);
		assertNotEquals(point, null);
		assertNotEquals(point, "PricePoint");
	}
}

