		for (int i = 0; i < 400; i++)
		{
			old.add(new RevisionRef(15_000_000L + i, start + (i / 8) * 86_400L + (i % 8) * 3L * 3_600L,
				RevisionRef.BOT_USER, RevisionRef.BOT_COMMENT));
		}
		when(store.loadRevisionIndex()).thenReturn(storedIndex(old, T0 - HOUR));

		service.start();

