		indexFutures.get(indexFutures.size() - 1).complete(Collections.singletonList(BOT_0908));
		final ArgumentCaptor<List<RevisionRef>> written = listCaptor();
		verify(store).saveRevisionIndex(written.capture(), eq(T0));
