	{
		final Map<Integer, TradedPriceClient.Quote> silentWhip = Collections.singletonMap(WHIP,
			new TradedPriceClient.Quote(860_000L, T0 / 1000L - 21L * 3_600L, 840_000L, T0 / 1000L - 22L * 3_600L));
