	/** An untradeable stack the tests plant a failure in. */
	private static final int PLANTED = 77_777;

	/**
	 * A stack whose {@code hasParts()} throws when - and only when - it is asked from the named method of the named
	 * class, found on the stack. A failure planted at one exact place in the service, with nothing else changed: it
	 * is how these tests reach code that throws for no input the real reader produces.
	 */
	private static final class Planted extends BankItem
	{
		private final String owner;
		private final String method;

		Planted(final String owner, final String method)
		{
			super(PLANTED, 1, "Planted item", false, true, 1_000);
			this.owner = owner;
			this.method = method;
		}

		@Override
		public boolean hasParts()
		{
			for (final StackTraceElement frame : new Throwable().getStackTrace())
			{
				if (frame.getMethodName().equals(method) && frame.getClassName().endsWith(owner))
				{
					throw new IllegalStateException("planted in " + owner + "." + method);
				}
			}
			return super.hasParts();
		}
	}

